window.POEM_DB=window.POEM_DB||{};POEM_DB["song_011"]={"n":"周紫芝","dyn":"宋","poems":[{"t":"白苧歌","f":"词","c":["大垂手，小垂手，江南白苧世希有。","吴姬十指玉纤纤，白苧新裁舞衣袖。","秋江四面绕吴宫，吴宫霜橘树树红。","吴王夜燕不知晓，但见红日升曈昽。","美人低鬟复回袖，持酒献君上君寿。","人生得意不行乐，白日如梭夜催昼。","吴山依旧吴江清，离宫故苑难为情。","不知谁遣南山鹿，还向姑苏台下行。"]},{"t":"越台曲","f":"词","c":["玉颜如花越王女，自小娇痴不歌舞。","嫁作江南国主妃，日日思归泪如雨。","江南江北梅子黄，潮头夜涨秦淮江。","江边雨多地卑湿，旋筑高台匀晓妆。","千艘命载越中土，喜见越人仍越语。","人生脚踏乡土难，无复归心越中去。","高台何易倾，曲池亦复平。","越姬一去向千载，不见此台空有名。"]},{"t":"寒食前五日作二绝 其二","f":"七言绝句","c":["寒食风埃满客巾，西湖烟雨送愁频。","日高未起鸟呼梦，春晚不归花笑人。"]},{"t":"五禽言 其五 布谷","f":"词","c":["田中水涓涓，布谷催种田，贼今在邑农在山。","但愿今年贼去早，春田处处无荒草。","农夫呼妇出山来，深种春秧答飞鸟。"]},{"t":"五禽言 其三 提壶卢","f":"词","c":["提壶卢，树头劝酒声相呼，劝人沽酒无处沽。","太岁何年当在酉，敲门问浆还得酒。","田中黍穗处处黄，瓮头新绿家家有。"]},{"t":"五禽言 其一 婆饼焦","f":"词","c":["云穰穰，麦穗黄，婆饼欲焦新麦香。","今年麦熟不敢尝，斗量车载倾囷仓，化作三军马上粮。"]},{"t":"一剪梅 送杨师醇赴官","f":"词","c":["无限江山无限愁。","两岸斜阳，人上扁舟。","阑干吹浪不多时，酒在离尊，情满沧洲。","早是霜华两鬓秋。","目送飞鸿，那更难留。","问君尺素几时来，莫道长江，不解西流。"]},{"t":"卜算子 其二 再和彦猷","f":"词","c":["霜叶下孤篷，船在垂杨岸。","早是凄凉惜别时，更惜年华换。","别酒解留人，拚醉君休管。","醉里朱弦莫谩弹，愁入参差雁。"]},{"t":"卜算子 其三 西窗见剪榴花","f":"词","c":["絮尽柳成空，春去花如扫。","窗外枝枝海石榴，特为幽人好。","密叶过疏篱，薄艳明芳草。","剪得花时却倚阑，楼上人垂手。"]},{"t":"卜算子 其一 席上送王彦猷","f":"词","c":["江北上归舟，再见江南岸。","江北江南几度秋，梦里朱颜换。","人是岭头云，聚散天谁管。","君似孤云何处归，我似离群雁。"]},{"t":"千秋岁 其一 生日","f":"词","c":["小春时候。","晴日吴山秀。","霜尚浅，梅先透。","波翻醽醁盏，雾暖芙蓉绣。","持寿酒。","仙娥特地回双袖。","试问春多少，恩入芝兰厚。","松不老，山长久。","星占南极远，家是椒房旧。","君一笑，金鸾看取人归后。"]},{"t":"千秋岁 其二 叶审言生日","f":"词","c":["当年文焰，蜀锦词华烂。","年正少，声初远。","手攀天上桂，书奏蓬莱殿。","人尽道，洛阳盛事今重见。","千尺青苍干。","直节凌霄汉。","天未识，应嗟晚。","饮残长寿盏，归奉春皇燕。","金叶满。","擗麟且受麻姑劝。"]},{"t":"千秋岁 其三 春欲去，二妙老人戏作长短句留之，为社中一笑","f":"词","c":["送春归去。","说与愁无数。","君去后，归何处。","人应空懊恼，春亦无言语。","寒日暮，腾腾醉梦随风絮。","尽日间庭雨。","红湿秋千柱。","人恨切，莺声苦。","拟倾浇闷酒，留取残红树。","春去也，不成不为愁人住。"]},{"t":"小重山 其二 方元相生日","f":"词","c":["碧玉山围十里湖。","水云天共远，戏双凫。","河阳花县锦屏铺。","人不老，长日在蓬壶。","一笑且踟蹰。","会骑箕尾去，上云衢。","十分深注碧琳腴。","休惜醉，醉后有人扶。"]},{"t":"小重山 其一","f":"词","c":["溪上晴山簇翠螺。","晓来霜叶醉，小池荷。","琐窗秋意苦无多。","帘绣卷，黄菊两三窠。","小睡拥香罗。","起来匀醉粉，玉垂梭。","只愁无奈夜长何。","你去也，今夜早来么。"]},{"t":"天仙子","f":"词","c":["雪似杨花飞不定。","枝上冻禽昏欲暝。","寒窗相对话分飞，箫鼓静。","灯炯炯。","一曲阳关和泪听。","酒入离肠愁欲凝。","往事不堪重记省。","劝君莫上玉楼梯，风力劲。","山色暝。","忍看去时楼下径。"]},{"t":"忆王孙 绝笔","f":"词","c":["梅子生时春渐老。","红满地、落花谁扫。","旧年池馆不归来，又绿尽、今年草。","思量千里乡关道。","山共水、几时得到。","杜鹃只解怨残春，也不管、人烦恼。"]},{"t":"木兰花/玉楼春 其一 长安狭邪中，有高自标置者，客非新科不得其门，时颇称之。予尝语人曰：相马失之肥，相士失之瘦，世亦岂可以是论人物乎！戏作此词，为花衢狭客一笑","f":"七言律诗","c":["嫦娥天上人谁识。","家在蓬山烟水隔。","不应著意眼前人，便是登瀛当日客。","双眸炯炯秋波滴。","也解人间青与白。","檀郎未摘月边枝，枉是不教花爱惜。"]},{"t":"木兰花/玉楼春 其二","f":"七言律诗","c":["江头雨后山如髻。","催送新凉风有意。","月来杨柳绿阴中，秋在梧桐疏影外。","小窗纹簟凉如水。","岁岁年年同此味。","眼前不忍对西风，梦里更堪追往事。"]},{"t":"水龙吟 其二 题梦云轩","f":"词","c":["楚山千叠浮空，楚云只在巫山住。","鸾飞凤舞，当时空记，梦中奇语。","晓日曈昽，夕阳零乱，袅红萦素。","问如今依旧，霏霏冉冉，知他为、谁朝暮。","玉佩烟鬟飞动，炯星眸、人间相遇。","嫣然一笑，阳城下蔡，尽成惊顾。","蕙帐春浓，兰衾日暖，未成行雨。","但丁宁莫似，阳台梦断，又随风去。"]},{"t":"水龙吟 其三 须江望九华作","f":"词","c":["楚山木落风高，暮云黯黯孤容瘦。","天晴似洗，明霞消尽，玉峦排秀。","九凤飞来，五云深处，一时轻矫。","恨三山不见，六鳌去后，天空远，人将老。","堪笑此生如寄，信扁舟、朅来江表。","望中愁眼，依稀犹认，数峰林杪。","万里东南，跨江云梦，此情多少。","问何时还我，千岩万壑，卧霜天晓。"]},{"t":"水龙吟 其一 天申节祝圣词","f":"词","c":["黄金双阙横空，望中隐约三山眇。","春皇欲降，渚烟收尽，青虹正绕。","日到层霄，九枝光满，普天俱照。","看海中桃熟，云幡绛节，冉冉度、沧波渺。","遥想建章宫阙，□熏风、月寒清晓。","红鸾影上，云韶声里，蒙天一笑。","万国朝元，百蛮款塞，太平多少。","听尧云深处，人人尽祝，似天难老。"]},{"t":"水调歌头 其三 丙午登白鹭亭作","f":"词","c":["岁晚念行役，江阔渺风烟。","六朝文物何在，回首更凄然。","倚尽危楼杰观，暗想琼枝璧月，罗袜步承莲。","桃叶山前鹭，无语下寒滩。","潮寂寞，浸孤垒，涨平川。","莫愁艇子何处，烟树杳无边。","王谢堂前双燕，空绕乌衣门巷，斜日草连天。","只有台城月，千古照婵娟。"]},{"t":"水调歌头 其二 王次卿归自彭门，中秋步月作","f":"词","c":["濯锦桥边月，几度照中秋。","年年此夜清景，伴我与君游。","万里相随何处，看尽吴波越嶂，更向古徐州。","应为霜髯老，西望倚黄楼。","天如水，云似扫，素魂流。","不知今夕何夕，相对语羁愁。","故国归来何事，记易南枝惊鹊，还对玉蟾羞。","踏尽疏桐影，更复为君留。"]},{"t":"水调歌头 其四 雨后月出西湖作","f":"词","c":["落日在烟树，云水两空濛。","澹霞消尽，何事依约有微红。","湖上晚来风细，吹尽一天残雨，苍翠湿千峰。","谁遣长空月，冷浸玉壶中。","问明月，应解笑，白头翁。","不堪老去，依旧临水照衰容。","良夜几横烟棹，独倚危樯西望，目断远山重。","但恨故人远，此乐与谁同。"]},{"t":"风入松","f":"词","c":["禁烟过后落花天。","无奈轻寒。","东风不管春归去，共残红、飞上秋千。","看尽天涯芳草，春愁堆在阑干。","楚江横断夕阳边。","无限青烟。","旧时云去今何处，山无数、柳涨平川。","与问风前回雁，甚时吹过江南。"]},{"t":"永遇乐 五日","f":"词","c":["槐幄如云，燕泥犹湿，雨馀清暑。","细草摇风，小荷擎雨，时节还端午。","碧罗窗底，依稀记得，闲系翠丝烟缕。","到如今、前欢如梦，还对彩绦无语。","榴花半吐，金刀犹在，往事更堪重数。","艾虎钗头，菖蒲酒里，旧约浑无据。","轻衫如雾，玉肌似削，人在画楼深处。","想灵符、无人共带，翠眉暗聚。"]},{"t":"汉宫春 其二 别乘赵李成以山谷道人反魂梅香材见遗","f":"词","c":["香满箱奁，看沈犀弄水，浓麝含薰。","荀郎一时旧事，尽属王孙。","残膏剩馥，须倾囊、乞与兰荪。","金兽暖，云窗雾阁，为人洗尽馀醺。","依稀雪梅风味，似孤山尽处，马上烟村。","从来甲煎浅俗，那忍重闻。","苏台燕寝，下重帏、深闭孤云。","都占得，横斜乱影，伴他月下黄昏。"]},{"t":"汉宫春 其一 己未中秋作","f":"词","c":["秋意还深，渐银床露冷，梧叶风高。","婵娟也应为我，羞照霜毛。","流年老尽，漫银蟾、冷浸香醪。","除尽把，平生怨感，一时分付离骚。","伤心故人千里，问阴晴何处，还记今宵。","楼高共谁同看，玉桂烟梢。","南枝鹊绕，叹此生、飘转江皋。","须更约，他年清照，为人常到寒霄。"]},{"t":"生查子 其四","f":"五言律诗","c":["清歌忆去年，共唱秦楼曲。","门外月横波，帐里人如玉。","秋风吹彩云，梦断惊难续。","别调不堪闻，红泪销残烛。"]},{"t":"生查子 其一","f":"五言律诗","c":["春寒入翠帷，月淡云来去。","院落半晴天，风撼梨花树。","人醉掩金铺，闲倚秋千柱。","满眼是相思，无说相思处。"]},{"t":"生查子 其六","f":"五言律诗","c":["轻云浅护霜，晓日红生砌。","烟共宝薰浓，人与山长翠。","银浪酒杯浓，锦幄双鸾戏。","庭下彩衣郎，共祝千千岁。"]},{"t":"生查子 其五","f":"五言律诗","c":["金鞍欲别时，芳草溪边渡。","不忍上西楼，怕看来时路。","帘幕卷东风，燕子双双语。","薄幸不归来，冷落春情绪。"]},{"t":"生查子 其三","f":"五言律诗","c":["新欢君未成，往事无人记。","行雨共行云，如梦还如醉。","相见又难言，欲住浑无计。","眉翠莫频低，我已无多泪。"]},{"t":"生查子 其二","f":"五言律诗","c":["青丝结晓鬟，临镜心情懒。","知为晓愁浓，画得双蛾浅。","柳困玉楼空，花落红窗暖。","相对语春愁，只有春闺燕。"]},{"t":"好事近 其二 谢人分似蜡梅一枝","f":"词","c":["香蜡染宫黄，不属世间风月。","分我照寒金蕊，伴小窗愁绝。","高标独步本无双，一枝为谁折。","压尽半春桃李，任满山如雪。"]},{"t":"好事近 其五 海棠","f":"词","c":["春似酒杯浓，醉得海棠无力。","谁染玉肌丰脸，做燕支颜色。","送春风雨最无情，吹残也堪惜。","何似且留花住，唤小鬟催拍。"]},{"t":"好事近 其三","f":"词","c":["帘外一声歌，倾尽满城风月。","看到酒阑羞处，想多情难说。","周郎元是个中人，如今鬓如雪。","自恨老来肠肚，诮不堪摧折。"]},{"t":"好事近 其一 青阳道中见梅花。是日微风，花已有落者","f":"词","c":["江路绕青山，山翠扑衣轻湿。","谁酿晚来云意，做一天愁色。","竹溪斜度尽篮舆，疏梅暗香入。","何处最关心事，恨落梅风急。"]},{"t":"好事近 其四","f":"词","c":["雨后欲斜阳，红满井梧风叶。","还是夜来时候，共小轩明月。","不关纤手与调冰，消除这些热。","自是月娥肌骨，似玉壶香雪。"]},{"t":"好事近 其六","f":"词","c":["秋意总关愁，那更与君轻别。","从此共谁同醉，恨老来风月。","遥知手板笑看云，江边醉时节，应为老人回首，记白头如雪。"]},{"t":"江城子 其二","f":"词","c":["碧梧和露滴清秋。","小庭幽。","翠烟流。","羞带一襟，明月上危楼。","苦恨秋江风与月，偏管断，这些愁。","此情空道两绸缪。","信悠悠。","几时休。","到得如今，刬地见无由。","拟待不能思想得，无限事，在心头。"]},{"t":"江城子 其一","f":"词","c":["夕阳低尽柳如烟。","淡平川。","断肠天。","今夜十分，霜月更娟娟。","怎得人如天上月，虽暂缺，有时圆。","断云飞雨又经年。","思凄然。","泪涓涓。","且做如今，要见也无缘。","因甚江头来处雁，飞不到，小楼边。"]},{"t":"西地锦","f":"词","c":["雨细欲收还滴。","满一庭秋色。","阑干独倚，无人共说，这些愁寂。","手把玉郎书迹。","怎不教人忆。","看看又是黄昏也，敛眉峰轻碧。"]},{"t":"西江月 其七","f":"词","c":["谁把蓝揉翡翠，天将蜡做梅花。","晚来秋水映残霞。","水墨新描图画。","纸上写将心去，眼边送却愁来。","今回相见比前回。","心下忡忡越㬠。"]},{"t":"西江月 其六 和孙子绍拒霜词","f":"词","c":["天意未教秋老，花容刬地宜霜。","酒肌红软玉肌香。","不与梨花同样。","来伴孙郎小宴，临风为舞霓裳。","更深绿水照红妆。","便是采莲船上。"]},{"t":"西江月 其五 席上赋双荔子","f":"词","c":["连理枝头并蒂，同心带上双垂。","背灯偷赠语低低。","一点浓情先寄。","翡翠钗头摘处，鸳鸯枕上醒时。","酸甜红颗阿谁知。","别是人间滋味。"]},{"t":"西江月 其三","f":"词","c":["罗袖云轻雾薄，醉肌玉软花柔。","相逢不道有春愁。","只道春来微瘦。","一点人间深意，数声柳下轻讴。","带将离恨上归舟。","肠断月斜时候。"]},{"t":"西江月 其一","f":"词","c":["画幕灯前细雨，垂莲盏里清歌。","玉纤持板隔香罗。","不放行云飞过。","今夜尘生洛浦，明朝雨在巫山。","羞蛾且莫斗弯环。","不似司空见惯。"]},{"t":"西江月 其二","f":"词","c":["池面风翻弱絮，树头雨退嫣红。","扑花蝴蝶杳无踪。","又做一场春梦。","便是一成去了，不成没个来时。","眼前无处说相思。","要说除非梦里。"]},{"t":"西江月 其四","f":"词","c":["发白犹敧旅枕，溪深未挂烟莎。","往来苕霅意如何。","应有轻鸥笑我。","细算年来活计，只消一个渔舟。","金鱼无分不须求。","只乞鲈鱼换酒。"]},{"t":"阮郎归 其二","f":"词","c":["月棂疏影照婵娟。","闲临小玉盘。","枣花金钏出纤纤。","棋声敲夜寒。","飞雹冷，水精圆。","夜深人未眠。","笑催炉兽暖衾鸳。","莫教银漏残。"]},{"t":"阮郎归 其三 西湖摘杨梅作","f":"词","c":["西湖山下水潺潺。","满山风雨寒。","枝头红日晓斓斑。","越梅催晓丹。","连翠叶，拥金盘。","玉池生乳泉。","此生三度试甘酸。","欲归归尚难。"]},{"t":"阮郎归 其一","f":"词","c":["酴醾花谢日迟迟。","杨花无数飞。","章台侧畔尽风吹。","飘零无定期。","烟漠漠，草萋萋。","江南春尽时。","可怜踪迹尚东西。","故园何日归。"]},{"t":"沙塞子 其一 中秋无月","f":"词","c":["秋云微淡月微羞。","云黯黯、月彩难留。","只应是、嫦娥心里，也似人愁。","几时回步玉移钩。","人共月、同上南楼。","却重听、画阑西角，月下轻讴。"]},{"t":"沙塞子 其二 席上送赵戒叔，时东南方扰","f":"词","c":["玉溪秋月浸寒波。","忍持酒、重听骊歌。","不堪对、绿阴飞阁，月下羞蛾。","夜深惊鹊转南柯。","惨别意、无奈愁何。","他年事、不须重问，转更愁多。"]},{"t":"苏幕遮 其二","f":"词","c":["老相邀，山作伴。","千里西来，始识庐山面。","爱酒扬雄浑不管。","天与邻翁，来慰穷愁眼。","似惊鸿，吹又散。","画舸横江，望断江南岸。","地角天涯无尽远。","一阕清歌，且放梨花满。"]},{"t":"苏幕遮 其一","f":"词","c":["水傍边，山尽处。","唤取云来，共我山头住。","分得一江风共雨。","满院芙蓉，更听红妆舞。","趁霜晴，闲独步。","那里烟村，有个梅花树。","小径斜穿来又去。","醉后知他，有甚青云路。"]},{"t":"定风波令/定风波","f":"词","c":["梅粉梢头雨未乾。","淡烟疏日带春寒。","暝鸦啼处，人在小楼边。","芳草只随春恨长，塞鸿空傍碧云还。","断霞销尽，新月又婵娟。"]},{"t":"采桑子 雨后至玉壶轩","f":"词","c":["跳珠雨罢风初静，阑槛凭虚。","绛阙清都。","只在仙人碧玉壶。","九原唤起王摩诘，画作新图。","十里芙蕖。","乞与知章老鉴湖。"]},{"t":"采桑子 将离武林","f":"词","c":["云踪老去浑无定，飘泊寒空。","又被东风。","吹过江南第几峰。","长安市上看花眼，不到衰翁。","好趁归鸿。","家在西岩碧桂丛。"]},{"t":"雨中花令 吴兴道中，颇厌行役，作此曲寄武林交旧","f":"词","c":["山雨细、泉生幽谷，水满平田。","雪茧红蚕熟后，黄云陇麦秋间。","武陵烟暖，数声鸡犬，别是山川。","嗟老去、倦游踪迹，长恨华颠。","行尽吴头楚尾，空惭万壑千岩。","不如休也，一庵归去，依旧云山。"]},{"t":"青玉案 其一 凌歊台怀姑溪老人李端叔","f":"词","c":["青鞋忍踏江沙路。","恨人已、骑鲸去。","笔底骅骝谁与度。","西州重到，可怜不见，华屋生存处。","秋江渺渺高台暮。","满壁栖鸦醉时句。","飞上金鸾人漫许。","清歌低唱，小蛮犹在，空湿梨花雨。"]},{"t":"青玉案 其二","f":"词","c":["梅花落尽人谁管。","暗凄断、伤春眼。","雪后平芜春尚浅。","一簪华发，满襟离恨，羞做东风伴。","斗花小斛兰芽短。","犹是当时旧庭院。","拟把新愁凭酒遣。","春衫重看，酒痕犹在，忍放金杯满。"]},{"t":"临江仙 其一","f":"词","c":["水远山长何处去，欲行人似孤云。","十分瘦损沈休文。","忍将秋水镜，容易与君分。","试问梨花枝上雨，为谁弹满清尊。","一江风月黯离魂。","平波催短棹，小立送黄昏。"]},{"t":"临江仙 其二 送光州曾使君","f":"词","c":["记得武陵相见日，六年往事堪惊。","回头双鬓已星星。","谁知江上酒，还与故人倾。","铁马红旗寒日暮，使君犹寄边城。","只愁飞诏下青冥。","不应霜塞晚，横槊看诗成。"]},{"t":"南柯子/南歌子 其二","f":"词","c":["雾帐兰衾暖，薰炉宝篆浓。","眼波犹带睡朦胧。","卧听晓来双燕、语春风。","螺浅欢馀黛，霞销枕处红。","断云飞雨怕匆匆。","欲去且留情绪、两冲冲。"]},{"t":"南柯子/南歌子 其一 方钱唐出侍儿，范谢州要予作此词","f":"词","c":["蝉薄轻梳鬓，螺香浅画眉。","西湖人道似西施。","人似西施浓淡、更相宜。","画烛催歌板，飞花上舞衣。","殷勤犹劝玉东西。","不道使君肠断、已多时。"]},{"t":"南柯子/南歌子 其三","f":"词","c":["白羽传觞急，金鞍跃马迟。","云间彩凤看双飞。","飞上碧梧枝上、稳双栖。","林下风流女，堂东坦腹儿。","此郎标韵世间稀。","好为伯鸾举案、又齐眉。"]},{"t":"品令 其一 重九前一日，飞卿携酒相过，坐中歌空青送客词，因用其韵。是日淮上贼军退舍","f":"词","c":["西风持酒。","诮不做、愁时候。","机云兄弟，坐中玉树，琼枝高秀。","且莫劝人归去，坐来未久。","甘泉书奏。","报幽障、沈烽后。","明朝重九，茱萸休恼，泪沾襟袖。","怕衰黄花，也解笑人白首。"]},{"t":"品令 其二 九日寓居招提，旅中不复出，步上西庵绝顶，撷黄菊一枝，凄然有感，复作此歌","f":"词","c":["霜蓬零乱。","笑绿鬓、光阴晚。","紫茱时节，小楼长醉，一川平远。","休说龙山佳会，此情不浅。","黄花香满。","记白苎、吴歌软。","如今却向，乱山丛里，一枝重看。","对著西风搔首，为谁肠断。"]},{"t":"五禽言 其四 思归乐","f":"词","c":["山花冥冥山欲雨，杜鹃声酸客无语。","客欲去山边，贼营夜鸣鼓。","谁言杜鹃归去乐，归来处处无城郭。","春日暖，春云薄。","飞来日落还未落，春山相呼亦不恶。"]},{"t":"昭君怨","f":"词","c":["满院融融花气。","红绣一帘垂地。","往事忆年时。","只春知。","风又暖。","花渐满。","人似行云不见。","无计奈离情。","恶销凝。"]},{"t":"洞仙歌","f":"词","c":["江梅吹尽，更幽兰香度。","可惜浓春为谁住。","最嫌他、无数轻薄桃花，推不去，偏守定、东风一处。","病来应怕酒，□眼常醒，老去羞春似无语。","准拟强追随，管领风光，人生只、欢期难预。","纵留得、梨花做寒食，怎吃他朝来，这般风雨。"]},{"t":"点绛唇 其一 西池桃花落尽赋此","f":"词","c":["燕子风高，小桃枝上花无数。","乱溪深处。","满地飞红雨。","唤得春来，又送春归去。","浑无绪。","刘郎前度。","空记来时路。"]},{"t":"点绛唇 其二 内子生日","f":"词","c":["人道长生，算来世上何曾有。","玉尊长倒。","早是人间少。","四十年来，历尽闲烦恼。","如今老。","大家开口。","赢得花前笑。"]},{"t":"贺新郎","f":"词","c":["白首归何晚。","笑一椽、天教付与，楚江南岸。","门外春山晚无数，只有匡庐似染。","但想像、红妆不见。","谁念香山当日事，漫青衫、泪湿人谁管。","歌旧曲，空凄怨。","将军未老身归汉。","算功名、过了唯有，古词尘满。","谁似渊明拚得老，饱看云山万点。","况此老、斜川不远。","终待我他年自，剪黄花、一酹重阳盏。","君为我，休辞劝。"]},{"t":"宴桃源/如梦令 其二","f":"词","c":["林外野塘烟腻。","衣上落梅香细。","瘦马步凌兢，人在乱山丛里。","憔悴。","憔悴。","回望小楼千里。"]},{"t":"宴桃源/如梦令 其三","f":"词","c":["绿尽小池芳草。","门外柳垂春昼。","花上雨廉纤，帘幕燕来时候。","消瘦。","消瘦。","依约粉香襟袖。"]},{"t":"宴桃源/如梦令 其四 与孙祖恭求酴醾","f":"词","c":["旧日酴醾时候。","酒涴粉香襟袖。","老去惜春心，试问孙郎知否。","花瘦。","花瘦。","剪取一枝重嗅。"]},{"t":"宴桃源/如梦令 其一","f":"词","c":["帘幕疏疏风透。","庭下月寒花瘦。","宽尽沈郎衣，方寸不禁僝僽。","难受。","难受。","灯暗月斜时候。"]},{"t":"浣溪沙 其三","f":"七言古诗","c":["无限春情不肯休。","江梅未动使人愁。","东昏觑得玉奴羞。","对酒情怀疑是梦，忆花天气黯如秋。","唤春云梦泽南州。"]},{"t":"浣溪沙 其五","f":"七言古诗","c":["多病嫌秋怕上楼。","苦无情绪懒抬头。","雁来不寄小银钩。","一点离情深似海，万重凄恨黯如秋。","怎生禁得许多愁。"]},{"t":"浣溪沙 其四 和陈相之题烟波图","f":"七言古诗","c":["水上鸣榔不系船。","醉来深闭短篷眠。","潮生潮落自年年。","一尺鲈鱼新活计，半蓑烟雨旧衣冠。","庙堂空有画图看。"]},{"t":"浣溪沙 其七","f":"七言古诗","c":["学画双蛾苦未成。","鬓云新结翠鬟轻。","伴人歌笑已多情。","飞絮乱花闲院宇，舞鸾歌凤小娉婷。","阳关休唱断肠声。"]},{"t":"浣溪沙 其二","f":"七言古诗","c":["欲醉江梅兴未休。","待篘春瓮洗春愁。","不成欢绪却成羞。","天意若教花似雪，客情宁恨鬓如秋。","趁他何逊在扬州。"]},{"t":"浣溪沙 其一 今岁冬温，近腊无雪，而梅殊未放。戏作浣溪沙三叠，以望发奇秀","f":"七言古诗","c":["近腊风光一半休。","南枝未动北枝愁。","嫦娥莫是见人羞。","么凤不传蓬岛信，杜鹃空办鹤林秋。","便须千杖打梁州。"]},{"t":"浣溪沙 其六","f":"七言古诗","c":["醽醁新翻碧玉壶。","水精钗袅绛纱符。","吴姬亲手碎菖蒲。","彩索系时新睡起，榴花剪处要人扶。","心情还似去年无。"]},{"t":"浪淘沙令 其二","f":"词","c":["落日在阑干。","风满晴川。","坐来高浪拥银山。","白鹭欲栖飞不下，却入苍烟。","千里水云寒。","正绕烟鬟。","拍浮须要酒杯宽。","天与吾曹供一醉，不是人间。"]},{"t":"浪淘沙令 其一 己未除夜","f":"词","c":["江上送年归。","还似年时。","屠苏休恨到君迟。","觅得醉乡无事处，莫放愁知。","红灺一灯垂。","应笑人衰。","鹤长凫短怨他谁。","明日江楼春到也，且醉南枝。"]},{"t":"秦楼月/忆秦娥","f":"词","c":["东风歇。","香尘满院花如雪。","花如雪。","看看又是，黄昏时节。","无言独自添香鸭。","相思情绪无人说。","无人说。","照人只有，西楼斜月。"]},{"t":"减字木兰花 其一","f":"词","c":["春闲昼永。","城下江深山倒影。","净扫风埃。","收拾烟光入句来。","短窗闲倚。","身似浮云门似水。","谁伴馀年。","结得青山一个缘。"]},{"t":"减字木兰花 其二 汤词","f":"词","c":["门外青骢月下嘶。","映阶笼烛画帘垂。","一曲阳关声欲尽，不多时。","凤饼未残云脚乳，水沈催注玉花瓷。","忍看捧瓯春笋露，翠鬟低。"]},{"t":"减字木兰花 其四 晁别驾生日","f":"词","c":["当年文伯。","曾是东坡门下客。","文采风流。","奕叶传芳总未休。","为公持酒。","愿祝彩衣无限寿。","归觐枫宸。","剩醉长安几度春。"]},{"t":"减字木兰花 其二 内子生日","f":"词","c":["蓬莱三岛。","上有青青千岁草。","玉佩烟鬟。","来作人间一笑欢。","麻姑行酒。","萼绿华歌清韵袅。","玉秀兰芳。","醉舞东风彩袖长。"]},{"t":"减字木兰花 雨中熟睡","f":"词","c":["快风消暑。","门近雨边梅子树。","昼梦腾腾。","急雨声中唤不醒。","轻衫短箑。","林下日长聊散发。","无计医贫。","长作云山高卧人。"]},{"t":"减字木兰花 其三","f":"词","c":["西山岩桂。","常恨香闻烟雨外。","何似君家。","戏彩堂前早试花。","黄金千粟。","风撼芳条香馥馥。","一剪无多。","桃李漫山奈俗何。"]},{"t":"清平乐 其六","f":"词","c":["东风庭户。","红满桃花树。","准拟踏青南陌路。","双凤绣鞋新做。","秋千月挂黄昏。","画堂深掩朱门。","立尽花阴归去，此时别是销魂。"]},{"t":"清平乐 其一","f":"词","c":["芦州晚净。","雨罢江如镜。","属玉双飞栖不定。","数点晚来烟艇。","梦回满眼凄凉。","一成无奈思量。","舟在绿杨堤下，蝉嘶欲尽斜阳。"]},{"t":"清平乐 其四","f":"词","c":["团栾小树。","天与香无数。","薄艳不禁风日苦。","剩著红油遮护。","移栽未到江南。","香山鼻观先参。","勾引老情偏醉，锦薰笼暖春酣。"]},{"t":"清平乐 其二","f":"词","c":["烟鬟敛翠。","柳下门初闭。","门外一川风细细。","沙上暝禽飞起。","今宵水畔楼边。","风光宛似当年。","月到旧时明处，共谁同倚阑干。"]},{"t":"清平乐 其三","f":"词","c":["青春欲暮。","柳下将飞絮。","月到阶前梅子树。","啼得杜鹃飞去。","人归不掩朱门。","一成过了黄昏。","只有琐窗红蜡，照人犹自销魂。"]},{"t":"清平乐 其五","f":"词","c":["浅妆匀靓。","一点闲心性。","脸上羞红凝不定。","恼乱酒愁花病。","晚来泪揾残霞。","坠鬟小玉钗斜。","细雨一帘春恨，东风满地桃花。"]},{"t":"罗叔共五色线中得玄真子渔父词拟其体仆亦拟作六首 其一","f":"词","c":["好个神仙张志和，平生只是一渔蓑。","和月醉，棹船歌，乐在江湖可奈何。"]},{"t":"罗叔共五色线中得玄真子渔父词拟其体仆亦拟作六首 其六","f":"词","c":["花姑溪上鹭鸶滩，辜负渔竿二十年。","无可载，不抛官，携取全家去不难。"]},{"t":"罗叔共五色线中得玄真子渔父词拟其体仆亦拟作六首 其三","f":"词","c":["解印归来暂结庐，有时同钓水西鱼。","闲着屐，醉骑驴，分明人在辋川图。"]},{"t":"罗叔共五色线中得玄真子渔父词拟其体仆亦拟作六首 其四","f":"词","c":["趁梅寻得水边枝，独棹渔舟却过溪。","人似玉，醉如泥，闲歌五色线中诗。"]},{"t":"罗叔共五色线中得玄真子渔父词拟其体仆亦拟作六首 其五","f":"词","c":["人间何物是穷通，终向烟波作钓翁。","江不动，月横空，漫郎船过小回中。"]},{"t":"罗叔共五色线中得玄真子渔父词拟其体仆亦拟作六首 其二","f":"词","c":["禁中图画访玄真，晚得歌词献紫宸。","天一笑，物皆春，依旧扁舟钓白蘋。"]},{"t":"渔家傲 其一","f":"词","c":["遇坎乘流随分了。","鸡虫得失能多少。","儿辈雌黄堪一笑。","堪一笑。","鹤长凫短从他道。","几度秋风吹梦到。","花姑溪上人空老。","唤取扁舟归去好。","归去好。","孤篷一枕秋江晓。"]},{"t":"渔家傲 其二 往岁阻风长芦，夜半舟中所见如此","f":"词","c":["月黑波翻江浩渺。","扁舟系缆垂杨杪。","渔网横江灯火闹。","红影照。","分明赤壁回惊棹。","风静云收天似扫。","梦疑身在三山岛。","浮世功名何日了。","从醉倒。","柁楼红日千岩晓。"]},{"t":"渔家傲 其四","f":"词","c":["路入云岩山窈窕。","岩花滴露花头小。","香共西风吹得到。","秋欲杪。","天还未放秋容老。","谁道水南花不好。","犹胜金蕊浑如扫。","留取光阴重一笑。","须是早。","黄花更惜重阳帽。"]},{"t":"渔家傲 其三 送李彦恢宰旌德","f":"词","c":["休惜骑鲸人已远。","风流都被仍云占。","腰下锦绦缠宝剑。","光闪焰。","人间莫作牛刀看。","见说河阳花满县。","相邀更约疏狂伴。","幸有小蛮开小燕。","须少款。","玉堂此去知非晚。"]},{"t":"渔家傲 其五 夜饮木芙蓉下","f":"词","c":["月黑天寒花欲睡。","移灯影落清尊里。","唤醒妖红明晚翠。","如有意。","嫣然一笑知谁会。","露湿柔柯红压地。","羞容似替人垂泪。","著意西风吹不起。","空绕砌。","明年花共谁同醉。"]},{"t":"菩萨蛮 其一","f":"词","c":["翠蛾懒画妆痕浅。","香肌得酒花柔软。","粉汗湿吴绫。","玉钗敲枕棱。","鬓丝云御腻。","罗带还重系。","含笑出房栊。","羞随脸上红。"]},{"t":"菩萨蛮 其三 赋疑梅香","f":"词","c":["宝薰拂拂浓如雾。","暗惊梅蕊风前度。","依约似江村。","馀香马上闻。","画桥风雨暮。","零落知无数。","收拾小窗春。","金炉檀炷深。"]},{"t":"菩萨蛮 其二","f":"词","c":["风头不定云来去。","天教月到湖心住。","遥夜一襟愁。","水风浑似秋。","藕花迎露笑。","暗水飞萤照。","渔笛莫频吹。","客愁人不知。"]},{"t":"朝中措 其五","f":"词","c":["黄昏楼阁乱栖鸦。","天末淡微霞。","风里一池杨柳，月边满树梨花。","阳台路远，鱼沈尺素，人在天涯。","想得小窗遥夜，哀弦拨断琵琶。"]},{"t":"朝中措 其四 移桃花作","f":"词","c":["小桃花动著枝浓。","移得伴衰翁。","多谢天公怜我，一时染就轻红。","春光犹在，花枝未老，莫放尊空。","休倚半岩烟树，能消几度东风。"]},{"t":"朝中措 其一 登西湖北高峰作","f":"词","c":["西湖烟尽水溶溶。","一笑与谁同。","多谢湖边霜菊，伴人三见秋风。","两高南北，天教看尽，吴越西东。","趁取老来犹健，登临莫放杯空。"]},{"t":"朝中措 其二 二妙堂落成二十馀年，而庐阜隐然常在有无间，似不肯为老人出也，作长短句以招之","f":"词","c":["大江流处是庐峰。","苍玉照晴空。","何事浅鬟浓黛，却成烟雨溟濛。","如今纵有，云涛万顷，翠巘千重。","传语云间五老，一尊须要君同。"]},{"t":"朝中措 其三","f":"词","c":["雨馀庭院冷萧萧。","帘幕度微飙。","鸟语唤回残梦，春寒勒住花梢。","无憀睡起，新愁黯黯，归路迢迢。","又是夕阳时候，一炉沈水烟销。"]},{"t":"感皇恩 其四 送晁别驾赴朝","f":"词","c":["江上一山横，偶来同住。","山北山南共来去。","今朝何事，目送征鸿轻举。","可堪吹不断，梨花雨。","千里莫厌，重霄云路。","飞下彤庭伴鹓鹭。","紫骝乌帽，看尽章台风絮。","故人应问我，今何处。"]},{"t":"感皇恩 其二 除夜作","f":"词","c":["玉箸点椒花，年华又杪。","绛蜡烧残暗催晓。","小窗醒处，梦断月斜江悄。","故山春欲动，归程杳。","天意不放，人生长少。","富贵应须致身早。","此宵长愿，赢取一尊娱老。","假饶真百岁，能多少。"]},{"t":"感皇恩 其一","f":"词","c":["残月挂征鞍，路长山绕。","独拥寒貂犯霜晓。","水边林下，孤负此生多少。","星星空满鬓，因谁有。","不如办个，短蓑长钓。","唤取轻鸥伴人老。","思量也胜，看人眉头眼脑。","世间浑是梦，何时了。"]},{"t":"感皇恩 其三 竹坡老人步上南冈，得堂基于孤峰绝顶间，喜甚，戏作长短句","f":"词","c":["无事小神仙，世人谁会。","著甚来由自萦系。","人生须是，做些闲中活计。","百年能几许，无多子。","近日谢天，与片闲田地。","作个茅堂待打睡。","酒儿熟也，赢取山中一醉。","人间如意事，只此是。"]},{"t":"感皇恩 其五 送侯彦嘉归彭泽","f":"词","c":["何处是云庵，本来无住。","云共谁来共谁去。","菊篱杯酒，聊为渊明频举。","幅巾应屡湿，斜川雨。","此去常恨，相从无路。","记取孤飞水边鹭。","重来一笑，又是柳飞残絮。","梦魂飞不到，君闲处。"]},{"t":"摊破浣溪沙/山花子 其一 茶词","f":"词","c":["苍璧新敲小凤团。","赤泥开印煮清泉。","醉捧纤纤双玉笋，鹧鸪斑。","雪浪溅翻金缕袖，松风吹醒玉酡颜。","更待微甘回齿颊，且留连。"]},{"t":"满江红","f":"词","c":["寂寂江天，雪又满、晚来风急。","空懊恨、散盐飞絮，未成轻集。","万里长空飞不到，珠帘卷尽还羞入。","问向晚、谁欲画渔莎，寒江立。","天黯淡，催残日。","波浩渺，添寒力。","又何如聊遣，舞衣红湿。","好与月娥临晚砌，莫教先放梅花拆。","便准拟、一醉广寒宫，千山白。"]},{"t":"蓦山溪","f":"词","c":["月眉星眼，阆苑真仙侣。","娇小正笄年，每当筵、愁歌怕舞。","水亭烟树，春去已无踪，桃源路。","知何处。","往事如风絮。","如今闻道，误剪香云缕，闲系小乌纱，更无心、浅匀深注。","三山路杳，终不是人间，知谁与。","吹箫女。","共驾青鸾去。"]},{"t":"虞美人 其二 食瓜有感","f":"词","c":["西园摘处香和露。","洗尽南轩暑。","莫嫌坐上适来蝇。","只恐怕寒、难近玉壶冰。","井花浮翠金盆小。","午梦初回后。","诗翁自是不归来。","不是青门、无地可移栽。"]},{"t":"虞美人 其一 西池见梅作","f":"词","c":["短墙梅粉香初透。","削约寒枝瘦。","恼人知为阿谁开。","还伴冷烟疏雨、做愁媒。","飘零苦恨春情薄。","不管花开落。","小池疏影弄寒沙。","何似玉台鸾镜、对横斜。"]},{"t":"虞美人 其三","f":"词","c":["痴云压地风尘卷。","雪共春寒浅。","山城寒夜不烧灯。","时见竹篱茅舍、两三星。","九衢风里香尘拥。","十载鳌山梦。","如今独自倚冰檐。","落尽短檠红灺、不成眠。"]},{"t":"潇湘夜雨/满庭芳 其四 二妙堂作","f":"词","c":["楚尾江横，斗南山秀，辋川谁画新图。","几时天际，平地出方壶。","应念江南倦客，家何在、飘泊江湖。","天教共，银涛翠壁，相伴老人娱。","长淮，看不尽，风帆落处，天在平芜。","算人间此地，岂是穷途。","好与婆娑尽日，应须待、月到金枢。","山中饮，从教笑我，白首醉模糊。"]},{"t":"潇湘夜雨/满庭芳 其二","f":"词","c":["晓色凝暾，霜痕犹浅，九天春意将回。","隔年花信，先已到江梅。","沈水烟浓如雾，金波满、红袖双垂。","仙翁醉，问春何处，春在玉东西。","瑶台。","人不老，还从东壁，来步天墀。","且细看八砖，花影迟迟。","会见朱颜绿鬓，家长近、咫尺天威。","君知否，天教雨露，常满岁寒枝。"]},{"t":"潇湘夜雨/满庭芳 其三 和潘都曹九日词","f":"词","c":["江绕淮城，云昏楚观，一枝烟笛谁横。","晓风吹帽，霜日照人明。","暗恼潘郎旧恨，应追念、菊老残英。","秋空晚，茱萸细撚，醽醁为谁倾。","人间，真梦境，新愁未了，绿鬓星星。","问明年此会，谁寄幽情。","倚尽一楼残照，何妨更、月到帘旌。","凭阑久，歌君妙曲，谁是米嘉荣。"]},{"t":"潇湘夜雨/满庭芳 其一 濡须对雪","f":"词","c":["楼上寒深，江边雪满，楚台烟霭空濛。","一天飞絮，零乱点孤篷。","似我华颠雪领，浑无定、漂泊孤踪。","空凄黯，江天又晚，风袖倚蒙茸。","吾庐，犹记得，波横素练，玉做寒峰。","更短坡烟竹，声碎玲珑。","拟问山阴旧路，家何在、水远山重。","渔蓑冷，扁舟梦断，灯暗小窗中。"]},{"t":"酹江月/念奴娇 其二 送路使君","f":"词","c":["楚山无尽，看西来新拥，石城双旆。","立马花边金镫暖，遥想元戎小队。","白雪歌成，莫愁去后，往事空千载。","一时吟啸，风流不减前辈。","闻道梦泽南州，日高初睡足，雅宜高会。","老去愁多谁念我，空对云山苍翠。","南雁归时，白头应记得，尊前倾盖。","送君南浦，无情空恨江水。"]},{"t":"酹江月/念奴娇 其一","f":"词","c":["冰轮飞上，正金波翻动，玉壶新绿。","风帽还攲清露滴，凛凛微生寒粟。","白玉楼高，水精帘卷，十里堆琼屋。","千山人静，怒龙声喷蕲竹。","夜久斗落天高，银河还对泻，冷悬双瀑。","此地人间何处有，难买明珠千斛。","弄影人归，锦袍何在，更谁知鸿鹄。","素光如练，满天空挂寒玉。"]},{"t":"蝶恋花","f":"词","c":["天意才晴风又雨。","催得风前，日日吹轻絮。","燕子不飞莺不语。","满庭芳草空无数。","春去可堪人也去。","枝上残红，不忍抬头觑。","假使留春春肯住。","唤谁相伴春同处。"]},{"t":"踏莎行 其三 谢人寄梅花","f":"词","c":["鹊报寒枝，鱼传尺素。","晴香暗与风微度。","故人还寄陇头梅，凭谁为作梅花赋。","柳外朱桥，竹边深坞。","何时却向君家去。","便须倩月与徘徊，无人留得花常住。"]},{"t":"踏莎行 其一 和人赋双鱼花","f":"词","c":["风翠轻翻，雾红深注。","鸳鸯池畔双鱼树。","合欢凤子也多情，飞来连理枝头住。","欲付浓愁，深凭尺素。","戏鱼波上无寻处。","教谁试与问花看，如何寄得香笺去。"]},{"t":"踏莎行 其二","f":"词","c":["燕子归来，梅花又落。","缃桃雨后燕支薄。","眼前先自许多愁，斜阳更在春池阁。","梦里新欢，年时旧约。","日长院静空帘幕。","几回猛待不思量，抬头又是思量著。"]},{"t":"踏莎行 其四","f":"词","c":["情似游丝，人如飞絮，泪珠阁定空相觑。","一溪烟柳万丝垂，无因系得兰舟住。","雁过斜阳，草迷烟渚，如今已是愁无数。","明朝且做莫思量，如何过得今宵去！"]},{"t":"醉落魄/一斛珠 其四","f":"词","c":["云深海阔。","天风吹上黄金阙。","酒醒不记归时节。","三十年来，往事无人说。","浮生正似风中雪。","丹砂岂是神仙诀。","世间生死无休歇。","长伴君闲，只有山中月。"]},{"t":"醉落魄/一斛珠 其一","f":"词","c":["江天云薄。","江头雪似杨花落。","寒灯不管人离索。","照得人来，真个睡不著。","归期已负梅花约。","又还春动空飘泊。","晓寒谁看伊梳掠。","雪满西楼，人在阑干角。"]},{"t":"醉落魄 其三 重午日过石熙明，出侍儿鸳鸯","f":"词","c":["薰风池阁。","小红桥下荷花薄。","沙平水浅山如削。","水上鸳鸯，何处风吹落。","今朝端午新梳掠。","锦丝围腕花柔弱。","人生只有尊前乐。","前度刘郎，莫负重来约。"]},{"t":"醉落魄/一斛珠 其二","f":"词","c":["柳边池阁。","晚来卷地东风恶。","人生不解频行乐。","昨日花开，今日风吹落。","杨花却似人飘泊。","春云更似人情薄。","如今始信从前错。","为个蝇头，轻负青山约。"]},{"t":"鹧鸪天 其四 沈彦述生日","f":"词","c":["名在休文季孟间。","一时风味更萧然。","琼林不逐春风老，安用丹砂巧驻颜。","春入户，酒吹澜。","小桃枝上锦阑斑。","明年欲与君为寿，无路相从入道山。"]},{"t":"鹧鸪天 重九登醉山堂，戏集前人句作鹧鸪天，令官妓歌之，为酒间一笑。前一首，自为之也 其八","f":"词","c":["年少登高意气多。","黄花压帽醉嵯峨。","如今满眼看华发，强捻茱萸奈老何。","千叠岫，万重波。","一时分付与秦娥。","明年身健君休问，且对秋风卷翠螺。"]},{"t":"鹧鸪天 其五 和刘长孺有赠","f":"词","c":["袅袅云梳晓髻堆。","涓涓秋净眼波回。","旧家十二峰前住，偶为襄王下楚台。","闲院静，小桃开。","刘郎前度几回来。","东风易得行云散，花里传觞莫谩催。"]},{"t":"鹧鸪天 其二 七夕","f":"词","c":["乌鹊桥边河汉流。","洗车微雨湿清秋。","相逢不似长相忆，一度相逢一度愁。","云却静，月垂钩。","金针穿得喜回头。","只应人倚阑干处，便似天孙梳洗楼。"]},{"t":"鹧鸪天 其六 和孙子绍菊花词","f":"词","c":["晴日烘帘暖似春。","菊回霜晕浅仍深。","谁知此地栽花手，便是当时嗅蕊人。","秋渺渺，夜沈沈。","一声清唱袅残音。","娇痴应挽香罗比，六幅双裙染郁金。"]},{"t":"鹧鸪天 予少时酷喜小晏词，故其所作，时有似其体制者，此三篇是也。晚年歌之，不甚如人意，聊载于此，为长短句体之助云 其十一","f":"词","c":["楼上缃桃一萼红。","别来开谢几东风。","武陵春尽无人处，犹有刘郎去后踪。","香阁小，翠帘重。","今宵何事偶相逢。","行云又被风吹散，见了依前是梦中。"]},{"t":"鹧鸪天 其一 荆州都倅生日","f":"词","c":["读尽牙签玉轴书。","不知门外有园蔬。","借令未解銮坡去，也合雠书在石渠。","微雨后，小寒初。","满斟长寿碧琳腴。","不须更问荆州路，便上追锋御府车。"]},{"t":"鹧鸪天 其七","f":"词","c":["一点残红欲尽时。","乍凉秋气满屏帏。","梧桐叶上三更雨，叶叶声声是别离。","调宝瑟，拨金猊。","那时同唱鹧鸪词。","如今风雨西楼夜，不听清歌也泪垂。"]},{"t":"鹧鸪天 其一","f":"词","c":["荷气吹凉到枕边。","薄纱如雾亦如烟。","清泉浴后花垂雨，白酒倾时玉满船。","钗欲溜，髻微偏。","却寻霜粉扑香绵。","冰肌近著浑无暑，小扇频摇最可怜。"]},{"t":"鹧鸪天 其三 李彦恢生日","f":"词","c":["尊酒年年乐事多。","古铜犹得几摩挲。","他时人物君须记，玉笋班中李泰和。","烦翠袖，把金荷。","功名馀事且高歌。","新来学得长生诀，写就黄庭不换鹅。"]},{"t":"鹧鸪天 其九","f":"词","c":["终日看山不厌山。","寻思百计不如闲。","何时得到重阳日，醉把茱萸仔细看。","敧醉帽，倚雕阑。","偶然携酒却成欢。","篱边黄菊关心事，触误愁人到酒边。"]},{"t":"鹧鸪天 其十三","f":"词","c":["花褪残红绿满枝。","嫩寒犹透薄罗衣。","池塘雨细双鸳睡，杨柳风轻小燕飞。","人别后，酒醒时。","午窗残梦子规啼。","尊前心事人谁问，花底闲愁春又归。"]},{"t":"鹧鸪天 其十二","f":"词","c":["彩鹢双飞雪浪翻。","楚歌声转绿杨湾。","一川红旆初衔日，两岸朱楼不下帘。","阑倚处，玉垂纤。","白团扇底藕丝衫。","未成密约回秋水，看得羞时隔画檐。"]},{"t":"吹台曲","f":"七言古诗","c":["天门玉钥双龙开，霓旌羽盖天上来。","管弦嘈杂入霄汉，美人侍燕黄金台。","羽觞行酒欢未足，燕姬成行列红玉。","梁王半醉起更衣，夜按玉箫亲度曲。","曲终举袂俱争妍，拜舞樽前称万年。","三山玉女朝群仙，当时弄玉飞上天，至今台下草如烟。"]},{"t":"水调歌头 其一 十月六日于仆为始生之日，戏作此词为林下一笑。世固未有自作生日词者，盖自竹坡老人始也","f":"词","c":["白发三千丈，双鬓不胜垂。","人间忧喜如梦，老矣更何之。","蘧玉行年过了，未必如今俱是，五十九年非。","拟把彭殇梦，分付举痴儿。","君莫羡，客起舞，寿琼卮。","此生但愿，长遣猿鹤共追随。","金印借令如斗，富贵那能长久，不饮竟何为。","莫问蓬莱路，从古少人知。"]},{"t":"湖州","f":"七言古诗","c":["霅溪景物见歌诗，只有当年杜紫微。","沽酒店穿斜巷出，采莲船傍后门归。","翠沾城郭山千点，清蘸楼台水一围。"]},{"t":"次韵次卿林下行歌十首 其二","f":"七言绝句","c":["闻道全家隐鹿门，竹篱茅屋寄江村。","庞公事业无多子，只有平安遗子孙。"]},{"t":"次韵次卿林下行歌十首 其一","f":"七言绝句","c":["风吹苏小门前柳，雨暗罗敷陌上桑。","遥想锦江春色暖，被花恼得少陵狂。"]},{"t":"巫山曲","f":"七言古诗","c":["楚宫夜半旌旗动，晓逐君王猎云梦。","君王醉挽金仆姑，笑射双雕落飞鞚。","霜风猎猎吹白羽，狨鞍下时日未午。","天上台高翠被寒，雨湿烟霏梦神女。","行云飞去不可留，却望阳台无处所。","魂凝睇远烟凄迷，猿啼巫峡东复西。","江边猎火一万炬，貂裘醉拥君王归。","章华千门复万户，侍女焚香迎辇步。","君心谁能念旧恩，忍泪悲啼不成语。","愿寿君王一万年，常向阳台梦云雨。"]},{"t":"五杂俎 其一","f":"词","c":["五杂俎，垄头水。","往复来，玉关骑。","不得已，从士子。"]},{"t":"五杂俎 其二","f":"词","c":["五杂俎，云际翮。","往复来，长安陌。","不得已，千里客。"]},{"t":"五杂俎 其三","f":"词","c":["五杂俎，夜茫茫。","往复来，雁南翔。","不得已，思故乡。"]},{"t":"荔枝香","f":"七言古诗","c":["千秋节当八月五，御楼卷帘看马舞。","黄衫玉带分两行，绣衣宫人击雷鼓。","梨园法曲凄且清，相传犹是隋家声。","宜春北院蛾眉小，初按新声未有名。","侍女焚香跪瑶席，更看真妃作生日。","恰值南方驿使来，旋采风枝露犹湿。","当时盛事人争传，荔枝香曲是新翻。","宫中行乐事亦秘，此曲不许人间闻。","马嵬梦断香尘息，满山荔子无人摘。","却归西内冷如冰，一听遗音泪空滴。"]},{"t":"武溪深","f":"七言古诗","c":["五溪妖蛮盘瓠种，穴狐跳梁恃馀勇。","汉庭老骥闻朔风，两耳如锥四蹄踊。","南方毒雾堕跕鸢，五溪溪深军不前。","健儿六月半病死，欲渡五溪无渡船。","将军誓死心独苦，本为官家诛黠虏。","谁知君侧有谗徒，刚道将军似贾胡。","人生富贵一衰歇，会令薏苡成明珠。","祁连高结卫青冢，文渊藁葬无人送。","至今行客武溪傍，谁为将军一悲恸。"]},{"t":"公无渡河","f":"七言古诗","c":["清江漫漫日夜流，江边无风人自愁。","冯夷击鼓河伯怒，蛟龙掉尾鱼吞舟。","人生一死亦难处，何不相从听媪语。","公无渡河公自苦，人心险过山嵯峨，豺狼当路君奈何。","劝君收泪且勿歌，世间平地多风波。"]},{"t":"饮马长城窟行","f":"词","c":["长安城边边地永，万里沙场地无井。","秦人掘土土作城，城下窟深胡水冷。","汉家将军号都护，西征上陇寒日暮。","野驼跑水无处寻，饮马长城窟边去。","长城窟，古来战死多白骨。","征人半作马下尘，犹向阴山斗驰突。","去时胡天霜雁鸣，归见玉关春草生。","将军功高封列城，斗死伍符无姓名。"]},{"t":"金铜歌","f":"七言古诗","c":["武皇开疆三万里，滇池初穿柏梁起。","更铸仙人承露盘，万岁千秋奉天子。","当时谩说邜金刀，谁知更有当涂高。","铜雀台高阿瞒死，八方才人闹如蚁。","玉井绮栏心未厌，犹取金仙着前殿。","金仙辞汉忆汉主，登车殷勤垂玉箸。","独捧金盘出故宫，回头忍看咸阳树。","魏宫群臣眼亲见，朝着魏冠暮归晋。","可怜长安肉食儿，不如顽铜犹有知。"]},{"t":"日出东南隅行","f":"七言古诗","c":["春风淡荡春云浅，陌上柔桑青宛宛。","青天易雨亦易晴，吴蚕催眠欲成茧。","罗敷采桑南陌头，翠鬟皴鬌光欲流。","罗襦吹香白玉佩，青丝络笼黄金钩。","君王年少如秋水，欲学鸳鸯对飞起。","赠君身上双明珰，结君同生亦同死。","罗敷敛衽前致词，词多慷慨中含悲。","念言夫婿良家子，委身结发为夫妻。","人生匹配各有偶，愿逐狗走随鸡飞。","江水可竭山可移，妾心皎皎君当知。"]},{"t":"乌夜啼","f":"词","c":["黄门急诏下，趣封南郡王。","鸾辂俨且深，班剑列成行。","建以左纛旆，树以羽葆幢。","骨肉厚恩义，门户生辉光。","分封得大国，四境弥土疆。","那知以嫌猜，将身触嗔怒。","徵我还上都，令我不得住。","夺我封侯印，被我五两组。","低头屏气息，对客不敢语。","红窗昏夜灯，白泪堕秋雨。","郁郁两大树，依依近墙宇。","鸦鸦枝上啼，腷腷振两羽。","沉沉夜未央，紞紞方三鼓。","侍儿闻之喜，揽衣中夜起。","起敲斋閤门，秉烛具肴旨。","再拜前致词，灵乌未可鄙。","吾闻乌夜啼，霈泽覃万里。","杲杲方平旦，使者已在门。","官家有诏书，为君敦厚恩。","旧愤知己释，徙封意增勤。","客有鲍书记，当代称能文。","命作啼乌曲，乐府传清芬。","人生欲富贵，生身恨不早。","富贵岂不好，危机亦难蹈。","古来兄弟间，生死在一朝。","煮豆然豆豆叶焦，灵乌莫厌声哓哓。"]},{"t":"上之回","f":"五言古诗","c":["汉宫三十六，复道高崔嵬。","皇情极游豫，警跸北之回。","苍螭挟龙辀，风伯清路埃。","羽卫森戛击，玉舆久徘徊。","青娥绝望幸，故宫秋叶催。","举头望霄汉，白露零玉阶。"]},{"t":"得宝子","f":"七言古诗","c":["蓬莱宫中春草绿，君王无事欢不足。","宜春北院小蛾眉，日日霓裳按新曲。","侍女倾心复尽计，歌舞君前不如意。","今年新得太真妃，从此龙颜不胜喜。","望春楼下纥那歌，枉说扬州古铜器。","梨园乐府两部齐，尽歌乐府新歌词。","君门谁道九重远，岁久欢声闻远夷。","渔阳万骑仓黄入，帐中妃子吞声泣。","当时掌上不忍看，玉骨埋时烟雨湿。","属车尘远空邮亭，邮亭牧竖嗟娉婷。","凌波袜在香未绝，万人争看俱伤情。","一朝持入咸阳市，空得千金贾客惊。"]},{"t":"昭君行","f":"七言古诗","c":["汉宫侍女知几千，争妍取宠俱可怜。","谁知恩爱托画手，黄金买得昭阳眠。","昭君自恃玉颜好，未信光阴镜中老。","不知万里嫁胡儿，憔悴蛾眉葬秋草。","忆得昭君初嫁时，含羞忍泪无人知。","胡天漫漫沙漠远，空抱琵琶说别离。","捐金得宠固可耻，委身胡酋不如死。","世间妍丑何曾分，自古贤愚亦如此。"]},{"t":"乌飞曲","f":"词","c":["江云欲雪江风吹，王敦城头乌夜啼。","云深月暗风转急，惊乌绕树无安枝。","狂风忽来飞不定，夜半无巢何所依。","情知天公有风雨，何不结巢高树栖。","君不见秦氏庭中双桂美，庭乌生雏八九子。","乌生岂不念高飞，托君庭阴飞不起。","那知君家轻薄儿，弹丸脱手两翅垂。","无巢悔不巢巍巍，有巢悔不常高飞，人生祸福难豫期。"]},{"t":"秋兰词","f":"五言古诗","c":["艺兰当九畹，兰生香满路。","纫君身上衣，光明夺缣素。","孤芳一衰歇，凋零湿秋露。","佩服得君子，亦足慰迟暮。","采摘良不辞，新枝忽成故。","向来桃李场，红颜照当户。","纷纷自芳菲，荣枯复谁顾。"]},{"t":"金错刀","f":"五言古诗","c":["美人临晓镜，睡足含春娇。","手持白玉尺，睥睨金错刀。","欲将双綵凤，对飞宫锦袍。","谁知游冶郎，经年事游遨。","但知山上山，不说大刀头。","君看良家子，尽属六郡豪。","一朝著铠甲，万里随炊刁。","家人剪春衫，欲寄道里遥。","缄封望绝塞，蓬首时自搔。","荡子会当归，行人日儦儦。","别去隔生死，不保夕与朝。","寄言楼中妇，清泪且当收。","犹胜作征衣，远寄边城秋。"]},{"t":"湖阴行","f":"七言古诗","c":["石头城南五马渡，一马成龙上天去。","晋家天子再御朝，洛阳胡骑空无数。","当时枉道马与王，高官饱食丰豺狼。","车前已赐兰斑物，江上空馀剑戟场。","日光射天惊贼垒，封豖长蛇梦中起。","仓皇只欲玩遗鞭，谁信龙媒已千里。","黄须有智人岂知，不料将军未死时。","着新脱故真是贼，白犬下齧天应迟。","谁道晋朝公与相，不及金谷园中儿。"]},{"t":"隋渠行","f":"七言古诗","c":["黄榆落尽河水冰，隋渠两岸无人行。","雪花漫天大如掌，北风吹马南人惊。","县官藏冰避炎热，健儿凿冰手流血。","安得身随花石官，当路谁人敢呵喝。","黄流千里冻彻底，舳舻相仍冻衔尾。","天公便合回阳和，桃花水暖流春波。","望春楼上天颜喜，齐声争唱纥那歌。"]},{"t":"长干曲","f":"七言律诗","c":["黄昏明月上朱楼，帘旌射月香雾浮。","画栏垂手楼中女，对月低眉不举头。","人似长干桥下水，一去悠悠几千里。","谩道嫁鸡逐鸡飞，长干夫婿那得知。"]},{"t":"五男父","f":"七言律诗","c":["白头垂垂五男父，一生辛勤立门户。","五男炊白割红鲜，阿翁采薪供五男。","悲风惨惨寒日暮，翁入采山遭猛虎。","猛虎磨牙卧道边，五男持戟谁敢前。"]},{"t":"魔军行","f":"七言古诗","c":["五岭南来山最多，驱军日涉千坡陁。","山中食菜不食肉，十室九家俱事魔。","县官给钱捕魔鬼，八万魔军同日起。","将军新破强虏回，马前班剑如流水。","生斩妖精拔羽幢，传首天庭藁街死。","当时平田作战场，至今遗骼无人藏。","旧居虽在人不见，破屋萧萧围短墙。"]},{"t":"野妇行","f":"七言古诗","c":["新安野妇双鬓垂，红膏涂靥深画眉。","青襜两幅不掩骭，赤脚一双深染泥。","饷耕如宾有翁媪，头戴银冠相媚好。","银冠犹是嫁时妆，马上不知人绝倒。","长年相见无别离，竟死不识愁眉啼。","红颜暗逐春光老，暮栉常随落日低。","秋娘一尺春风髻，下蔡阳城尽风靡。","倾城可爱亦可怜，野妇谁知有西子。"]},{"t":"输粟行","f":"词","c":["天寒村落家家忙，饭牛穫稻催涤场。","燎薪炊黍呼妇子，夜半舂粟输官仓。","大儿担囊小负橐，扫廪倾囷不须恶。","县胥里正不到门，了得官租举家乐。","去年有米不愿馀，今年米白要如珠。","路傍老人拍手笑，尽道官兵嫌米粗。","良农养兵与胡竞，胡骑不来自亡命。","田家终岁负耕縻，十农养得一兵肥。","一兵唱乱千兵随，千家一炬无孑遗。","莫养兵，养兵杀人人不知。"]},{"t":"寒食曲","f":"词","c":["三月江南好春色，买酒家家作寒食。","男呼女唤俱出游，扶路醉归欢乐极。","街头尽日无人行，多在山村少在城。","踏歌赛愿一时了，上冢归来闻笑声。","岂料如今一百五，画戟满城椎战鼓。","子孙半作泉下人，薄酒不浇山上土。","死者已往生者存，随分欢娱各儿女。","烹鱼裹菜当盘飧，花作红妆鸟歌舞。","君不见江南江北多战场，去年白骨无人藏。"]},{"t":"木芙蓉歌","f":"七言古诗","c":["吴江十月霜华浅，秋空无云霜日暖。","芭蕉树暗帘幕垂，木芙蓉开红婉婉。","银床露重梧叶飞，金钱扫地秋兰萎。","无人自对秋风笑，黄菊葵花不同调。","慢绿妖红解醉人，徐娘未老秋娘少。","少年时节欢乐多，红莲影落秋江波。","若耶女儿白如玉，夜半采莲闻棹歌。","惊风吹浪鸳鸯起，回头日月飞梭里。","对花不饮今蹉跎，泪湿秋风当奈何。"]},{"t":"雍门行","f":"七言古诗","c":["忆昔长安昼闭门，胡兵四面如云屯。","嗣皇明圣日月出，尽刬宿蠹清妖氛。","黄门急诏忽夜下，驿骑四出争驰奔。","明朝都人看传首，贺客纵横各持酒。","利剑空膏六贵人，富贵回头信何有。","一身成粉骨成尘，当时近前丞相嗔。","高台曲池已荆棘，援琴谁作雍门吟。"]},{"t":"艨艟行","f":"七言古诗","c":["汉作楼船三百尺，江南父老何曾识。","船头击鼓转红旗，船尾踏车人不知。","君王英略似汉武，要挽江心射蛟弩。","天戈指日殄匈奴，先遣偏舟下江浦。","三年血满秋江红，洞庭摇落悲秋风。","漫山栅水作城寨，逆气不腥河伯宫。","惊涛捲地喷飞雪，艨艟一出千艘空。","将军自驾木城去，莫叹龙骧作阿童。"]},{"t":"五溪道中见群牛蔽野问之容州来感其道里之远乃作短歌以补乐府之阙","f":"七言古诗","c":["淮田一废不复秋，五夫扶犁当一牛。","番兵大入郡不守，青窠未熟官来收。","狐狸昼啸荆棘里，此事最贻廊庙忧。","羽檄徵牛牛蔽野，问言万里来容州。","容州价贱苦易得，四蹄才堪一剑易。","来时草青今草黄，道路既远多死伤。","沙场草浅食不饱，夕阳时见乌衔创。","江北江南几阡陌，几牛能满千家仓。","愿言田父各努力，会见西风禾黍长。","将军官大马亦壮，肯使胡儿窥汉疆。"]},{"t":"黥奴行","f":"七言古诗","c":["山西骁将真黥奴，两斛笑弯金仆姑。","偶然浮云变苍狗，身骑高马称金吾。","胡兵仓黄忽南渡，地黑天昏两龙去。","贼臣僭伪谁适从，将军一呵百官惧。","仗剑前驱趣翠华，路人辟易空回顾。","至今愿返河阳狩，荆棘艰难窘天步。","未悬北阙新头颅，犹带安西旧都护。","前年纵兵肥水头，横尸千里行人愁。","帐前骑士勇如虎，帐下娇娥双脸羞。","藁街流血天忽怒，小儿跳梁健儿舞。","寄语卢龙与范阳，中书相公今尚父，慎勿更如奴跋扈。"]},{"t":"秣陵行","f":"七言古诗","c":["秣陵城门夜不开，城头椎鼓鸣春雷。","绯衣擎火燎民屋，万井一炬飞红埃。","道傍横尸人不识，血流但见秦淮赤。","府中官吏一百人，尽取姓名书罪籍。","元戎被执不得归，贼坐黄堂纵呵斥。","明朝传檄下九州，九州牧伯不敢收。","可笑官军櫜羽箭，环视走卒撄城楼。","将军楼船下巫峡，胆落双旌俱卷甲。","日枭五十三头颅，一战何曾短兵接。","今年新起故将军，灞陵醉尉勿浪嗔。","文致太平武定乱，非渠谁复清风尘。"]},{"t":"射鹿行","f":"七言古诗","c":["白羽红旌绕山麓，争向山南射奔鹿。","猎夫举网常苦辛，谁寝其皮食其肉。","腹中着子初成斑，梅花碎点真珠圆。","双桃压髻玉簪短，去作谁家头上冠。","贵家金多逐时好，尚蹙蛾眉嫌不早。","一皮可直三万钱，竞作苞苴当珍宝。","大者有茸胎有纹，举无遗族如何冤。","玉缨琼弁者谁子，始作此俑知非贤。"]},{"t":"督耨词","f":"七言古诗","c":["十里一候五里置，渡海梯山来万里。","赐入长安卿相家，夜暖金猊香彻髓。","琼香入骨作晓酲，斗帐烧烟隔秋水。","青娥添火窗欲明，红锦薰衣人未起。","梅花不用波律来，零藿何劳香传记。","兰闺半掩春昼长，参差吹竹罗红妆。","令君一去三日香，更遣小儿缝紫囊。","夜来宾客满高堂，谁家有女嫁韩郎。"]},{"t":"汉宫词","f":"七言古诗","c":["汉宫五月多南风，宫槐覆砌花阴浓。","彤庭破晓瑞雾薄，宝槛茙葵迎日红。","池面鸡头青蹙衄，菖蒲有花池水绿。","殿阁风清白日长，五丝结綵献君王。","汉皇年来新受箓，自篆天书辟邪毒。","六宫此日多欢娱，就中何人恩宠殊。","黄金钗横绛囊小，争带君王亲写符。"]},{"t":"竞渡曲","f":"七言古诗","c":["江风猎猎吹红旗，舟人结束誇水嬉。","短衣青帽锦半臂，横波鼓鬣飞鲸鲵。","江潮漫漫江水阔，浪花击碎千堆雪。","画桡擘水挽不回，白羽离弦箭初脱。","岿来醉作踏浪歌，应笑吴儿拜浪婆。","朱楼相映绿阴里，两岸人家欢乐多。","饭筒角黍缠五綵，楚俗至今犹未改。","日暮空歌何在斯，不见三闾憔悴时。"]},{"t":"牛女行","f":"七言古诗","c":["天孙晓织云锦章，跂彼终日成七襄。","含情倚杼长脉脉，灵河南北遥相望。","天风吹衣香冉冉，乌鹊梁成月华浅。","青童侍女骖翔鸾，玉阙琼楼降华幰。","明朝脩渚旷清容，归期苦短欢期远。","昔离今聚自有期，天帝令严何敢违。","犹胜姮娥窃仙药，一入广寒无嫁时。"]},{"t":"双鹄飞行","f":"七言古诗","c":["忆昔江乡遭乱离，两翁避地双鹄飞。","一鹄南翔一鹄北，北鹄堕地南鹄栖。","天长地远去不返，巢倾卵覆令人悲。","去年贼兵初聚党，今岁王师方解围。","舂陵万户才有几，骆谷一家空独归。","归寻故里不知处，白骨支撑满涂路。","城西有屋无人居，城东有地无屋庐。","仿佛相从旧游处，泪栖双睫还欷歔。"]},{"t":"燕衔柏行","f":"七言古诗","c":["双燕何时来瀚海，寄巢脩椽巢不改。","春深巢稳初养雏，双雏引颈仰哺呼。","雄将雌出双雏孤，雏危堕地声呱呱。","雌随雄归见雏泣，主人将雏纳其室。","双雏脱死翅欲开，玄衣素臆去复来。","明年主人开寿燕，画鼓停挝歌舞遍。","双雏傍席争回旋，共衔青柏置樽前。","口不能言对以臆，再拜寿君如柏年。"]},{"t":"石妇行二首 其一","f":"五言古诗","c":["贞妇生江南，少小称丰秾。","委身事良人，相与欢笑同。","良人去不返，两鬓常蓬松。","谓言有膏沐，未识谁为容。","日日上山望，水远山复重。","藁砧竟不来，望望终无穷。","一朝化作石，僵立由天公。","天公表坚贞，令与山始终。","仙衣绣藓晕，宝髻摇花丛。","滔滔日月逝，此石存高峰。","清名阅千古，劲节摩苍穹。","恨无采诗官，作诗颂遗踪。","用之邦国间，庶以消淫风。"]},{"t":"石妇行二首 其二","f":"词","c":["生男有闺房，莫娶青楼倡。","生女事姑嫜，莫嫁游冶郎。","倡家从人无定准，游子一去忘故乡。","山头义妇无人识，踊身上山生死隔。","人将此妇作石看，不信此心元是石。","相从岂复无它人，髧彼两髦真我特。","江流可尽山可平，不尽悠悠千古情。","早知郎去无消息，悔不将身事尾生。"]},{"t":"拟客从远方来","f":"五言古诗","c":["客从远方来，遗我故人书。","故人久别离，一别万里馀。","相望不相见，各在天一隅。","感君慇勤意，字字如明珠。","上陈昔欢乐，次问今何如。","昔别俱少年，老大今苍须。","良时不我与，岁月空踌躇。","馀生如梦寐，尺素徒卷舒。","为我谢故人，远致双鲤鱼。","恨无木瓜篇，报君以琼琚。"]},{"t":"拟青青河畔草","f":"五言古诗","c":["四序相推迁，日月倏已逝。","春风入猗兰，光艳照罗绮。","一朝霜雪至，容华苦憔悴。","佳人惜朱颜，结缡奉君子。","安知远征途，中道成弃置。","昔持鸳鸯锦，裁成合欢被。","今织回文机，中有相思字。","相思日夜切，尺书无雁寄。","谁能知妾心，脉脉含远意。"]},{"t":"拟燕赵多佳人","f":"五言古诗","c":["沙丘有馀风，赵女多跕纚。","燕丹养勇士，后宫出女子。","至今馀倡优，吹弹满都市。","佳人北方来，倾城尽风靡。","妙舞萦纤腰，清歌发皓齿。","一歌四座欢，再歌宾客起。","回眸与目成，哀弦忍重理。","愿为双飞燕，与君共栖止。","人生不行乐，岁月如流水。"]},{"t":"拟梁父吟","f":"五言古诗","c":["驾言方北征，遵彼淮阴路。","悠悠墟落间，中有淮阴墓。","将军蕴奇略，功名照今古。","谈笑下燕齐，北面师降虏。","一朝遭谗诬，衔冤复谁诉。","谁能为此谋，宫中汉家妇。"]},{"t":"拟司马相如琴歌代文君答二首 其一","f":"楚辞体","c":["凤兮凤兮胡不归，胡为四海求其雌。","其室良迩知者谁，邂逅相遇君独知。","彼美人兮伟容仪，愿与君兮相追随，归丹山兮栖高枝。"]},{"t":"拟司马相如琴歌代文君答二首 其二","f":"楚辞体","c":["凤兮凤兮鸣噰噰，雄将飞兮雌将从。","天寒惨惨多悲风，双翮欲举心所同。","山石可凿金可镕，妾心皎皎如日中。"]},{"t":"莫愁歌","f":"七言古诗","c":["莲花深红莲叶绿，平沙月上鸳鸯宿。","青腰三板兰作桡，月下莫愁歌一曲。","移船入花花转深，花深调苦难为音。","江边夜半谁为语，只有婵娟知此心。","露华渐白月渐午，刺舟自觅来时路。","明朝系缆柳边门，却在夜来潮落处。"]},{"t":"拟桃叶团扇歌三首 其一","f":"五言绝句","c":["倚杼织冰纨，殷勤作团扇。","为君惜朱颜，相期日相见。"]},{"t":"拟桃叶团扇歌三首 其二","f":"五言绝句","c":["裁纨作团扇，纤纤如白玉。","岁寒不改姿，持用可郎目。"]},{"t":"拟桃叶团扇歌三首 其三","f":"五言绝句","c":["团扇复团扇，团扇亦已好。","但恐秋风至，弃捐在中道。"]},{"t":"秋闺词","f":"五言古诗","c":["西风动帘幕，蟋蟀鸣高堂。","蔓草湿零露，秋闺知夜长。","佳人掩朱户，背烛解罗裳。","愿言鸳鸯梦，双飞入方塘。","清影横疏棂，奈此明月光。","依依照长夜，炯炯明愁肠。","不恨郎不归，恨月入我床。","披衣复起坐，嚬翠挑残缸。","开缄取素书，解结罗带傍。","一读再三叹，再读泪数行。","终夜不成寝，曙色忽满窗。","虽云有膏沐，谁能理晨妆。"]},{"t":"倡楼词","f":"五言古诗","c":["桃李艳春风，荣华照京洛。","九陌飞香尘，朱楼响弦索。","美人倚脩栏，青娥卷珠箔。","白面谁家郎，巴商载金橐。","大艑何岢峨，系舟楼下泊。","哀弹杂清歌，日日楼中乐。","谓言如江流，偕老有盟约。","一朝买婵娟，蝉鬓轻梳掠。","情从新人欢，恩与旧人薄。","去年与青棠，今年赠芍药。","人生有荣谢，曾不待衰落。","倡女不嫁人，深心失期约。"]},{"t":"霁月谣","f":"七言律诗","c":["江鼍吹浪江水急，雷师鞭鼓旌旗湿。","黑风驾雨霹雳鸣，怒龙拿空半天立。","须臾阴云空四垂，广寒殿冷风披披。","玉觞燕罢王母归，红鸾簇扇香雾飞。"]},{"t":"插秧歌","f":"七言古诗","c":["田中水满风凄凄，青秧没垄村路迷。","家家趁水秧稻畦，共唱俚歌声调齐。","树头幽鸟声剥啄，半雨半晴云漠漠。","五白草斑谁敢闲，农夫饷田翁自作。","去年两经群盗来，妇儿垂泣翁更哀。","蚕丛烧尽不成茧，陵陂宿麦无根荄。","今年插秧忧夏旱，旱得雨时兵复乱。","官军捕贼何时平，处处村村闻鼓声。"]},{"t":"古离别二首 其一","f":"五言古诗","c":["弦断何由续，镜分难再圆。","感君绸缪意，赠我双纹鸳。","百年会有尽，此意终难捐。"]},{"t":"古离别二首 其二","f":"五言古诗","c":["行行重行行，此别深可惜。","临分意难传，欲语泪复滴。","我欲从君游，恨乏双飞翮。"]},{"t":"长短歌","f":"词","c":["砻石磨砖作新垒，角楼亭亭四边起。","谁家一曲长短歌，长安贵人葬蒿里。","东方作矣事若何，口珠腰带黄金多。","墓门重闭子孙泣，树上纸钱空满柯。","君不见胡骑南来相州路，仓皇尚觅韩王墓。","解鞍下马拜墓前，更遣羌兵作调护。","凭谁试问尔何为，定恐当年识吾父。"]},{"t":"壬午秋日观桥刈穫五首 其一","f":"五言古诗","c":["清晨起盥栉，卷箔坐南轩。","红日忽满树，飞鸟相喧翻。","农夫告铚艾，导我之前村。","露晞芒屦滑，地僻秋芜繁。","行行不逾里，委蛇到其门。","父老喜客至，为黍烹鸡豚。","劝我当力穑，醉中多好言。","低头谢父老，我志久已存。","归来三叹息，默诵归田园。"]},{"t":"壬午秋日观桥刈穫五首 其二","f":"五言古诗","c":["交亲不相知，笑我营小筑。","人生如风灯，一灭不容续。","胜负棋一枰，信手安用覆。","与君共此世，百岁但信宿。","进退均有求，要各随所欲。","君轨趋朝市，我履在林麓。","胡为浪相笑，吾计念已熟。","客来不与辨，聊用铭我屋。"]},{"t":"壬午秋日观桥刈穫五首 其三","f":"五言古诗","c":["胡马嘶北风，游子思故乡。","富贵人所羡，危机亦难防。","幕上巢岂安，剑头炊易伤。","乃知三亩耕，此策为最良。","寒士但藜藿，肉食馀膏粱。","脱粟众所食，万钱谁得尝。","终然均一饱，果腹俱徜徉。","饭蔬岂不乐，厚味生祸殃。","以此较得失，岂复无短长。"]},{"t":"壬午秋日观桥刈穫五首 其四","f":"五言古诗","c":["人言秋日短，无事日更长。","篱落既补治，稼穑已涤场。","薄暮有微兴，悠然步东冈。","东冈枣与梨，累累半青黄。","幽菊虽未吐，已含风露香。","风物良可喜，客来有杯觞。","但使常如此，贫贱亦何伤。"]},{"t":"壬午秋日观桥刈穫五首 其五","f":"五言古诗","c":["祠宫昔所筑，古屋栖真灵。","谁知员峤徙，亦叹曲池平。","我即废址北，结茅寄幽情。","高秋肃万籁，彷佛闻箫笙。","夜梦着琼冠，结佩朝玉京。","谈笑悟至理，俯仰了八纮。","安能事香火，餐霞学长生。","明朝日复出，抱耒还躬耕。"]},{"t":"题龙眠画四马图","f":"七言古诗","c":["裕陵神谟与天通，昆崙以西俱凿空。","渥洼初来九夷服，尽得大宛三象龙。","于阗凤脑世未识，但见蹴踏长秋风。","鬼章锦膊惊绝代，更看吐蕃狮子骢。","胡儿肮脏双眼碧，锦鞯错落青丝笼。","最后一匹号雄健，见自往来天仗中。","羽林骑士铁挝肃，鸣珂蹀躞缨垂红。","诸番入贡御闲溢，君王昼坐蓬莱宫。","为临玉陛阅神骏，诏写真形谁最工。","龙眠妙伎非俗画，不数当年老曹霸。","三骢岂是拳毛騧，俶傥权奇颇闲暇。","籋云之姿迣万里，太一来贶天马下。","内人传看十二蹄，一笑微生咫尺威。","自从鼎湖弓剑坠，龙媒上天久不归。","只今空对画图泣，忍听鸟呼金粟堆。"]},{"t":"游麻姑观","f":"五言古诗","c":["清秋禾黍罢，南亩幽事少。","凌晨有佳兴，振策事轻矫。","微踪蹑飞猱，雄眺高木杪。","上有仙子祠，栋宇颇倾挠。","腾虚想云軿，遗像空鸟爪。","黄冠三四辈，生意良草草。","更欲问丹炉，云山遂穷讨。","道人笑不言，此意未遽晓。","但云须趣辕，山静虎出早。","胜践良独难，仙事亦杳渺。","了知世俗人，尘凡隔蓬岛。"]},{"t":"小壶贮江蜡二梅幽绝俱可喜作三绝 其一","f":"七言绝句","c":["遮眼梅花不要多，着人无复奈香何。","月明羞看铜壶影，矮树斜枝忆短坡。"]},{"t":"小壶贮江蜡二梅幽绝俱可喜作三绝 其二","f":"七言绝句","c":["吴娘解滴酥成蕊，天女能融蜡作花。","付与诗人说妍丑，风流二士本同家。"]},{"t":"小壶贮江蜡二梅幽绝俱可喜作三绝 其三","f":"七言绝句","c":["天上姮娥白玉肌，蕊珠宫女郁金衣。","相逢月下浑无语，笑指蓬壶作伴归。"]},{"t":"病中戏作本草诗","f":"词","c":["长空青云昼风卷，雨馀凉生开病眼。","垣衣洗雨绿生光，芍药翻阶红照晚。","幽人却扫惊半夏，独杜衡门心颇远。","提壶劝酒意甚劳，花间伏翼终日号。","大枣如爪安可得，竹叶岂宜空蟹螯。","何当如淮注石斛，天南星移碎红烛。","锦缠更命刘寄奴，回雪香柔体如玉。","人生富贵不早休，乌头成白空自愁。","浩歌自驾木兰去，范蠡实能知远游。","君不见赤车使者将君命，五加皮币不少留。","一朝逐客便当去，王不留行空泪流。","又不见浪荡子长负羁橐，石下长卿无住着。","贾论空高远志孤，屈草初成奇祸作。","何如独活考涧槃，不遇自然同此乐。","嗟余知此解马衔，蜗庐僻在陵阳角。","谁能更朝紫真坛，丹砂岂解驻衰颜。","五色神符亦安用，菖蒲谩说能引年。","玉泉泠泠漱虚壑，独寻鹤虱负朝暄。","故人远引羁旅夕，寒水石畔思清言。","何时从容乃如此，烟蓑去作牵牛子。","平生甘遂丘壑贫，常有忧怀思洗耳。"]},{"t":"道由于潜将游西菩问之路人则云过之已远","f":"五言古诗","c":["人生如落花，随寓皆可喜。","但恐兜罗绵，牵连入荆杞。","我马今未羁，犹堪作幽事。","道逢西菩山，欲问参寥子。","举鞭信蹇驴，褰裳渡流水。","隐约望三山，展转才十里。","吴儿指似侬，但隔一山耳。","涂穷殊可笑，兴尽亦复止。","吾曹坐天阨，万事无不尔。","小者今复然，大者斯已矣。"]},{"t":"越台夜雨","f":"五言律诗","c":["夜暗秦淮雨，灯昏越女祠。","寒窗归梦短，秋枕客情知。","凫雁初何定，鸡虫事亦卑。","明朝江上去，重理钓鱼丝。"]},{"t":"晚游戒珠寺寺王逸少旧宅寺僧秉烛观王右军画像出访鹅墨二池归已三更","f":"五言古诗","c":["悠悠倦徂征，忽忽厌羁旅。","出门复风埃，况乃迫繁暑。","兹游惬初心，突兀见精宇。","高人昔所庐，树木亦奇古。","微风入冠裳，林影散廊庑。","僧窗静无尘，灯火照眉宇。","阅此坦腹姿，须发稀可数。","乐死固不虚，颜色如处女。","平池渺清深，淅沥过新雨。","谁言临池工，至技本天与。","鹅群久已空，团扇复何许。","兴尽且当归，夜半月方吐。"]},{"t":"归云洞","f":"五言古诗","c":["南华老明师，遗像颇清古。","昔为挂空月，今作归云土。","云来初无心，云去定何处。","空馀暗窦泉，翠盎含白乳。","华堂谁复枝，缺甃久未补。","林深自成风，山润疑欲雨。","穷幽眼未餍，曳杖足已苦。","入山无与迎，出山信谁阻。","有客自去来，山僧无一语。"]},{"t":"次韵次卿见寄","f":"七言律诗","c":["此生怀抱向谁开，唯有华颠苦见催。","万事只今浑是梦，寸心堪笑已成灰。","路长安得诗飞去，交浅唯愁雨不来。","此意喜君无冷暖，尺书频寄塞鸿回。"]},{"t":"食瓜二首 其一","f":"五言古诗","c":["酂侯昔微时，刀笔一小吏。","起依日月光，勋业高百世。","道大原不容，功高亦为累。","所以韩彭徒，累累就庖胾。","萧何于是时，身任天下寄。","坐安刘帝心，赖有东陵计。","东陵固明哲，避地有深意。","此物原不凡，世俗岂知味。","此味当自知，未可语儿辈。"]},{"t":"食瓜二首 其二","f":"五言古诗","c":["元和数才子，例指到元白。","香山诋中奄，进寸辄退尺。","元侯躐要涂，崔子实卵翼。","两公贤与愚，何啻白与黑。","二武有直气，诋评恣呵斥。","苍蝇从何来，污我盘中食。","想像怀昔人，抚几三叹息。"]},{"t":"游衡廊山山中有梁武帝杯渡禅师像","f":"七言绝句","c":["瀛渤从来是一沤，何妨飞锡到中州。","解将瓶钵横云海，懒向秦淮障逆流。"]},{"t":"次韵韦深道见寄","f":"七言律诗","c":["不见苏州五字诗，韦郎有句解人颐。","长镵白柄林间事，折角乌巾世外姿。","失马未应无后福，亡羊政恐坐多岐。","人生一笑真难事，白发逢君苦恨迟。"]},{"t":"宿琴高岩二首 其一","f":"五言古诗","c":["琴高古仙人，控鲤飞上天。","丹炉访遗迹，邂逅馀山巅。","石壁削寒玉，万仞凌云烟。","隐雨有石屋，垂钓临平川。","旧闻钓处石，可坐八九筵。","邑宰颇呼客，醉歌日留连。","里胥厌追索，挽石沈深渊。","高秋见涯涘，巨石呈方圆。","斯民不可扰，此理甚坦然。","岂非仙圣居，未易污荤膻。","馀生欣晚遇，想像追真仙。","净绿不敢唾，薄暮聊周旋。"]},{"t":"宿琴高岩二首 其二","f":"五言古诗","c":["长川抱空岩，春水三月深。","有鱼岁一来，琐细如寸针。","网鱼聚乾腊，白艇争分阴。","与人作苞苴，囊纱走权门。","人言投鲙残，成鱼只侵寻。","岂有仙家庖，烹鲜赤刀砧。","又言弃药滓，入水成纤鳞。","仙事亦渺茫，讵可穷本因。","不知谁作古，遗祸今犹存。","杀鱼岁亿万，可易千黄金。","仅令贵公子，醉嚼聊一欣。","世俗自乃尔，仙人亦何心。"]},{"t":"宿隐静作","f":"七言律诗","c":["短策羸骖山路长，松阴十里午风凉。","飞来一水自碧落，屹立五峰丛宝坊。","青鸟也随人听法，老禅聊为客烧香。","泉声绕枕浑如雨，月色满岩疑是霜。"]},{"t":"次韵石端若惠长句","f":"词","c":["仲容无双天下士，草木自应殊臭味。","嵇康似鹤在鸡群，子阳如蛙真井底。","小巫神气惊大巫，一见敛颜羞欲死。","眼无皂白敢妍媸，口有雌黄谁?訾。","借令卷舌终自羞，吾颡峣然宁不泚。","伯仁大腹号空洞，步兵醉语无臧否。","君方二子不啻过，视我当如发蒙耳。","浪将五字比长城，要为庖丁作馀地。","人言政似韩潮州，欲借新声与侯喜。","苍颜槁项日摧颓，回雪流风更雄伟。","乃知愚知本相悬，何啻人间三十里。","我诗颇似西台书，时虽可喜终可鄙。","人言嫫毋不自怜，捧心成颦亦成耻。","少年有意慕黄初，岂料永嘉闻正始。","诗坛新拜少陵侯，颇笑棘门儿子戏。","劝君此语勿浪传，俗物还来败人意。"]},{"t":"次韵端若再惠长句","f":"七言古诗","c":["功名本是儿时事，过是悬知终少味。","向来欲度骅骝前，无命能居百僚底。","未容晚辈识风流，顿遣前贤隔生死。","党狱十年犹未开，谗口嚣嚣苦相訾。","且将皮里著阳秋，敢复眼前分浊泚。","颜之厚矣终自羞，论少卑之人亦否。","路逢俗士呼与言，公独未知其趣耳。","无人为吊楚客魂，谁肯更作将军地。","此心此语只自知，闻君足音惊且喜。","词倾三峡颇壮观，气吞云梦真奇伟。","时从雾豹得一斑，行看飞黄日千里。","如君人物尚淹留，此事宁非肉食鄙。","枘方虽自与凿乖，瓶竭那知是罍耻。","一生恨未识荆州，万事政须咨伯始。","忘形已自到尔汝，论事何妨杂嘲戏。","人生一笑不易得，莫遣征航有归意。"]},{"t":"次韵伯尹赠奇童二绝句 其一","f":"七言绝句","c":["它人有子但豚犬，是家此郎真芝兰。","异时笔底问珠玉，已在只今眉宇间。"]},{"t":"次韵伯尹赠奇童二绝句 其二","f":"七言绝句","c":["昔闻徐卿有二子，今喜卫家称一儿。","只有九方真具眼，固应知是渥洼姿。"]},{"t":"次韵伯尹晚游松林寺","f":"五言古诗","c":["詹侯学古淡，胸次无炎冷。","高情屏嗜好，邃宇极深静。","清心乐幽禅，世外得佳境。","静悟已闻法，踊跃更深省。","应复嗤卫侯，耄期犹自警。","能事两禅师，句法颇清颖。","无谁可悟言，举世我独醒。","故来追若人，两耳静蛙黾。","我生尘埃中，况迫桑榆景。","安得薝卜林，婆娑共清影。","君今富春秋，器业窥魏丙。","兹游慎无厌，流光不俄顷。","恐未免簪缨，问道勤造请。"]},{"t":"次韵韦深道独乐堂十绝 其一","f":"五言绝句","c":["廊庙登元勋，四海歌画一。","群公各交章，君乃卜少室。"]},{"t":"次韵韦深道独乐堂十绝 其二","f":"五言绝句","c":["人生几蜡屐，千古一草堂。","得失了自判，较然不须量。"]},{"t":"次韵韦深道独乐堂十绝 其三","f":"五言绝句","c":["棐几坐永日，岩花动微风。","未知堂中人，此乐谁与同。"]},{"t":"次韵韦深道独乐堂十绝 其四","f":"五言绝句","c":["达人信死生，过眼阅暖冷。","了知梦境中，此味独差永。"]},{"t":"次韵韦深道独乐堂十绝 其五","f":"五言绝句","c":["曩喜韦苏州，有句尽平淡。","只今把君诗，去眼不可暂。"]},{"t":"次韵韦深道独乐堂十绝 其六","f":"五言绝句","c":["鬻钱走京师，我笑员半千。","玉阶求自试，北牖输高眠。"]},{"t":"次韵韦深道独乐堂十绝 其七","f":"五言绝句","c":["闻君开华堂，图书富千古。","应笑碧衣郎，试吏坐蓝缕。"]},{"t":"次韵韦深道独乐堂十绝 其八","f":"五言绝句","c":["爱酒惜杯乾，懒衣愁客至。","世无锦江翁，谁识幽人意。"]},{"t":"次韵韦深道独乐堂十绝 其九","f":"五言绝句","c":["草木各有态，臭味久已分。","愿言兰芷丛，东风佩微薰。"]},{"t":"次韵韦深道独乐堂十绝 其十","f":"五言绝句","c":["跂首望蘅皋，远目聊增明。","相逢定何夕，剧谈到参横。"]},{"t":"病后二首 其一","f":"五言律诗","c":["山有生前约，花留病后开。","得闲如我少，扶步与谁来。","闭户深防客，哦诗稳送杯。","夕阳如有意，催月与徘徊。"]},{"t":"病后二首 其二","f":"五言律诗","c":["病起身还健，凭高喜欲颠。","乱山推不去，一水忽当前。","远碧飞双鹭，平湍落钓船。","自今如不死，馀日尽诗年。"]},{"t":"次韵詹伯尹舒天用和答二首 其一","f":"五言律诗","c":["豫章有奇气，铿然两青萍。","埋光久未识，神焰凌太清。","二子廊庙姿，肯负丘壑情。","会当束冠裳，未可终岩坰。"]},{"t":"次韵詹伯尹舒天用和答二首 其二","f":"五言律诗","c":["我生如眢井，芜秽久不凿。","况此一日别，辄作数日恶。","碧云晚自合，红日丽林薄。","思君在何许，行行绕飞阁。"]},{"t":"白桃","f":"七言律诗","c":["缃桃落尽又春回，雪白桃花最后开。","怪我此生新入眼，问君何处旧移栽。","枝头已暖犹馀雪，江上从今不数梅。","只有玉人宜玉树，翠鬟应近小妆台。"]},{"t":"次韵刘元素","f":"七言律诗","c":["白头烦恼不堪醒，满引休嫌酒趣行。","世事可惊嗟豆落，人生安得俟河清。","旧交倾盖由来久，年少论心苦不情。","谁与寄声刘校尉，肯来同此看春耕。"]},{"t":"次韵黄梦及见寄","f":"七言古诗","c":["长卿未老久倦游，家无斗酒不得州。","平生拙甚屋背鸠，羊头可烂身不侯。","言辄触讳恐转喉，怒逢醉尉常反眸。","庙堂戛击方鸣球，老人行歌聊饭牛。","我贫木奴欠千头，夜长昼短怀百忧。","岩栖谷汲谁与俦，草木黄落空悲秋。","饥鹰小呼即下韝，老顽不受良工锼。","长年憔悴拟四愁，浮生无根同舞沤。","更以外物为赘疣，黄侯皎皎清且修。","怜我南冠如楚囚，落笔衮衮不肯休。","人物眼前无此流，合持五线裨冕旒。","姓名下覆黄金瓯，万里一秣看骅骝。","去年操瑟不见收，闻君欲买吴江舟。","明珠白璧惜暗投，千金价重苦未酬。","感君尺鲤论绸缪，逝将好我那肯魗。","微吟有句亦复搜，敢撼大树看蚍蜉。","元龙气高百尺楼，此而未遇彼则不。","人虽曰畸天乃侔，会当有驲旌林丘。","钓丝未可归沧洲。"]},{"t":"和郑文昌雨中看花之作","f":"词","c":["郑侯好客如郑庄，客常满座酒满觞。","春来洛城被花恼，千金一醉姚家黄。","慇勤置酒急招唤，更来古寺窥红妆。","春风微寒春雨细，秉烛看花花已睡。","春光骀荡与妖妍，夜色侵凌增妩媚。","卧枝不起终无言，脸泪欲垂如有意。","樽中有酒客当歌，我醉欲眠人未起。","君不见春来雨急风屡颠，危芳堕地无馀妍。","扫花恐被落红笑，持杯欲倩何人传。","愁多满怀乐事少，人自惜花天不怜。","烹羊炰羔且为乐，酒酣耳热亦不恶。","明朝有兴却重来，莫遣残红抱青萼。"]},{"t":"题王摩诘画袁邵公卧雪图","f":"五言古诗","c":["东京数人物，矫矫称袁公。","经纶有能事，早岁初未逢。","何许结蓬茅，草树风淅沥。","幽梦寄一椽，暮雪深几尺。","平田已无路，况复知公门。","人言公苦寒，谓死宁当存。","鸣驺入空谷，暖律破寒冱。","岂伊逢异人，天实起僵仆。","汉明号贤主，杖击无名郎。","冤囚我自理，微绪渠当昌。","摩诘亦可人，六幅写奇事。","浩荡怀远图，徘徊有佳思。","炎天挂空壁，一洗毛骨寒。","意岂在冰雪，高风薄云端。"]},{"t":"浴罢书妙严壁","f":"七言绝句","c":["云散香槽客未回，月团重瀹睡馀杯。","小窗斜日无人语，只有松声入梦来。"]},{"t":"杖藜","f":"五言古诗","c":["杖藜款幽步，苑囿粲景物。","汪湾小池间，草树极幽郁。","泼剌跳鱼鸣，聿役科斗出。","高荷为谁芳，清芬苦飘忽。","鹭下复飞去，偃蹇不易屈。","空馀扁舟闲，菱藻互蒙密。","馀生本江湖，幸不困簪绂。","豹席与棕轿，愿此寄清逸。","一水便有馀，焉用跨溟渤。"]},{"t":"秋晚二绝 其一","f":"七言绝句","c":["凉月初欣薄露天，井梧吹叶又凄然。","墙根可笑无名草，依倚秋风翘碧鲜。"]},{"t":"秋晚二绝 其二","f":"七言绝句","c":["月向寒林欲上时，露从秋后已沾衣。","微萤不自知时晚，犹抱馀光照水飞。"]},{"t":"次韵徐南美题赵彦符拳石","f":"五言古诗","c":["翩翩佳公子，逸气凌青云。","戏写苍石姿，遂逼仇池真。","平生三昧手，举世谁与伦。","清诗为披拂，警语良亦神。","一朝入双眼，二妙俱可人。"]},{"t":"次韵南美再赋简仆与王次卿贾善长","f":"五言古诗","c":["交游得二子，淡如秋空云。","长头喜问事，坦腹意自真。","但饱北山蔬，固应嗤阿伦。","句法未得妙，画品如入神。","岂兹一漫士，可并千载人。"]},{"t":"读高帝纪","f":"五言古诗","c":["始皇坑儒生，秦室遂颠覆。","取冠溺其中，何乃踵前躅。","亭长初秦民，秦事鉴已熟。","事有异取舍，安用自窘束。","方从丰沛豪，起逐中原鹿。","君王自神武，将士岂局促。","当时分汉茅，素行甚污辱。","屠沽与刀笔，杂然非一族。","叔孙晚见推，韩彭旋烹戮。","一弛复一张，往往如转轴。","高皇躬独断，此理深照烛。","英风渺何之，遗事空简牍。"]},{"t":"读淮阴传","f":"五言古诗","c":["淮阴一世豪，勋业满天地。","晚节不自全，遗恨在百世。","君臣如父子，焉得置猜忌。","功高良易疑，地大苦难制。","折箠下燕齐，群豪自风靡。","岂有须假王，而可镇齐伪。","祸生固有胎，失在此举尔。","沛公窘荥阳，齐卒尽精锐。","颉颃楚汉间，事若反掌易。","信岂不自王，何乃遣汉使。","帝意自此疑，齐楚终易位。","哙等何足羞，鞅鞅遂失意。","晚路说陈豨，咄嗟甚儿戏。","吕姥何能为，公乃自失志。"]},{"t":"二月二十八日雪晴步上西山亭示天用兄弟二首 其一","f":"五言律诗","c":["山崦犹残雪，人家欲禁烟。","客宁嫌鸟语，晴亦借花妍。","愁色连千里，春风又一年。","亭高莫回首，白发满江天。"]},{"t":"二月二十八日雪晴步上西山亭示天用兄弟二首 其二","f":"五言律诗","c":["晴色牵人出，春风恼不归。","鸟争呼永日，花各醉斜晖。","杖策从谁去，持杯与愿违。","兵戈愁外满，人物眼中稀。"]},{"t":"和人摘茶","f":"七言律诗","c":["结庐闻似辋川家，更趁东风摘露芽。","短梦唤回春正好，枯肠搜尽句方嘉。","酪奴语陋真堪笑，瑞草名高岂复加。","明岁莫教烟雨里，白蔷薇秀小岩花。"]},{"t":"次韵姑溪兴国寺晚眺","f":"七言律诗","c":["禅房花木有残红，此地还因曲径通。","竹影看摇金琐碎，风铃解语玉丁东。","人来白鸟横空处，山在先生倚杖中。","绝唱未酬才已尽，夜灯搔首鬓如蓬。"]},{"t":"钱申仲大夫索四亭诗各赋一首 白云亭","f":"五言古诗","c":["登临思昔人，有意在山麓。","举首瞻孤云，怅怀思宰木。","云亦初何心，意乃自感触。","人生风木念，此念何由足。","忽忽不可留，悠悠空满目。","愿言结斯庐，聊用慰幽独。"]},{"t":"钱申仲大夫索四亭诗各赋一首 芳美亭","f":"五言古诗","c":["春风始用事，天意有反覆。","坐令冰雪姿，吹作锦绣谷。","粲粲玄都花，依依照人目。","花气欲薰人，醉眼眩红绿。","想当瓮头春，颇为客频漉。","慎勿遣红雨，零乱飞满屋。"]},{"t":"钱申仲大夫索四亭诗各赋一首 遂初亭","f":"五言古诗","c":["为贫作漫仕，未必胜陆沈。","冠缨日羁縻，鬓发空侵寻。","昔为云出岫，今作鸟归林。","暮年一丘壑，往往谐初心。","窗明设净几，衣露张鸣琴。","缅怀靖节翁，更赋归来吟。"]},{"t":"钱申仲大夫索四亭诗各赋一首 通惠亭","f":"五言古诗","c":["昔人品淄渑，惠山压东南。","谁知十里隔，通此一勺甘。","初不劳箨龙，漫山走嵌岩。","方池汲清碧，地脉通溶涵。","瓷瓯落飞雪，石鼎鸣风杉。","悬知与佳客，午梦回春酣。"]},{"t":"次卿与余终日坐竹间以何人有酒身无事谁家多竹门可款为韵余得上七字 其一","f":"五言古诗","c":["养痾慕夷旷，避俗蒙讥诃。","用兹结神交，长年与婆娑。","脩篁不见天，万玉方森罗。","隐几张净琴，共鼓南风歌。","人生要行乐，取乐不必多。","傥无一笑适，奈此风月何。"]},{"t":"次卿与余终日坐竹间以何人有酒身无事谁家多竹门可款为韵余得上七字 其二","f":"五言古诗","c":["典午方中否，举世无贤人。","高爵岂不佳，奇祸终相因。","七子各见几，引身良及辰。","至今白眼徒，往往多怒嗔。","愚智不同调，孤高固难群。","自信苟不疑，俗说空纷纷。"]},{"t":"次卿与余终日坐竹间以何人有酒身无事谁家多竹门可款为韵余得上七字 其三","f":"五言古诗","c":["人言不如意，十事常八九。","君看得意人，夺去亦难守。","子云草玄文，覆瓿人不取。","更喜渊明门，春风五杨柳。","当年富贵士，泯默亦何有。","乃知百世下，静者差得久。"]},{"t":"次卿与余终日坐竹间以何人有酒身无事谁家多竹门可款为韵余得上七字 其四","f":"五言古诗","c":["昔年嗜酒人，常恐不到口。","卧瓮宁免贼，窥窦真若狗。","幸兹身无事，家复有名酒。","竹亦不待寻，清阴到窗牖。","长啸风满襟，相劝杯在手。","不知平生欢，重复有兹否。"]},{"t":"次卿与余终日坐竹间以何人有酒身无事谁家多竹门可款为韵余得上七字 其五","f":"五言古诗","c":["人命甚脆弱，百岁良逡巡。","日月不可恃，齿发宁长新。","但恐㰦欠间，二首仍六身。","尘冠急须弹，荷佩便可纫。","愿言同耦耕，永继沮溺尘。","会看此水头，有人行问津。"]},{"t":"次卿与余终日坐竹间以何人有酒身无事谁家多竹门可款为韵余得上七字 其六","f":"五言古诗","c":["子猷爱竹者，起卧与竹俱。","未知有何好，不可一日无。","我亦澹少欲，鸿毛视金珠。","眇观霄壤间，无一可与娱。","眷言此青士，平生有葭莩。","可怜杜中舍，羽林观万夫。"]},{"t":"次卿与余终日坐竹间以何人有酒身无事谁家多竹门可款为韵余得上七字 其七","f":"五言古诗","c":["人生天宇间，动作均有寄。","谁知林下人，亦复有幽事。","短步舒微芳，长吟抽逸思。","有梦烦青奴，无弦须绿绮。","寒日忽满窗，香销人未起。","慎勿唤客来，昏昏败人意。"]},{"t":"次韵伯达大水见怀二绝 其一","f":"七言绝句","c":["雨涨平池绿似淮，半扉春水眼慵开。","无钱得买扁舟去，莫道旧来今不来。"]},{"t":"次韵伯达大水见怀二绝 其二","f":"七言绝句","c":["相望千家信不通，悬知春在雨声中。","蹇驴欲去愁泥滑，安得西飞六尺鸿。"]},{"t":"次韵赵思诚沈彦述春日和答","f":"七言律诗","c":["三千客里贤公子，八咏诗中瘦沈郎。","他日功名垂竹帛，只今歌笑共杯觞。","鸟能娱客时相劝，雨亦怜花不打香。","唤取春来同一醉，天教闲日为君长。"]},{"t":"次韵次卿宴坐烧香二绝 其一","f":"七言绝句","c":["燕堂窗静一帘垂，鹊尾薰浓客未知。","稍忆风流王子晋，月明闲弄玉参差。"]},{"t":"次韵次卿宴坐烧香二绝 其二","f":"七言绝句","c":["薄雾霏霏欲满空，炉烟不动宝薰浓。","莫将俗语讥时辈，更学东京范蔚宗。"]},{"t":"三月二十二日游昭山前一日讷禅师死","f":"五言古诗","c":["今日天色佳，晴光与山秀。","道人邀我出，共访山中旧。","马首转岩阿，佛屋露螭兽。","残花趣春事，白水决崖溜。","山行乱人影，香火各奔辏。","禅师秋月空，遗像孤鹤瘦。","平生三昩句，高压岛与昼。","风吹水成纹，妙语本天就。","莫言鸠摩罗，临死出神咒。"]},{"t":"与松林道人求竹栽","f":"五言古诗","c":["人生殊臭味，不异莸与薰。","岁晚期金兰，矫矫惟此君。","缅怀古招提，脩竹如云屯。","道人淡无与，所居竹为群。","馀阴满窗户，肯惜为我分。","他年蜗牛庐，净几横清芬。","疏疏便可意，霭霭亦足欣。","千亩不足侯，万夫宁是军。","客问有何好，仰屋不必言。","幽径傥可开，迟子日款门。"]},{"t":"次韵李姑溪过王次卿留终日","f":"七言律诗","c":["昔日风流李泰和，暮年流落竟如何。","追随天骥元分路，蹭蹬金銮不上坡。","人物眼高谁睥睨，江山兴在且婆娑。","幅巾倒载归时节，想得扁舟漾月波。"]},{"t":"次韵端叔题余所藏山谷茶诗尾","f":"七言古诗","c":["翰林门生两苍璧，似是天人人不识。","学得黄初五字诗，不作人间万钱食。","晚向江头看药栏，花前一笑聊开颜。","自言千载司玉局，尚记桥山分省宿。","今朝玉乳打团龙，昨夜新诗刻红烛。","我识风流李元礼，人物流中有泾渭。","平生漫刺不浪持，晚得龙门略相似。","诗成袖手初相羊，便识从来锦作肠。","梦回却诵矞云句，彷佛官焙闻馀香。","从今下客牛马走，问字不妨时载酒。"]},{"t":"次韵端叔叠前韵见贻因以为别","f":"七言古诗","c":["夜光分得千金璧，从来有限未省识。","一从韶濩到两耳，三月遂令忘肉食。","高楼同倚百尺栏，江山满眼方怡颜。","先生官冷不坐局，古寺分床雨中宿。","清谈亹亹不断头，几度寒窗拔残烛。","晚岁升堂来问礼，谁遣黄流入清渭。","金华上天朝紫皇，往事空劳公举似。","明日山中归牧羊，九回日断思公肠。","他年华屋傥遂约，笑语尚闻兰芷香。","青丝络马不须走，一杯且饮姑溪酒。"]},{"t":"次韵沈彦述官舍书事二绝 其一","f":"七言绝句","c":["幕中从事最能诗，恐是当年杜牧之。","渠为秋娘方觅句，莫将公事恼痴儿。"]},{"t":"次韵沈彦述官舍书事二绝 其二","f":"七言绝句","c":["晚得休文一解颜，识君曾是画图间。","阳春白雪何由和，句有雌霓诵亦难。"]},{"t":"撷野蔬示小儿","f":"五言古诗","c":["荒村无鸡豚，何以供刀机。","山蔬杂百种，此物含妙理。","幽居有胜事，一笑随稚子。","朝甑饭凫茈，暮鼎羹马齿。","笋包出土肥，蕨芽含露紫。","试采少陵苣，更撷天随杞。","举杯香覆坐，摇喉滑流匕。","悠然理尘策，果腹万事已。","君看金谷楼，步障五十里。","韭齑及豆粥，为具咄嗟耳。","回观奇祸作，一死政坐此。","寄声肉食徒，吾事勿轻鄙。"]},{"t":"题赵侯画沧江远岫图","f":"七言绝句","c":["公子风流绝代无，名高当与大年俱。","自从剪得吴江水，不爱滕王蛱蝶图。"]},{"t":"次韵吴思道赠姑溪道人","f":"七言律诗","c":["残生拟觅山中伴，万事厌从儿辈谈。","笑我携家常作客，羡君买地已成庵。","早将辽海千年梦，换得曹溪一滴甘。","闻与道人新结社，懒云今不是常参。"]},{"t":"次韵次卿携酒见过","f":"七言律诗","c":["睡过花时无好怀，柴门谁闭复谁开。","拟从月夜放舟去，更趁东风携酒来。","须发且休论早白，悲欢正可付残杯。","君无旧雨仍今雨，相见应须日百回。"]},{"t":"送虞伯瞻以宣城尉为上元方田官","f":"七言古诗","c":["曩时人物询石渠，风流文采知诸虞。","老成不见典刑在，定识载行家有书。","此郎胸中有泾渭，不比当年灞陵尉。","可怜汗血名家驹，未有长途试千里。","空鞭赤兔鞬臂弓，射杀穷山赤丸子。","只今廊庙方赓歌，群材并用肩相摩。","将分壤地辨垆㯺，要追禹迹穷岷嶓。","悬知使者欲推毂，岂止朱墨精研磨。","简书可畏君莫厌，会见天边给飞传。","时来富贵亦偶然，且尽十分金潋滟。"]},{"t":"收次卿近书二首 其一","f":"五言律诗","c":["故国春空老，三吴信不通。","客犹如社燕，书或寄宾鸿。","鬓发风埃里，林庐梦寐中。","西归如有意，一笑复谁同。"]},{"t":"收次卿近书二首 其二","f":"五言律诗","c":["白水彭门道，秋风古战场。","人应思故国，楼更在斜阳。","消息凭鱼素，游从问草堂。","兰芽知己茁，何日见诸郎。"]},{"t":"怀旧一首","f":"词","c":["三月既晦，维暮之春。","居我穷巷，门无杂宾。","谁与晤语，千载一人。","歌此好言，以侑清樽。","酌我春醪，载笑载欣。","言念我友，在彼彭门。","江濆之别，于今三年。","夐夐只影，祗复自怜。","素书聿至，式慰我心。","蔚我嘉木，有莺在林。","尚求其友，载好其音。","人而不如，有怀其愔。","何当言归，昔盟是寻。","眷此二老，实为兰金。"]},{"t":"晚霁","f":"五言律诗","c":["翠叶看成幄，浓春唤不回。","愁今连落絮，雨欲到黄梅。","扫地花狼藉，开门燕往来。","晴峰数点出，暝色一禽催。"]},{"t":"过张参军故居曲肱亭旧基在焉山谷老人名亭且有诗所谓邻鸡呼不起拥被听松风者是也","f":"七言律诗","c":["脱手新诗咳唾成，曹刘鲍谢未为能。","少时不厌家如磬，岁晚聊因酒作丞。","天与吾人终淡泊，才如此老不飞腾。","盖棺何物无遗恨，太史知公解曲肱。"]},{"t":"雨馀便有秋意夜闻络纬声甚急","f":"五言古诗","c":["朝来三尺雨，一洒遍原隰。","秋风扫快霁，凉气便相袭。","幽人倚寒窗，睡眼已生涩。","淅沥闻井梧，风枝摆馀湿。","推枕夜未央，牵幌月还入。","凄然裘褐念，感此络纬泣。","嗟我岂不知，索衣寒无及。","家机卧空轴，麻缕无可缉。","殷勤语秋虫，相煎何太急。","谁能太早计，不死会当给。","吾言甚酸寒，不足劳掇拾。","书之示二豪，以当一笑集。"]},{"t":"入秋初种芭蕉","f":"七言绝句","c":["着叶芭蕉三四根，怕秋全似可怜人。","老来安得无馀事，细听维摩说是身。"]},{"t":"中秋无月夜半大雨忽忆去年江楼之会","f":"七言古诗","c":["去年秋半西江口，夜上江楼饮江酒。","欲问青天借玉盘，等得浮云变苍狗。","天风惨澹含清秋，夜色苍茫江水流。","移床傍檐看月出，月未肯出令人愁。","圆芦吹裂客罢语，恐在丹霄复何许。","一声初自耳边来，三更却向楼前去。","人生无定可堪论，东西南北似浮云。","故人吹散天一角，惊鸿零落秋江群。","今年不听鸣江橹，月黑风悲窗绕树。","一杯无酒可浇愁，夜闭蓬门听风雨。"]},{"t":"九日至苏家园","f":"五言古诗","c":["良辰不浪出，坐久无谁言。","闲携老铃去，旋觅登高樽。","悠然理孤策，徐行当华轩。","步穿鼪鼯径，来过鸡犬村。","炊烟起茅庐，衍沃多平原。","翳翳桑柘密，霭霭禾黍繁。","黄童与白叟，相携负朝暄。","我求方寸地，拟设常关门。","谁知南冈底，近有苏家园。","心知淳朴处，可避喧嚣烦。","归来得好语，高意谁当论。","他年刘子骥，定觅桃花源。"]},{"t":"过双庙","f":"七言绝句","c":["巡远功名绝古今，后先俱死只侵寻。","两家子弟犹相訾，百世何由识此心。"]},{"t":"行迈一首","f":"五言古诗","c":["秋山凄无风，木叶寒自萎。","羁客不得归，行迈日靡靡。","瘦马嘶暮涂，忍饥渡寒水。","落日晚更明，栖鸟惊复起。","人生各有求，谁能异生死。","行行重行行，辛苦那得尔。","乱石摧前辀，旋车亦当止。","饥寒苦见驱，临风一长喟。"]},{"t":"暮宿一首","f":"五言古诗","c":["朝行绕山麓，暮宿投孤村。","父老颇见招，落日犹在门。","庖烟不满灶，汲水复抱薪。","为我炊黄粱，一饱裁逡巡。","百金得香醪，湛湛盈清樽。","我虽不解饮，亦足濡我唇。","濯足扪饱腹，燎衣暖馀薰。","原言息劬劳，少浣尘埃昏。","慇勤戒鸣鸡，未用呼晨暾。"]},{"t":"汴堤冬日二首 其一","f":"七言绝句","c":["榆柳风微不动尘，平沙如粉衬车轮。","今年汴上三冬暖，已带长安二月春。"]},{"t":"汴堤冬日二首 其二","f":"七言绝句","c":["当年漫漫雪如尘，古汴重冰欲折轮。","暖日如今著行客，长安三度见青春。"]},{"t":"将出京","f":"五言律诗","c":["老恨愁千斛，饥须粟一囊。","遂成迟去鲁，还作薄游梁。","客思风尘恶，乡音道路长。","何时秣归马，看我理晨装。"]},{"t":"雪后再至菊坡","f":"七言古诗","c":["长安二月春风里，马似游龙车似水。","青鞋久惯踏江沙，黄帽岂堪随马尾。","梁王旧筑黄金台，台荒草满谁复来。","云中羽盖去不反，坡底菊苗寒欲开。","老僧相对话乡井，童子瀹苗分乳杯。","为言诸老有遗迹，细寻石刻摩苍苔。","春风无情固相似，倦客逢春还少味。","篱边踏雪忆故年，渡口呼船梦千里。","人生万事要随缘，到处一身俱偶然。","林间春动有佳兴，更携官焙来同煎。"]},{"t":"寒食滁阳阻雨","f":"七言古诗","c":["去年束书薄游梁，今年下马古滁阳。","滁阳寒食少人出，满城山雨惊淋浪。","闭门客舍颇无事，五白大呼同舍郎。","樽前谁唱醉翁曲，鸟歌花舞催红妆。","竟须薄酒浇永日，肯放羁愁煎客肠。","功名老矣白发出，岁月几何归路长。","江头藉草作寒食，细雨梨花思故乡。","何当秣马候明发，便可一苇横长江。","千村万落鸟呼客，山南岭北花吹香。","仍须戒妇速作黍，会见鹿门归老庞。"]},{"t":"游醉翁亭","f":"七言律诗","c":["醉翁诗里识滁山，蚤岁神游只梦间。","云外浅寒欺短帽，马头深秀得烟鬟。","时携妓女人犹说，倒著接䍦谁与还。","文物风流今扫地，乱泉空绕玉孱颜。"]},{"t":"谢公墩","f":"五言古诗","c":["风流谢文静，世俗未可屈。","但怪东山云，肯为老桓出。","谁知奸雄心，本自畏豪逸。","君看新亭会，此意未易诘。","坦之独何者，手版遂倒执。","烦公挥猬须，谈笑安晋室。","暮年淝水师，逆虏甚窘急。","幅巾棋局间，百万一战袭。","功名亦馀事，聊为儿辈立。","平时诮虚旷，闻此自羞涩。","万古终悠悠，客意颇萧瑟。","忍看西州门，更作羊昙泣。"]},{"t":"卞公祠","f":"五言古诗","c":["卞公古刚者，直节不可挫。","岩岩六龙子，矫矫中兴佐。","可怜谢幼舆，梭飞齿还堕。","志怀不事事，见面辄欲唾。","非关执鄙吝，要欲激疲愞。","茂弘岂驽骀，庙社因迁播。","维公抗剧贼，婴此不测祸。","平生忠义气，临绝不自奈。","愤心握两拳，爪甲穿掌过。","英风渺何之，末路悲坎轲。","高堂风入帷，坏壁尘生坐。","清魂不可招，聊为歌楚些。"]},{"t":"游定林","f":"五言古诗","c":["青山绕招提，危磴迎屐齿。","泉声去悠悠，秀色来亹亹。","定林得幽处，胜践发新喜。","当年手种树，来禽杂青李。","横斜照壁诗，平淡如止水。","尚想扶风帐，横经多士子。","奈此后学徒，发冢用诗礼。","朝回丹青像，暮撤配食簋。","空馀古祠荒，老木寒藤委。","遗像犹便便，念往悲复起。","举似与山僧，山僧岂知此。","日暮归去来，林深足荆杞。"]},{"t":"采石道中示伯尹","f":"七言律诗","c":["飞尽杨花京洛春，又将一舸到江滨。","聊凭浅碧浮烟水，为洗软红随马尘。","紫蟹黄鸡秋渐近，东阡北陌酒将醇。","只今我与君同梦，他日君容我卜邻。"]},{"t":"伯瞻作酒官植竹局中见索鄙句","f":"七言古诗","c":["虞郎种粟秋不收，一生坎轲多穷愁。","有才无命百寮底，人笑猕猴骑土牛。","蚤时脱身隐吴市，晚岁作吏分糟丘。","贵人官高印如斗，君独鸡栖马如狗。","骑曹只可呼马曹，漫仕何人知漫叟。","平生好竹心未阑，小分云岭青檀栾。","横窗尚恐翠露薄，得雨便作秋声寒。","向来曲糵一扫尽，风月已足供蹒跚。","吾门如市心若水，箕坐不知身是官。","念我平生绝韵友，相从久结无情欢。","君当下榻我亦往，风雨对眠听梦残。"]},{"t":"次韵次卿寄李姑溪时欲问舍宛陵","f":"七言律诗","c":["我亦平生愿执鞭，拜公眉宇记当年。","泰和人物真图画，李白风流是列仙。","雪里已无回棹意，文中新有卜居篇。","幅巾还作溪堂梦，何日相从句水边。"]},{"t":"河鲀三绝 其一","f":"七言绝句","c":["水没春江不见沙，河鲀吹絮荻生芽。","平生所欠但一死，可更杯中论镆邪。"]},{"t":"河鲀三绝 其二","f":"七言绝句","c":["钓蓑常恨此盟寒，两岁珍庖屡入盘。","细雨春江从此逝，不应犹弃季鹰官。"]},{"t":"河鲀三绝 其三","f":"七言绝句","c":["一饱欣然下箸馀，庾郎鲑菜复何须。","当时献纳堪怜许，只解区区说䱥鱼。"]},{"t":"戏蛙","f":"七言绝句","c":["梦回闲看绕灯蛾，窗外蛙声两更多。","莫遣盘中种鲑菜，要留水底作笙歌。"]},{"t":"为蛙答","f":"七言绝句","c":["偶作长吟君莫嗔，一泓聊占小池春。","斗升虽未分公廪，青紫犹堪作卖人。"]},{"t":"次韵李子泽过次卿溪堂二首 其一","f":"七言绝句","c":["溪雨廉纤作晚晴，斜川风物唤渊明。","归来定自有新句，醉著乌巾一幅轻。"]},{"t":"次韵李子泽过次卿溪堂二首 其二","f":"七言绝句","c":["时人但数李北海，恶客远过元次山。","笑我不能同一醉，也来溪上看烟鬟。"]},{"t":"次韵次卿穿池得古研","f":"七言律诗","c":["功名到手莫嫌迟，妙琢先分紫玉池。","他日北门当视草，只今南涧且题诗。","人间未忍终埋没，神力应先作护持。","好替青毡成旧物，知君家有宁馨儿。"]},{"t":"次韵次卿鸣琴终日二绝 其一","f":"七言绝句","c":["大音固自元无曲，绿绮何劳更著弦。","此调最高人不会，未知今复为谁传。"]},{"t":"次韵次卿鸣琴终日二绝 其二","f":"七言绝句","c":["平生有味在朱弦，想得清风入指寒。","小阁香消帘不捲，知君不为俗人弹。"]},{"t":"代人赠别二首 其一","f":"七言绝句","c":["缕金歌里越姬羞，红蜡光中翠黛愁。","贪向樽前话离别，不知郎酒十分流。"]},{"t":"代人赠别二首 其二","f":"七言绝句","c":["越奴年纪似罗敷，年纪无多情有馀。","别后此情能记否，好凭北雁寄南书。"]},{"t":"端午日小雨已而复晴","f":"七言律诗","c":["断云飞雨过平川，吹作团栾碧玉天。","酒绿强能开病眼，绦长那解系流年。","闲收艾叶晴窗外，忍对榴花白发边。","细葛香罗天上有，乌纱白簟北窗眠。"]},{"t":"五月七日南堂见杨花","f":"七言绝句","c":["柳深何处可藏鸦，窗绕长廊绿暗纱。","造物惜春知有意，薰风时一度杨花。"]},{"t":"五月八夜月色明甚望麻姑昭亭二山","f":"七言律诗","c":["天高月白夜漫漫，倚杖来看月下山。","老眼直穷烟霭外，诸峰浑在有无间。","翰林耽酒今何处，仙女乘鸾去不还。","天恐两山看未足，故飞明镜照孱颜。"]},{"t":"读林和靖集书其尾","f":"七言律诗","c":["泉石膏肓挽不回，笑看嵩少仕涂开。","暮年封禅无遗藁，平日江湖只钓台。","月自黄昏人已老，鹤无消息客谁来。","吴儿不解高人意，秋菊何当荐一杯。"]},{"t":"六月四日大水","f":"七言律诗","c":["夜雨声喧万壑雷，奔流明日自天来。","深疑瓠子河初决，复讶浮山堰始摧。","水涸成梁真漫尔，山行乘橇信悠哉。","望中何物关诗眼，银海光中碧玉堆。"]},{"t":"潘择之惠合溪芦菔种","f":"七言绝句","c":["庾郎鲑菜只春蔬，新向金城得上酥。","会见银丝堆细缕，酒香橙熟鲙江鲈。"]},{"t":"忻师开小轩秋霜之侧范龙阁名以绝尘要予作诗","f":"七言律诗","c":["虎溪大士轩虽小，龙阁老翁诗更新。","积翠但令常到眼，软红元不解随人。","抗容俗里自得计，望拜马头渠岂嗔。","只好与君供一笑，世间何事可关身。"]},{"t":"次韵刘元亢读白乐天与刘梦得书","f":"五言古诗","c":["香山天下士，直道可事君。","口语作奇祸，后来成积薪。","巨栋虽已捐，白璧原自珍。","百年付春梦，千载期斯人。","可怜肉食子，议者空反唇。","文华一照耀，今古无搢绅。","才高固不世，盛德终少邻。","鹿鹿数馀子，琐琐非公伦。","丰盈与名誉，讵可钟一身。","暮年林壑意，觞咏全天真。","君子与小人，两者自此分。","寄言颜巷徒，勿语伤哉贫。"]},{"t":"五月二十四日避暑东寺折简邀子容不至","f":"五言古诗","c":["凉飙呼不来，恶热苦难避。","城南有佳人，相望隔秋水。","愿言倚琼瑶，相携谢簪履。","花木通禅房，茶瓜供幽事。","君方从簿书，相仍日填委。","咫尺如参商，况乃在千里。","日暮殊未来，清风为谁起。"]},{"t":"次韵元亢见贻","f":"五言古诗","c":["人生如浮云，梦境无真乐。","功名绕床卢，聚散合钱醵。","可怜灯火读，圣处恨未博。","我非金闺彦，敢静玉关柝。","衰年未免俗，万事随猎较。","安得共芳洲，相期采兰若。","眷言平生欢，宁负岁寒约。","唾手可书绅，君意良不薄。"]},{"t":"次韵元亢雨中见寄","f":"五言古诗","c":["穷巷结蜗庐，仅有一席广。","风雨不出门，山林负清赏。","怅怀念幽人，道阻不得往。","瀰漫隔江汉，契阔异霄壤。","清风吹句来，念我作技痒。","安得从君游，此意良惘惘。"]},{"t":"酌明寂泉","f":"五言古诗","c":["脩途缭重冈，病足倦游历。","山根得蒙泉，石盎贮深碧。","亭虚绕朱栏，绿净明水色。","老禅黄檗米，弃置久复忆。","振策望青云，清泉裂崖壁。","至今一掬甘，长饮山中客。","金鼎候松风，苍龙破圆璧。","醉腹浇彭亨，真味付泯默。","何当谋挈瓶，徙倚终日夕。","清甘不可嗽，猿鸟与同吃。","洗我两月尘，烂煮南山石。"]},{"t":"题王定父淑问堂","f":"七言律诗","c":["平生心笑伯州犁，罗织虽工不当威。","莫采黄金铸刑鼎，要令青草入圜扉。","于张必大君须记，六蓼先亡事恐非。","闻说堂成已无讼，卧看庭树转斜晖。"]},{"t":"次韵元素登城暮归二首 其一","f":"七言律诗","c":["天遣刘郎又白头，少年文学似求由。","朱门华毂聊安命，藜杖芒鞋可散忧。","大隐未成聊小隐，浊流谁得寘清流。","赋成准拟吾先读，王粲秋来正倚楼。"]},{"t":"次韵元素登城暮归二首 其二","f":"七言律诗","c":["晚来飞鞚上城头，欲蹑华镳苦末由。","醉里有乡须着屐，人间无地可埋忧。","功名于我真聊尔，人物似君无此流。","想对青天回白鸟，半钩斜月挂江楼。"]},{"t":"中秋月下作","f":"七言古诗","c":["去年城南作中秋，江云遮月烂不收。","幽人独对秋风立，姮娥似隔重云羞。","更长忽听晓鼓急，梦去只有残灯留。","今岁不知身在此，门枕长江风自起。","樽中有酒坐有客，江面如天月如水。","秋风满树凉叶飞，新欢欲尽还成悲。","身其馀几事不偶，老之将至吾今衰。","人生阅世自有数，万事反覆难预知。","何当举酒一再拜，与月更作明年期。"]},{"t":"宿蒋山","f":"五言古诗","c":["薄游践初心，寓宿便晚静。","山空秋有声，人寂夜更永。","华鲸催晓色，有客动深省。","焚香礼大士，杖策上危岭。","黄金明窣堵，妙音生佛境。","眼穷天无尽，地转江万顷。","缅怀梁武帝，问法昔造请。","识师鸟巢中，道契言自领。","会令天龙宫，金碧粲绝顶。","我来脩法供，汲水具乳茗。","愿同桑下留，览胜毕馀景。","还从天际归，悠然理烟艇。"]},{"t":"九日登凤凰台","f":"五言古诗","c":["落木惊高秋，旅食念行役。","含羞古祠花，青蕊未堪摘。","云山不着脚，佳节似可惜。","一啸百尺台，往趁凌风翮。","群山如玉玞，千古围故国。","孤城打寒潮，往事谁记忆。","玉树那得花，金莲去无迹。","兴亡更六朝，溅血几飞镝。","重瞳飞上天，毰毸避矰弋。","何年览德辉，古榜犹可识。","父老无由询，残碑少遗刻。","空馀吊古涕，自对斜阳滴。"]},{"t":"次韵元中芭蕉轩","f":"五言古诗","c":["道人悟无生，开轩有深意。","是身如芭蕉，妙语良默契。","婆娑坐芳丛，聊复此游戏。","秋风鸣环佩，晓露湿苍翠。","闭窗得阴多，凉簟惊雨细。","索句清梦馀，时能助幽思。","我亦个中人，平生会佳致。","此乐倘见分，杖策时一至。"]},{"t":"符川逢次卿遂约同舟","f":"五言古诗","c":["被褐念游客，落帆逢故人。","晚岁风露寒，一笑樽俎春。","馀子岂不佳，数面聊成亲。","平生不漫与，知君意良真。","少日共林壑，剧谈唾冠巾。","皎然两玉壶，不受一点尘。","各以口腹累，老大成参辰。","政坐造物儿，有意相怒嗔。","荏苒时不再，俛仰迹遂陈。","秋风吹前溪，摇荡生碧鳞。","不如载扁舟，相视聊饮醇。","醉听篷底语，共卧南溪垠。"]},{"t":"次韵国师对月见怀","f":"七言律诗","c":["老子关门不著书，奄奄真复似曹蜍。","月来林下苦相忆，诗落眼前欢有馀。","满挹清光归酒面，小分秋色到吾庐。","胸中拍塞愁千斛，特地烦君一扫除。"]},{"t":"寄徐季长","f":"五言古诗","c":["念昔桃始华，别君漳水头。","相别几何时，天事司蓐收。","阙月六度圆，相见间何阔。","百年飞电中，能得几回别。","别君几何时，忆君如饥渴。","饥渴良有时，思君无时节。","野人苦幽独，相值谁与亲。","流落在苍莽，坎轲一伤神。","相望参与商，相隔云与泥。","草木忝臭味，笑谈极相思。","相思一何久，行行重回首。","回首征雁行，中有来书否。"]},{"t":"送王天民归双泉","f":"五言古诗","c":["旧闻双泉居，缥渺在寥廓。","仙人上丛霄，遗甃结飞阁。","广庭三百步，一木可四角。","刀圭分苍虬，鳞鬣自皴错。","至今风雨枝，疑有孤栖鹤。","王郎吹玉箫，飞凫下双屩。","时乘三峰云，来绕月城脚。","人生多乖离，未践绣水约。","知心念独君，时来慰牢落。","我欲从之游，何当解羁缚。"]},{"t":"圩氓叹","f":"五言古诗","c":["圩氓筑败圩，饱腹无粟菽。","强扶南亩犁，辛苦望一熟。","插秧在中田，秋来半黄绿。","白雨忽翻盆，积潦齧圩腹。","波头卷春雷，汹涌裂坤轴。","仓皇未出门，白水已半屋。","攀椽栖木杪，寝饭杂鹅鹜。","客行舣孤舟，系缆怯水宿。","叩门乞灯火，父老迎我哭。","我亦一酸鼻，软语聊抚祝。","老稚且相收，慎勿辄弃逐。","行看散陈红，官仓有馀粟。","救尔无远谋，每饭惭食肉。"]},{"t":"八月二十日种竹八本","f":"七言绝句","c":["东冈新种八龙孙，北岭清阴肯见分。","留取一林听夜雨，莫教千亩僣封君。"]},{"t":"次韵次卿中秋月下书所见","f":"五言律诗","c":["三载彭门梦，新年故国秋。","月当千里共，酒要十分酬。","翠幕知谁卷，双鬟不奈羞。","寒螀莫相恼，啼作晚窗愁。"]},{"t":"题大着肚并引 其一","f":"词","c":["平生颇笑王会稽，坦腹惊动郗家儿。","暮年羞涩为怀祖，计较毫末如儿痴。","嵚?更诮周郎鄙，自说空洞终何为。","达人大观无不可，无盐未必非西施。","了知倚杖清言者，外示夷旷中难窥。","不如此老身如寄，万事模棱真得计。","掉臂行歌眼看天，拥膝长吟腹垂地。","羞遣家奴捧玉环，肯为门生作经笥。","白肥如瓠君莫轻，终年贮酒真酒罂。","结喉道士倘复见，敢托石鼎讥彭亨。"]},{"t":"次韵元杰病中书怀","f":"七言律诗","c":["本来无病是维摩，人说烟霞久卧疴。","独闭衡门春尚在，却携藜杖句还多。","已将名字传三语，懒作悲凄和九歌。","止酒渊明今复饮，便须俗客到无何。"]},{"t":"次韵几圣见贻二首 其一","f":"七言律诗","c":["梅花雪后有残枝，留与幽人照夕晖。","已借水光浮净几，更将山翠染春衣。","回中漫叟移舟去，月下渊明种豆归。","知我短坡无客到，肯携长麈为翁挥。"]},{"t":"次韵几圣见贻二首 其二","f":"七言律诗","c":["坎止流行念已轻，常关虽设是吾扃。","事如痛定何堪说，出为饥驱岂有情。","满座自倾鸲鹆舞，半岩拟作凤凰声。","醉中深意知谁解，付与前身阮步兵。"]},{"t":"李似表雪中置酒席上次韵","f":"五言古诗","c":["东风吹玉尘，十指寒欲堕。","西斋借微温，妙语惊咳唾。","诗成酒行间，一扫飞电过。","坐令止酒陶，酒戒为君破。","但愁飞絮零，似我霜鬓鬌。","他年玉堂人，伴直谁对卧。","恨无屈宋才，共续离骚些。"]},{"t":"次韵元素对雪十韵","f":"五言古诗","c":["云冻风仍急，天低雪未收。","山寒飞鸟绝，江晚一蓑幽。","晓树梅初放，风帘絮自投。","孤鶱迷远鹤，痴立看饥鸥。","枥马归鞍速，韝鹰猎羽遒。","连城理睥睨，千骑冷貔貅。","何处回兰棹，谁人拥钓裘。","闭门怜我病，得句付君搜。","上瑞书三白，登年在九秋。","何当明月夜，同作广寒游。"]},{"t":"甘菊数本旧植之地沮洳湫隘颇有悴色十一月二十三日移植墙下明日小雨数刻欣然便有生意","f":"五言古诗","c":["小草偷微生，崛强沮洳间。","托根倘失所，憔悴无好颜。","嗟哉一大地，宁无尺寸闲。","造物惜不与，无乃亦太悭。","栎社岂不恶，盘错未易刊。","下可百牛蔽，上可星斗干。","此物有远韵，何人悯清孱。","我移东篱栽，往近九畹兰。","天心固有在，生理似可还。","小雨喜霢霂，低枝湿斓斑。","春苗已足采，落英行可餐。","为我制颓龄，使我升飞仙。","物微自有知，报君以长年。"]},{"t":"蜡梅六言三首 其一","f":"词","c":["剪蜡枝横陇月，酿花蜜满蜂房。","谁遣凌寒枝上，中含百和花香。"]},{"t":"蜡梅六言三首 其二","f":"词","c":["云佩风侵玉冷，仙裳雾卷罗黄。","家在蕊珠宫里，衣薰鹊尾炉香。"]},{"t":"蜡梅六言三首 其三","f":"词","c":["桃花占上林簿，兰芷擅离骚经。","欲吊花中遗逸，聊寻世外林坰。"]},{"t":"再赋三首 其一","f":"词","c":["孤根雅宜幽处，空明宛似僧房。","我作蒲团燕坐，时参鼻观清香。"]},{"t":"再赋三首 其二","f":"词","c":["浅俗微嫌菊陋，粗粗不爱葵黄。","花里谁方高韵，人中可比黄香。"]},{"t":"再赋三首 其三","f":"词","c":["移种定从天上，世间那有此香。","白发人应羞看，鹅儿酒可争尝。"]},{"t":"送詹伯尹之大梁","f":"五言古诗","c":["寒风转平林，密雪吹重裘。","游子当北征，朝曦趣行辀。","人生会有别，一诀宁复愁。","念君最少孤，束发勤清脩。","寿母岂不力，白发今满头。","功名唾手事，岁月逝欲流。","长安小车儿，哆口笑土牛。","君才岂不高，逸气横九州。","弊帚已千金，白璧价未酬。","愿言慎行李，去去君勿留。"]},{"t":"次韵何师与梅花二绝示刘凝远 其一","f":"七言绝句","c":["月姊宫前玉树春，杏花菖叶不同村。","多情谁道天无意，先与梅花雨露恩。"]},{"t":"次韵何师与梅花二绝示刘凝远 其二","f":"七言绝句","c":["何人急遣蓬莱使，唤得春回江上村。","谁信广平心已冷，老于花似太无恩。"]},{"t":"文殊老人寄和张宰共赋堂诗要余同作","f":"五言古诗","c":["世无陈太丘，民隐念谁诉。","儿饥不肯乳，咿嘤复谁慕。","殖禄膏妻孥，居官付羁旅。","何心书下考，绝意蹑高步。","张侯名家郎，作吏得奇趣。","提携念疲劳，忧勤急朝暮。","散作千家春，一洗五里雾。","簪缨被馀辉，草木饱朝露。","官闲理朱丝，云静落飞屦。","当期卓子康，扬镳各分路。","飞书恐到来，筑屋宁久住。","诗成梯几间，酬酢语交互。","酒杯方流行，喜甚捷官渡。","歌诗载欢谣，鞭箠息嗔怒。","翰墨良从容，流冗自奔赴。","声今诧父老，名亦借童孺。","觞豆落明珠，万壑疾东注。","宾从俱邹枚，含毫各惊顾。","战须老将鏖，兵思勍敌遇。","主人方燕喜，饮至非草具。","人生俟河清，俯仰有新故。","寄言三不欺，令尹勿轻忤。","民今知己疲，着艾岂胜炷。","锋传固应须，轺车少当驻。","鲁山久寂寞，冠虎宁有数。","苦恨郭林宗，未遇黄叔度。","名尝仰韩老，雅意良默喻。","何当奉周旋，看君琢幽句。","愧无脱手弹，可逐马中兔。","只今钓斜川，临流与谁赋。"]},{"t":"读涪翁黔南诗作","f":"七言律诗","c":["阿香名字本无双，流落真成窜夜郎。","蚤岁浪言肠是锦，只今空复鬓成霜。","名传故国犹惊座，诗入浯川尚满囊。","天为少陵增秀句，故教迁客上瞿塘。"]},{"t":"次韵元亢和邦师喜其归自钱塘","f":"七言律诗","c":["道人青眼为君开，前度刘郎今又来。","白雨饱催湖上句，红妆谁把醉时杯。","篱边采菊山千叠，渡口呼船溪九回。","便恐横翔到蓬阁，试寻林下小徘徊。"]},{"t":"送吕霞卿吕当世弃官而出家今为道士","f":"七言古诗","c":["得钱梦秽官梦尸，等为臭腐焉用为。","世人爱官如爱命，君独弃官如弃泥。","道人胸中少荆棘，一色但种枣与梨。","华名自毁不足取，高位疾颠无乃危。","鱼须忽复入君手，三命循墙急须走。","朝持玉磬诵琅函，夜着黄冠朝北斗。","天上云车久未来，壶中日月空长久。","吴山楚泽两西东，与子一笑殊匆匆。","会当握手五百载，摩挲金狄还相逢。"]},{"t":"赵丞家野堂","f":"五言古诗","c":["近喜崔斯立，新成背郭堂。","傍崖深置屋，唤客小飞觞。","稍遣花经眼，频移竹过墙。","官清公事少，梦熟鸟声长。","藤倚樛枝瘦，芸翻乱叶香。","骑曹休问马，聱叟漫为郎。","丘壑胸中事，乾坤醉处乡。","人间一游戏，出处两俱忘。"]},{"t":"元夕睡起","f":"五言律诗","c":["元夕不复饮，夜寒谁与娱。","人随千骑出，自对一灯孤。","有梦须黄妳，无情问紫姑。","鳌山在天上，回望隔中区。"]},{"t":"次韵元素野步","f":"七言律诗","c":["金堤不复上蹒跚，矍铄何劳强据鞍。","从我泥中甘蠖屈，看他高处作鹏抟。","锦江春色能供醉，濠上游鱼亦可观。","闻有平沙邀晚步，定随明月下林端。"]},{"t":"姑溪书报录近作因寄宣毫越简","f":"七言律诗","c":["五云书札何时得，古锦诗囊久未倾。","急遣能言管城子，仍烦解事楮先生。","饱霜穴兔秋方健，照雪溪藤捣更精。","南雁去时人尚远，双鱼欲到眼先明。"]},{"t":"次韵王次卿喜刘元亢登第","f":"七言律诗","c":["刘郎才思似春闲，文在阿房季孟间。","尽把胸中着云梦，还从笔底看波澜。","我无富贵询唐举，人说科名污次山。","驰马行看归旧物，舞衣先喜慰亲颜。"]},{"t":"奉酬韦深道见寄诗","f":"七言律诗","c":["盖世功名岂不佳，韦郎心事本烟霞。","秋风自老千章木，春雨谁分一部蛙。","夜鹤政愁云出岫，鲈鱼会遣客思家。","从君细意论幽恨，准拟应须到落花。"]},{"t":"韦深道和诗且以书坚扁舟之约仆以禁烟归扫邱墓未暇先寄此诗","f":"七言律诗","c":["阙然不见十年馀，借屋新来共一湖。","已向双鱼逢尺素，更因五字得明珠。","子猷心欲随烟棹，摩诘居应似画图。","会待庞公归上冢，便求奴饭马青刍。"]},{"t":"次韵邦伯达春寒","f":"七言律诗","c":["岭外梅花使已来，江南正月未春回。","顽云放日归蓬牖，残雪将寒入酒杯。","便有社风催燕到，何须羯鼓打花开。","老于春事浑无意，睡起群书正作堆。"]},{"t":"高公墓","f":"五言古诗","c":["高公古遗直，三年立螭头。","载笔有公言，高论肃冕旒。","少年取巍科，妙学穷九流。","晚窥青囊书，穴地生公侯。","当时千载人，继出欧与刘。","如何百年后，零落归山丘。","墓门梗荒棘，长松泣高秋。","佳城定天与，政自非人谋。","我来倚墓木，伴客聊遨游。","斗酒与只鸡，谁为桥公羞。"]},{"t":"次韵章季常题石鱼研屏","f":"词","c":["苍崖百丈悬江滨，江潭下跃吞舟鳞。","戏将双影倒挂崖石上，妙绝始信阳侯神。","短屏谁为琢山骨，与君一障西风尘。","世间百怪那可解，清诗宛转聊穷因。","问谁幻出水底石，掉尾鼓鬣波粼粼。","固应凤咮与龙尾，明窗净几长相亲。","君家机云好兄弟，玉山对峙高嶙峋。","为贫聊试漆园吏，手板拄颊心看云。","要收江湖入几席，钓竿拂水垂风纶。","谁当为我语石鱼，莫爱浪翻月白千顷江镕银。","但愿玉堂常伴直，对此风流千载人。"]},{"t":"次韵何丈即席","f":"七言律诗","c":["春风无力柳嫣然，花欲争春作意妍。","坐上诗成云态度，樽前人斗玉婵娟。","凤箫初暖参差竹，檀板还催大小弦。","恶客正应妨作乐，主人浑似孟公贤。"]},{"t":"次韵子容池亭晚思二首 其一","f":"七言绝句","c":["便到青云尚黑头，有亭莫赋二宜休。","如君岂是池中物，要趁官闲作浪游。"]},{"t":"次韵子容池亭晚思二首 其二","f":"七言绝句","c":["漫叟江湖闲日月，辋川图画小池亭。","谢郎春草有新句，付与老人双眼青。"]},{"t":"次韵次卿林下行歌十首 其三","f":"七言绝句","c":["事向闲中种种休，春来林下兴还幽。","上山双屐与谁着，挂杖百钱时独游。"]},{"t":"次韵次卿林下行歌十首 其四","f":"七言绝句","c":["郡郭东边是草堂，岩花时杂涧花香。","愁从把酒杯中少，日向读书窗下长。"]},{"t":"次韵次卿林下行歌十首 其五","f":"七言绝句","c":["愁多应怪独醒人，心事全凭曲米春。","醉后逢花堪一笑，狂来曳杖却成真。"]},{"t":"次韵次卿林下行歌十首 其六","f":"七言绝句","c":["身世无营策最良，年来幽事不多忙。","饭牛欲起方朝露，种豆才归又夕阳。"]},{"t":"次韵次卿林下行歌十首 其七","f":"七言绝句","c":["卖酒罾鱼只数家，卜邻元在水之涯。","扁舟定自桃源去，斜日红飞两岸花。"]},{"t":"次韵次卿林下行歌十首 其八","f":"七言绝句","c":["人情危甚剑头炊，未可云鹏笑一枝。","冠冕窟中元不到，云山堆里复谁知。"]},{"t":"次韵次卿林下行歌十首 其九","f":"七言绝句","c":["得酒固应聊复饮，有田何苦不亲锄。","客来深巷闻鸡犬，便是渊明归后居。"]},{"t":"次韵次卿林下行歌十首 其十","f":"七言绝句","c":["勃窣蹒跚不上堤，却来林下小徘徊。","已知脩竹有千亩，更为桃花求百栽。"]},{"t":"闻蛙","f":"七言绝句","c":["草合平沟涨绿醅，乱蛙声在古城隈。","何时细雨春风夜，还我西池鼓吹来。"]},{"t":"次韵赵钤饮次卿家时牡丹盛开而仆不及见","f":"七言律诗","c":["扬子草玄仍有居，河间好事复多书。","独来林下相寻处，醉倒花间得句初。","人去不知红烂熳，春残忍看绿扶疏。","明年许作樽前客，准拟篮舆唤阿舒。"]},{"t":"林间烧笋戏作","f":"七言绝句","c":["满山稚子欲翻篱，莫管春风上番时。","来伴野僧参玉版，不知今日已茶毗。"]},{"t":"夜读艾子书其尾","f":"七言律诗","c":["万里投荒海一隅，八年蜑子与同居。","可怜金殿銮坡日，浑在蛮烟瘴雨馀。","奇怪谁书方朔传，滑稽空著子长书。","不知平日经纶意，晚作儿曹一笑娱。"]},{"t":"雨意甚浓方起而止","f":"七言律诗","c":["欲成冻雨又吹残，香稻垂垂不救乾。","谩对醨云讼风伯，还将火伞付炎官。","未容涨绿浮烟艇，且看晴云转玉盘。","谁与天工论赤地，尽倾银汉作波澜。"]},{"t":"次韵赵明叔喜雨不寐","f":"七言律诗","c":["云忽油然雨沛然，黄童白叟尽成颠。","唤晴鸠妇鸣屋角，饱水秧孙明稻田。","御史平冤魂亦喜，弘羊言利死谁怜。","草玄窗下子扬子，凉入孤灯夜不眠。"]},{"t":"送强幼安","f":"五言古诗","c":["慈固必能勇，刚亦能近仁。","内荏色徒厉，定知非仁人。","强公本仁者，笑语生阳春。","散为三年泽，不及千里民。","庬恩出岂弟，雅量含清醇。","应容盗取毡，肯叱吏吐茵。","谁知乃中刚，临难气益振。","前年摄虎符，折冲如有神。","邻封堕贼手，齿寒已亡唇。","孤城危累卵，夜卧寄积薪。","清诗见横槊，高会开重闉。","群奔窜狐鼠，万刃抗一身。","岂但虎渡河，遂使盗入秦。","至今忠义士，不数远与巡。","嗟我挟策子，缪作升堂宾。","忠风激中肠，别语聊重陈。","公议谁能掩，伟绩终难湮。","阴功及黎庶，天语形丝纶。","富贵当自兹，照眼功名新。"]},{"t":"东坡老人居儋耳尝独游城北过溪观闵客草舍偶得一蒻笠戴归妇女小儿皆笑邑犬皆吠吠所怪也六月六日恶热如堕甑中散发南轩偶诵其语忽大风自北来骤雨弥刻","f":"七言律诗","c":["持节休誇海上苏，前身便是牧羊奴。","应嫌朱绂当年梦，故作黄冠一笑娱。","遗迹与公归物外，清风为我袭庭隅。","凭谁唤起王摩诘，画作东坡戴笠图。"]},{"t":"娄黥庵纳凉","f":"七言律诗","c":["娄黥无骨可封王，生事全凭药一囊。","闭户翻经头已白，开门延客酒初尝。","竹从春后知无数，花自山来别有香。","未有数椽容我老，聊分一榻借君凉。"]},{"t":"晚浴崇教寺","f":"五言古诗","c":["闲居谁与游，幸此招提邻。","时乘下泽车，访我物外人。","往往听鱼鼓，相随作朝昏。","斋得饱佛饭，暮浴沾僧巾。","情熟自不厌，无求亦何嗔。","我生束世故，欲解未有因。","愿丏一滴甘，为洗千劫尘。","无冠顾安整，有衣聊自振。","道人小轩窗，池净花色新。","芭蕉过微雨，苍翠争丛筠。","劲节秋益好，柔葩委菅榛。","岂但娱老眼，亦足观是身。","攲眠寄静榻，小休只逡巡。","茶甘犹在口，龛灯已前陈。","日暮行当归，击柝催重闉。"]},{"t":"次韵元杰暑中书事","f":"七言律诗","c":["刘郎家世尽名卿，晚岁怜君尚带经。","道在莫嫌榆历历，诗高何愧草青青。","杜门不出人应笑，与世相违我独醒。","谁与林塘共清夜，绿荷时照两三萤。"]},{"t":"次韵李子泽中秋无月","f":"七言绝句","c":["月在愁云黯淡中，绿樽谁与共秋风。","君家自有人如玉，袅袅停停似楚宫。"]},{"t":"次韵春卿游黄蘖道场","f":"五言古诗","c":["长安多贵人，被服萦宝带。","名字垂鼎彝，功勋压崧岱。","一怀上蔡悲，乐事钟我辈。","知君汗漫游，食蛤据龟背。","若若笑痴儿，洋洋飞大盖。","梯空瞰千山，阅此烟雨态。","小阁亦何有，长松飒微籁。","聊将身世梦，净洗佛祖戒。","行乐要及时，幸此无籍在。","只今况丰年，禾黍已旆旆。","狂风不鸣条，积雨不破块。","赏心失幽期，噬脐有馀悔。","晓猿倘未惊，斯游君勿怪。","便当买薄田，往抱躬耕耒。"]},{"t":"八月二十一日大热夜半微凉","f":"七言律诗","c":["八月大地千里赤，蓐收权轻苦无力。","未许寒蝉饱风露，聊为秋蚊增羽翼。","蒲葵呼扇腕欲摇，絺绤捐衣汗犹滴。","谁遣秋风半夜来，先向高梧寄消息。"]},{"t":"和李似表丞厅梅发用胡士曹韵","f":"七言古诗","c":["江头雪屋知谁家，雪中冷艳空争华。","不知何郎闭东阁，坐看江梅初着花。","谷底春回犹未透，天寒袖薄姿微瘦。","黄昏有月谁复知，举世无花出君右。","人生一月几胡卢，枝犹在手霜满须。","湖边孤坐不饮酒，西湖处士空清臞。","知君不学崔斯立，幅巾漫对枯松株。","铁心虽冷白自胜，金缕醉歌欢岂无。","明朝花在有新句，诗成阿买还当书。"]},{"t":"次韵次卿约寻梅二绝 其一","f":"七言绝句","c":["拟摘寒梢一点春，佩囊无句久生尘。","寻花会得王郎意，应为江梅似玉人。"]},{"t":"次韵次卿约寻梅二绝 其二","f":"七言绝句","c":["想得瑶林玉树春，高标元自出风尘。","殷勤欲共梅花笑，却恐梅花解笑人。"]},{"t":"寄题折将军家忠勇堂","f":"五言古诗","c":["折侯古将家，雄算詟边土。","将军最晚出，骁勇不媚妩。","十年守雁门，飞矢射猛虎。","平生程不识，不作一钱数。","誓言月支胡，唾手端可取。","夜半奏捷书，欢声晓飞舞。","云旗涂黄金，彩错映寰宇。","谈笑开华堂，忠勇揭天语。","功成倘坚壁，镇静古所与。","何当使敌人，开户玩处女。","置酒日高会，缓带击歌鼓。","要令无智名，折冲在樽俎。"]},{"t":"东墙橘将熟催以长句","f":"七言律诗","c":["木奴袅袅半垂墙，故恼幽人苦未忙。","雨细不妨无赖绿，帘疏时与可怜香。","谁将磊落黄金颗，为赋甘酸白雪囊。","只有天公真解事，便须先借满林霜。"]},{"t":"夜宿东寺雪作寒甚","f":"五言律诗","c":["古寺初投箠，荒陴已授更。","雪飞穿幕片，风作撼窗声。","今日招提境，当年敌骑营。","可怜王处仲，江上筑孤城。"]},{"t":"哭普儿","f":"五言古诗","c":["胸中欠梨枣，种此无明根。","造物初戏剧，忧伤裂心肝。","夺我破壳雏，长鸣犹未翰。","况乃渥洼种，堕地已足观。","此理竟莫晓，老泪空阑干。","端如卜子夏，泪尽双眼眢。","母哭不忍听，听之鼻辛酸。","人言有子尔，欲遣吾心宽。","有生无短长，视死同一叹。","晓人当如是，自晓终为难。","究竟无奈何，哀哉亦何言。","安得大灵龟，骑云款天门。"]},{"t":"次韵答子容三首 其一","f":"五言古诗","c":["载酒念畴昔，幽寻日相过。","十年登鬼录，奄冉今已多。","旧盟难重寻，俗子终殊科。","只今惊大巫，为我驱妖魔。","但恐费推挽，劳君戒蹉跎。","愿随翩翩子，徙倚南山阿。"]},{"t":"次韵答子容三首 其二","f":"五言古诗","c":["老懒不出门，泯默抱穷独。","赖此千载人，洗我双病目。","公思如悬河，倾泻归四渎。","我如眢井泉，凿地日不足。","幸分一滴甘，濡此将槁木。","行当奉周旋，归囊粲珠玉。"]},{"t":"次韵答子容三首 其三","f":"五言古诗","c":["故交天一涯，涂路困脩阻。","新交同一邦，对面日晤语。","知君相知心，政在亹亹处。","朝屐穷幽深，夜床同晓雨。","似闻跫然音，振翮便轻举。","俗物多败人，公其勿轻许。"]},{"t":"次韵苏如圭乞猫","f":"五言古诗","c":["苏侯家四壁，每饭歌权舆。","庾郎鲑菜盘，三韭罗春蔬。","饥鼠窜旁舍，不复劳驱除。","何为走老黥，贯鱼乞狸奴。","颇知红锦囊，万卷家多书。","我时醉着帽，过子城南居。","手擎乌丝栏，棐几自卷舒。","寒具久不设，趸尾亦足娱。","犹恐遭咬齧，备豫须不虞。","狸奴当努力，鼠辈勤诛锄。","无为幸一饱，高卧依寒垆。"]},{"t":"食蛤蜊一首","f":"七言古诗","c":["旧闻若士升中天，俗眼未识乌鸢肩。","据龟食蛤结汗漫，卢敖尚肯游人间。","高谈谩骂沈昭略，坐视元长嗤稚弱。","更言且共食蛤蜊，忿气难平两讥谑。","下临无地高无天，更作儿女争媸妍。","平生我亦笑二子，岂知真味含芳鲜。","何如结屋清江曲，风雨关门酒初熟。","自烹折鼎吹湿薪，笑倚胡床摩醉腹。","但愿年年对蛤蜊，一杯荐我梨花玉。"]},{"t":"演师跳珠泉","f":"词","c":["阿?事穷奢，供亿在寰宇。","云锦张风帆，明珠溅飞雨。","须臾就变灭，庆吊只仰俯。","何如西山泉，迸石互吞吐。","寻源上层巅，流脉下深坞。","散作跳空珠，累累不堪数。","虽无千金赏，玉漱罗堂庑。","道人得摩尼，夜光还合浦。","不知方外士，得失两安取。","此意谁复知，寒流自千古。"]},{"t":"琼师苍筤轩","f":"五言古诗","c":["绝境渺天末，招提入云端。","汪湾一溪水，似与山屈盘。","僧房各上下，处处闻惊湍。","道人更幽独，开窗对檀栾。","细雨洗轻碧，微风生暮寒。","云梢自袅袅，玉佩时珊珊。","繄我绝韵友，久结无情欢。","相逢如故人，弃置良独难。","婆娑弄清影，夕阳殊未残。","何当分清阴，与子同考槃。"]},{"t":"蜡梅一首","f":"五言古诗","c":["彼美青楼倡，颜色岂不好。","春风桃李花，过雨堪一扫。","粲粲星冠女，云宫在三岛。","雾帔卷黄罗，披风出云表。","焚香礼夜坛，香雾生杳渺。","恨无脂粉颜，千金聘袅袅。","刘郎竟不来，含嚬弄清晓。","谁怜傲霜枝，照眼自明瞭。","永怀蕊宫姿，微黄淡飞标。","清蟾耿寒枝，与月自相恼。","真赏久未逢，残英惜空老。"]},{"t":"次韵雷飞卿雪中掉小舟见过","f":"七言律诗","c":["别时江上草离离，相见寒枝欲放梅。","目送征鸿天外去，梦惊烟棹雪中来。","青云谁料未十里，白发政须同一杯。","老日相逢能有几，春花欲动莫先回。"]},{"t":"次韵似表谢胡士曹分梅花","f":"七言古诗","c":["李侯自以诗名家，诗成与月争霜华。","谁将尤物调韵语，拄笏骑曹分好花。","花寒力浅香微透，恼乱诗翁作诗瘦。","对花欲作楚狂颠，草赋谁居广平右。","但愁急管吹羌胡，便应买酒烦长须。","参横想见绿衣舞，月中笑语花微臞。","天香艳艳与谁好，君家兄弟元三株。","明日新诗入花萼，人间此事应久无。","可怜多病闭门叟，对月痴坐空中书。"]},{"t":"雪中过庆老方丈","f":"七言律诗","c":["云满江天雪意酣，拥炉聊复听巴谈。","老人不出真藏六，来客何劳说后三。","已借团蒲摇短梦，更浇春饼荐馀甘。","此生试向闲中看，何止人间七不堪。"]},{"t":"次韵答春卿寻梅","f":"七言古诗","c":["霜梅槁立清江濆，谁当为挽归来魂。","青鞋醉踏江沙路，玉蕤簪帽惊王孙。","临风想见花有语，此郎词赋如文园。","花开无情落亦易，闻香当款知谁门。","怕看落地白雪满，便恐缀枝青子繁。","温风明月不易得，绕树莫放花黄昏。","知君共醉有佳客，此意归来谁与论。","烦君与问花无恙，尚堪一笑同清樽。"]},{"t":"饮沈都曹家梅花下","f":"七言古诗","c":["去年夜走山百盘，山中飞雪朝漫漫。","不知春向梦中尽，更有梅花醉后看。","今年冬温寒力软，春入梅梢已堪剪。","插花重饮故人樽，犹得一枝供细撚。","岂知丛棘避戈鋋，还对粉香惊婉娈。","花前楚客狂欲颠，月下吴牛空自喘。","明年尚恐贼连营，零落肯教花满眼。","只今犹可醉馀香，杯行到君莫嫌满。"]},{"t":"次韵舒天用元夕观灯喜甚成诗二首 其一","f":"七言律诗","c":["河陜妖氛渐欲平，不应戎马尚连营。","声传万井灯花丽，月到中天夜气清。","烂醉且须游阆苑，论功终合拟长城。","归来袖手无人识，唤作风流阮步兵。"]},{"t":"次韵舒天用元夕观灯喜甚成诗二首 其二","f":"七言律诗","c":["乐事悠悠不系情，生涯狗苟复蝇营。","嫌渠灯烛红纱乱，为我歌词白雪清。","岂料脱身归故国，可怜行乐记王城。","开元盛事元如许，何日中原不用兵。"]},{"t":"次韵元司理元夜三绝 其一","f":"七言绝句","c":["火龙衔烛御城游，喜入升平四百州。","惆怅长安今夜月，为谁重上汉宫楼。"]},{"t":"次韵元司理元夜三绝 其二","f":"七言绝句","c":["忆得葆真池上春，水晶帘底看灯人。","当年京洛随车客，今夜江湖卧病身。"]},{"t":"次韵元司理元夜三绝 其三","f":"七言绝句","c":["花落残缸睡味酣，九霄谁正梦传柑。","百千灯满虚空界，半夜回光独闭庵。"]},{"t":"次韵同舒天用和元侯三绝 其一","f":"七言绝句","c":["舒郎人物是清流，不解蒲萄得一州。","郡守无灯亦行乐，也随宾客上江楼。"]},{"t":"次韵同舒天用和元侯三绝 其二","f":"七言绝句","c":["乱离灯火不成春，月下归时有几人。","我老尚堪陪一笑，世间无似此闲身。"]},{"t":"次韵同舒天用和元侯三绝 其三","f":"七言绝句","c":["游骑归来尚半酣，一杯谁与瓮头柑。","小窗梦断龛灯在，影落疏梅月上庵。"]},{"t":"菖蒲山子歌","f":"楚辞体","c":["南人生长在山间，家家有窗窗有山。","吴峰楚峤不知数，但见云埋雨洗堆烟鬟。","谁知长安绮纨子，一拳何处镵云根。","阳侯疏凿出岩穴，上有斓斑皱藓纹。","下有千岁不死瑶草苍须繁，痴儿持此矜王孙。","朝携磈礧登朱门，暮拥红旌辞帝阍。","开元承平二十年，四边无警不控弦。","绣衣半是花鸟使，达官避路谁敢言。","大艑岢峨春浪碧，处处争看太湖石。","天心不肯乾太湖，八州万口空嗟吁。","累石作山齐华岳，千峰万峦撑碧落。","樛龙夭矫揽云雨，彷佛去天无一握。","锦帆东下飞龙舟，咸阳苑籞空萧索。","杜陵野老哀江头，菖蒲之山兮谁尔留。"]},{"t":"次韵罗仲共山村题咏十首 其一","f":"五言绝句","c":["晏坐销长日，禅心薰妙香。","已成三折臂，安用九回肠。"]},{"t":"次韵罗仲共山村题咏十首 其二","f":"五言绝句","c":["花片风前落，江流雨后浑。","少陵新得句，应似浣花村。"]},{"t":"次韵罗仲共山村题咏十首 其三","f":"五言绝句","c":["丧乱何时定，江村愁杀人。","日长空有睡，花在不成春。"]},{"t":"次韵罗仲共山村题咏十首 其四","f":"五言绝句","c":["老去家无定，名高席未前。","如君尚穷约，谁与问苍天。"]},{"t":"次韵罗仲共山村题咏十首 其五","f":"五言绝句","c":["避地成真隐，依山结草庐。","此身无籍在，随寓即成居。"]},{"t":"次韵罗仲共山村题咏十首 其六","f":"五言绝句","c":["北阙书难上，南方贼未诛。","诸公在廊庙，谁与问唐虞。"]},{"t":"次韵罗仲共山村题咏十首 其七","f":"五言绝句","c":["欲问濯潭路，悬知隔数村。","晓来茅屋梦，相对饱朝暄。"]},{"t":"次韵罗仲共山村题咏十首 其八","f":"五言绝句","c":["有醉销千日，无诗学四愁。","几因君得句，技痒不能休。"]},{"t":"次韵罗仲共山村题咏十首 其九","f":"五言绝句","c":["塞北兵戈满，竹西歌吹空。","何堪故乡梦，真在白头中。"]},{"t":"次韵罗仲共山村题咏十首 其十","f":"五言绝句","c":["两国兵难解，三春花自飞。","愁因春鸟唤，心逐暮鸿归。"]},{"t":"次韵草堂主人雨中十首 其一","f":"七言绝句","c":["反锁衡门谁复开，草堂殊不见兵埃。","雄风斜卷云头去，雌霓横遮雨脚回。"]},{"t":"次韵草堂主人雨中十首 其二","f":"七言绝句","c":["有家怜我无乡地，好事知君不世情。","借得小窗安净榻，卧听风雨入荷声。"]},{"t":"次韵草堂主人雨中十首 其三","f":"七言绝句","c":["虎头山下元无路，龙骨溪边尚有窗。","风里荷花吹不倒，雨中鸂鶒自成双。"]},{"t":"次韵草堂主人雨中十首 其四","f":"七言绝句","c":["少年结客不思家，酒涴春衫白苧麻。","今日江村烟雨里，兵戈满地鬓双华。"]},{"t":"次韵草堂主人雨中十首 其五","f":"七言绝句","c":["满溪烟雨湿芙蕖，绿叶红花锦不殊。","闻说宛西桥畔宅，小园无地不荒芜。"]},{"t":"次韵草堂主人雨中十首 其六","f":"七言绝句","c":["醉里青春挽不留，眼前戈甲几时休。","溪边雨细花吹尽，陇上风寒麦又秋。"]},{"t":"次韵草堂主人雨中十首 其七","f":"七言绝句","c":["乱来岁月总如流，头白江村不奈愁。","老罢此身何处着，尚堪同倚雨中楼。"]},{"t":"次韵草堂主人雨中十首 其八","f":"七言绝句","c":["含桃熟后莺还语，柳絮飞时燕亦忙。","风物但随时节好，不知人意自凄凉。"]},{"t":"次韵草堂主人雨中十首 其九","f":"七言绝句","c":["浴凫飞鹭下横塘，花过莺归草自长。","恰似碧鸡坊口望，浣花溪上一茅堂。"]},{"t":"次韵草堂主人雨中十首 其十","f":"七言绝句","c":["避地偷生只闭门，不堪搔首对醨尊。","行歌野哭江头路，雨叶风花总断魂。"]},{"t":"避兵遣怀六首 其一","f":"五言律诗","c":["鸟噪乌江渡，鲸吞白下州。","地分元帅重，声入贼营愁。","近磔巡江尉，将俘北阙头。","兵行速如鬼，高鼻半毡裘。"]},{"t":"避兵遣怀六首 其二","f":"五言律诗","c":["江阔烽烟冷，城危战骑骁。","虏从诸道入，将拥溃兵骄。","万国昼多垒，三军夜击刁。","干戈空满眼，蛇豕不胜枭。"]},{"t":"避兵遣怀六首 其三","f":"五言律诗","c":["避地苍黄夜，悲凉郡郭西。","扪萝危绝磴，杖策困深泥。","掩面怜痴女，回头愧老妻。","惊魂犹未定，胡马莫频嘶。"]},{"t":"避兵遣怀六首 其四","f":"五言律诗","c":["野宿宁堪度，风餐寔自怜。","妻孥浑在眼，戈甲暗凋年。","夜月翻惊鹊，炎天看跕鸢。","射敌无一矢，南渡几楼船。"]},{"t":"避兵遣怀六首 其五","f":"五言律诗","c":["心折来时路，身行乱后村。","土兵呵白昼，野妇哭黄昏。","贼去烟留屋，人归日在门。","舂陵四万户，今日几家存。"]},{"t":"避兵遣怀六首 其六","f":"五言律诗","c":["阊阖乾坤大，封疆四百州。","蒙尘二圣哲，伐叛六春秋。","地入强胡阔，官封悍将优。","奉天哀诏下，感泣万方愁。"]},{"t":"次韵常元明西坑见寄二首 其一","f":"七言绝句","c":["西坑只在乱山间，寻得仇池十九泉。","有句能催千嶂雨，无人共钓一川烟。"]},{"t":"次韵常元明西坑见寄二首 其二","f":"七言绝句","c":["南来贼骑欲凌川，北岭人家自烧原。","闻道西坑堪避地，拟寻鸡犬问桃源。"]},{"t":"寒食杂兴三首 其一","f":"五言古诗","c":["寒食只数日，天气殊未佳。","轻云澹微茫，细雨吹横斜。","青春似无情，不到愁人家。","霁色忽浩荡，平原绣芳华。","走马恶少年，挟矢射戟牙。","白羽叫饿鸱，举网连五豝。","会当斩长鲸，封侯鸣鼓笳。","时危何不有，寒士空泥沙。","凛凛羞侠气，悠悠但咨嗟。"]},{"t":"寒食杂兴三首 其二","f":"五言古诗","c":["忆昔在京华，醉踏长安市。","长安白面郎，快马如流水。","罗襦照暮春，斗草携佳丽。","就中五侯家，云幄耀金翠。","九陌过香軿，都人拾遗珥。","歌喧乐佳节，日暮多沉醉。","荣华一消歇，祸乱苍黄起。","北狩随两宫，血属六万指。","征车去悠悠，河水日瀰瀰。","浩歌哀江头，老泪不可止。"]},{"t":"寒食杂兴三首 其三","f":"五言古诗","c":["北邙何巍巍，高冢如鱼鳞。","慨彼墓中士，中朝称贵人。","万金树丰碑，千金琢麒麟。","自从胡骑入，乱离隔中原。","生者各奔窜，死者衔长冤。","子孙无奠享，白杨悲馁魂。","峨峨缨冠子，往往无丘坟。","举酒西北向，野哭望白云。","我今上先陇，覆杯松下根。","时危不自保，念之殊酸辛。"]},{"t":"寒食夜月下作","f":"七言律诗","c":["一百五夜对明月，二十七种无蔬柈。","莫嫌万点飞花恨，且结三人对影欢。","流落忽成身老大，乱离谁不涕阑干。","颠狂自笑那能寐，立尽春风午夜寒。"]},{"t":"送詹伯尹丞泾邑","f":"七言律诗","c":["西溪寒食柳花飞，正是琴高欲到时。","薄禄仅酬三釜志，新篇莫负两松诗。","催科未办何妨拙，作吏能清不用知。","高论平生期活国，一方疲瘵看君医。"]},{"t":"题冯尉绿净堂","f":"七言律诗","c":["不种平池玉井莲，卷帘堂下水如烟。","溶溶自涨晴江绿，脉脉还通暗谷泉。","谁道冯唐今白首，始知梅福是真仙。","客来莫吐青铜面，要看蟾宫上下天。"]},{"t":"野饭","f":"五言律诗","c":["野饭聊娱老，登盘春物佳。","芼羹横荻笋，煮饼荐槐芽。","鱼尾初垂剑，台苗未着花。","谁言庾郎瘦，蔬腹渐禁茶。"]},{"t":"明皇羯鼓图","f":"五言律诗","c":["禁籞莺声外，天袍拥御黄。","曲名翻荔子，春苑绕沉香。","白雨花奴手，风鬉舞马床。","向来歌吹地，何处是渔阳。"]},{"t":"送智上人","f":"五言古诗","c":["道人饮山流，颜色颇秀整。","经营一庵足，偃蹇万事屏。","忽随铜峰云，飞下铜峰顶。","欲了一大缘，此意极勇猛。","白昼多豺狼，横涂半坑阱。","为言尸陁林，谁能保腰领。","要凭降魔力，化作清净境。","师亦初无言，薄俗时自警。","尽洗历劫冤，愿力周涬溟。","瘦藤行可支，慎勿厌驰骋。"]},{"t":"张载扬言扬州燕子无屋可居即船为巢命黄叔鱼赋诗今年春余始见叔鱼诗于宣城遂同赋","f":"七言律诗","c":["塞北胡儿归去日，扬州燕子却来时。","空寻画舸藏风雨，更为傍人话别离。","回首凄迷春水路，伤心零落旧巢泥。","斜阳不见乌衣巷，一读君诗泪欲垂。"]},{"t":"送吕右丞罢镇宛陵","f":"五言古诗","c":["汉室承平久，侯邦拱卫尊。","勋华垂日月，展错动乾坤。","开辟规模大，纷更制作繁。","民劳箕敛日，虏痛凿空痕。","鸣镝侵榆塞，穹庐指凤阍。","羽书飞始急，鱼鼎沸初浑。","内禅皇图远，春宫晓日暾。","群妖悉菹醢，黄发半腾鶱。","公入登丞辖，忠称自谏垣。","论思知蹇蹇，属意本元元。","蠖濩资扶掖，奇庬力引援。","犬羊盟易失，虎兕敌仍存。","转战知何已，风尘忽再昏。","仓皇趋帐殿，奔北弃弓鞬。","倾日心应折，瞻天眼欲眢。","徽音求太姒，基命本姜嫄。","大物归明辟，苍生荷国恩。","推符迎代邸，结绶拥尧轩。","灞上真人出，涂山万国奔。","回天功不世，徙突事堪论。","已复安西土，犹烦护北门。","要须调鼎手，为洗泣隅冤。","万杵坚城垒，千兵列戍屯。","贼锋忧寇钞，原燎畏烧燔。","坐啸初何事，渠凶不足吞。","持平本宽大，馀事到平反。","论说波澜阔，提携礼数蕃。","时悬徐孺榻，亦置穆生樽。","有客安圭筚，忘机在鸟猿。","疾驰看騕袅，妙琢愧玙璠。","始下横经帐，还攀欲去辕。","月楼空窈窕，风旆舞缤翻。","竹帛勋猷著，丝纶诏册温。","磻溪未容老，琳馆且辞烦。","閟计今犹在，忠怀不易谖。","白麻终拜相，左衽待称藩。","巨蠹消奸宄，良农植本根。","抗章陈上策，补衮要嘉言。","镇薄敦流俗，疏壅究治源。","微生有荣耀，洗眼在山樊。"]},{"t":"元素僻在草野群盗纵横久不得问新作鼎来喜次其韵三首 其一","f":"五言律诗","c":["兵气缠沧海，斜阳入暮林。","魂伤春落絮，泪湿晚啼禽。","只有衣成结，浑无发受簪。","残生已飘泊，老日更侵寻。"]},{"t":"元素僻在草野群盗纵横久不得问新作鼎来喜次其韵三首 其二","f":"五言律诗","c":["自失云桥路，空伤烟树林。","天骄犹射月，青犊未成禽。","尚怯矛头米，空横柱后簪。","春光无赖好，花落共谁寻。"]},{"t":"元素僻在草野群盗纵横久不得问新作鼎来喜次其韵三首 其三","f":"五言律诗","c":["近闻君隐处，茅屋带平林。","但可占鸣犊，谁能黜展禽。","书应丛净几，尘已暗横簪。","杖策终随子，云山上百寻。"]},{"t":"同仲共兄弟访赵行可行可置酒二首 其一","f":"五言律诗","c":["倚杖山头寺，维舟柳下堤。","莫催金騕袅，且醉玉东西。","乱后兵犹满，风惊鸟未栖。","看君飞动意，两目在鲸鲵。"]},{"t":"同仲共兄弟访赵行可行可置酒二首 其二","f":"五言律诗","c":["坐客三珠秀，王孙玉树高。","酒宁关尔辈，山合对吾曹。","游子家何定，将军战未鏖。","相逢莫相失，群盗正如毛。"]},{"t":"读陈公葆真宫诗有感而作","f":"五言古诗","c":["念昔全盛日，天子方祈年。","崆峒拟问道，桂馆延列仙。","葆真号上宫，柳色参云烟。","方池下见底，上映壶中天。","长安二三月，游女飞朱軿。","蹒跚步金堤，依约遗翠钿。","芙蕖倚红妆，弄影秋江边。","我亦时结客，曳杖相周旋。","不知客中人，有此稀世贤。","临老诵公诗，抚卷徒惘然。"]},{"t":"初夏","f":"七言律诗","c":["絮飞长陌又春馀，绿满菖蒲夏已初。","双蝶不来花蔌蔌，一莺时到树疏疏。","平生懒作折杨曲，万事可占长柳书。","只有故山真耐久，伴人闲处作踟蹰。"]},{"t":"贼退后经旧居","f":"五言古诗","c":["反侧虞戈兵，流离厌山谷。","师兴解重围，乱定出荼毒。","提携望乡关，老稚甘趼足。","故里成丘墟，门巷亡诘曲。","大木亦已薪，蔓草行可束。","东邻杀翁媪，祸难云最酷。","白骨在草间，零落不相属。","西家各奔窜，系掳及僮仆。","当时黄金囊，掉头不肯赎。","新交半亡没，变故谁记录。","举家竟何归，寄食叹局促。","凶年大军后，旱气日熇熇。","涸井不供炊，垢腻那得浴。","不知病瘦躯，何以度蒸溽。","自从关陜乱，威弧殊未韣。","十人九无家，荡析岂所欲。","微生何足论，主食久不玉。","但愿早休兵，四海各安俗。"]},{"t":"悯雨叹","f":"五言古诗","c":["南方久不雨，旱气日益酷。","起视夜何其，星斗灿满目。","朝云蔼空濛，暮雨思霢霂。","雷师方鞭车，风伯忽舞纛。","百神各颠倒，谁为调玉烛。","两宫方蒙尘，百执被驱逐。","万里沙漠行，长征犯三伏。","悬知臣子心，北望眢两目。","愿兴肤寸云，朝隮暮渗漉。","天公倘悔祸，何止望一熟。","皇舆既言归，壤地亦旋复。","谁当挽天河，下洗忧愤辱。"]},{"t":"和人题徐献可倅厅池莲二首 其一","f":"七言绝句","c":["风流别乘水中仙，百丈新移玉井莲。","试掉小舟花里去，便如苕霅雨中眠。"]},{"t":"和人题徐献可倅厅池莲二首 其二","f":"七言绝句","c":["西风吹雨绿杨湾，香满红妆一水间。","不把监州比螃蟹，看花谁似两公闲。"]},{"t":"毅果出示次卿诗编中有彭门见寄之作乃追和元韵","f":"五言古诗","c":["往忆乌衣郎，北走彭门道。","六年隔音容，万事挂怀抱。","相思枉停云，尺纸开小草。","为言清夜梦，莞尔同一笑。","黄楼渺天末，路远何由到。","我亦仰屋梁，恍若落月照。","神交见颜色，此理固良妙。","抚事思少年，相期在嵩少。","是时海内安，王师未征讨。","尚有丘壑姿，可寄沮溺傲。","一从胡雏骄，斯民困征调。","一死抗贼徒，奇祸发词藻。","造物苦见憎，与俗坐殊好。","微躯此栖迟，长夜悲静悄。","苍狗变浮云，世事那可料。","伤心埋白玉，急景转飞鸟。","幸此好事人，遗编为倾倒。","老眼倏巳明，权门益慵扫。"]},{"t":"毅师以次卿诗编见示以二诗还之 其一","f":"五言律诗","c":["云锦当年事，伤心不忍思。","江寒收骨后，山晚断魂时。","直节君何恨，天心我独疑。","老怀无处著，更复把君诗。"]},{"t":"毅师以次卿诗编见示以二诗还之 其二","f":"五言律诗","c":["人物忽扫地，风流谁复知。","子猷心爱竹，摩诘少能诗。","畴昔山林意，残年丧乱悲。","明珠在沧海，好句莫多遗。"]},{"t":"蔡生缚毡根毛笔戏书小诗","f":"七言绝句","c":["卧沙细肋策勋馀，点鼠何劳强挽须。","毛颖典型空复在，髯郎今巳号中书。"]},{"t":"九日度折岭","f":"五言古诗","c":["脩途苦悠悠，行迈日靡靡。","间道避群凶，弛担倦行李。","重冈颇峻极，一上三十里。","荆榛塞旧蹊，设险防贼轨。","凿空破狼石，猿径仅容趾。","俯身视悬崖，骇汗如流水。","回首问仆夫，仓皇谋进止。","邓公固忠臣，王阳真孝子。","经营能几何，蹈历乃至尔。","佳晨怀故乡，绝顶步屐齿。","醉帽落清樽，浮香嚼金蕊。","岁事行晏阴，四郊复多垒。","浩歌归去来，吾行且安俟。"]},{"t":"宿灵河寺","f":"五言古诗","c":["风餐倚虚壑，险步跻云梯。","惊魂栖客枕，夜宿投招提。","殷勤入檐月，肯为幽人低。","沧海念横流，万方喧鼓鼙。","胡为困行役，窜伏随麇麑。","南枝越鸟巢，北风胡马嘶。","耿耿念徒旅，依依怀故溪。","脂车待明发，胡为尚栖栖。","人生如醵饮，暂聚还复暌。","百年能几何，行乐戒噬脐。"]},{"t":"秋霖叹","f":"五言古诗","c":["去年阴山雪，平地三尺馀。","人言土中蝗，入土不用驱。","今年岁枯旱，野食无豆蔬。","西来三尺蝗，旧岁雪不如。","秋田有遗秉，未足饱一夫。","细雨生谷芽，屯云几时舒。","群凶剧豺虎，诸将劳驱除。","横尸作京观，流血如决渠。","高穹厌杀气，荆棘满郊墟。","尚复此恒雨，未知当何如。","岂欲令斯民，竟死不少纾。","天亦念赤子，理岂有是欤。","会当开晴云，却返羲和车。","我廪虽巳殚，我地尚可锄。","庶用种宿麦，更作来岁储。"]},{"t":"次韵赵鹏翔秋夜叹","f":"五言古诗","c":["朝弹雍门琴，暮歌梁父吟。","秋容日欲老，客愁秋更深。","问言愁何许，万里怀归心。","昔在洛阳日，颇遭胡骑侵。","骨肉尽奔迸，岁月良侵寻。","譬如痛定人，当痛难重任。","辞亲就薄禄，夜寝无完衾。","家亡河间书，囊鲜鸿宝金。","谁能援一臂，使子无陆沉。","老骥得平坂，惊凤翔长林。","佳名一朝白，高义千古钦。"]},{"t":"山谷先生吊秦少游诗云少游醉卧古藤下谁与愁眉唱一杯解道樽前断肠句江南唯有贺方回此以言语文字知少游者也余乡人有官藤州者谓藤人为余言少游既病洗沐步上光华亭手持白玉杯命取江水立酌一杯而逝呜呼此岂徒然者哉东坡题少游自作挽词以为能一死生齐物我是真知少游者也","f":"七言律诗","c":["古藤阴下偶婆娑，南北随缘意若何。","白玉杯寒亭上月，缕金衣断醉时歌。","还将万里澄江水，尽洗平生绮语魔。","能道秦郎解忘物，岭南唯有雪堂坡。"]},{"t":"岁杪雨雪连日闷题六绝 其一","f":"七言绝句","c":["春前旧雪连新雪，雨后春寒带腊寒。","残日送年能几许，一番风雨岁将阑。"]},{"t":"岁杪雨雪连日闷题六绝 其二","f":"七言绝句","c":["树头雪过梅犹在，地上春回柳未知。","旧岁新年浑似梦，冻云寒雨不胜悲。"]},{"t":"岁杪雨雪连日闷题六绝 其三","f":"七言绝句","c":["春回九地初颁历，人傍千门复看傩。","尽是汉家无事日，白头扶杖意如何。"]},{"t":"岁杪雨雪连日闷题六绝 其四","f":"七言绝句","c":["去年胡马渡淮流，江北江南处处愁。","破虏只今犹遣将，富民何日定封侯。"]},{"t":"岁杪雨雪连日闷题六绝 其五","f":"七言绝句","c":["鞭牛迎得春来了，爆竹催将岁欲徂。","莫把流年作悲喜，人间万事有乘除。"]},{"t":"岁杪雨雪连日闷题六绝 其六","f":"七言绝句","c":["大雪今宵一尺馀，王春明日岁云初。","丰年已识天公意，上瑞仍烦太史书。"]},{"t":"凌歊晚眺","f":"七言律诗","c":["故乡南望几时回，落日登临眼自开。","倚杖独看飞鸟去，开窗忽拥大江来。","伤心不见姑溪老，抱病聊寻宋武台。","岁晚无人吊遗迹，壁间诗在半灰埃。"]},{"t":"次韵伯尹登严子陵钓台","f":"七言古诗","c":["明光宫中枭夜鸣，汉鼎何人窥重轻。","老颅未污属镂血，四海掩鼻愁膻腥。","当时避地岂得已，岩栖水宿俱非情。","谁知举世无真隐，此意独高严子陵。","一钩明月满蓑雨，桃花水涨春江平。","生涯颇似玄真子，端欲钓鱼非钓名。","故人巳作飞龙起，犹着羊裘钓烟水。","异时侯霸岂其俦，未可轻将衮衣比。","心知不为世人屈，无故不作三公耳。","富贵浮云只眼前，执戟长怜子扬子。","丈夫名节倘未立，安用区区识奇字。"]},{"t":"环翠亭","f":"七言律诗","c":["客意长随倦鸟还，翠屏空梦小孱颜。","更将临老双愁眼，来看平生未见山。","西子为谁颦远黛，湘娥何事髻烟鬟。","千岩万壑无人处，便是辋川图画间。"]},{"t":"种德亭","f":"七言律诗","c":["万缘宜作梦时看，只有情田种德难。","但把胸中着梨枣，不愁庭下欠芝兰。","倡条冶叶浑无赖，错节盘根颇耐寒。","莫笑襄阳庞老子，全家长享鹿门安。"]},{"t":"蔡澄源录三家诗见借各题一诗以还之 其一","f":"七言绝句","c":["翰林才大今师伯，目短曹刘数仞墙。","我亦当年曾问字，云泥无路可升堂。"]},{"t":"蔡澄源录三家诗见借各题一诗以还之 其二","f":"七言绝句","c":["早时得句唾成珠，晚岁分符雪似须。","聊复把公诗过日，何心赋我食无馀。"]},{"t":"蔡澄源录三家诗见借各题一诗以还之 其三","f":"七言绝句","c":["少年湖海识元龙，老去功名事已空。","笔阵旧知无与敌，诗城今复有谁攻。"]},{"t":"睡起有感","f":"七言律诗","c":["日长谁复款幽扉，睡到斜阳恰尽时。","缺月要圆云未肯，青春欲老絮先知。","天於我辈元无分，梦比人间更不疑。","门外故人千嶂远，灯前华发万丝垂。"]},{"t":"次韵伯远春雪","f":"七言律诗","c":["风寒欲下欺春雪，天近先垂压地云。","堆得楼头成玉色，吹来酒面作波纹。","凭陵暖日竟何事，调护新花谁解纷。","温诏始闻如挟纩，九重应复念三军。"]},{"t":"光武二十八年五溪蛮反马文渊年六十三矣踊跃请行卒致困败班定远久在绝域上疏请归词甚切至其略曰臣不敢望至酒泉郡但愿生入玉门关遂老中朝辛亥季春三日灯下读此二传感而赋诗","f":"七言律诗","c":["平生长叹马文渊，功业遨游二帝间。","洛社龙飞初有意，峤南鸢堕不知还。","虽迷槃瓠壶头路，肯愧祈连冢上山。","政坐不如班定远，乞身生入玉门关。"]},{"t":"题赵周宾家夜猎图","f":"词","c":["翰林作醉石，偶似苍于菟。","龙眠见之笑，为作匹马弯彫弧。","云是将军出夜猎，上有仇池行草书。","云沙苍茫日欲下，道逢伏虎南山隅。","心知是虎不是石，双弦急控皆卢胡。","明朝白羽饮顽石，摩挲欲尽金仆姑。","君不见赐累千金新垣平，连佩六印栾将军。","致君大略岂在尔，封侯细事不到君。","先生言语妙天下，瘴海七年皮肉皴。","邂逅英物数苏李，曹蜍如生亦如死。","龙眠有眼识天人，异世同成一奇事。","君当什袭勿漫摹，此人此画人间无。"]},{"t":"五禽言 其二 泥滑滑","f":"词","c":["山中流水声聒聒，春禽说雨春泥滑。","谁为春禽语，莫报幽人明日雨。","幽人明日欲上山，山头雨足花斓斑。"]},{"t":"水西壁间见吕居仁绝句次其韵","f":"七言绝句","c":["秋霜落后题诗处，醉墨淋漓苦未乾。","不见穷愁孟东野，乱峰空锁一溪寒。"]},{"t":"题圣龙泉时方避贼山中","f":"七言绝句","c":["泉声来自古龙湫，山底惊雷万壑秋。","溅雹打窗空破梦，飞流无尽不湔愁。"]},{"t":"次韵伯尹食糟民示赵鹏翔","f":"七言古诗","c":["十年用兵九不熟，人家有田不种谷。","尽枯膏血作军储，却买官糟贮饥腹。","富者鬻田贫鬻妻，夜困桁杨晓敲朴。","长腰一粒不下咽，输入官仓常满屋。","昔年贯朽内府钱，诸公何苦开汉边。","自从胡马饮江水，便恐黔首流饥涎。","黄尘白骨尚满眼，锦裘绣帽谁当前。","烹羊炰羔固不恶，饥民食糟真可怜。","元侯幕下短主簿，肯与斯民作调护。","不愁吏考拙催科，宁脱青衫赋归去。","詹侯老文称大手，乐府诗高古无有。","安得狂歌彻圣明，便叱风雷清九有。","却驱群贼作良农，还我昭陵旧丁口。"]},{"t":"山中避盗后十首 其一","f":"五言律诗","c":["丧乱今犹尔，安危了未分。","叛羌初射月，群盗忽如云。","妙略归诸将，深忧轸圣君。","灞陵逢醉尉，应有故将军。"]},{"t":"山中避盗后十首 其二","f":"五言律诗","c":["避地今犹雪，移家春复深。","岂无花到眼，可奈鸟惊心。","茶动容时摘，兰香得细寻。","山中有幽事，青犊未成禽。"]},{"t":"山中避盗后十首 其三","f":"五言律诗","c":["浩荡奔流急，仓黄突骑来。","拥旌方满目，纵炬巳成灰。","去踏青山道，归看白骨堆。","须烦郭中令，一为洗胡埃。"]},{"t":"山中避盗后十首 其四","f":"五言律诗","c":["横道俱蛇豕，亲交信绝疏。","别来应隔岁，乱定始收书。","转徙移家后，存亡雪涕馀。","微生一蝼蚁，播越念皇舆。"]},{"t":"山中避盗后十首 其五","f":"五言律诗","c":["夜燧馀三月，新愁有百端。","惊魂频雨泣，枵腹任风餐。","射雉山居险，薰狐穴处难。","胡来犹可尔，寇至不胜残。"]},{"t":"山中避盗后十首 其六","f":"五言律诗","c":["黯惨春归日，荒凉贼后村。","鼓犹闻去寨，火未息平原。","不恨室庐尽，重欣老稚存。","此方惟是姥，亦复饭王孙。"]},{"t":"山中避盗后十首 其七","f":"五言律诗","c":["今日报贼去，下山犹复迟。","群儿收泪笑，老眼顾人疑。","梦入乡关屡，魂应躯干离。","一春三避贼，十事九成悲。"]},{"t":"山中避盗后十首 其八","f":"五言律诗","c":["翠巘几曲折，往来三数家。","捣皮催作纸，拥焙看烘茶。","山尽始见日，溪晴时露沙。","武陵知便是，隔岸有桃花。"]},{"t":"山中避盗后十首 其九","f":"五言律诗","c":["贼去方烧县，兵来复打城。","艰难唯有骨，生死两无情。","欲住家何有，谋归计未成。","人言李御史，满腹是精神。"]},{"t":"山中避盗后十首 其十","f":"五言律诗","c":["可怪子刘子，全家肯见存。","长分夜雨榻，复共草堂樽。","磊落吾何取，笑言君益温。","它时此心在，结草报深恩。"]},{"t":"侯元进赋待凤堂佳句见邀同作","f":"五言律诗","c":["见说封君竹，风枝饱岁寒。","会看双鸑鷟，飞下碧琅玕。","恶鸟良复厌，闲花吹自残。","绝知门可款，梦对小檀栾。"]},{"t":"题赵钤家墨牛图","f":"七言古诗","c":["昔我筑室花姑川，短蓑青帽耕春田。","一犁落尽菖叶雨，双犊自分春草眠。","向晚归来卧牛背，小巷疏林日犹在。","系牛柳下门未关，邻翁携酒牛边醉。","回头往事无十年，田入富家牛卖钱。","草荒春陇贼烧屋，十口有家无一椽。","眼昏头秃不如意，此画一见心惘然。","河间岂是田家子，书多自可天禄比。","平生眼厌玉骅骝，水牯作图聊复尔。","北陌东阡唤未归，空遣农人告春事。","田间望月看吴牛，老子从来乃如此。","便当火急解龙泉，换取四蹄耕雨水。"]},{"t":"贼后收拾残书作","f":"七言律诗","c":["此生空作短檠痴，老去犹惭阅市资。","岂有邺书犹插架，更无班史可充饥。","今朝过眼亡三箧，它日还君欠一瓻。","乱叶纷披在悬磬，春风可是故相欺。"]},{"t":"燕欲来巢","f":"七言律诗","c":["乱后乌衣巷欲空，拟寻茅舍伴蓑翁。","戏将雏去春风里，衔得泥归暮雨中。","炙手不嫌门户冷，傍人如献语言工。","明年记取来时节，应是桃花满院红。"]},{"t":"三月三夜得梅花数枝灯下作","f":"七言古诗","c":["故人远客天一涯，寄我万里风前枝。","方壶含澌不受污，可着玉树瑶林姿。","孤芳妙质不可说，天香肯复须人知。","老人不作世间梦，但见玉友如儿时。","急张青灯当明月，要看疏影横屏帏。","花寒不睡斗欲落，笑语似与人追随。","持杯未怪此宵乐，论情忍负平生期。","回头却忆青山道，处处相逢花不老。","短篱飞雪山更寒，古木啼乌月催晓。","清魂屡往途路遥，故人久别相知少。","只今如此邂逅何，莫厌诗成苦相恼。"]},{"t":"桓公祠","f":"五言律诗","c":["苏峻兵方急，桓公气未平。","一身唯死节，四海但孤城。","岁月人间梦，功勋纸上名。","可怜山下老，浇酒问阴晴。"]},{"t":"次韵元进寒食感事","f":"七言律诗","c":["寒食江天雨弄晴，夕阳花草一川明。","持杯欲下它乡泪，上冢宁无故国情。","渐喜三春逢禁火，会须五斗解朝酲。","知君屡作东莱梦，我亦飘零叹此生。"]},{"t":"次韵元进再示","f":"七言律诗","c":["屋角鸣鸠唤晚晴，眼惊新火一番明。","兵戈处处伤时事，花柳村村恼客情。","无复御廊分冷食，只将蹋鞠醒春酲。","德公上冢知何日，满眼春愁太瘦生。"]},{"t":"雨后过琴高岩","f":"五言古诗","c":["夜雨喧旅枕，晓径深春泥。","奔流自山来，转眼忽渺瀰。","微生抱羁蹇，老病凌攲危。","青山岌当前，客意恍若遗。","空崖倚天立，怪石从云垂。","云间笙箫声，隐约天风吹。","斯人已仙去，孤踪邈何之。","钓石屹中流，谁来把纶丝。","一水绕山麓，浅碧涵涟漪。","长年抗尘容，照水羞华髭。","羡门不可遇，惜哉吾巳衰。","人生不学仙，万冢空累累。","于今岂未可，抚事聊歔欷。"]},{"t":"读枢密张公梅雪二诗公讳叔夜","f":"七言古诗","c":["禁中颇牧谁最良，上前论事张子房。","张公九尺须眉苍，谈兵说剑眼为方。","金城有策若未试，便恐谈笑无戎羌。","时平不用临边手，乞得南州作醉乡。","黄堂酒尽客未起，清畎风多禾自长。","只今白雪醉中句，犹带东阁官梅香。","胡狂敢挽射日弩，当年谁上东封章。","王城三月断信息，贼军蚁附方跳梁。","白头侍郎最先至，拥兵直入趋咸阳。","中人传诏天为喜，戎师夜遁军威张。","太宰官高亦动色，毬路带禠腰金黄。","功名无成落边土，此老此功谁更数。","想得韦韝毳幕寒，夜听边声泪如雨。"]},{"t":"次韵元进以长句见勉","f":"七言律诗","c":["一雨俱回草木春，槁枝着叶定何因。","烦君笔底三昧句，洗我胸中千斛尘。","忧患此生真已了，风烟万里正愁人。","白头攘臂干戈里，欲遣何人唤孔宾。"]},{"t":"次韵元进病中书怀","f":"七言律诗","c":["一竿烟雨钓羊裘，稍负初心只自羞。","拟学倦飞双去鸟，可怜无定一虚舟。","未成大隐定小隐，为用人谋更鬼谋。","君有胸中经济策，不须犹说二宜休。"]},{"t":"次韵元进书事","f":"七言律诗","c":["七尺看君玉作山，倦游莫赋鸟知还。","大椿本自八千岁，天马终縻十二闲。","笑我生涯真草草，如公人物未班班。","他时一枕江南梦，犹记相从水石间。"]},{"t":"次韵元素见寄","f":"七言律诗","c":["吾曹心事寄微言，此意难从世俗论。","妙句已先醒醉梦，尺书何止到寒温。","因缘只睡心情懒，习气唯书眼力昏。","知有草庐能避地，满村烟雨一柴门。"]},{"t":"次韵奉答冯远猷","f":"五言古诗","c":["翩翩绮纨子，粲粲洁衣服。","朱门酒肉臭，不饱膏粱腹。","凄迷百草中，得比兰与玉。","手持白瑶琴，欲鼓朱弦曲。","閟兹清庙音，未易可流俗。","名家千里驹，历块步巳独。","妙年振华镳，肯折盐车轴。","中原暗风尘，国步日窘促。","勒铭树高勋，要是一夔足。","期君乃如此，使我安小筑。"]},{"t":"刘将军宝刀歌","f":"词","c":["将军宝刀玉三尺，夜半有光如日赤。","苍水使者谁敢扪，蓬头剑士眼不识。","鸊鹈膏瑩秋水光，切玉如泥不动芒。","秋风夜作蛟龙吼，人言乃是真干将。","知君老将家有种，谈兵论事书撑肠。","不愿君持此刀日解三千牛，愿刳月支作饮器，却缠锦绦朝未央。","妖腰乱领不自保，丰狐老猘谁跳梁。","酒酣起舞为君语，时危此剑知难藏。"]},{"t":"雨过","f":"五言律诗","c":["池面过小雨，树腰生夕阳。","云分一山翠，风与数荷香。","素月自有约，绿瓜初可尝。","鸬鹚莫飞去，留此伴新凉。"]},{"t":"五月十八日魏宗明官舍作","f":"七言绝句","c":["黄尘白骨已无人，青谷朱楼尚有村。","今夜三更山吐月，共倾双泪看金盆。"]},{"t":"蔡长源以老马见借驽甚戏作","f":"七言绝句","c":["羸骖已老莫嗔渠，涉世迂疏我自愚。","马不能言当臆对，未知吾孰与君驽。"]},{"t":"吴思道示藏海小集","f":"七言律诗","c":["文物风流数建安，此生犹及见波澜。","清诗更遣何人到，馀子悬知一笑看。","犹恐向来无鲍谢，谩劳当日话吴韩。","知君有意分膏馥，老眼空惊白雪寒。"]},{"t":"读郑公奉使录 其一","f":"七言绝句","c":["黠虏难交玉帛欢，只因献纳是争端。","郑公不请长缨去，有口真堪伐可汗。"]},{"t":"读郑公奉使录 其二","f":"七言绝句","c":["诸公有意勒燕然，不道昭陵闭玉关。","却遣毡裘窥汉鼎，拜公遗像独何颜。"]},{"t":"小蔡许借徐诗未至","f":"七言古诗","c":["马中未必无骅骝，人中岂可无曹刘。","龙媒西来几万里，异士一出三千秋。","李白坐诗窜夜郎，退之论佛流潮州。","天公可笑无老眼，两翁憔悴令人愁。","平生四海黄太史，长庚配月何曾死。","西江自是南国纪，公有高名政如此。","人言此老酷似舅，坐上拈花独公喜。","分得西江一派流，万古正须公一洗。","我老耽诗空瘠臞，起死针盲正要渠。","子岂有意能起予，书来并寄囊中珠。"]},{"t":"次韵费茂和风月亭新成","f":"七言律诗","c":["十室熙熙俗自恬，令君岂弟不多严。","簿书遣吏且堆案，风月撩人时到檐。","剩种幽花无限好，满倾春酒十分甜。","何劳结屋深防客，清节如君有底嫌。"]},{"t":"孙耘老酒间出麻姑像要余作诗","f":"七言律诗","c":["青丝一尺高蓬松，玉颜微驻丹砂红。","云軿飞来自何许，满山落叶元无踪。","长天如烟月如雾，便恐乘鸾月边去。","烦君急与问中郎，从此更谁知痒处。"]},{"t":"夏热叹","f":"七言古诗","c":["祝融当权不可夺，海水欲沸山欲裂。","黄头父老见事多，谓有此身无此热。","老人何得怨天公，山堂日日多南风。","乌纱攲帽剪云叶，白鬓吹雪飞蓬松。","已挹蔗浆浇热恼，更注井花回睡容。","人生如此亦不恶，饱食安坐初何功。","蒙尘况驻奉天辇，避暑望幸骊山宫。","蕃兵入汉作巢窟，战骑横戈岁驰突。","旌旗耀日红蔽天，铁甲烘云气销骨。","安得壮士如恶来，上诉帝阍关钥开。","尽泻天河作飞雨，四海八方无一埃。","秋禾不槁敌不来，我亦高枕喧春雷。"]},{"t":"送许体之守贵州","f":"五言古诗","c":["人物久衰谢，斯文寄渺茫。","先生推老成，词采今擅场。","交游数辈行，犹及晁与张。","大坡渺云汉，小坡与相羊。","岂兹丝纶手，不入鹓鹭行。","尔来南中守，雨露新汉章。","南中俱乐土，佩带安农桑。","铜花秀铠甲，芝菌生桁杨。","霜林荔子熟，酿瓮千家香。","使君啸铃阁，宾客醉高堂。","古来多循吏，治行何曾彰。","愿公饮无何，坐使斯民康。"]},{"t":"许贵州出苏叔党树石","f":"七言律诗","c":["老坡骑鲸上天去，小坡落笔如风雨。","能添老树着岩间，为石传神自翁语。","两坡俱死真可惜，君有一拳何处得。","谁向九原呼此翁，为我五日画一石。"]},{"t":"立秋前三日夜雨","f":"五言律诗","c":["残漏催灯暗，风梧带雨鸣。","细听惊梦点，浑作断肠声。","乍冷秋应近，无眠句又成。","愁多推不去，头白更忧兵。"]},{"t":"乱后并得陶杜二集","f":"七言律诗","c":["少陵有句皆忧国，陶令无诗不说归。","常恨两翁埋槁壤，顿惊双璧堕穷扉。","风催锦里花枝少，草长江南豆叶稀。","自古高才多寂寞，遗编读尽泪频挥。"]},{"t":"读徐伯远书外家遗事作二绝句以纪之并序 其一","f":"七言绝句","c":["就死由来不自疑，玉颜那为贼锋低。","了知今日投渊妇，犹胜当年断臂妻。"]},{"t":"秋旱既久巳而大雨","f":"五言律诗","c":["霜旱忧千里，灵湫卧蛰龙。","丛祠亦何力，女觋遂论功。","冻雨云霓过，秋田寇盗空。","饥肠蒙一饱，欢甚雪髯翁。"]},{"t":"夜雨不寐","f":"五言律诗","c":["岁已随流水，身犹转断蓬。","秋风双鬓短，夜雨一灯红。","衰病无多力，穷愁莫漫攻。","残年消底物，溪外两三峰。"]},{"t":"次韵罗叔共纪事见寄","f":"五言古诗","c":["中原困胡虏，此事昔固闻。","何尝大江南，犬羊动成群。","踊跃万骑入，苍黄两龙奔。","五年三避狄，十室九见焚。","相公既降虏，盗贼俱官军。","遂令江以南，填山满屯营。","老稚五六辈，相呼走荒村。","君昔东道主，窜身亦荆榛。","两家三十口，既死惊复存。","共求草中生，有似獐与麇。","平时巳蹭蹬，老恨有此身。","湛湛两玉壶，炯炯无一尘。","犹喜垂尽中，得此千载人。","珠玑皎在前，自然洗妖氛。","恨君济时策，百未有一伸。","半通犹绾戾，两肘空悬鹑。","无人作游扬，恐得按剑嗔。","浓云卷肤寸，未许膏斯民。","念昔仲夏夜，赤气腾天曛。","雨足下垂地，诛斩当奸臣。","敌将果夜遁，王师策殊勋。","班荆记是夕，同我二三君。","君歌独慷慨，泪下沾衣巾。","愿言补周衮，八表均尧仁。","昆虫及草木，同播一大钧。","良会有如此，吾生岂非辰。","吟君洗兵马，大雅何深醇。","安得清庙瑟，朱弦奏春温。"]},{"t":"七月十八日夜独坐静寄月出麻姑背开户徜徉夜久不寐","f":"五言古诗","c":["秋日忽复翳，暮色横陂陁。","黯黯窗户暗，森森修竹多。","我懒不点灯，枯藤与婆娑。","青山忽吐月，隔竹翻金波。","须臾满幽林，欸乃被岩阿。","开门望天汉，星宿方森罗。","秋风入梧楸，白露沾芰荷。","夜寒有惊鹊，飞鸣绕南柯。","苍生愿安枕，壮士方横戈。","谁能请缨剑，故地收关河。","我意忽不惬，邻鸡复当歌。","诗成月巳落，奈此老狂何。"]},{"t":"次韵魏宗明携酒小集","f":"七言律诗","c":["山翁烂醉习家池，碎剪黄花点玉卮。","亹亹听君真有味，皇皇怜我欲何之。","难陪痛饮心先醉，强作朱颜老易衰。","明日囊中有新句，尚堪醉墨写淋漓。"]},{"t":"次韵吕居仁诗尾见及四绝 其一","f":"七言绝句","c":["诗成邂逅得穷愁，眼见郎潜又白头。","人物向来山吏部，篇章今日谢宣州。"]},{"t":"次韵吕居仁诗尾见及四绝 其二","f":"七言绝句","c":["狗监连衡苦未平，秋成戈甲尚乘城。","梦魂几欲随公去，为问高安路几程。"]},{"t":"次韵吕居仁诗尾见及四绝 其三","f":"七言绝句","c":["楼上看山酒一卮，人间此乐岂儿知。","秋风吹落霜前雁，寄得西来别后诗。"]},{"t":"次韵吕居仁诗尾见及四绝 其四","f":"七言绝句","c":["白发书生谁复论，萧然深闭一蓬门。","自知赤壁功名晚，羞与周郎作耳孙。"]},{"t":"题裴晋公画像二绝 其一","f":"七言绝句","c":["朝论当年汹汹时，此翁奇事少人知。","梦中缚得吴元济，犹说绯衣是小儿。"]},{"t":"题裴晋公画像二绝 其二","f":"七言绝句","c":["瘦着轻裘似不胜，书生事业复谁能。","莫嗔小鸭可禽兔，真有禅师解放鹰。"]},{"t":"玉友初成戏作二首 其一","f":"七言律诗","c":["小瓮鹅黄拨不开，晚风吹蚁转荷杯。","灯前细酌情何限，病后朱颜老却回。","我亦平生笑馀耳，人今何处有陈雷。","方从欢伯作幽事，莫唤酪奴相继来。"]},{"t":"玉友初成戏作二首 其二","f":"七言律诗","c":["旧交谁复可相忘，晚向林中得此郎。","政恐大儿妨笑语，频呼小友共回翔。","坐来乌有聊为客，醉后无何即是乡。","多谢故人分玉粒，夜灯和雨捣新香。"]},{"t":"捡故书得旧写真戏书","f":"七言律诗","c":["杨柳春风濯濯枝，深惭张绪少年时。","期期尚有胸中意，种种真成鬓上悲。","暮四朝三心巳了，年头月尾老俱遗。","此中空洞今何有，曲尽周郎更不知。"]},{"t":"八月三日早起","f":"五言古诗","c":["金枢坏残月，旸谷宾朝曦。","九日浴沧海，一日腾上枝。","上枝邈何许，但隐山半规。","须臾挂铜钲，飞上天一涯。","光景被草木，晔晔含幽姿。","微暾入圆吭，飞鸣各嘤咿。","物意自欣悦，人情伤岁时。","卷我东窗帘，群山抺脩眉。","炙背翻故书，搜肠出新诗。","俟河几时清，种豆落为萁。","人生行乐耳，富贵终何为。","丈夫风云会，事业肩皋夔。","时哉不我与，浩歌君勿疑。","纫兰可为佩，制荷可为衣。","驾以白玉虬，骖以苍精螭。","翩翩八荒外，渺渺天风吹。","世俗付一笑，造化真小儿。"]},{"t":"雨作留水西溪涨不可复归","f":"七言律诗","c":["东溪打桨过西溪，南岭云飞北岭时。","鸟语屡呼人载酒，山行不厌雨催诗。","静中秋色人间少，客里泉声夜半知。","老去随缘皆可耳，愁霖未用苦相欺。"]},{"t":"病中王邦宪见过以诗为谢因以当别","f":"七言律诗","c":["别后衡门久不开，壮心消尽已成灰。","白头羁客病中老，青眼故人天外来。","相见有时那易得，语离终在莫频催。","山城归路应残腊，早寄春风岭上梅。"]},{"t":"病起负暄菊篱一首","f":"五言古诗","c":["卧疴初肃霜，小间倏玄冬。","老境知几何，半落呻吟中。","医师固楚产，砭灼矜神功。","巫师杂荒怪，呼吸生雷风。","江乡郁毒雾，禦湿无鞠藭。","况复窘行役，六月伤蕴隆。","寒热遂百战，药石徒屡攻。","槁项与黄馘，苶然非昔容。","逮兹脱九死，更生本苍穹。","今晨颇欣悦，步我菊篱东。","无谁与共语，梵诵庶可终。","忧乐有乘除，涉世殊穷通。","幸兹未暝间，有乐聊复从。"]},{"t":"送詹伯尹赴三衢酒官","f":"七言律诗","c":["东观谁临未见书，起居君不解何如。","懒从瓜陇耕春雨，聊听糟床滴夜渠。","满世棘荆浑未定，白头书尺莫全疏。","官曹有禄仍无事，看着斑衣从版舆。"]},{"t":"辛亥冬无雪天气妍暖如禁烟时书所感三绝句 其一","f":"七言绝句","c":["夕阳微傍小窗明，便遣飞虫作意鸣。","天共梅花元有约，谁教草色上荒城。"]},{"t":"辛亥冬无雪天气妍暖如禁烟时书所感三绝句 其二","f":"七言绝句","c":["当年白雨打凉州，春色还催禁籞游。","记得端门迎辇路，轻冰一夜绿杨沟。"]},{"t":"辛亥冬无雪天气妍暖如禁烟时书所感三绝句 其三","f":"七言绝句","c":["去年和雪卧榛丛，雪里旌旗分外红。","江上只今无盗贼，楼头昨夜已春风。"]},{"t":"仁宗皇帝飞白歌","f":"词","c":["八神警跸群灵趋，风师雨伯当前驱。","汉家四叶圣主出，共扶日御升天衢。","当时农桑三万里，地上钱流已如水。","左有稷契右皋夔，四岳九官真济济。","太师当国天下安，貂蝉绣衮身如山。","范公特节下金銮，名落百蛮毛发寒。","郑公有口伐可汗，可使一言无契丹。","太平天子坐垂拱，蝉蜎蠖濩朝千官。","侍臣愕立蓬莱殿，看草宸奎丽云汉。","中人传赐宣口敕，雨露恩光极昭焕。","公家什袭宫锦囊，五彩属天惊夜光。","试从父老说嘉祐，百年厚德知难忘。","自从丧乱双眼暗，犹喜人间得时见。","小臣拜舞喜欲颠，安得身随千官朝九天。","眼见万骑无控弦，四海复似昭陵年。"]},{"t":"雪中睡起书北窗二首 其一","f":"七言律诗","c":["断云疏雨暗楼台，春在寒空不肯回。","梅亦羞人花未笑，柳知何事眼慵开。","久拚双鬓缘诗老，忍放痴愁入酒来。","犹有暮年文字业，睡馀重秩乱书堆。"]},{"t":"雪中睡起书北窗二首 其二","f":"七言律诗","c":["窗下梅花冻玉壶，梦回闲听雪跳珠。","樽中酒尽何由得，枕上诗成可自娱。","身世固应浑是梦，功名知巳不成卢。","明朝醉倒春风路，试问黄公觅旧垆。"]},{"t":"次韵元素自东皋寄新诗贼退犹未久 其一","f":"七言律诗","c":["北风胡马自长鸣，月到南枝鸟共惊。","留我小溪回短棹，看渠红旆作长城。","人思庞老皆知隐，贼说康成亦畏名。","乱后欲从君一笑，满林荆棘未堪行。"]},{"t":"次韵元素自东皋寄新诗贼退犹未久 其二","f":"七言律诗","c":["先生老去以诗鸣，乱定诗来眼倍惊。","但把明珠照兼乘，未须白璧换连城。","人言陶令尝耽酒，我识玄真不钓名。","晚日追随叹才尽，始知天马足能行。"]},{"t":"奉圣山中邂逅忻师相与话十年旧事为之惘然二十一日同游陈侍讲附子园偶作此篇","f":"七言律诗","c":["不见跳珠巳十年，旧游重说固依然。","此生如我岂非梦，到处逢师真是缘。","倦客来看栽药圃，先生昔侍讲经筵。","人间作计无多子，也合归耕种谷田。"]},{"t":"过石壁","f":"五言古诗","c":["两峰夹天高，一水绕山麓。","鸟道盘山腰，下临千仞谷。","仰视寸草青，千章罗巨木。","转峡泻哀湍，惊雷裂坤轴。","日月所隐庇，光景不到目。","道险当舍车，重趼摩两足。","不知谁凿空，穿穴入山腹。","平生蜀道难，耳目闻见熟。","兹山亦尤物，初未挂史牍。","了知天宇间，万险自重复。","穷人重锱铢，凌冒取危辱。","岁晏霜雪多，归途戒当速。"]},{"t":"出石壁","f":"五言古诗","c":["倚空山崭岩，平地石龃龉。","脩途绕危磴，千里无寸土。","山高不见日，雾重自成雨。","入壁天始明，出壁日过午。","青苍断崖谷，开豁见天宇。","稻田棋局方，梯山种禾黍。","道傍两三家，稍稍闻笑语。","始知在人寰，邂逅得徒旅。","倦仆饥欲啼，游子欢自许。","携孥老一廛，白发无处所。","何当把春犁，望月耕陇亩。","闭门了残年，危磴不复取。"]},{"t":"徽州道中观山二首 其一","f":"七言绝句","c":["老去心安一味闲，江南江北饱看山。","不知今日徽州路，始落千岩万壑间。"]},{"t":"徽州道中观山二首 其二","f":"七言绝句","c":["暖日岩花上翠藤，半岩松桂耸亭亭。","南来到处无山似，唤作东川小锦屏。"]},{"t":"上饶道中望月岩","f":"五言古诗","c":["瘦马度莽苍，悠悠忽长年。","群山不知数，衮衮来眼前。","忽逢天上月，下挂苍崖巅。","炯如碧玉玦，中空窦云天。","岩柯亦薄相，为作蟾桂圆。","阴晴无显晦，千古长婵娟。","坐令马上梦，忆我江南川。","江空月自吐，万顷含风烟。","静闻欸乃声，入我独宿船。","误从尘网中，见似喜欲颠。","何当追昔游，摆脱区中缘。","买地结茅屋，攀云蹑飞仙。","朝吸白露光，暮饮山根泉。","清欢倘可结，浩歌与周旋。"]},{"t":"于潜道中戏作","f":"七言绝句","c":["徐娘虽老风流在，学得啼眉时世妆。","只有于潜旧家女，但携篷沓嫁新郎。"]},{"t":"收伯尹三衢书","f":"五言律诗","c":["近有南州使，双持赤鲤鱼。","花时孤客泪，乱后故人书。","一别真如许，三年少定居。","时危消息好，老去莫情疏。"]},{"t":"正月十日雪","f":"五言古诗","c":["维时孟春月，岁事司勾芒。","微阳力犹弱，未足扶百昌。","风伯偶偃旆，电师亦潜光。","坚冰顿欲解，蛰户不肯藏。","群阴势未屈，寒飙忽飞翔。","积阴既得泄，雪意亦异常。","痴云迷澒洞，烟水俱苍茫。","行人有堕指，裹足畏前冈。","疏梅强解事，一笑矜芳香。","谁怜百草死，万木寒仍僵。","东君始用事，抗此凛冽刚。","那知假微暾，乃复为此祥。","幽人解春衣，酒券仅可偿。","倚此数日暖，苍黄索衣裳。","万事多反覆，天心难重量。","赖我有残榼，聊足资清狂。","此意谁复论，醉眼空望羊。"]},{"t":"铜爵研","f":"七言古诗","c":["藁街夜腹空燃脂，可怜汉祚终陵夷。","老瞒自在作家主，欺它寡妇并孤儿。","洛阳宫殿皆颓圮，更作高台半天起。","台上吹香十里闻，台下洗妆漳水浑。","当时歌管一消歇，回望西陵空断魂。","百年岁月空中鸟，花不长妍人易老。","台倾人去不复存，碧瓦澄泥为谁好。","那知流落向寒窗，乞与诗人赋花草。"]},{"t":"次韵伯尹见寄二首 其一","f":"七言律诗","c":["种种星星苦见侵，已无心作四愁吟。","三秋令我频成梦，一月劳君几嗣音。","臭味每嗟无草木，因缘已定只山林。","此心耿耿从谁语，遗恨依然泪满襟。"]},{"t":"次韵伯尹见寄二首 其二","f":"七言律诗","c":["从古何人解识真，夜光欲到了无因。","只今怀璧还归赵，它日挥毫有过秦。","馀子不应沾厚禄，此郎宁合坐长贫。","白衣苍狗俱成梦，富贵功名不在人。"]},{"t":"次韵常元明寄侯元进","f":"七言律诗","c":["丞哉风味似崔侯，松下行吟万事休。","乱后只应堪一笑，官闲如此复何求。","看花欲下春衫泪，射月先忧塞草秋。","赖有道人三昧句，为君一洗向来愁。"]},{"t":"和赵鹏翔赠李生","f":"词","c":["人间作画如作诗，妙由心得非人为。","五日一石十日水，此事无乃亦可期。","向来郭恕先，妙手真复奇。","经年不肯下一笔，胸中丘壑谁当知。","忽然有兴不可遏，写作槎枒风雨枝。","回头却笑阎立本，缓急与人为画师。","李生闻是成远后，一生落魄唯饮酒。","贵人金多不可呼，閒日为多画日偶。","心知公子非俗人，平生笔底波澜翻。","故作沧江与巨石，要看万里风涛相吐吞。","谁知此老不足数，自笑一生常苦辛。","桃花水暖小艇窄，十年辜负江边春。","时危力小去未得，画图入眼空伤神。"]},{"t":"次韵韦深道哭陈谏议","f":"七言律诗","c":["自是群奸误圣君，初心岂愿作忠臣。","平生劲气埋黄壤，当日嘉言在紫宸。","谏议裂麻方伏閤，诸公鸣玉自垂绅。","向来六子俱诛灭，此道于谁较屈伸。"]},{"t":"叔达许分萱柳二栽作二绝 其一","f":"七言绝句","c":["华颠老去几霜秋，知处元应不奈愁。","但得稍分花到眼，谁能更觅地埋忧。"]},{"t":"叔达许分萱柳二栽作二绝 其二","f":"七言绝句","c":["锄荒巳出墙根路，剪绿仍分雪后栽。","便与数椽容我老，当留一径待君来。"]},{"t":"谢元不伐寄灵岩七诗用梅圣俞韵","f":"七言古诗","c":["灵岩胜绝天下稀，开凿乃自太古出。","山名初岂有显晦，胜处要须诗黼黻。","自从梅老登列仙，尤物谁怜久埋没。","具茨笔力扛九鼎，坐遣清诗入山骨。","据龟食蛤谁与游，绛节云车到仙窟。","云间招手疑有无，月下吹箫真仿佛。","飞云杳蔼风吹香，翠润空濛雨垂湿。","谁从洞口看金书，想对神清时独立。","我家灵岩山脚底，识面何由恍如失。","虽无幽梦到三山，尚有明珠容什袭。"]},{"t":"送别徐南美","f":"七言古诗","c":["谋臣如云将如雨，欲剪天骄奉明主。","御营飞诏肃虎貔，妙略纵横自神武。","谁骑驳马蹄双朱，梦从璜溪亲帝舆。","手提大钺杀两将，日御少却公重扶。","此公堂堂出当国，群盗相看少颜色。","江上鲸鲵尽扫除，草中狐兔无窠窟。","折冲自可销戈兵，寸地尺天归圣明。","帐下偏禆何足数，幕中宾客公独称。","愿资硕画戡祸乱，坐遣四海歌升平。","书生白首亦安用，尚可平戎作短行。"]},{"t":"送侯元进罢泾溪丞","f":"七言古诗","c":["胡雏饮马窥长江，巨鼎一沸俱仓黄。","我携老稚不知处，流离夜窜泾山阳。","山中小邑真蕞尔，井邑无声但流水。","乱石巉峥虎看人，贾客稀疏市争米。","忆昔相逢群盗中，过我天宫宝坊里。","人言觅句崔立之，恐是前身侯叔起。","当官论事嚼寒冰，醉后诗成只弹指。","三年兵火梦中游，别去何堪日千里。","人生直气忌太高，论少卑之亦聊尔。","功名唾手良偶然，邂逅庸奴亦如此。","如公人物自有馀，似我苍华真老矣。","只今满世尚干戈，应念相思遣双鲤。"]},{"t":"李使君示开化诸诗","f":"七言古诗","c":["使君一出承明庐，当年两佩龟峰鱼。","龟峰小儿骑竹马，笑挽朱轓归故闾。","门外春风吹画戟，小阁香浓绮疏碧。","苏州五字老更奇，东阳八咏人谁敌。","山堂闻说公自开，烟雨遥供翠鬟色。","更向招提山窟中，竹杖穿云饱经历。","夜上孤峰看明月，晓趁钟鱼着僧屐。","诗成知复几牛腰，倒廪倾囷公不惜。","他人举似与何人，知我耽诗老成僻。","平日看囊止一钱，惊见纵横着圭璧。","当遣儿童勿浪传，按剑从来少人识。"]},{"t":"赠元具茨二首 其一","f":"七言律诗","c":["平生结客少年场，人物如君见未尝。","早岁风流知漫叟，一时师友是黄香。","相从便作双凫去，欲见应须一苇航。","只恐涪翁门下士，九重应合奉清光。"]},{"t":"赠元具茨二首 其二","f":"七言律诗","c":["名在金华季孟间，流传佳句落人寰。","异时文采今何在，扫地风流唤欲还。","剩馥见分虽有意，小巫自顾独何颜。","源明不恨生衰俗，尚喜人中识鲁山。"]},{"t":"罗仲共兄弟文集为贼所残","f":"七言律诗","c":["照眼明珠两陆离，机云兄弟似当时。","文章未许轻沾丏，神物何为欠护持。","白璧悬知从间道，青毡亦复付偷儿。","谁言举世无苏炜，收得香奁第一诗。"]},{"t":"何元静以诗索花次韵诗尾致剪花之约","f":"七言古诗","c":["城南有客身倦游，饭无脱粟衣无裘。","短墙雨湿花木晚，穷巷草深篱落秋。","心常自许玉川辈，人言恐是原宪流。","千奴安得封君禄，偶有一花聊可目。","綵椽作架恐未暇，春到听花飞上屋。","衡门无酒客不知，寒谷少春花更迟。","慇勤未足供一笑，惭愧烦君作好诗。","谁遣春风吹急雨，枝头会见花无数。","夜窗月白得暗香，晓枕风微战轻素。","已办并州快剪刀，为剪长条送春去。","君当酿酒买肥羔，莫倚匆匆陈草具。"]},{"t":"后数日以诗偿剪花之约","f":"七言古诗","c":["春风吹云不成雨，暖日将春到花坞。","知君不羡鹤林神，但将诗作催花鼓。","饕风虐雨一扫空，国艳天香为君吐。","金刀盟在不敢寒，急走送君花满盘。","何郎要将汤饼试，不放枝头朝露乾。","樽虽有酒莫谩把，客未可人谁共看。","想当风暖月更白，流苏帐挂香团栾。","应笑老翁门寂寂，咫尺谁来草玄宅。","暗香和月与谁同，芳条委地无人摘。","春与幽姿似少情，雨打风翻漫狼藉。"]},{"t":"送舒永丰","f":"五言古诗","c":["斯民如草木，九圣含春温。","秋风一披拂，零落难重陈。","嗣皇回日御，杲杲升朝暾。","谁令天骄子，欲肆长鲸吞。","王师一倡乱，诸将皆星奔。","可怜尔群苍，终不负汉恩。","固亦念颠仆，所喜邦本存。","舒侯名家郎，翔鸾未腾鶱。","稍分民社寄，似欲亲拨烦。","盍敷宽大诏，力补疮痍痕。","勿谓蕞尔邑，安能著华轩。","妙割俱有用，鸡牛无足言。","君看密县宰，视民真子孙。","汗马无寸劳，太傅岂不尊。","扶衰其有意，愿复矜元元。"]},{"t":"次韵何君与晚晴","f":"七言律诗","c":["花深雨过一鸠鸣，唤起何郎对晚晴。","暮霭连山明白鹭，夕阳回处带啼莺。","浮生可笑能几屐，万事政须论一枰。","想得追随共飞盖，玉觞零乱酒催行。"]},{"t":"次韵刘元素暮春书怀","f":"七言律诗","c":["断肠风雨落花时，空遣刘郎赋柳枝。","涉世功名真蚁穴，送春歌吹只蛙池。","尚堪短策时乘兴，犹有寒杯可共持。","更愿馀生似东野，云龙无地不相随。"]},{"t":"次韵元素再用前作","f":"七言律诗","c":["春晴无复少年时，那作惊乌夜绕枝。","愿与君游云梦泽，不愁人夺凤凰池。","北窗付我常高卧，手板看渠自倒持。","拟伴遗民钓烟水，萧规真欲效曹随。"]},{"t":"元素将与余别再赋前篇因以留之","f":"七言律诗","c":["江头云雁欲飞时，倦翮依然在一枝。","少伫晚潮青版舫，共听朝雨绿荷池。","伯生醉熟惭空洞，梦得诗高有护持。","南浦分襟定何日，悬知清梦与君随。"]},{"t":"送元素","f":"七言律诗","c":["重来樽酒定何时，藜杖同谁把一枝。","雅量久知吞梦泽，高飞犹恨隔天池。","凌烟事业归骠骑，乐府歌行付总持。","自载笔床茶灶去，喜君风味似天随。"]},{"t":"次韵元不伐暮春再游俞氏园期任道卿刘长孺不至","f":"五言古诗","c":["素心失前期，幽事萦老念。","小筑犹未成，残年作逋欠。","五字俯见投，光芒肯收敛。","遐想徒意消，从游知礼僭。","流离兵盗馀，有籍犹未占。","尚想南冈花，依依弄残艳。","栖迟倘会意，往返殊未厌。","如何两公子，盟寒久无验。","我语良可删，公当为磨玷。","载酒苦未能，兹焉负深歉。"]},{"t":"春晚绝句二首 其一","f":"七言绝句","c":["春来白水欲平田，未拆鞦韆已禁烟。","伤雨落花空着地，倚风轻絮解漫天。"]},{"t":"春晚绝句二首 其二","f":"七言绝句","c":["鸟声时向静中闻，尽日阴晴漫不分。","庭下落花如落絮，眼前春思似春云。"]},{"t":"次韵张元明书刘氏草堂","f":"七言律诗","c":["草堂闻出碧鸡西，一色桃花去路迷。","有眼固应元自白，无腰略可为人低。","池塘看浴双凫雨，帘幕时衔燕子泥。","想得君家旧蓑笠，依然犹在太真溪。"]},{"t":"四月二十八日江元楷置酒坐客皆醉卧已而主人亦就睡戏作数语以纪其事","f":"五言古诗","c":["西园春事阑，歌管罢丝竹。","青钱落高榆，幽鸟啭空谷。","江侯不能闲，折简到吾属。","净扫南窗尘，共把一樽玉。","重觞各颓然，睡味久乃熟。","齁齁两鼻雷，艳艳当筵烛。","因知欢有馀，谁谓饮不足。","伟哉三玉人，曾不愧坦腹。","应怜俗子陋，礼法困窘束。","坐中饮湿生，起舞自成曲。","主人亦忘客，去留随所欲。","可笑陶渊明，欲睡客须逐。"]},{"t":"题张元明四鬼捕懒龙图","f":"七言古诗","c":["五月江南地无黍，帝遣雷师下行雨。","百神受职群龙奔，一龙藏头翳玄云。","雷师奋虬叱四鬼，拽取老龙朝帝阍。","张侯直气不可屈，云间睥睨旁怒嗔。","归来面壁聊一吐，画作新图走儿女。","潜虬怕死不肯行，夜叉飞天发毛竖。","人间空笑虎头痴，笔底风云遽如许。","今年雨足年亦丰，蜥蜴蝘蜓俱论功。","龙方下避千里赤，疾雷破柱颂天公。","天公有令那得尔，寄语痴龙莫辞死。"]},{"t":"次韵赵伯武病中即事五首 其一","f":"五言律诗","c":["卧疴念经时，勿药有新喜。","便应走骎骎，谁复称起起。","啸歌理壶觞，婆娑在窗几。","想当呼浊醪，与客谈妙理。"]},{"t":"次韵赵伯武病中即事五首 其二","f":"五言律诗","c":["赵侯佳公子，妙伎数三绝。","对君如春水，熇熇消内热。","一为药石误，良会能契阔。","便当亟相过，共此良夜月。"]},{"t":"次韵赵伯武病中即事五首 其三","f":"五言律诗","c":["爱酒知有癖，耽书久成痴。","官曹足馀暇，幽策约屡枝。","但恐蒹葭陋，缪倚琼玉姿。","况无弹丸手，突过黄初诗。"]},{"t":"次韵赵伯武病中即事五首 其四","f":"五言律诗","c":["病馀春巳归，飞花满空堂。","萱草欲成窠，戎葵粲微黄。","高门有贺客，新篘怯初尝。","人生贵强健，馀事亦渺茫。"]},{"t":"次韵赵伯武病中即事五首 其五","f":"五言律诗","c":["平生沈东阳，鹤骨俨如故。","朝来闻巾车，载酒定何处。","暮归坐东轩，翰墨有佳趣。","当持乌丝栏，为乞锦囊句。"]},{"t":"送费茂和二首 其一","f":"七言律诗","c":["谁言令尹拙催科，鞭朴当如岂弟何。","楼下久传于蔿曲，人间方唱纥那歌。","虎知低首须应杀，雉已将雏不可罗。","太史若书神爵传，慈祥未愧昔人多。"]},{"t":"送费茂和二首 其二","f":"七言律诗","c":["前贤零落谩知名，后辈何由识老成。","谁遣斯民俱卧辙，因知循吏本无声。","眼前公事何时了，月下清樽且复倾。","想得新栽池上柳，送君归棹亦多情。"]},{"t":"汪才任寺簿得刘遗民钓台于泾水之上将作小亭而未暇有诗次其韵","f":"七言律诗","c":["眼前时事只纷纷，林下谁来吊逸民。","断石至今留故物，赤栏何日照江滨。","飘流岁月人空远，料理风烟意转新。","拟借一椽垂短钓，此生真欲继前尘。"]},{"t":"秋暑卧病示庄簿","f":"五言古诗","c":["老火倏巳尽，金行殊未刚。","弱枣渐可剥，七月犹骄阳。","赤日不可向，白汗惊流浆。","谁将穷谷冰，为我濡枯肠。","况兹老病躯，息偃真在床。","敲秋赖风玉，微飙袭衣裳。","言念北征士，万里方拓疆。","秋云静边日，光耀剑戟场。","君今饱韬略，论事时抗章。","诸公颇动色，有策云甚良。","何当给锋车，结佩朝明光。","一鼓收关河，再鼓擒戎王。","兵戈既静洗，不复腥犬羊。","万夫各解甲，四海均清凉。"]},{"t":"雨后微凉再示庄簿","f":"五言古诗","c":["蓐收始用事，健行肃乾刚。","微飙生淅沥，一雨洗亢阳。","香罗阨团扇，玉椀辞蔗浆。","况蒙慷慨词，犹激卑懦肠。","当食忽亡匕，起立遂失床。","鸡鸣中夜兴，呼灯揽冠裳。","自从羯胡乱，四海失故疆。","向来桑麻区，半作荆棘场。","黔首未安堵，皂囊思献章。","闻有圯上书，今代谁张良。","风云须嘉会，日月依末光。","当宁方侧席，谁能荐吾王。","鸷鸟尚垂翅，老眼空望羊。","秋风一夕起，抚事增悲凉。"]},{"t":"观大阅","f":"五言律诗","c":["落日鸣笳鼓，西风卷旆旌。","熊罴千骑肃，锦绣一川明。","猛士方投石，将军未请缨。","不须誇剑舞，却縠是书生。"]},{"t":"复愁二首 其一","f":"七言律诗","c":["秋风袅袅秋云愁，寒日耿耿还西流。","昏鸦接翅带远水，暮雨满山昏北楼。","微凉渐欲入枕簟，白露复恐沾梧楸。","横戈壮士半茅土，云壑布衣悲素秋。"]},{"t":"复愁二首 其二","f":"七言律诗","c":["江南郡邑半成灰，江北诸藩信不来。","此日兵连殊未解，向来边衅复谁开。","三关故地何时得，二帝征銮几日回。","白发草莱无远策，时垂双泪只兴哀。"]},{"t":"次韵冯远猷夜雨屋漏有作","f":"五言古诗","c":["我昔在田间，秋霖伤岁熟。","常忧床床雨，夜下东屯屋。","饭牛起晨耕，短蓑聊栉沐。","违湿因五迁，劳形真仆仆。","坐歌南山粲，那惜清夜促。","平生小冯君，秀齿粲冰玉。","生馀华屋姿，岂识沾濡辱。","谁知折角巾，肯念滹沱轴。","会将秋雨谣，写入朱弦曲。","知君有过秦，妙画行见录。","衮衣坐法宫，当宁调玉烛。","吾庐虽独破，受冻死亦足。"]},{"t":"饮魏宗明家分韵得酒字","f":"五言古诗","c":["闭门苦秋炎，散发卧北牖。","小雨度微凉，西风飒衰柳。","起邀马服君，步过云中守。","云中雅好事，酌我玉卮酒。","诸公饮方豪，何曾问升斗。","而我才饮湿，已复困濡首。","臭味本自同，初何间能否。","不然琼瑶林，何以着老叟。","欢同一笑间，义重千载后。","脱弹无新诗，刻烛愧敏手。","诗成慎勿再，坐客惊欲走。"]},{"t":"感韩碑用李义山韵","f":"词","c":["长蛇封豕矜雄姿，弄兵三世窥皇羲。","自从胡骑入中土，侥倖岁月宽诛夷。","锦缠红帕五十载，肯输赤豹兼黄罴。","宪皇神算本天授，指顾不劳戈一挥。","元和上相拜元帅，黄金铸印手自持。","三军踏雪砍墉入，夜摩贼垒朝搴旗。","侍中西平老将种，属鞬拜舞行相随。","绯衣小儿却健武，未怕贼首如虎貔。","功垂竹帛不可掩，名在万古谁能訾。","行军司马号大手，苍珉承诏镵瑰词。","平生直笔有公议，从人乞米知羞为。","狗功须赖发纵者，尽勒殊勋归鼎司。","宫中小女强解事，敛祍雪涕垂丰颐。","絺章绘句随断裂，厖恩下沛惊淋漓。","空馀大雅配吉甫，春秋庙享存歌诗。","当时左右无谏者，应惭鸣佩趋龙墀。","襄阳太守独何事，殷勤自刻平吴碑。","将军更勒燕然石，蛮风瘴雨侵蟠螭。","张功耀武示万世，二子无乃为已私。","晋公纯德古未有，彊藩悍将亲平治。","群奸闻风胆为落，自奋老拳擒宛脾。","都人尚想白羽扇，野蔓已理黄绢词。","唐家晚岁事如此，谁令举世跻纯熙。","君不见郑公之死肉未冷，停婚碎石恩还追。","文皇英明犹复尔，功臣谁肯躬胼胝。","玉溪慷慨书万本，要识元老为邦基。"]},{"t":"寄题元具茨双梅庵","f":"七言律诗","c":["高节知公冠九州，梅花却对令君羞。","诗如往日陶彭泽，人是只今陈太邱。","挽得繁枝供宴坐，小分疏影入清流。","簿书堆里浑无事，玉雪香中醉即休。"]},{"t":"读东坡儋耳新诗","f":"七言律诗","c":["先生流落久居夷，属国前身事巳非。","万里岷峨空入梦，七年海峤不思归。","桄榔叶暗蛮村雨，荔子红垂瘴岭扉。","政坐诗穷关底事，云鹏谁道总卑飞。"]},{"t":"次韵时然惠徽州近作","f":"七言古诗","c":["庄侯四海习凿齿，鸾栖一枝亦聊尔。","沸镬那寻袁处州，独跨羸骖度徽水。","羊肠路绕十八坡，危磴天悬三十里。","扪参历井不复休，一握去天真有此。","军符夜下星火急，吏习文书日填委。","青山倥偬未可厌，方外周旋人有几。","坐看云生拄颊间，便恐诗成横槊里。","万壑千岩入句来，天遣江山助奇伟。","我昔经行五岭头，芙蓉峰高天正秋。","凄音怨曲不成调，细雨寒烟空复愁。","晓得新诗惊欲倒，句似当年山色好。","一生忍泪泣秋风，可笑区区郊与岛。"]},{"t":"题吕节夫园亭十一首 其一 云林堂","f":"五言律诗","c":["高情恶喧嚣，结屋傍空旷。","草堂寄云林，远目聊自放。","偃蹇良不疑，世情真可抗。","不知堂中人，谁同倚藤杖。"]},{"t":"题吕节夫园亭十一首 其二 半隐寮","f":"五言律诗","c":["显晦固有时，出处本同致。","乘流与遇坎，等是一戏事。","真隐了无心，宁须论朝市。","君看半隐名，是中有深意。"]},{"t":"题吕节夫园亭十一首 其三 岁寒披","f":"五言律诗","c":["山中与谁语，俗士不我过。","时携登山屐，闲上岁寒坡。","不知青女威，奈此苍官何。","从今桃李花，漫漫空复多。"]},{"t":"题吕节夫园亭十一首 其四 朝阳台","f":"五言律诗","c":["残月坏金枢，朝曦吐旸谷。","南台凌日观，杲杲明万木。","白露亦巳晞，桐阴转檐曲。","危坐读黄庭，想像巾一幅。"]},{"t":"题吕节夫园亭十一首 其五 众芳阁","f":"五言律诗","c":["草木有盛德，俗眼未易观。","幽姿不可见，微香在林间。","植我东篱菊，艺此九畹兰。","芳意似有知，为君笑朱栏。"]},{"t":"题吕节夫园亭十一首 其六 藤洞","f":"五言律诗","c":["云山渺无何，地胜馀草木。","苍藤饱风霜，夭矫作岩谷。","幽香出空洞，清樾交翠麓。","想时携客来，班荆对棋局。"]},{"t":"题吕节夫园亭十一首 其七 学圃亭","f":"五言律诗","c":["疏泉灌空畦，折柳樊小圃。","关心有幽事，寄意在衡宇。","但恐经纶人，兹焉忽高举。","慎勿厌荷锄，烟蓑湿春雨。"]},{"t":"题吕节夫园亭十一首 其八 卷书阁","f":"五言律诗","c":["机云佳兄弟，胸中几石渠。","万事资不理，三箧补有馀。","它时策高勋，已复得异书。","安用结飞楼，傍架时卷舒。"]},{"t":"题吕节夫园亭十一首 其九 舒啸轩","f":"五言律诗","c":["渊明磊落人，啾唧倦吟讽。","聊将舒啸声，一为洗喧閧。","寄言枭獍徒，请勿恣嘲哢。","君看半岭间，依稀有鸣凤。"]},{"t":"题吕节夫园亭十一首 其十一 容安轩","f":"五言律诗","c":["生理须几何，安分一枝足。","向来高明中，百鬼作祸福。","何如此衡茅，长年乐幽独。","慎勿将蜗牛，轻比蛮与触。"]},{"t":"金华老人分老潘点漆墨十月二十三日久雨新霁弄笔北窗戏作此语华严经云须弥山笔大海聚墨不能书写一字法门","f":"七言绝句","c":["老来窗几漫尘埃，谁与潘郎点漆煤。","一字法门书不得，又撩风月作诗媒。"]},{"t":"东窗对雪六言四首 其一","f":"词","c":["月观云台何处，瑶林玉树谁家。","幻成银色世界，雨此天女宝花。"]},{"t":"东窗对雪六言四首 其二","f":"词","c":["天净银潢渺渺，林寒玉佩珊珊。","有月时翻瑶草，无人来踏琼田。"]},{"t":"东窗对雪六言四首 其三","f":"词","c":["拥鼻驼裘不暖，浇肠蚁榼还空。","助我茶瓯玉雪，煎成石鼎松风。"]},{"t":"东窗对雪六言四首 其四","f":"词","c":["睡起山惊堆玉，诗成研欲敲冰。","飘瓦莫嫌碎点，打窗留伴寒灯。"]},{"t":"闻雪二首 其一","f":"七言绝句","c":["黄昏雪意未全成，寒入重衾晓更清。","风里未看穿幕片，梦中先听打窗声。"]},{"t":"闻雪二首 其二","f":"七言绝句","c":["朔风初唤梦魂回，晓枕时闻急雪来。","未有春衣堪换酒，明朝谁办送寒杯。"]},{"t":"次韵庄簿对雪","f":"七言律诗","c":["月姊云冠玉作肤，白鸾飞鞚下天衢。","欲酬平地雪三尺，正要浇愁酒一壶。","林下闭门须好句，庙堂调烛费嘉谟。","它时琼佩朝银阙，共醉寒江记老夫。"]},{"t":"读外舅高晋翁诗集","f":"五言古诗","c":["结发论人物，倾心慕老成。","扫门嗟齿暮，洗眼失冰清。","心苦弹冠懒，名应脱屦轻。","眼高空尔辈，醉熟自平生。","长啸苏门冷，微颦下蔡倾。","千兵森武库，五字筑诗城。","鲍谢篇章丽，阴何句法精。","聱牙徒自放，贞耀复谁旌。","草露功名薄，春云岁月更。","鸭头江自绿，马鬣墓还平。","踪迹荆襄在，文华剑佩荣。","尘编愁独把，清泪一纵横。"]},{"t":"吴几圣许分蜡梅栽二首 其一","f":"七言绝句","c":["林下幽姿恼杀人，书来分我月黄昏。","杜陵老子堪怜许，枉乞桃栽一百根。"]},{"t":"吴几圣许分蜡梅栽二首 其二","f":"七言绝句","c":["越罗新学染宫黄，不著红蓝一点妆。","移取綵衣歌舞树，莫教晓梦怨馀香。"]},{"t":"几圣以三诗寄蜡梅栽次韵 其一","f":"七言绝句","c":["寄将琢玉风前句，剪送和香雪后枝。","要识此花真面目，细看无色画中诗。"]},{"t":"几圣以三诗寄蜡梅栽次韵 其二","f":"七言绝句","c":["酿蜜成花此似难，移根深恨老来看。","丰肌弱骨须调护，可怕寒梢白露团。"]},{"t":"几圣以三诗寄蜡梅栽次韵 其三","f":"七言绝句","c":["惯见江边雪样梅，此根常恐自天来。","悬知老去醉中眼，便是姚黄花懒开。"]},{"t":"次韵沈给事对雪长句二首 其一","f":"七言律诗","c":["洒天飞雪被长峦，落絮萦风醉后观。","塞上餐毡公独记，月中回棹我知寒。","已书上瑞归天阙，又挽丰年到笔端。","悬瓠功名知有意，微生底处更求安。"]},{"t":"次韵沈给事对雪长句二首 其二","f":"七言律诗","c":["翠失千峰与万峦，烂银宫阙纵奇观。","楼空翠湿衣裘重，诗就风生齿颊寒。","聊与江山分绝致，浪陪樽俎问更端。","莫嗔郢曲无人和，七子风流负建安。"]},{"t":"韵庄时然徽州山下见梅三绝 其一","f":"七言绝句","c":["冻蕊寒梢也自芳，断桥深坞独闻香。","山中行处花吹面，马上归时诗满囊。"]},{"t":"韵庄时然徽州山下见梅三绝 其二","f":"七言绝句","c":["雪后花开人未归，津亭谁共把寒杯。","句中解道梅如雪，梦里可无人似梅。"]},{"t":"韵庄时然徽州山下见梅三绝 其三","f":"七言绝句","c":["春到梅梢雪作堆，庾郎愁眼为谁开。","白龟城里未曾见，徽岭句中浑寄来。"]},{"t":"雪将晴闻梅已有开者","f":"七言绝句","c":["腊雪自知春欲回，冻云元不耐朝晖。","便须急买寻山屐，莫放梅花一片飞。"]},{"t":"题雪堂大研一首","f":"七言古诗","c":["河间多书人共知，未见紫岩方玉池。","东坡老人上天去，流落人间君得之。","宝匣初开眼光眩，相约君家与同看。","麝煤霮䨴云满天，尺璧坚温玉微汗。","峨眉山高两苏出，自是斯文有秦汉。","先生著书书满家，晚得穷愁坐城旦。","只今虿尾人争传，异时龟趺不须断。","百年荣辱一梦馀，空与高人作奇玩。","安得大手揭阳君，为我铭此元宾研。"]},{"t":"次韵具茨老人观腊月十五日按兵","f":"七言古诗","c":["六花阵合红满川，鼓鼙声喧旌暗天。","锦裘绣帽不动鞭，腰鞬两弓谁更先。","城狐社鼠空百千，一呼辟易投戈鋋。","霹雳昼射蛟螭渊，妖星夜落蚩尤躔。","谷城老父书谁传，可为帝师策万全。","脱兔一出忽复旋，风声鹤唳惊虚弦。","常山蛇势孰后前，四头八尾屡变迁。","何止内政分轨连，部伍聊足相纠联。","势如漂石奔流泉，蒙冲未数浮江船。","三军不用呼飞燕，功成唾手岂待年。","长安贼平不改廛，万里玉关沉夕烟。","降王曳组未解缠，白麻晓下彤庭宣。","兵雄泽潞非公贤，谈笑自足空戎边。"]},{"t":"沈元用太守和具茨诗张元明两用其韵见邀同赋","f":"七言古诗","c":["汉阳胡骑嘶秦川，六龙御日升中天。","翠銮亲巡耀宝鞭，神武自作诸将先。","子阳盗据众万千，井中蛙腹不受鋋。","虎头谁敢当文渊，一洗万古空英躔。","风威巳落诸蕃传，上兵伐谋军贵全。","固应玉陛当周旋，朱幡犹此阅望弦。","安危以身谁肯前，愿扶国步整播迁。","劲兵出塞鏖祁连，长缨曳首来翩联。","尽驱酋长朝甘泉，未惭骠骑羞戈船。","先声旋下齐与燕，称觞拜舞呼万年。","黄童佩犊无征廛，农桑万里通人烟。","蓬头舞剑空腰缠，要分颇牧来藩宣。","古来千里制一贤，长城未必能防边。"]},{"t":"横溪小市再宿慨然有感","f":"七言律诗","c":["小市人烟南北头，清江贾客去来舟。","儿时风物依然在，老去光阴不奈愁。","可怜白发无好意，更对故城思旧游。","烟尘蓬勃兵火急，岁晚棹歌归去休。"]},{"t":"夜宿长林明日游仙坛宫","f":"五言古诗","c":["麻川过长林，路转无百里。","积雨断津梁，日乱十六水。","忽从冈阜间，稍得千家市。","凌晨上仙祠，遂作折屐喜。","水流自汪湾，山亦甚雄伟。","小邑颇下临，扰扰屯聚蚁。","一笑相与言，黄冠有仙子。","为言庭前菊，霜馀烂黄蕊。","采之制颓龄，可以坚发齿。","不须事虚旷，至道亦良迩。","神仙固可学，吐纳乃馀事。","斯言虽甚简，中亦含妙理。"]},{"t":"星源逢仲共兄弟别后道中奉寄二首 其一","f":"七言律诗","c":["晓色凄迷客梦长，贾胡留滞更他乡。","自随匹马家千里，眼见故人天一方。","霜落驼裘朝着帽，雨来山驿夜分床。","与君相别无多日，已听鸣鸿欲断肠。"]},{"t":"星源逢仲共兄弟别后道中奉寄二首 其二","f":"七言律诗","c":["十年四海不解甲，一日三秋更忆君。","别后光阴逐流水，老来踪迹似浮云。","心怀丘壑情虽在，眼暗风尘首重分。","满眼尚添新战骨，何年真起故将军。"]},{"t":"苦寒二首 其一","f":"七言律诗","c":["朔风吹雪天漫漫，厚地欲裂江水乾。","悬知北客未省见，太古以来无此寒。","冰檐垂笋风撼屋，布衣生棱体生粟。","老翁炙手厌朱门，明朝晨暾更堪曝。"]},{"t":"苦寒二首 其二","f":"七言律诗","c":["天容黯惨悲风吹，寒日欲出寒云垂。","千门昼闭人迹绝，万里长空鸟不飞。","豺虎号寒声怒急，行人指堕毛为立。","易水风高燕地寒，白头书生望云泣。"]},{"t":"具茨老人读书寮","f":"七言古诗","c":["具茨四壁无斗储，载行书多常满庐。","胸中嵬垒几石渠，三箧补亡无复馀。","起居谁不解何如，校书著作虚诏除。","元元本本穷古初，雌黄付与金银车。","朅来穷山岁三徂，催科政拙民力苏。","黄童佩犊耕菑畬，戴白未见空欷歔。","焚香晏坐临绮疏，三年不识园中蔬。","迩来结屋聊卷舒，手抄平生未见书。","曼倩两目如悬珠，四十四万何多欤。","较公所得无锱铢，门生校雠谁与居。","我欲从公路郁迂，著鞭何时跨蹇驴。","不求奴饭马青刍，得公奇字归自娱。"]},{"t":"送元具茨归黄山","f":"七言律诗","c":["元祐宗师数圣朝，两公分路久扬镳。","具茨人物真奇伟，双井风流未寂寥。","可怪鲁山犹簿领，不应聱叟是渔樵。","何时收拾江湖句，归作歌诗补舜韶。"]},{"t":"乞蜡梅 其一","f":"七言绝句","c":["老翁真是可怜人，却觅花医病眼昏。","乞取疏枝更疏蕊，莫论桃叶又桃根。"]},{"t":"乞蜡梅 其二","f":"七言绝句","c":["腊尽冰消未见时，春风应入近南枝。","悬知老树开花早，苦恨幽人得句迟。"]},{"t":"秀淮亭晚眺","f":"五言律诗","c":["未得三吴去，东来且过淮。","要须烦晓浪，聊为洗风霾。","飘泊从人笑，穷愁费力排。","平生临水意，老去若为怀。"]},{"t":"次韵赵师是题乌江连云观二绝 其一","f":"七言绝句","c":["项王才器固无双，秦鼎虽轻可独扛。","丰沛故人如不用，济师犹得问长江。"]},{"t":"次韵赵师是题乌江连云观二绝 其二","f":"七言绝句","c":["连云台上倚阑干，着眼何妨尽日闲。","公子胸中有云梦，更须为助借江山。"]},{"t":"送潘择之尉南巢","f":"七言律诗","c":["潘郎胸中有文艺，白发青衫初试吏。","少年欲射汉庭策，晚乃去作南巢尉。","寒厅结屋八九椽，导骑挽弓三数辈。","但愿君如梅子真，人物风流亦何愧。"]},{"t":"题善应师毋我庵","f":"七言律诗","c":["今君无我亦无人，谁识毗邪妙悟身。","宴坐只应山是伴，夜禅唯与月相亲。","支郎好马元成癖，懒瓒垂洟却是真。","更待众生总无病，万金良药不妨神。"]},{"t":"元夕访忍毋我已睡复起","f":"七言律诗","c":["残缸零落数枝红，春在空濛薄雾中。","月似冰轮人似玉，车如流水马如龙。","山僧睡起三更后，游客闲来一笑同。","明暗短檠君莫厌，此灯无尽法无穷。"]},{"t":"次韵忍毋我春日三绝句 其一","f":"七言绝句","c":["暖入平林啭鸟雏，日烘花气满庭隅。","道人元不关春事，肯把新晴饷客无。"]},{"t":"次韵忍毋我春日三绝句 其二","f":"七言绝句","c":["雨馀绕屋一渠水，日落满帘何处山。","我亦时来开病眼，怕将春色照愁颜。"]},{"t":"次韵忍毋我春日三绝句 其三","f":"七言绝句","c":["春意全灰病后心，粥鱼斋鼓听禅林。","鸟啼南岭梦初断，花发故园人懒寻。"]},{"t":"灯下读韩致光外集","f":"七言律诗","c":["吴宫花草弄纤柔，西子妆成特地羞。","笑我老情难妩媚，爱渠好句尽风流。","香奁诗在人何处，断腕名高事已休。","更欲与谁论此恨，遗编读罢一灯留。"]},{"t":"春寒","f":"五言律诗","c":["寒意苦未解，春阴连昼霾。","文书堆午枕，风雨闭寒斋。","花落空惊眼，愁多欲满怀。","客情须一醉，安得酒如淮。"]},{"t":"试湖阴徐道久笔","f":"七言古诗","c":["山中三窟遭荡焚，十年遗种无礽云。","管城已老既谢事，柔毛遂出收微勋。","骚人手握奴隶管，人间自此无莸薰。","徐生晚出颇自喜，妙伎天与人皆闻。","羝羊退舍栗尾避，族非东郭不肯论。","往岁江南说诸葛，至今有口皆能言。","眼前厚利聊取足，身后典刑宁复存。","骍牲自是犁牛出，忠臣岂但孝子门。","古来取士贵阀阅，未必元成俱有孙。"]},{"t":"送孙秀才兼寄达道人","f":"七言律诗","c":["当年御史凛霜风，见说金狨玉面骢。","汗简有名知不朽，皂囊无稿岂非忠。","梦思故国兵犹满，身落它乡路更穷。","只有老禅真具眼，识君应在典型中。"]},{"t":"鰔鲊","f":"五言律诗","c":["放箸朝盘空，食指昨夜动。","软玉开香包，桃花点春瓮。","平生江瑶柱，异名寔同用。","何当登禹书，永作淮海贡。"]},{"t":"淮寇及境而退喜甚成诗","f":"五言律诗","c":["近喜横戈寇，南来偃旆旌。","濒江犹树栅，带甲谩持兵。","夜柝初寒枕，春田已趣耕。","使君今尚父，应便是长城。"]},{"t":"题米元章祠堂","f":"七言律诗","c":["绣溪遗迹巳茫茫，父老时能说漫郎。","苍碣尚馀唐翰墨，古祠犹是晋衣裳。","旌旗还向江湖老，檐庑空悲草木长。","我亦敢持寒具手，为公来炷影前香。"]},{"t":"次韵魏定甫早春题咏五首 其一","f":"七言绝句","c":["腊雪初晴梅欲花，有人闻说鬓如鸦。","清诗勾引江南梦，应向今宵还到家。"]},{"t":"次韵魏定甫早春题咏五首 其二","f":"七言绝句","c":["三十六番风未回，微红难倩剪刀裁。","魏侯句里有春色，不打凉州花自开。"]},{"t":"次韵魏定甫早春题咏五首 其三","f":"七言绝句","c":["雨后桃花可意红，一川杨柳醉春风。","舞衣歌扇重撩理，百尺朱楼烟树中。"]},{"t":"次韵魏定甫早春题咏五首 其四","f":"七言绝句","c":["白头憔悴未归身，羞作须江入社人。","自是愁多无好句，不关诗瘦与伤春。"]},{"t":"次韵魏定甫早春题咏五首 其五","f":"七言绝句","c":["柴扉春亦借融和，客少高轩谁肯过。","醉里我应惭毕阮，诗中君合是阴何。"]},{"t":"正月十八日谒客意甚不乐已而过正师犹未起书小诗窗间而已","f":"七言绝句","c":["玉壶花暖日烘窗，夺我寒衾晓梦长。","惭愧高人方拥鼻，小炉沉水宿残香。"]},{"t":"张老借东轩昼睡","f":"七言绝句","c":["谁言知处是闲愁，一入华胥万事休。","借得东轩还宿愿，何须云梦泽南州。"]},{"t":"畦蔬一首","f":"词","c":["猗嗟老人，如水中槎。","携壶挈榼，泛宅浮家。","飘然北来，寓此一蜗。","食无畎亩，衣无桑麻。","藜苋满腹，杂以蚬虾。","以鼓我腹，妻孥笑哗。","旅人之食，岂曰不腆。","不足则求，我颜亦腼。","乃即舍隅，蒿莱是剪。","艺此春蔬，侵畦覆畹。","雨叶风枝，忽其满眼。","撷之掇之，以芼以烹。","聊以当肉，亦足彭亨。","摇喉泽吻，茹菹啜羹。","如天酥酡，饭在家僧。","彼哉膏粱，孰为重轻。","安得长江，载扬我舲。","买地五亩，抱瓮躬耕。","驾言聿归，以毕馀生。"]},{"t":"解人敦武郎富君为余言解池广二百里其利不赀又有六小池官虽置戍以为厉禁而民寔擅其利或悉以属县官则盐不复成其事颇怪作小诗以纪之","f":"七言绝句","c":["天意悬知损有馀，小池分水计非疏。","谁知当日萧丞相，亦解区区说海鱼。"]},{"t":"春日小诗三首 其一","f":"七言绝句","c":["乱离回首又春风，江上人家一半空。","燕子多情依旧舞，桃花无语可怜红。"]},{"t":"春日小诗三首 其二","f":"七言绝句","c":["乌鸢衔纸欲成窠，寒食羁愁不奈多。","梦到鹿门亲上冢，花前老泪欲悬河。"]},{"t":"春日小诗三首 其三","f":"七言绝句","c":["兵戈无地可窥临，风物依然恼客心。","未有莺时春欲尽，已无花处绿成阴。"]},{"t":"抄宛邱先生集见和许贵州诗因以悼之","f":"七言律诗","c":["台阁诸公尽要途，一麾新拜岭南除。","当时为我歌新句，别后何人哭讣书。","梦断世间青琐闼，醉倾天上碧琳腴。","平生交旧晁张辈，馀子纷纷可作奴。"]},{"t":"米元章为须江太守闻有怪石在河壖莫知其所自来人以为异而不敢取公命移置州沼为燕游之玩石至而惊遽命设席拜于庭下曰吾欲见石兄二十年矣闻者以为言坐是罢去余游濡须而石犹在询之邦人信然乃作此诗","f":"七言古诗","c":["漫郎与世苦不偶，俶傥如公世安有。","平生学书笔似锥，晚岁得州大如斗。","淮西道院长江边，天公付与公高眠。","使君闭阁作奇字，门前白浪春风颠。","人言异石天所出，三十六峰如洞天。","亟呼我兄更再拜，俗眼相看颇惊怪。","唤钱作兄真可怜，唤石作兄无乃贤。","望尘罗拜良可笑，米公拜石不同调。","愚智相悬乃如此，何啻人间三十里。","是非从古无公论，彼此相笑何时巳。","巉岩对客初不言，尧桀纷纷渠自尔。"]},{"t":"芍药今岁着三花","f":"七言绝句","c":["春归那肯为侬留，尚有三花慰客愁。","十里红楼卷珠箔，不知谁在古扬州。"]},{"t":"群山台暮雨","f":"五言古诗","c":["杰观凌寒江，朱栏俯平野。","群峰江上来，屹立罗万马。","山容多态度，显晦入模写。","朝云结烟鬟，翠色远相射。","夜月横脩眉，娟娟亦闲雅。","天生此尤物，政复为闲者。","冯夷翻怒涛，汹汹激风榭。","神女亦将云，时从楚台下。","造物出奇杰，娱客助挥洒。","时方苦积潦，百里无十舍。","我虽非官曹，对酒那忍把。","人生急行乐，有味如啖蔗。","悲喜有乘除，归愁耿长夜。"]},{"t":"须江暮春杂题三首 其一","f":"七言律诗","c":["三月阴晴江上天，江花落尽水平川。","红蚕老去桑垂椹，黄鸟飞来柳扑绵。","千里心常悬梦里，十分春总在愁边。","时时更谢苏司业，乞与杖头沽酒钱。"]},{"t":"须江暮春杂题三首 其二","f":"七言律诗","c":["须江旧事与谁论，万古悠悠入夕曛。","楚子名今推伍伯，阿瞒功独盖三分。","空埋冶父山边骨，已散濡须坞口军。","欲为英雄吊遗迹，笔头无古战场文。"]},{"t":"须江暮春杂题三首 其三","f":"七言律诗","c":["淮上风埃满客衣，二年楼阁送斜晖。","心如落絮随风去，春与残花作伴归。","塞外夕烽悲鼓角，江边飞雨湿旌旗。","只今便觅东皋路，巳失南山种豆期。"]},{"t":"寓舍杂题三首 其一","f":"五言律诗","c":["久作乘风去，重寻听雨眠。","更无轻絮落，又见小荷圆。","芍药何人种，茂葵一笑妍。","乱离归未得，且复此经年。"]},{"t":"寓舍杂题三首 其二","f":"五言律诗","c":["老去书中得，心因病后衰。","栖栖身是梦，种种鬓成丝。","鸟自知时节，人犹说乱离。","倚楼天万里，无地置吾锥。"]},{"t":"寓舍杂题三首 其三","f":"五言律诗","c":["客路犹飘泊，江山未定居。","卖刀安得犊，弹铗竟无鱼。","一饱非难事，平生不愿馀。","但能休旅枕，便可税征车。"]},{"t":"客舍有井极深而寒今岁大暑日汲以供盥濯喜甚赋此","f":"七言古诗","c":["重廊阴阴与天隔，下有井泉馀百尺。","乍垂修绠已复寒，深注花瓷不胜白。","山城夏旱百井眢，盥濯从谁问涓滴。","暮年来此看老黥，日倚银床卷深碧。","炎官火伞空自张，玉川清风已生腋。","翰林醉熟呼不醒，宫中谁赋花娉婷。","中人传诏玉起立，井花吹面诗还成。","诗成白雪真同调，咫尺回姿妃子笑。","此郎自是醉谪仙，肯作官家诗待诏。","北窗老子贪昼眠，蓬头突鬓良可怜。","但将饱睡答长健，安得新诗追昔年。","我生无誉亦无毁，老去功名薄如纸。","日向山堂洗睡容，空费君家一壶水。"]},{"t":"六月十二日过笑庵道人颇出近诗二首 其一","f":"七言绝句","c":["无人与作绣川游，共看荷花一雨秋。","乞得道人三昧句，破除千斛庾郎愁。"]},{"t":"六月十二日过笑庵道人颇出近诗二首 其二","f":"七言绝句","c":["来寻午枕林间梦，分得羲皇窗底风。","且与笑庵同一笑，不知家在大江东。"]},{"t":"笑庵两和前韵复作二绝 其一","f":"七言绝句","c":["莫把须江作浪游，笑庵如水气如秋。","但知有道能忘我，便恐无天可寄愁。"]},{"t":"笑庵两和前韵复作二绝 其二","f":"七言绝句","c":["新诗时出笑谈中，清似松江夜雨风。","邂逅碧云来入句，老夫真欲愧辽东。"]},{"t":"徐使君送冰","f":"七言古诗","c":["江南地暖不藏雪，六月无冰破烦热。","俱在炎官火伞中，暍死行人不堪说。","今年渡江当入淮，淮人荫子恰复开。","眼明一见玉壶面，仿佛肺腑无尘埃。","使君忽遣铃下走，金盆分似来铃斋。","方圭圆璧不可数，玉峰中立高崔嵬。","蔗浆退舍不入口，井花避席当停杯。","我生坐甑安得此，借以清风亦聊尔。","明年公复侍甘泉，御府分光照窗几。","却忆敲冰饷野人，回望江城在千里。"]},{"t":"寓秀师房","f":"七言律诗","c":["寂寂疏窗秋更催，班班菊蕊为谁开。","山曾有约终相负，鸟解嘲人怪复来。","阅世了知心是梦，倒床须放鼻如雷。","又从白足西庵老，共试斋馀双井杯。"]},{"t":"雨过凉甚","f":"七言律诗","c":["龙脚蜿蜒苦未收，乱云携雨过西州。","倚栏斜日到烟树，回首数星横夕楼。","乐岁岂关羁客事，好风聊为老人留。","今宵枕簟凉如水，又向华胥作烂游。"]},{"t":"望黄山","f":"五言古诗","c":["宿云忽解驳，晓色明朝暾。","高秋寓远目，万象秋毫分。","群峰杂遝来，突骑从横奔。","骅骝独骧首，迥出凡马群。","嵩高实维岳，罗列如儿孙。","玉京与金阙，亭亭在云峦。","群仙骖苍虬，冠佩朝至尊。","往者风露夕，妙奏闻清圆。","名理以弦歌，异事父老传。","丹成已仙去，流脉在山根。","至今兹山下，幽泉湛馀温。","安得从浴沂，聊以濯我冠。","一沐去尘土，再沐生羽翰。","朝游参安期，暮躅追羡门。","振足八荒外，垂手青云端。"]},{"t":"次韵郑使君白菊","f":"五言古诗","c":["平生郑康成，不种花婵娟。","但闻书带草，罗生满堂前。","佳菊苦解事，殷勤为公妍。","红油护霜日，一笑真嫣然。","秋风转寒枝，束素争回旋。","团栾立芳砌，皎若璧月圆。","使君颇牧手，年来出临边。","燕衎自折冲，宾从时招延。","苦爱白玉姿，临风嗅芳鲜。","扬州东阁梅，自此复谁怜。","安得白云词，写入朱丝弦。","渊明眼独醒，载酒知谁先。","骚人茹精蕊，世尘聊自蠲。","幽姿倏已空，二士穷益坚。","人生五马贵，行乐须何年。","绝胜杜陵老，江花恼成颠。","才名与富贵，似公真两全。","新诗如脱弹，一出万口传。","锋车行复来，琬琰殊未镌。","且当对香雪，燕寝凝沉笺。"]},{"t":"次韵远猷旅夕二首 其一","f":"七言律诗","c":["西风满眼莫登楼，回望乡关去末由。","晚色不催金络马，夜灯空梦玉搔头。","梁王行识相如赋，楚国方悲宋玉秋。","万里长途知不晚，一杯聊为老人留。"]},{"t":"次韵远猷旅夕二首 其二","f":"七言律诗","c":["久占无何作醉乡，人间万事只逢场。","潘郎已老谩华发，梦得多情还断肠。","政恐新愁无处着，不知清夜为谁长。","烦君试草思归曲，付与蛾眉小抑扬。"]},{"t":"王将军以李伯时二马遗张天民","f":"词","c":["龙眠笔意天与妙，尺素幻出双骅骝。","一马不动尾，四蹄踣铁边风秋。","一马争前趋，平坡欲下方回头。","两马交颈万里愁，龙媒未免羁长秋。","风鬃雾鬣不受囚，锦鞯坐遣驽骀羞。","将军六郡良家子，卷送归君深有意。","蹶如历块一过都，使恐谈笑无狂胡。","人间岂有渥洼足，不与天骥争长途。","草黄沙晚天欲黑，纵有权奇少人识。","眼中千里不易得，时危愿尔一努力。"]},{"t":"须江雨中","f":"七言绝句","c":["须江楼上倚秋风，草树荒凉故垒空。","吹尽角声人不见，画桥和雨系艨艟。"]},{"t":"择之得鹿割鲜见饷以诗为谢","f":"五言古诗","c":["潘郎尉居巢，月止万钱俸。","遥怜寒孟郊，午食勤夜诵。","空庖无鸡豚，敢设亚父供。","如何得伊尼，割鲜勤远送。","老夫极惊喜，儿曹亦嘲讽。","悯我太常斋，此意君良重。","饥肠罄一饱，状若蹲鸱冻。","茅檐坐局促，山禽听晓哢。","安得随少年，短衣飞挽鞚。","烧野得惊麋，即之那忍纵。","呦呦寒声微，麌麌一矢中。","聊复从左盂，猎我江南梦。"]},{"t":"秋意三首 其一","f":"五言律诗","c":["雨细方淋露，云疏欲护霜。","老情常落莫，秋物半青黄。","榆塞弓窥月，天田马犯疆。","防城江上急，时节近重阳。"]},{"t":"秋意三首 其二","f":"五言律诗","c":["老去何曾健，秋来白发新。","万方多难日，四海独愁人。","论愧倾三耳，年今已六身。","太平犹眼见，知复几青春。"]},{"t":"秋意三首 其三","f":"五言律诗","c":["病骨骎骎老，清愁日日深。","寒添青士节，霜与木奴金。","迹共云无定，愁随月满林。","幽虫泣床下，可是不知心。"]},{"t":"次韵远猷东池晚思","f":"五言律诗","c":["多事冯公子，含情不奈秋。","东池寄飘泊，画舫信夷犹。","烽尚连三月，诗应拟四愁。","且须倾酒椀，未可唤归舟。"]},{"t":"次韵元素见寄二首 其一","f":"七言律诗","c":["秋来烹鲤得明珠，颇胜当年获异书。","里社相从真是伴，江湖作计未全疏。","愁须强把樽中蚁，老亦宁思组上鱼。","回望花姑溪北墅，可能无路到华胥。"]},{"t":"次韵元素见寄二首 其二","f":"七言律诗","c":["人间何处不蘧庐，匹马来游偶束书。","晚岁光阴频入梦，雁来消息莫相疏。","淮南乘兴非关米，箸下烹鲜喜有鱼。","避地偷生落闲处，功名无复似包胥。"]},{"t":"次韵王彦猷参谋避胡山中寄茶字韵诗卷二首 其一","f":"七言律诗","c":["诗如摩诘自名家，未数刘颠赋雪车。","问字谁携子云酒，敲门拟送玉川茶。","回头拾得风前句，扫地先除眼界花。","老去无缘浑似梦，相随真欲问毗邪。"]},{"t":"次韵王彦猷参谋避胡山中寄茶字韵诗卷二首 其二","f":"七言律诗","c":["扁舟流浪作浮家，病齿凋零脱左车。","千里归心秋后燕，一年春事雨前茶。","它时我自开三径，此去君当判六花。","相见已还平日愿，豚蹄何用祝污邪。"]},{"t":"绣溪秋晚二首 其一","f":"五言律诗","c":["羁客三年别，风裘九月寒。","暮鸦啼日落，红叶坠霜乾。","地接淮山远，天浮楚服宽。","须江无父老，旧事说曹瞒。"]},{"t":"绣溪秋晚二首 其二","f":"五言律诗","c":["不作黄花梦，空悲紫塞秋。","泪悬江上点，心结雨边愁。","久客犹千里，残年念一邱。","倚栏多少恨，暝色满江楼。"]},{"t":"历阳道中二绝 其一","f":"七言绝句","c":["斜照孤村一水闲，维舟尽日柳阴间。","此生已作淮西梦，更看江南隔岸山。"]},{"t":"历阳道中二绝 其二","f":"七言绝句","c":["江边孤垒古濡须，憔悴斯民百战馀。","赖有丰年慰羁客，软炊云子荐鲈鱼。"]},{"t":"将别须江作","f":"七言律诗","c":["落叶江头枫树枝，秋风又入去年衣。","淮南米贱聊乘兴，笠泽鱼肥却念归。","老境但知随物化，幽期常恐与心违。","群山堂下山干点，不见祠云作雨飞。"]},{"t":"九日郡楼独坐","f":"七言律诗","c":["西风斜日可怜秋，已作重阳更上楼。","门外白衣来独晚，坐中司马醉应休。","茱萸香在人何处，黄菊花开泪欲流。","山意娱人不胜好，苦无佳句若为酬。"]},{"t":"过雨二首 其一","f":"五言律诗","c":["短日收残雨，西风送夕阳。","时光双去鸟，世事一炊粱。","卷箔山堆案，翻书月满囊。","诸君方给札，不拟献长杨。"]},{"t":"过雨二首 其二","f":"五言律诗","c":["自落山边日，孤飞雨后云。","树将风报客，天遣月争曛。","诗苦穷堪忍，胡强老怕闻。","残更随梦尽，长日与愁分。"]},{"t":"次韵黄子才野步饭怀禅师道场","f":"五言古诗","c":["闻说寻山屐，闲穿近郭村。","眼明山净绿，心爱水清喧。","幽事付馀日，狂歌终放言。","地经殊代远，名为老僧存。","境胜醒朝梵，蔬甘饱夕飧。","僧应只灵运，客或是文园。","觅句闻吴咏，投文吊楚魂。","梦时惊远籁，背喜曝微暾。","历井窥云窟，穷山绕石根。","蹇驴当复跨，促席未容温。","儿辈休嗤点，吾曹自引援。","浊醪聊共把，蠹简付重论。","归和山中句，挑灯老眼昏。"]},{"t":"十六夜月色甚明与客棹舟至普宁寺","f":"七言古诗","c":["昨宵明月共千里，今夕极天无一云。","不知谁令太虚空，着此皎皎白玉盆。","长空与月慰愁眼，良夜得酒含微醺。","天公有约不可负，急荡两桨凌江濆。","更携江上满船月，来打寺下三更门。","脩廊夜寂风叶乱，古佛不语残膏存。","老禅今夕但拍手，狂客数辈空馀樽。","高谈剧语天亦怒，白璧故遣云相吞。","人言祸福真倚伏，欢常有馀饮不足。","篙师促客归去来，夜半风颠浪如屋。"]},{"t":"朝盘二首 其一","f":"七言绝句","c":["郭索何人捕草泥，朝盘新见玉团脐。","却思烟雨江南夜，红火青蓑入稻畦。"]},{"t":"朝盘二首 其二","f":"七言绝句","c":["江近秋深足鲙材，半青橙子带香开。","黄金鳞鬣丹砂尾，落纸看成白雪堆。"]},{"t":"砖炉","f":"五言古诗","c":["秋风吹孤鸿，浩荡去乡国。","心悲淮山秋，家近楚江侧。","囊无狐白裘，奈此风雨夕。","经营尺寸地，便可寄幽寂。","砖炉规旧制，蒲团买新织。","虽无琢兽红，可醉珠履客。","会当与狸奴，曲肱分坐席。","急雪度寒飙，夜窗鸣淅沥。","诗成几醉梦，残缸耿虚壁。","何必游八关，吾手自可炙。"]},{"t":"山鬼行","f":"七言律诗","c":["黑风夜度鹙鸧高，黄狐出窟山鬼号。","江空人静雪飞急，城头击柝催鸣刁。","老翁愁寒小儿哭，薪如黄金米如玉。","将军半醉猎城南，铁马敲冰响山谷。"]},{"t":"次韵明叔九日见怀","f":"七言律诗","c":["准拟重阳共一杯，幅巾临水复登台。","飞花扑面君相送，落叶满山人未回。","故国只凭幽梦到，断肠频寄尺书来。","此生终向江湖老，黄菊红萸笑谩催。"]},{"t":"十月十九日江晴放舟","f":"五言律诗","c":["云静天无滓，霜晴日乍暄。","风平初放缆，江稳自流船。","贾客眠吹笛，篙工坐意钱。","吾行聊尔尔，百丈莫频牵。"]},{"t":"雪后殊未有梅颇怀故山二首 其一","f":"七言绝句","c":["淮山落莫水苍茫，雪在梅梢冷欲僵。","要与玉奴苏冻骨，不知谁有反魂香。"]},{"t":"雪后殊未有梅颇怀故山二首 其二","f":"七言绝句","c":["真色生香无世尘，参横犹记梦回人。","风前懊恼梅花使，不寄江南一点春。"]},{"t":"王静翁言客有赋食虎肉诗者词甚壮要余同作","f":"七言古诗","c":["六郡良家家好武，相试翘关来征虏。","夜从恶少数十辈，醉上南山缚骁虎。","短衣匹马不挽强，虎而有翼谁敢当。","旁观睥睨方缩手，一脔割鲜君巳尝。","平生饮血如甘露，羞作车中三日妇。","但当一饱不摇喉，谁说万钱难下箸。","寝皮食肉君勿嗔，虎为人害当复去。","可笑长杨射猎儿，日暮归来数狐兔。"]},{"t":"次韵黄子才冬至日醉卧王丞家梦还家如平时","f":"五言古诗","c":["黄郎本天才，骥足尚少屈。","平生嗜烟霞，投老成痼疾。","乞食方叩门，携幼未入室。","何为作斯游，瘦马醉自兀。","朝饥乃见驱，妙思何由逸。","诵君思归吟，感我羁旅日。","道涂颇风埃，岁月苦飘忽。","尚须营一饱，不愁屈两膝。","可怜蓬阁姿，未珥螭头笔。","丞哉苦风流，威令宽且栗。","悬知千里驹，肯为牢之出。","胡为倚寒窗，清梦恍若失。","但愁一线红，又过白驹隙。","妇眉谁与画，旅发归亦栉。","咿嘤儿女欢，馀事听造物。"]},{"t":"次韵赵茂卿书事","f":"七言律诗","c":["自昔人高马服名，胸中有策似金城。","玉阶方寸何由借，榆塞风尘几日清。","万里有家无梦到，一樽和泪与谁倾。","竹西回首扬州路，肠断故园春草生。"]},{"t":"王彦猷用色字韵见贻和答","f":"五言古诗","c":["人生殊用舍，初不系失得。","念君垂天鹏，未作六月息。","佳人绝代姿，蛾眉本倾国。","人皆倚市门，孰乃有国色。","风云倘复遇，富贵或见逼。","一朝得天骥，遂可空冀北。","况今登俊良，百吏归黜陟。","洗眼看横飞，故山勿轻忆。"]},{"t":"冶父寺","f":"五言古诗","c":["楚俗乐战斗，征诛专莫敖。","蛇豕肆吞噬，一举夷蒲骚。","小器良易盈，举趾凌云霄。","轻敌取败衄，缢死由矜骄。","浅识耻邓曼，安在誇雄豪。","至今冶父山，遗迹真寥寥。","何年化龙宫，金碧争岧峣。","耽耽群于菟，跪伏尾自摇。","乃知道力妙，智数何能高。","曩者罗与楚，蚁忿较一朝。","慈哀洗万劫，自足消兵刀。","道人结界地，远引离喧嚣。","欲礼大士塔，恨无野僧包。","临风一怅望，短发空爬搔。"]},{"t":"贾主簿家蜡梅","f":"七言绝句","c":["腊月边城风雨沙，带香谁剪蜡梅花。","寒灯枉作江南梦，春在墙东主簿家。"]},{"t":"仆将南归笑庵以诗见留次韵","f":"七言律诗","c":["思家一日似三秋，病眼凄然怯上楼。","十幅风蒲催我去，数枝烟竹为君留。","还将晓枕灯前句，分作孤蓬雨后愁。","便合北来寻老伴，人间何处有汤休。"]},{"t":"挂席","f":"五言律诗","c":["挂席下晴江，归从我北窗。","年今真晼晚，事亦付奇厖。","酒可浇肠饮，胡谁缓颊降。","买田如有路，誓欲老吾邦。"]},{"t":"归自须江泊舟于湖舟中书事","f":"五言古诗","c":["一自胡尘起，飘零十载过。","危情窘荆棘，老眼暗干戈。","草草真聊尔，栖栖可奈何。","功名麟阁晚，兴在鹿门多。","避地依淮浦，伤心听楚歌。","边烽明夕峤，戍鼓击寒波。","江控曹公坞，山连冶父坡。","凭高怀更远，吊古事应讹。","久客横归棹，长年着短蓑。","风高饱帆腹，潮稳转山阿。","渐喜乡音似，还成醉脸酡。","凄凉想茅屋，留滞厌江沱。","井邑疏星火，津亭长薜萝。","连樯自来往，坏壁本嵯峨。","蜂目今何在，黄须迹巳磨。","馀生能几屐，急景付飞梭。","岁熟如堪隐，诗成可自哦。","平生南亩愿，无地与婆娑。"]},{"t":"复故庐一首","f":"词","c":["我卜我居，于城之隅。","缭以群山，带以清渠。","日出扶桑，月翳金枢。","朝云夕烟，变灭卷舒。","乔木丰草，蔚其周庐。","群书在床，浊酒在壶。","蹒跚簪裾，亦复晏如。","淮水之游，谁脂我车。","逮其归而，四壁其徒。","柔柯既剪，稚竹日疏。","山为改容，木为槁枯。","吾亦浩然，言念归与。","今我来思，为之踌躇。","扊扅在门，鞿靮在涂。","驾言曷归，杜门寔娱。","寒止皲瘃，饥止瘠臞。","人谁不死，焉识其馀。"]},{"t":"雪后留报恩方丈三绝 其一","f":"七言绝句","c":["文脊坊边雪作堆，报恩溪上冻全开。","一天云叶卷风去，四面玉峰攒马来。"]},{"t":"雪后留报恩方丈三绝 其二","f":"七言绝句","c":["浇睡莫教茶乳薄，留香不放画帘开。","道人知我无馀事，特为寻诗借榻来。"]},{"t":"雪后留报恩方丈三绝 其三","f":"七言绝句","c":["老禅心地已如灰，愁眼能令一笑开。","落日无情且归去，梅花若在却须来。"]},{"t":"张元明罗仲共赋郡池白莲仆时在淮西十二月中休方德脩始出巨轴追和","f":"七言律诗","c":["花似当时傅粉郎，不须汤饼试新妆。","固知桃李无国色，犹恐兰荪是俗香。","人在匡庐新结社，诗传淮楚梦还乡。","波沉不见香罗袜，空向牛腰得夜光。"]},{"t":"送舜卿游建昌","f":"七言律诗","c":["并门当日倚长城，笑遣妖凶卷旆旌。","江上长鲸知巳灭，草中封豕不劳平。","十年当念疮痍苦，此日宁论战伐名。","虎帐夜谈资婉画，为言奇策是休兵。"]},{"t":"官军屡捷淮寇渐平五首 其一","f":"七言绝句","c":["北来骁虏尽成禽，九庙行闻奏凯音。","从此燕齐如振槁，将军勋业似淮阴。"]},{"t":"官军屡捷淮寇渐平五首 其二","f":"七言绝句","c":["拥道行人拨不开，槛车行看缚戎魁。","羽书便恐椎门入，知是淮阴露布来。"]},{"t":"官军屡捷淮寇渐平五首 其三","f":"七言绝句","c":["风声鹤唳是王师，大似秦苻欲破时。","黄屋乍闻天一笑，此欢应有近臣知。"]},{"t":"官军屡捷淮寇渐平五首 其四","f":"七言绝句","c":["枣熟梨黄河朔秋，颇闻箕敛不胜愁。","迎师已欲携箪食，脔炙何劳费万牛。"]},{"t":"官军屡捷淮寇渐平五首 其五","f":"七言绝句","c":["新得降番壤地开，玉觞争奉万年杯。","明年御枣红千颗，又见青徐入贡来。"]},{"t":"立春日闻捷","f":"五言律诗","c":["未献椒花颂，先颁凤历春。","亚钗双燕小，垂鬓綵幡匀。","兵已知胡远，欢应与岁新。","遥闻汉天子，喜色动中宸。"]},{"t":"题李彦恢家龙眠七马图","f":"七言古诗","c":["古来画马知几人，当时只数曹将军。","龙媒貌得照夜白，七十万匹空云屯。","但令韩干作弟子，未许韦偃窥藩垣。","风流扫地五百载，始得龙眠空马群。","龙眠自是天下士，胸中元有真骐驎。","宁王玉面久不见，风騣雾鬣惊犹存。","四蹄翻风不受絷，意在万里绝驰奔。","安能局促盐车下，更与蹇驴分短辕。","先生既老谁入室，后来只数城南孙。","孙郎继死骨又朽，人间此马如浮云。","劝君掩卷勿浪出，世无九方谁与论。"]},{"t":"题彦恢家仇池四石刻","f":"词","c":["伏波南来自交趾，可笑汗牛推薏苡。","人言包裹足珠犀，谁识闲身谢簪履。","如何当年元相国，胸中饱饮贪泉水。","胡椒八百亦安用，坐此杀生真可鄙。","龙眠主簿亦儿嬉，银钩虿尾搜遗奇。","三年独有一钱在，归来清节人皆知。","囊空安得紫丝帐，车重只馀黄绢碑。","自言所至辄寓目，穷搜屋壁翻阶墀。","不嫌尤物触时禁，恍然入手心惊疑。","君不见峄山篆刻焚野火，磨崖万仞高崔嵬。","何如四石横棐几，左提右挈行相随。"]},{"t":"正月十五日同圆明老师渡溪西雨作不可回三绝 其一","f":"七言绝句","c":["伴师同拄一枝藤，野岸凌兢踏断冰。","老去莫辜元夜眼，试凭江阁看渔灯。"]},{"t":"正月十五日同圆明老师渡溪西雨作不可回三绝 其二","f":"七言绝句","c":["旧时好客孔文举，无事长随支道林。","灯夜羞归对妻子，传柑知我已无心。"]},{"t":"正月十五日同圆明老师渡溪西雨作不可回三绝 其三","f":"七言绝句","c":["一别风尘客恨长，凤城灯烛记微茫。","人生相见知何定，夜雨重来此对床。"]},{"t":"次韵和答圆明老师二首 其一","f":"七言律诗","c":["平生作剧谩逢场，枘凿由来苦未当。","笑我弹冠方适越，看谁纫佩独沉湘。","捧心政恐元非病，怒臂前知不自量。","它日小松山下路，合分风月与徜徉。"]},{"t":"次韵和答圆明老师二首 其二","f":"七言律诗","c":["回首云庵日又低，孤帆欲渡晚风吹。","桃花水暖拍堤去，莲叶舟轻随棹移。","老罢转知身是梦，愁来只有鬓成丝。","人间无地安双足，万事从头愧老师。"]},{"t":"次韵元素赋余新居","f":"七言律诗","c":["一樽能此共窥临，草色凄迷步履深。","黄帽青鞋聊偃蹇，白衣苍狗自浮沉。","瓮头酒熟须同把，窗下诗成亦共吟。","待得吾庐真可爱，更须绕屋树成阴。"]},{"t":"元素再邀同赋","f":"七言律诗","c":["载酒何人肯见临，情于老伴莫嫌深。","诵君词赋疑仙去，笑我功名付陆沉。","且可闭门留客饮，不知拥膝是谁吟。","幅巾趁取春犹在，来听黄鹂唤午阴。"]},{"t":"元素再邀同赋","f":"七言律诗","c":["家住三峰颇下临，畏人小筑不辞深。","南齐谢老楼空在，东海麻姑信已沉。","恨子不当青琐闼，伴人犹作白头吟。","我穷无物能娱客，只有苍梧满地阴。"]},{"t":"望故庐一首","f":"词","c":["龟城去江，邈在一隅。","我家龟舫，亦足轩渠。","草耕木茹，瓮牖蓬枢。","有客二人，寔邀望舒。","长须之奴，玉川之庐。","何必仙去，方丈蓬壶。","何必校书，起居何如。","无祸为福，徐行当车。","我乎谁交，谁乎我徒。","春蛙嘈杂，夏木扶疏。","大盗遽起，山摧海枯。","我焚其巢，将焉适欤。","善刀而藏，为之踟蹰。","望我故处，宛其在涂。","我友云亡，云谁与娱。","愿洗甲兵，肉四海臞。","奠我新宅，以饱三馀。"]},{"t":"次韵赵戒叔灯下见榴花明日重午","f":"五言律诗","c":["醉帽风前著，榴花烛下看。","嫣妍为谁好，流落未妨欢。","故国应千里，归涂梦百盘。","明朝是重午，努力愿加餐。"]},{"t":"次韵戒叔增明阁晚眺","f":"五言律诗","c":["朱阁瞰流水，曲栏横晚天。","薄云初过雨，高柳却鸣蝉。","杖履且终日，风尘今几年。","莫将怀远句，重说旧林泉。"]},{"t":"刘公祠","f":"七言古诗","c":["昔岁金胡始南渡，官军夜遁如脱兔。","孤城何啻累卵危，贼至不殊群蚁附。","夜提王师来解围，燕中老将如猛虎。","平明横槊属两鞬，疋马驰从贼营去。","峥嵘但见虏可擒，仓卒不知身已仆。","平生三箭得天山，白骨看成一丘土。","马前班剑不动尘，犹胜车中三日妇。"]},{"t":"送江子","f":"五言古诗","c":["六朝固陵夷，佳士亦间出。","风流数后来，诸江有人物。","总持伟文采，文通颇超越。","清忠若休映，对贼能抵突。","定知苏属国，不为延明屈。","斯人黄卷中，愿见未可必。","谁知有来云，遂入诸子室。","相从忽三年，不见无十日。","人生会相别，此别殊惨慄。","相望渺江湖，时危盗如栉。","愿言加餐饭，栖迟且蓬荜。","时来亦腾骞，安用苦密勿。","尺素倘可通，公当念伊郁。"]},{"t":"次韵圣谟见寄二首 其一","f":"五言古诗","c":["十年悲两京，万骑开幕府。","谁知鹿门翁，远引脱罪罟。","吾衰固安用，文字考前古。","尚烦金兰交，吊此饥寒苦。","庞公不可见，贱子何足取。"]},{"t":"次韵圣谟见寄二首 其二","f":"五言古诗","c":["青衫几痴儿，敛版上公府。","固应横海鲸，不可污池罟。","高才乏近用，初不异今古。","功名亦偶然，惨戚良自苦。","富贵如公等，唾手自可取。"]},{"t":"次韵木南稀见赠","f":"七言律诗","c":["上章分得鉴湖春，贺老前身恐是君。","常病薰莸难共器，岂容鸡鹜可同群。","已无若若累累意，颇坐奇奇怪怪文。","稍许白头亲杖履，少年功业付终军。"]},{"t":"蠹鱼","f":"词","c":["山堂夜雨如决渠，黄梅半熟书生鱼。","树头朝日忽复出，聊向空阶翻故书。","老人耕凿无膏腴，缃囊细字时相娱。","自欣引睡得黄奶，便恐无意呼青奴。","读书本不求甚解，姓名足记知有馀。","此虫何乃徒饱腹，死葬书叶真痴愚。","不如化作石帆山下茧，织成吴绫光满眼。","乞与袁娘作舞衣，常把花枝侍君辇。"]},{"t":"西斋闻禽","f":"七言古诗","c":["西斋草树颇蒙密，竹暗城头不通日。","风晴高柳恰飞绵，花尽黄蜂未成蜜。","北窗也复可怜人，乱离十载空伤神。","病对青山疑是梦，眼惊新绿已无春。","羁怀有句喑不吐，终日无言闻鸟语。","寒窗窈窕不嫌风，晚色溟濛却宜雨。","穿条隔叶止复啼，白粉画眉金作羽。","应为山翁久惯听，听久不知心转苦。","庙堂何日议销兵，携手尚堪归乐土。","还我花姑溪上椽，卧听春禽啭桃坞。"]},{"t":"五月二十九日对雨怀旧","f":"七言律诗","c":["危坐东窗日自长，幽人不出雨何妨。","未论饱饭三秋乐，且说高眠一枕凉。","晴后却疑犹点滴，夜深应是更淋浪。","此声有味知谁解，安得君来与对床。"]},{"t":"余既作前诗已而复晴客有诵余旧诗者其略云开门更待西南月无客来分上下床闻之恍然如梦中语漫不省记为何诗也乃和前篇以足之","f":"七言律诗","c":["贫共闲身味转长，雨随农事不相妨。","莫嫌旅枕喧朝梦，要与书檠作夜凉。","黄犊催耕思莽苍，短蓑垂钓念沧浪。","开门更待西南月，无客来分上下床。"]},{"t":"后二日望东南大雨久之白龙翔于云间掉尾而上老农云白龙见则旱祥也","f":"七言律诗","c":["白昼钩帘望处长，初于眼界了无妨。","坐看云岭埋烟雨，聊借西轩作晚凉。","卷水翔龙方矫矫，转山飞瀑更浪浪。","丰凶许事谁能问，独对残书月满床。"]},{"t":"旅夕","f":"五言古诗","c":["秋云翳长空，微雨饯残暑。","新凉入郊墟，中田熟禾黍。","秋虫自知时，入我床下语。","西风几何时，秋意遽如许。","晓色催鸣鸡，孤砧急寒杵。","游子未得归，留滞在江浦。","生理思田园，饥寒念儿女。","持此两鬓霜，世路复焉取。","起视夜何其，江月方欲吐。","便当随孤鸿，云霄肃双羽。"]},{"t":"次韵章季常见予所赋彦恢家七马四石二诗","f":"七言古诗","c":["灞陵老将身未侯，连城价重谁当酬。","龙眠三岁亦何有，满载缃囊归汗牛。","苍珉照眼裂趸尾，尺素抹电飞骅骝。","春风吹晴作妍暖，棋窗剥啄惊纹楸。","慇勤唤客出奇玩，一笑终日君家留。","此郎胸中有奇策，未能竟借前箸筹。","波澜收敛入诗律，报章还得明珠投。","九重真龙想天骥，入木八法馀银钩。","只今尤物不到手，空花老日生双眸。","章侯叹息恨未见，但听寒雀空嘲啁。","平生欸乃不成曲，无声可和绵驹讴。"]},{"t":"次韵季常叠前作见寄","f":"七言古诗","c":["人生富贵如五侯，禄丰位大功不酬。","朱轮华屋令人羞，一蓑不如归饭牛。","自驾款段马少游，胜骤玉腕尚书骝。","少年蹭蹬在丘壑，晚岁风雨悲梧楸。","江边短艇苦唤我，此心勇往谁能留。","幽期正怨齿发误，事定不须龟筴筹。","言虽太漫君莫笑，与语俗人真暗投。","香粳炊熟碧鲈美，横江已办秋风钩。","胸中它日几云梦，四海不劳围寸眸。","肯听儿女昵昵语，秋虫悲笑徒啾啁。","阳春白雪一落耳，竹枝凄怨惭蛮讴。"]},{"t":"次韵冯远猷观水","f":"七言律诗","c":["带雨山云晚尚繁，黄流先已涨江干。","海边鸥鸟恐不下，濠上游鱼谁肯观。","锦里十家俱半壁，龙门八节定无滩。","早知四载归神禹，疏凿谁能泄浩漫。"]},{"t":"次韵子雍同达书记游安林","f":"七言律诗","c":["江湖流落一乌巾，同障西风满扇尘。","试为支郎吐幽句，了知长吉是前身。","欲宽江上三年梦，更碾禅房一掬春。","不为相逢苦相挽，行吟应在楚江滨。"]},{"t":"远猷家高丽松扇","f":"七言律诗","c":["三韩使者身堂堂，手持汉节归明光。","宝刀不受戎王燕，便面空含风露香。","双鸾织花大如月，凛凛犹馀岁寒节。","莫将七宝画团栾，乞与谁家小桃叶。"]},{"t":"西斋金凤花开百馀日相继不绝难其能久而惜群芳之不留也","f":"七言古诗","c":["昨日晴天花满树，今日风前已飞絮。","闲花可是天与红，着意东风吹不去。","偶然乘此花树空，遂揽春晖学飞翥。","人间此鸟久不出，拟欲高翔入鹓鹭。","凌傲风光不自羞，狼藉空庭复谁觑。","自应敛衽避芳尘，一笑非关迫迟暮。","可怜开谢百日中，浪遣花神费调护。","岭梅何事挽不留，零落风枝怨寒冱。"]},{"t":"赠别木南稀","f":"七言律诗","c":["月下吹箫王子晋，醉中骑马贺知章。","无家只卖文为活，有酒聊凭醉作乡。","夜雨对床惊客枕，秋风无泪把离觞。","阆州此去如天上，说着城南只断肠。"]},{"t":"徐使君新作采菊亭","f":"五言古诗","c":["使君占吏师，老手便治剧。","论功饮无何，课最上殊绩。","人言神爵中，有此二千石。","拥麾几何时，千里静森戟。","遂移佳菊苗，步着东篱屐。","南山忽当眼，净几分晚碧。","黄花行欲开，吹帽尽佳客。","丰年公事少，闲日颇自适。","便恐趣公归，翱翔步丹极。","晓枕梦催班，朦胧想山色。"]},{"t":"陪徐使君登秋浦楼","f":"七言律诗","c":["白发衰颜已倦游，倚楼端为使君留。","天连远峤云埋树，波撼孤城水绕楼。","有客自伤愁外眼，何人解写雨中秋。","世间无此登临胜，休把城南说阆州。"]},{"t":"二十三日雨霁再陪徐使君登秋浦楼","f":"七言律诗","c":["细雨愁云特地晴，重来水秀复山明。","江风吹面沧波动，岚气侵衣翠润生。","南浦落帆催画角，丽谯残照满双旌。","未知九日齐山会，樽酒何人与共倾。"]},{"t":"睡起题西斋壁","f":"七言绝句","c":["熟睡闲攲一幅纱，梦残庭树落疏花。","屋头正喜鸠唤妇，墙下忽闻蜂打衙。"]},{"t":"题刘生画王子猷严子陵二图 其一","f":"五言律诗","c":["人生不相知，相视粤与秦。","臭味倘复同，万里心相亲。","何必儿女曹，尔汝相怨恩。","浩歌反归航，讵识此意申。"]},{"t":"题刘生画王子猷严子陵二图 其二","f":"五言律诗","c":["四皓挽复来，子陵呼不起。","天下复归心，两京同一轨。","义重势乃轻，理自固应尔。","卖菜苦求益，可笑真俗子。"]},{"t":"登杜牧之翠微亭故基","f":"七言绝句","c":["秋草无情上舞台，清江犹抱故山回。","紫微郎为谁携酒，斜日西风菊自开。"]},{"t":"中秋大晴采菊亭对月","f":"七言律诗","c":["风与秋容一样清，云随风尽十分晴。","江从采菊亭前过，月到双梧顶上明。","塞草又黄人亦老，霜须浑白酒还倾。","不应造物知愁极，故着玉蟾娱老情。"]},{"t":"秋蝗叹","f":"五言古诗","c":["驱车入秋原，懞懞尽禾黍。","田父刈且歌，笑言杂儿女。","路傍骑马翁，下与田父语。","问言田家劳，云何乐如许。","父老仰天叹，恳款话心膂。","今年遭岁凶，夏旱连秋暑。","谁知勤饷妇，社瓮刍绿醑。","君看西来蝗，落地辄盖土。","入境不入田，食草不食秬。","老农亦何幸，此乐讵天与。","为言相君贤，为惠寔在汝。","群凶满江淮，杀气自消阻。","微虫初何知，仁者亦复与。","知公意在民，有谷宁忍咀。","劝尔但自欢，蝗来不须禦。"]},{"t":"谒昭明祠","f":"五言古诗","c":["历年有攸归，脩短良亦异。","天乎不祚梁，斯人乃即世。","于皇元良资，盛德真岂弟。","高文贯百家，妙学穷六艺。","悠悠悲徂年，凛凛尚生气。","伟哉千载人，享此百世祀。","金朱焕灵宫，奔走恭祀事。","遐瞻俨森寒，神雨倏复至。","伛偻奠椒浆，悲风肃兰佩。","想像折芳馨，兹焉独长喟。"]},{"t":"次韵元杰听溪亭见寄","f":"七言律诗","c":["贫病相牵各异乡，心随南雁与翱翔。","感君三绝出妙手，慰我九回萦别肠。","山色为人分浅黛，泉声何事碎鸣珰。","千岩万壑山阴路，谁与临流共一觞。"]},{"t":"清樾晚雨效韩偓三绝 其一","f":"七言绝句","c":["池上风荷香扑衣，红妆镜里雨如丝。","试呼小艇寻烟去，便是苕溪五月时。"]},{"t":"清樾晚雨效韩偓三绝 其二","f":"七言绝句","c":["白鹭一双飞暮霭，乱鸦无数立官楼。","角声吹尽栏犹倚，雨落黄昏人白头。"]},{"t":"清樾晚雨效韩偓三绝 其三","f":"七言绝句","c":["黄昏帘幕人谁卷，暮雨阑干客自凭。","独自不知多少恨，一池荷叶碎秋声。"]},{"t":"齐山有岩穴宛转山间秀色可喜号小九华","f":"五言古诗","c":["衰容迫迟暮，驱车厌行役。","路逢玉孱颜，庶用慰愁寂。","谁知九凤群，夐与秋水隔。","落日自凄迷，转盼失虚碧。","幸兹登临间，会遇晚乃获。","玲珑八九峰，模写在寻尺。","郁云开层巅，飞瀑挂苍壁。","凛然削寒玉，秀色粲可摘。","缅怀融结初，岌嶪自开辟。","悬知孤客恨，为了爱山癖。","聊将小岩峦，入我寻山屐。","何时解尘鞿，卜筑在泉石。","遂当挹诸峰，罗列归几席。"]},{"t":"齐山依小岩作观音阁","f":"七言绝句","c":["乱山空洞自成龛，十里秋风响桧杉。","我亦来脩香火供，便疑身在普陁岩。"]},{"t":"池口观楼船","f":"五言律诗","c":["湘水妖氛静，楼船尽日横。","风涛心自恐，舟楫眼初惊。","伏莽膏金钺，将军驾木城。","太平无此物，指日望销兵。"]},{"t":"饮酒三首 其一","f":"五言古诗","c":["高皇扫强秦，纵横成妙略。","三杰岂不雄，曾不出笼络。","曹参晚为相，痛饮事杯酌。","当知清净化，寓意在酬酢。","魏武独何为，屡下禁酒约。","兵戈缠九州，猜忌恣暴虐。","堂堂孔北海，醉语杂谐谑。","斯人犹杀之，四海何由廓。","古来成败事，纷纷真一噱。"]},{"t":"饮酒三首 其二","f":"五言古诗","c":["昔我在田亩，薄言事耘薅。","种粳亦种秫，可食兼可醪。","清香满寒瓮，夜滴喧春槽。","洗我玉花瓷，酌此鹅黄膏。","阅岁更阉茂，下田但藜蒿。","里胥厌追索，县籍书逋逃。","迩来兵火急，斗粟千钱高。","不饮动逾月，憔悴成楚骚。","丈夫命运薄，困阨例所遭。","究竟无如何，随缘且陶陶。"]},{"t":"饮酒三首 其三","f":"五言古诗","c":["浊醪有何好，所贵资清欢。","如何毕阮辈，头没杯案间。","我饮但涓滴，而作饮酒篇。","儿曹见之笑，谓我狂且颠。","政应坐自失，说梦痴人前。","一酌忧已亡，再酌当陶然。","此意但自得，此理讵可言。","万古一渊明，何由与之论。"]},{"t":"秋晚念归","f":"七言绝句","c":["风寒黄叶未全落，露重流萤巳不飞。","胡马又肥秋欲老，旅巢无定客思归。"]},{"t":"亲征诏下朝野欢呼六首 其一","f":"七言绝句","c":["茫茫禹迹混殊方，谁遣中华识犬羊。","今日澶渊寻旧役，会看一矢殪戎王。"]},{"t":"亲征诏下朝野欢呼六首 其二","f":"七言绝句","c":["天戈未指敌先摧，掩耳谁能及迅雷。","便遣风师清辇路，奉迎北狩两宫回。"]},{"t":"亲征诏下朝野欢呼六首 其三","f":"七言绝句","c":["谁信妖凶胆自惊，君王亲驾六騑行。","江边红日三更出，怪得欃枪夜不明。"]},{"t":"亲征诏下朝野欢呼六首 其四","f":"七言绝句","c":["汉业当于马上成，谩劳诸将久经营。","庙堂早扈南阳驾，已为苍生洗甲兵。"]},{"t":"亲征诏下朝野欢呼六首 其五","f":"七言绝句","c":["雉扇遥闻拥翠銮，远方耕凿尚偷安。","谁知黄钺临戎地，江上秋风玉帐寒。"]},{"t":"亲征诏下朝野欢呼六首 其六","f":"七言绝句","c":["请看介子请长缨，白发书生百不能。","谁扫浯溪题岁月，漫郎端欲颂中兴。"]},{"t":"青阳道中望九华诸峰作","f":"五言古诗","c":["平生爱山意，瞑目想奇崛。","东南号多山，万岭空峍屼。","不知垆锤工，铸此一尤物。","峰峦与天近，紫翠争日出。","何年飞三山，此事亦恍惚。","要欲移嵌岩，下作仙圣窟。","我愿从之游，飞升蜕尘骨。","山行尚悠悠，客意殊忽忽。","弱水不可渡，瘦马聊自兀。","落日回寸眸，飞鸟但灭没。"]},{"t":"次韵吕仁父教授题余秋浦诗卷 其一","f":"七言绝句","c":["病客还随倦鸟翰，霜风犹带客衣寒。","谁持马上归来句，换得天孙云锦端。"]},{"t":"次韵吕仁父教授题余秋浦诗卷 其二","f":"七言绝句","c":["汗漫谁从食蛤游，岁穷真似贾胡留。","恨无摩诘丹青手，貌得潇湘两岸秋。"]},{"t":"次韵吕仁父教授题余秋浦诗卷 其三","f":"七言绝句","c":["试从秋浦望长江，犹有遗踪在渺茫。","满地黄花秋日晚，伤心不见紫微郎。"]},{"t":"烧芋","f":"七言古诗","c":["幽人日晏方索米，朱门醉头扶未起。","人微何敢望一囷，鲋死知谁濡斗水。","粪火拨灰聊效颦，玉糁誇羹未须尔。","紫团包玉不洗泥，火候初匀香透纸。","从来真味贵天全，大羹不致名太始。","馋涎为止翁欲颠，饥肠不鸣儿更喜。","口腹为灾莫漫誇，五亩应须急料理。","但托长镵仍短镵，谁能畏首复畏尾。","未知春雨荷锄归，空羡吾家烧芋美。"]},{"t":"十二月二十九日雪中煮茗","f":"七言绝句","c":["旋扫飞花煮玉尘，一杯聊饷作诗人。","未知折脚铛中雪，何似浮蛆瓮里春。"]},{"t":"小儿渍蜜雪见饷用前韵","f":"七言绝句","c":["黄蜜香和糁径尘，紫兰儿饷白头人。","谁知茅屋三冬雪，中有蜂房一掬春。"]},{"t":"雪后小霁撷菊苗荐茗","f":"七言律诗","c":["短窗烘日见深明，墙角泥乾路欲成。","槐叶索淘春渐近，菊苗荐茗雪初晴。","寒丛且对天随子，大白谁浮阮步兵。","愿借芳香明老眼，要翻书叶送馀生。"]},{"t":"雪后北墙","f":"七言律诗","c":["携儿聊作北墙行，泥雪初乾杖履轻。","病后茶枪浑不要，眼前蔬甲喜全生。","鸟声渐软春应近，梅萼催香日自晴。","忽忆读残书未了，却须归趁小窗明。"]},{"t":"冬至前七日极暖","f":"五言律诗","c":["风日炎洲似，暄妍趣岁华。","三冬开蛰户，十月见梅花。","翠管书云近，黄羊赛腊赊。","却愁迟暮雪，随意作横斜。"]},{"t":"冬至日晚晴可喜","f":"七言律诗","c":["云物才书雪未稀，楼台忽复带斜晖。","日从银色界中出，鸟向瑶池影外飞。","可忍便教烟欲瞑，会须更待月同归。","群山即是三山顶，八极聊将寸目围。"]},{"t":"送黄子才还姑苏用陶渊明王抚军座送客诗韵","f":"五言古诗","c":["岁事忽已晏，行迈良亦腓。","谁知出岫云，意作无心归。","嗟我寡徒旅，只影夐无依。","况乃远离别，与子千里违。","中原念乱久，意绪转愁悲。","迢迢两溪水，淡淡浮斜晖。","岂无双赪尾，尺素不可迟。","慎勿不相念，弃置忽如遗。"]},{"t":"奉寄黄端冕用送子才韵","f":"五言古诗","c":["至言如秋霜，既肃百草腓。","谄谀忘中正，千古良同归。","倘无鲠槩士，举世将畴依。","衮职或可补，鼎镬安得违。","所以长沙傅，恸哭为时悲。","谠语数十上，子今有馀晖。","我欲从之游，周道苦倭迟。","倭迟不足惜，子言愿无遗。"]},{"t":"陈公园梅极盛顷尝与客游观花下兵盗十年今复过之追念存殁怆然有感三绝 其一","f":"七言绝句","c":["忽忆梅花空断肠，十年依约梦中香。","如今濯锦江边路，不见栽花黄四娘。"]},{"t":"陈公园梅极盛顷尝与客游观花下兵盗十年今复过之追念存殁怆然有感三绝 其二","f":"七言绝句","c":["玉雪惊看乱后枝，梅花虽在鬓成丝。","当时一醉还如梦，今日嫣然复为谁。"]},{"t":"陈公园梅极盛顷尝与客游观花下兵盗十年今复过之追念存殁怆然有感三绝 其三","f":"七言绝句","c":["溪上长眠双玉瓶，只今谁在复谁倾。","花知何事遽如许，人亦看花太瘦生。"]},{"t":"纸阁初成","f":"七言绝句","c":["小阁春温借隙光，风帘不挂最宜香。","窗前睡鸭吹云缕，聊与幽人度日长。"]},{"t":"除夜杂兴三首 其一","f":"五言古诗","c":["华发日就槁，萎萎如秋草。","秋草剪复生，发秃不再好。","雅意怜儿童，软语媚翁媪。","镊白挽流光，持杯锡难老。","我老不足惜，汝生念不早。","兵戈常在眼，流离犹满道。","且当篘残缸，瓶空莫辞倒。","醒视夜何其，东行日杲杲。"]},{"t":"除夜杂兴三首 其二","f":"五言古诗","c":["忆昔元会日，汉家全盛时。","奉随观国宾，得见汉官仪。","中郎授国玺，属国朝远夷。","万邦瞻咫尺，龙姿喜元知。","皇天厌久治，夜见蚩尤旗。","微生脱九死，饮此除夜卮。","河阳狩未还，蝼蚁何足悲。"]},{"t":"除夜杂兴三首 其三","f":"五言古诗","c":["昔年避群盗，夜窜苍山阿。","偷生岁忽杪，妻孥共婆娑。","村醪薄如水，我颜安得酡。","夜半黑风起，挝门惊荷戈。","今夕复何夕，奈此欢乐何。","人生不自保，聚散如群傩。","更当增兰膏，照此杯中波。"]},{"t":"立春日雨中三绝 其一","f":"七言绝句","c":["满天云物正垂垂，何处青春欲到时。","花信未从风里得，丰年先自雨中知。"]},{"t":"立春日雨中三绝 其二","f":"七言绝句","c":["先自逢春老倍伤，两檐疏雨更淋浪。","眼前无复新幡胜，只有寒菹照庾郎。"]},{"t":"立春日雨中三绝 其三","f":"七言绝句","c":["春光先已到谁家，风里钗头小燕斜。","只有幽人了无事，卧看疏雨湿梅花。"]},{"t":"张载杨示元道州诗卷罗仲共有诗在卷尾次其韵","f":"五言律诗","c":["吾道嗟牢落，斯文得主盟。","马从西极到，凤入九霄鸣。","翰墨推前辈，篇章集大成。","向来侯叔喜，何得有新声。"]},{"t":"正月二十七日种木瓜五株","f":"五言古诗","c":["三峰真奥区，陆海富佳实。","此物冠九州，未数梨与栗。","园丁力扶持，璀璨成妙质。","镂花淹宿露，红晕生晚日。","玉颜醉自赪，丰肌滑仍密。","风味照盘飧，名字愈痹疾。","卫侯报琼瑶，盛德岂埋没。","野人献根株，春雨助芽蘖。","何当垂露颗，照眼行突兀。","畴敢与荔子，飞电争置驿。","况复具苞苴，缄封钻巨室。","一酌呼吾人，甘酸渍崖蜜。","人生鲜知味，相饷不可失。"]},{"t":"正月二十九日种柳三十五株","f":"五言古诗","c":["故国兵火馀，壤地日窘蹙。","千里无鸡豚，遗祸及草木。","火攻阨焚巢，云栖急新卜。","尺地无寸荄，山腰见茅屋。","小径卧修蛇，萦迂绕山麓。","垂杨剪孙枝，封殖勤养育。","正须清阴成，门巷森诘曲。","微风恼春絮，细雨滋浅绿。","悲凉听残蝉，徙倚扪饱腹。","种德须百年，种木十年足。","十年吾巳老，光景日夜速。","吾事倘复济，亦足快所欲。","何必羡张绪，风流标简牍。"]},{"t":"悯红椒树子作","f":"五言古诗","c":["东篱委榛菅，狼藉纷琐碎。","披丛得红椒，磊落本谁艺。","蓬窠颇自矜，枝叶相掩翳。","日月空复明，雨露不沾施。","结根一失所，埋没苦憔悴。","移栽俯西轩，吾乃借一臂。","要令远条且，密叶敷晚翠。","秋霜染丹砂，红寔相点缀。","馨香发潜德，错节振淹滞。","人生良可惜，会遇亦难值。","生理倘复存，馀恨当弃置。"]},{"t":"悯白菊两枝作","f":"五言古诗","c":["鲜鲜凌霜菊，艳艳粲云绮。","团栾双毬枝，婆娑照窗几。","颇讶银台俗，深憎泽兰紫。","琐碎悬万铃，金钱坐堪拟。","彼美谁家姝，轩然两仙子。","一登君子堂，衙官列桃李。","殷勤极调护，出斛埋地底。","结草障飞霜，分渠泄流水。","那知病根株，咬齧遭蠹蚁。","人生意外忧，多智亦谩尔。","朝来踏雪泥，呼奴亟移徙。","东株真已萎，西株有生理。","萎者不自持，生者能有几。","君看金谷园，花木亘百里。","忽然奇祸作，过眼尽荆杞。","悠悠可奈何，归步一笑喜。"]},{"t":"山居闻蛙","f":"五言古诗","c":["忆昔东南居，结屋古城背。","野色带危墙，花阴弄寒砌。","月彩淡微云，春风入衣袂。","万籁悄无声，独立与谁对。","殷勤古壕蛙，为我作鼓吹。","号昏初两三，闹雨忽鼎沸。","悬知世俗憎，自可幽人意。","胡行如鬼速，十年满天地。","弊庐飞劫灰，生涯转零替。","迩来三间茅，风雨仅可蔽。","青春不改色，人事有兴废。","一闻群蛙鸣，怀旧如梦寐。","抚事为叹嗟，伤心极流涕。"]},{"t":"二月四日大火吾庐独免","f":"词","c":["颠风尽日恶，顽云吹不开。","行人对面不相识，千岭万岭沉风霾。","不知谁纵一炬火，坐遣万屋成飞灰。","我闻人火曰火，天火曰灾，茫然不复知从来。","但见通衢半瓦砾，男呻女泣声酸哀。","避胡十年常作客，几见连甍变荆棘。","此生忧火复忧兵，一事不成头雪白。","学禅灵运本忘家，好赋子云终有宅。","向来穷巷冷如冰，今作权门手堪炙。","惊魂可招烟欲消，茅茨犹在书脱厄。","心知造物可怜生，留与云窗看山色。"]},{"t":"二月五日再火吾庐复免","f":"七言古诗","c":["昨日北风如箭疾，城南一燎三百室。","城西片瓦不复存，今日风高火仍急。","池鱼已作沸鼎焦，槁木那容飞鸟集。","糗粮不峙恐民流，楼橹俱空忧盗入。","传闻此火颇异常，宋卫陈郑实同日。","城中有屋无二三，道路横尸十六七。","三州飞报急上闻，诏书亟下隆宽恩。","既令折券已逋责，复振仓廪苏穷民。","东南无事官失职，火政不脩户无耤。","坐令恶少恣焚烧，更以深忧贻玉食。","小人何幸独晏然，饱食怀惭面仍赤。"]},{"t":"群不逞乘时纵火以病良民有捕于官者辄送遣之或厚与之金使之出境二月二十八日敝庐为恶少见焚虽复仅免而官不为直不能言安三月六日徙居寓舍","f":"七言古诗","c":["平生有窟如屋鼠，乱后飘零无定所。","身随海燕作去来，心似宾鸿识寒暑。","异时无地着妻孥，晚得三间蔽风雨。","迩来忧贼夜不眠，恶少屡来窥屋山。","不知今夕定何夕，忽置束缊茅茨闲。","念非曲突可得免，何由外户常不关。","公庭得贼尽纵遣，上诉官曹多怒颜。","青山元与我有约，俗驾苦遭神勒还。","山光无情鸟不语，主人当去心依然。","人生泛泛水中凫，身如逆旅家蘧庐。","东西南北皆可尔，梦幻泡影真须臾。","只今兵犹满天地，黔黎谁复能安居。","鸣泉绕屋花满眼，有窗况足翻吾书。","暮年卜筑倘未可，且借一椽聊自娱。"]},{"t":"酴醾盛开伯颍许携酒","f":"七言律诗","c":["洗雨梳风玉作肌，温泉初试太真妃。","莫惊雾帐人方睡，怕作风轩雪又飞。","未有酒樽酬玉艳，枉教春色到柴扉。","诗成不为花游说，要看山翁倒载归。"]},{"t":"上巳日雨中小集","f":"七言律诗","c":["老去伤春头绪多，花前不醉奈渠何。","重来倦客还脩禊，已去蕃兵却渡河。","薄酒为人浇磈礧，恶风将雨作么魔。","世闲何事非陈迹，莫谩相逢说永和。"]},{"t":"书淳师房六言三绝 其一","f":"词","c":["茗椀要看三昧，斋盂来饭伊蒲。","坐对禅房花木，梦成午枕江湖。"]},{"t":"书淳师房六言三绝 其二","f":"词","c":["长卿自是倦客，支郎殊复可人。","懒识闲中味好，老于方外情亲。"]},{"t":"书淳师房六言三绝 其三","f":"词","c":["罂粟汤翻白雪，梅花句嚼春冰。","助我看山老眼，借君倚壁枯藤。"]},{"t":"次韵任道卿见寄","f":"七言律诗","c":["连璧终惭玉一双，何曾有句似澄江。","九霄鸿鹄终掀举，三峡波涛看击撞。","长袖婆娑终解舞，短歌哀怨不成腔。","诗坛老将元无敌，合为奔军作受降。"]},{"t":"次韵道卿登楼有作","f":"七言律诗","c":["谢朓楼头烟树低，雨馀帘幕捲雌霓。","山从云外分千叠，水自天来落两溪。","南圃飞红香满砌，画桥春涨绿平堤。","登临日日伤愁眼，栏下夕阳还复西。"]},{"t":"次韵鲁庵道人","f":"七言律诗","c":["一事无成雪满颠，漫凭老眼寄韦编。","谁将爱酒周光禄，错比能诗孟浩然。","心与功名无宿约，天分泉石了残年。","相过更待秋风老，来钓琴公斫鲙鳊。"]},{"t":"夜雨达旦枕上作","f":"五言古诗","c":["夜雨不复止，寒声晓仍酣。","悬知变平陆，天水相溶涵。","今年春雨多，既失麦与蚕。","五种殊未入，此雨宁可堪。","日者诸大将，幕府开潭潭。","连营跨淮楚，仰食江以南。","郡县脱兵火，百城无二三。","何以供厞屦，坐贻有司惭。","是事姑且置，我穷谁共谈。","有茅两三椽，往往如漏篮。","中夜屡起卧，吾寝安得甘。","昼止方稍稍，暮作还毵毵。","了无山鞠穷，何由禦烟岚。","有躬不暇阅，忧心顾如惔。","何当烦雨师，驱车反龙骖。","一饱庶可期，寒饿少已谙。","小人无远虑，口腹空馋贪。"]},{"t":"重午日晚眺","f":"五言律诗","c":["野艾伤心碧，丛榴满意红。","兵戈人事别，风物岁时同。","山倚斜阳外，江横醉眼中。","楚冤终未洗，谁为饷丝筒。"]},{"t":"六月八日始开北窗得数峰于林樾间命力斩恶木而山态始尽出","f":"五言古诗","c":["老去舍轻舠，小室坐悬磬。","六月不出门，端居阅晨暝。","安知咫尺中，有此大殊胜。","今晨穿北垣，万象忽辉映。","太虚本无穷，眼力恐自竟。","遥岑蔽清樾，了不赴将迎。","翠幕空繁柯，烟鬟入幽凭。","双峰始幡然，起应高士聘。","长瘦有馀光，名与天地亘。","马鬣亦已颓，蓬颗没微径。","兹山与周旋，安得往脩敬。","斗酒时自浇，先生醉初醒。","落月挂长松，悲风绕危磴。","徘回想音容，彷佛听嘲咏。"]},{"t":"七月十六日晚雨已而月出","f":"五言古诗","c":["将雨日已晏，既晴天亦曛。","风从莽苍来，云向西南奔。","忽于苍玉玦，拥此黄金盆。","我居在山顶，升沉阅冰轮。","三年东冈头，入我圭窦门。","平生金兰友，老去无一存。","愿言结神交，相与论素心。","素心不可说，月亦终无言。"]},{"t":"暑夕","f":"五言律诗","c":["卷箔日巳落，移床月未来。","蛙号还作吹，蚊聚竟成雷。","我自羲皇卧，谁分河朔杯。","更凭风露夕，小为洗胡埃。"]},{"t":"夜枕","f":"五言律诗","c":["夜枕攲残梦，寒灯照白头。","楼空千嶂晓，簟冷一窗秋。","时事兵方急，天星火已流。","欲寻三径老，何日两京收。"]},{"t":"中秋月下怀西山亭示周都曹","f":"七言律诗","c":["顽云拨尽玉团栾，飞出青天白玉盘。","月似不关常夜白，风应先作九秋寒。","兴来有意携双屐，梦去还思把钓竿。","遥想风流三语掾，不知谁共倚栏干。"]},{"t":"次韵道卿咏雪约遵欧阳文忠公令不得用鹤玉洁白等字","f":"五言古诗","c":["鲁史书平尺，王春喜可占。","弄寒初照砌，逐吹旋萦帘。","水远还迷望，山高遂失尖。","欺梅时满树，妒舞或陵襜。","鹊冻痴如梦，儿娇喜欲拈。","人应横短棹，谁且卧穷阎。","壮士知何畏，衰翁亦懒觇。","打窗时蔌蔌，拂帽更纤纤。","兽炭寒仍在，驼裘晚自添。","鹧鸪茶椀酽，鹦鹉酒杯甜。","岁事新愁破，诗章旧令严。","遥思庾楼夜，万里一寒蟾。"]},{"t":"用晦访别为作长句","f":"七言律诗","c":["东风吹雪满征鞍，夺我濒湖一笑欢。","老病不堪频送客，乱离容易莫求官。","故人知有山公在，游子应怜范叔寒。","留得馀年可相见，不须回眼泪阑干。"]},{"t":"十二月二十六日北墙扪虱","f":"五言古诗","c":["今晨颇无事，步游古墙根。","眷兹万家邑，稍苦三户村。","于时积雪散，复值朝阳温。","解衣聊自得，班荆与谁言。","款欠良已久，吾虱庶可扪。","平生谢澡刷，懒惰从朝昏。","坐令边缝间，朝生暮仍孙。","回臭比蹠香，位卑道仍尊。","与世倘无求，中有至乐存。","勿语儿女曹，此意难具论。"]},{"t":"次韵道卿观诸葛生制笔有感而作","f":"五言古诗","c":["任侯富三冬，志在食五鼎。","平生名教地，不对纷华境。","细书抄蝇头，何当避炎冷。","毛锥捐脱兔，高与堆阜等。","遂呼东郭㕙，一一拔项领。","妙制窥良工，危坐销日永。","锱铢辨柔劲，束缚较攲整。","那因将军恬，始拜管城颖。","乃知鬻伎穷，不异束麻苘。","苞苴入朱门，蠹蚛不窥省。","吾曹坐书痴，微言姑自警。","他年草玄窗，长物俱可屏。","潜夫倘或著，封禅慎勿请。","相过有馀日，会待风云静。"]},{"t":"次韵静翁雪晴有作","f":"七言律诗","c":["晓天晴日丽朱楼，残雪晶瑩客舍幽。","寒柳江梅浑欲动，官军胡骑几时休。","颇无佳客堪同醉，当为衰翁作少留。","便典春衣买春酒，同将一酌散千忧。"]},{"t":"次韵道卿效离合体见赠","f":"五言古诗","c":["秾李有佳色，不如兰芷香。","鸣禽矜爪觜，肯入鸾凤行。","若士自有偶，俗子自有肠。","验志贵同术，异趋徒参商。","望羊久自叹，相思不相忘。","伟哉德祖贤，长年与徜徉。","逢君青云衢，弱羽难翱翔。","槁项与黄馘，珠玉俨在旁。","唧唧秋虫吟，敢赓韶濩章。","夜光入我室，什袭徒珍藏。"]},{"t":"早归","f":"五言律诗","c":["野日破朝雾，宿阴回暖风。","人家村崦外，春梦竹舆中。","天碧鹭斜起，水深桃卧红。","山阴几岩壑，应接自无穷。"]},{"t":"题徐伯远渚堂","f":"五言古诗","c":["徐侯当登瀛，结屋在幽渚。","于焉穷心迹，无乃异出处。","西风肃高秋，黄鹄时一举。","自谓可过之，丘壑出肺腑。","俗眼殊未高，此意吾窃取。","长卿少倦游，征衫涴尘土。","羞陪漉酒翁，共作斜川语。","鱼鸟杂冠巾，蒲莲暗樽俎。","江湖满天地，置身岂无所。","黄帽与青鞋，造化久见许。","平生钓饵兴，临老尚龃龉。","兹怀固泯默，感激聊自吐。","安得载笭箵，孤蓬听秋雨。"]},{"t":"次韵道卿尝新梅","f":"七言律诗","c":["梅梢着子叶青青，红萼犹存味已清。","竹外一枝和雨摘，钗头双蒂为谁情。","雪霜自是元同操，楟奈何由与并名。","商鼎欲调应有待，不随盐豉下莼羹。"]},{"t":"送元楷官莪桥","f":"七言律诗","c":["相见还须复语离，更看花雨湿征衣。","乐丞有酒聊自隐，季子无田安得归。","长钓不妨垂白雨，乱帆时看落斜晖。","何时去作津亭客，更待秋风一叶飞。"]},{"t":"次韵道卿喜贼平","f":"七言律诗","c":["无人试请一长缨，贤似防胡万里城。","共说庙堂初奏凯，似闻淮海已无兵。","黄头父老农桑晚，白面将军剑佩荣。","息马投戈知有日，黑山青犊已先平。"]},{"t":"小儿生日","f":"七言律诗","c":["锦里先生聊醉饮，玉川居士以诗鸣。","人言骥子能扶步，天遣添丁欲助耕。","穷苦助吾缘底事，饥寒怜汝若为情。","相看只有身长健，共沥馀樽作小赪。"]},{"t":"林老借可正平诗编以诗还之","f":"七言律诗","c":["苏家人物自有种，法护且放僧弥贤。","谁知癞可东溪句，参得涪翁双井禅。","落叶飞云空自好，流风回雪不成妍。","更须点检新编看，恐有隔林机杼篇。"]},{"t":"送罗仲共罢酒官归山中","f":"七言律诗","c":["虎额一山同避贼，草堂三月更通家。","音容久隔头俱雪，云雾相看眼各花。","晚厌微官犹曲糵，早知豪气已聱牙。","北扉青琐真如梦，且复西溪踏钓沙。"]},{"t":"次韵常元明见寄三首 其一","f":"七言律诗","c":["月明惊鹊未安巢，生事如僧止一包。","但得有门容看竹，不知何地可分茅。","愁来漫载盈鸱酒，老去难穿中鹄髇。","独有诗缘难洗尽，强随春鸟作啁嘲。"]},{"t":"次韵常元明见寄三首 其二","f":"七言律诗","c":["已分功名哙等高，平生谁问六花包。","千头愿种封侯橘，三脊仍惭缩酒茅。","乱后诗囊成长物，梦中惊胆落飞髇。","我非执戟明光客，知有何人肯见嘲。"]},{"t":"次韵常元明见寄三首 其三","f":"七言律诗","c":["我如病橘缀寒梢，璀璨何由入贡包。","交旧半应归宿草，乱离真已压前茅。","毛锥早信难当敌，铜弩何由学射髇。","愿借澜翻千偈手，为余一洗向来嘲。"]},{"t":"次韵道卿瑞香","f":"七言律诗","c":["春意催花不自禁，紫团犹复畏轻阴。","兰荪有意窥芳馥，桃李含羞漫浅深。","斗鸭并栏风冉冉，红油垂幕月沉沉。","任郎便是花东道，不学香山梦后寻。"]},{"t":"次韵道卿竹间桃花盛开","f":"七言律诗","c":["玉立疏疏不满栏，小桃宜向竹闲看。","看花何必三千岁，带雨宁须十万竿。","却怪靓妆情脉脉，不嫌青玉瘦栾栾。","何郎粉面堪怜许，拟学风枝耐岁寒。"]},{"t":"送徐彦思三首 其一","f":"七言律诗","c":["好事何人说醉翁，贤良名在著书中。","只今文采犹如此，当日渊源岂易穷。","遗恨可堪惊别雨，新诗不复咏流风。","惭公千里相求意，枫落吴江恐未工。"]},{"t":"送徐彦思三首 其二","f":"七言律诗","c":["凛凛忠言公自持，伪书初赦两淮时。","膝当不为奸雄屈，心亦唯应草木知。","独任安危百年事，宁辜父老一生思。","抗章终有论功日，便到銮坡已恨迟。"]},{"t":"送徐彦思三首 其三","f":"七言律诗","c":["枘方乖凿固应殊，草木相求世久无。","可怪风流如孺子，不嫌人物似曹蜍。","两溪风月空劳梦，千里歌谣尚载涂。","他日鹓行一回首，冷凫乘雁只江湖。"]},{"t":"二月二十六日伯远邀游小园明日有诗次韵","f":"七言律诗","c":["园荒不见二疏归，风引长藤欲上篱。","燕子作巢春寂寂，竹枝摇月影离离。","谁为五柳当年传，又诵三堂此日诗。","我欲一邱藏曲折，此心唯有子相知。"]},{"t":"二月二十八日静寄轩作","f":"七言律诗","c":["看得阶前碧草浓，小桃犹作亚枝红。","五更梦断鸡鸣雨，三月寒生燕子风。","归意拟寻黄篾舫，春愁最恼白头翁。","鹤长凫短知多少，尽付轩渠一笑中。"]},{"t":"驼山寒食二首 其一","f":"五言律诗","c":["时节近禁火，东风犹小寒。","絮飞争渡水，鞦稳欲平竿。","酒忍愁前把，春仍乱后看。","吾归须少日，花在莫吹残。"]},{"t":"驼山寒食二首 其二","f":"五言律诗","c":["过眼夕阳雨，满襟寒食风。","鸣禽说春事，暖树落嫣红。","杯莫频停手，花令解笑侬。","人生不相见，可忍更匆匆。"]},{"t":"张元明为道卿画竹间梅","f":"七言律诗","c":["我作东窗竹外开，断魂香自雪边来。","细寻水墨图中意，似对檀栾坞里梅。","笔下悬知有冰玉，胸中元自少风埃。","可怜能事王摩诘，解令春从一笑回。"]},{"t":"题周掾西山亭","f":"七言律诗","c":["江静云恬眼界空，危亭高枕丽谯东。","风来雨后凭阑处，山在人间拄笏中。","春去平芜随处有，鸟啼斜日满林红。","伯仁空洞浑无物，容我清樽一笑同。"]},{"t":"次韵道卿闻新莺","f":"七言律诗","c":["草长江南春欲阑，晓莺声在绿阴间。","定应春恨知公子，故作清歌学小蛮。","催尽落花风自暖，唤醒愁眼日长闲。","隔枝时见黄金羽，始信庭柯会解颜。"]},{"t":"次韵道卿县楼观雨之集","f":"七言律诗","c":["楼下江声杂雨声，断云初掩断霞明。","吹残恶热凉生面，泻作奔流绿绕城。","扰扰惊禽栖不定，娟娟缺月坐来生。","遥知举白酬丰岁，醉里凭栏句又成。"]},{"t":"道卿论吴中夏果词颇夸且借苏内相春菜诗韵作诗仆亦同赋聊为江南解嘲","f":"七言古诗","c":["江南五月菱垂叶，叶底紫菱如紫蕨。","梨香溅齿蔗浆寒，瓜熟堆盘水精滑。","红姜抺缕杂吴盐，纤手淹梅带微辣。","芳林露下摘金桃，入眼胭脂红脸抺。","木瓜甘酸天下无，百果论功谁可甲。","朱樱万颗滴阶红，满架蒲桃更肥茁。","橙香栗大芋如鸱，此品秋来不胜说。","老翁空作解嘲诗，但恐年衰左车脱。"]},{"t":"次韵罗仲共灵泉夏夜二首 其一","f":"七言绝句","c":["灵泉无暑竹连山，绝似秋霜五月寒。","我欲访君安得往，江湖满地一渔竿。"]},{"t":"次韵罗仲共灵泉夏夜二首 其二","f":"七言绝句","c":["泉声落枕唤诗成，杰句中含万壑声。","起看四更山吐月，又扶藜杖到天明。"]},{"t":"夜访伯远偶题长句","f":"七言律诗","c":["夜携桃竹上山枝，来叩徐侯种菊篱。","怜我风霜犹短褐，喜君人物是长离。","酣歌强对老来酒，忍泪重听乱后诗。","一笑相逢真我辈，此情慎勿遣儿知。"]},{"t":"驼山秋晚二首 其一","f":"七言律诗","c":["诗翁老去无人数，晚岁移家在河浒。","败絮蒙头那复霜，破屋穿天只愁雨。","大儿窗下抄奇书，小儿灯前诵论语。","明日羞囊馀几何，客至无钱具鸡黍。"]},{"t":"驼山秋晚二首 其二","f":"七言律诗","c":["溪边茅屋知谁家，门前水落溪露沙。","枯藤绕屋挂秋实，黑如点漆红丹砂。","蜀葵花空已收子，鸡冠树高犹有花。","客来倚杖主人出，屋头日暖听蜂衙。"]},{"t":"闻张伯真割奉粟二十斛见遗而书未至戏题小篇","f":"七言古诗","c":["老去空嗤守钱虏，我亦无钱买田亩。","未容残月喘吴牛，空对杏花耕宿雨。","昨宵夜诵偶连明，今日晨炊忽停午。","长腰闻有尺素书，腹饱先悬待椎鼓。","浣花老人殊可怜，忍饥更索饥肠语。","故人禄米肯长供，司业酒钱时亦与。","平生无句可惊人，未审何由坐斯苦。","几时去作多田君，满田䆉稏多黄云。","长年饱饭作谷伯，且免劳人勤指囷。"]},{"t":"九月十六日生日示内","f":"七言律诗","c":["从我怜君二十年，备尝险阻与艰难。","试看剪发师陶母，肯为亲舂愧阿鸾。","香火结缘聊为老，杯盘为寿小同欢。","鹿门愿遂平生志，更享全家百岁安。"]},{"t":"次韵道卿见贻","f":"七言律诗","c":["楼下秋空月似波，与君高目在庭柯。","新愁别后知无数，白发年来畏转多。","岁月催人驹过隙，世缘相缚雉罹罗。","多才似子仍多学，他日金銮稳上坡。"]},{"t":"次韵道卿催梅","f":"七言古诗","c":["江上连朝暗飞雪，花信风迟寒凛冽。","东阁观梅殊未妍，扬州何逊心应折。","何郎思苦花欲开，羯鼓不倩天公催。","诗翁自是催花手，能挽春从天际来。","帐下玉人羞起晚，弄粉含姿半骄蹇。","应怜冶叶与倡条，有意凌寒入芳苑。","君诗好更谁与论，会令寒谷生春温。","冰姿一笑忽满眼，谁道鹤林花有神。"]},{"t":"次韵道卿梅花长句","f":"七言律诗","c":["月娥窥水晚纤纤，风味能回铁石严。","满地不禁飞处急，一枝犹得醉时拈。","国香无意欺兰蕙，天质应羞拟絮盐。","冷蕊依然在空谷，何人重傍少陵檐。"]},{"t":"次韵邵文伯怀桐渚与陈子高唱酬之乐","f":"七言古诗","c":["谪仙骑鲸上天去，万古风流一丘土。","去天尺五城南杜，晚上瞿塘望江渚。","两翁憔悴人不与，造物嗔渠作奇语。","陈侯笔势谁可禦，九鼎自可独力举。","梦中尺锦君尽取，时向胸中作吞吐。","邵郎诗高孰宾主，一笑相看两相许。","清歌那忍听金缕，渠坐诗穷君勿怒。","衰翁老气不可鼓，篆鼎瓦棺心好古。","此别相逢定何所，他时剥啄叩君户，藜杖经行尚堪拄。"]},{"t":"次韵静翁雪中见过三首 其一","f":"七言律诗","c":["年年飞雪闭寒斋，老怯风威不下阶。","客至未妨频叩户，人生何必要笼街。","莫嫌纵饮方投辖，闻道中兴已勒崖。","自笑下愚移不得，从渠抚掌笑高柴。"]},{"t":"次韵静翁雪中见过三首 其二","f":"七言律诗","c":["故国飘零万事乖，十年不见雪中阶。","要令幽子安圭窦，少待凶酋脱藁街。","援笔何由赋梁苑，闭门只合老苍崖。","君来看我煨黄独，自采春山带叶柴。"]},{"t":"次韵静翁雪中见过三首 其三","f":"七言律诗","c":["端门万马想初回，跪贺群臣拜玉阶。","我约江鸥分雪浦，谁将乌帽踏天街。","从游久欲真浮海，送客悬知亦自崖。","犹有升平临老眼，尚堪方岳看燔柴。"]},{"t":"二十八日雪霁读晁无咎集呈别乘徐彦志且以奉怀","f":"七言古诗","c":["苏公论士昔未闻，四客辈出俱同门。","龙媒忽下洗凡马，野鹤一举空鸡群。","虞皇七友廊庙具，元和十子非渠伦。","张公屈宋排衙官，清词丽句冰雪寒。","秦公笔下有过秦，平生目短曹刘垣。","金华仙伯学杜甫，句法自许窥公藩。","晁公磊落天下士，帝遣长庚下人世。","旧闻一醉百梨花，醉后狂歌满天地。","诗成只在倚马间，高谈颇似悬河翻。","当时七发真少作，秦汉以来无此文。","今日晴窗有佳色，积雪为洗烟埃昏。","千山排峦削寒玉，万木拥户明朝暾。","试携尘编醒病眼，隐几一笑空炉芬。","是中有味知者少，此意便欲从公论。"]},{"t":"题彦恢家草堂","f":"七言古诗","c":["昭陵厚德如乾坤，廊庙补衮多公言。","徂徕官在百寮底，有时论事惊天阍。","皂囊欲上谤已满，霜台不到名空尊。","李侯自是千载士，人说赞皇今有孙。","长安御史一骢马，人物眼高争荐论。","南床小忍便可得，直气肯受高官吞。","青云垂上却回首，得州如斗车朱轓。","两公相望空落落，当年风采今仍存。","古来名节与富贵，轻重略等常平分。","天公相爱似有意，黄鹄欲举方腾鶱。","未开青琐霄汉上，故著草堂烟雨闲。","人生穷达固难料，时来鹤亦能高轩。","愿公努力善自爱，更进药石禆华勋。"]},{"t":"次韵道卿残腊步游林薮草木渐有生意三首 其一","f":"五言古诗","c":["抱病岁忽杪，杜门谁复来。","感子阳春句，为嘘寒谷荄。","君才那易得，辞华陋邹枚。","草木不足羡，云衢路当开。","春意私节物，荣枯竟何哉。","封侯与裂土，且当付舆台。"]},{"t":"次韵道卿残腊步游林薮草木渐有生意三首 其二","f":"五言古诗","c":["老意惨不乐，青春为谁来。","艺兰在九畹，谁能起残荄。","桃李忽满眼，其寔亦枚枚。","耕田种芝草，玲珑殊未开。","荣华竞春事，于我何有哉。","当浮白玉阙，下睨黄金台。"]},{"t":"次韵道卿残腊步游林薮草木渐有生意三首 其三","f":"五言古诗","c":["人生有荣瘁，否极泰必来。","君看九地春，寸草无馀荄。","白首始一遇，蒲轮迎老枚。","祁隐不可招，诩径行当开。","我欲寻卢敖，卢敖安在哉。","但当急洗眼，看子登云台。"]},{"t":"读元微之诗有感","f":"七言律诗","c":["从古才高少识真，此公句法老尤新。","世间言语浑无用，天上吹嘘却要人。","但遣前旒知妩媚，莫嫌后榻有嚬呻。","梦中富贵能多少，空使清流作怒嗔。"]},{"t":"舟次句茨","f":"七言律诗","c":["移居来近玉湖中，渔户新添白脚翁。","觅句深惭何水部，浮家全似陆龟蒙。","山寒政恐无黄独，地湿应须要鞠藭。","晚日飘零天不管，双凫乘雁听西东。"]},{"t":"雨寒连日大风病中作此诗","f":"七言律诗","c":["门外湖光潋滟中，春寒那听雨濛濛。","吹残梅雪如山雪，颠得江风似飓风。","双燕拟来寻旧约，小桃浑未试新红。","黄紬独拥眠方熟，剥啄何须来恼翁。"]},{"t":"暝立","f":"五言律诗","c":["山隔湖边路，人栖柳下扉。","船从几席过，燕掠水波飞。","鸟亦昏才定，牛知晚自归。","幽人常暝立，日日到斜晖。"]},{"t":"次韵黄文若寄灯夕不出之作","f":"五言古诗","c":["少小从舞雩，鼓瑟常屡希。","结发事坟典，愿言探玄微。","钟鸣漏忽尽，残星独晖晖。","征鞍老涂路，白露沾裳衣。","齿发倏已暮，富贵终难祈。","佳辰念京洛，流车看騑騑。","结客少年场，儿女如瓠肥。","红灯白昼暖，醉盌黄金挥。","回头二十载，狗盗相因依。","时光了如梦，菽粟不救饥。","飘零少行乐，老大空歔欷。","今年四海静，扊扅张外扉。","芙渠焰明缸，金波丽春帏。","秾李樽前歌，游子月下稀。","铮铮银漏中，扑扑春蛾飞。","此老最可怜，已杜禦寇机。","但知草中和，浩荡歌皇威。","晶荧一短檠，搔首悟昨非。","风流如黄香，不作传柑归。","更携袖中珠，来寻北山薇。","诗盟倘可同，愿复无余遗。"]},{"t":"题赵安定像","f":"七言古诗","c":["乌巾白角云锦裘，长胫肮脏高结喉。","王孙自是真龙种，世上悬知无此俦。","醉里哦诗诗欲就，风月平欺两肩瘦。","秋风为神玉为骨，画手何从写奇秀。","仇池客多谁在亡，高准虬髯唯汝阳。","紫皇苦欲奏璈语，此曲至今空断肠。","肠断公歌侍儿拍，瓮里黄柑自春色。","老坡不见空凄然，此诗此意无人传。"]},{"t":"题包鼎大虎图","f":"七言古诗","c":["人间妙伎古亦有，画虎从来易成狗。","何人为作老于菟，鼎死百年无此手。","想当运笔亦有神，睥睨知谁看回肘。","便恐阴崖风雨来，何止草中狐兔走。","易生惊猿羞挂枝，周昉稚犬空复肥。","画中生意似可喜，此虎一出无馀姿。","迩来丧乱书阨苦，唯有君家此画古。","妖狐一丘渠自安，狡兔三窟无人取。","建章宫殿空咸阳，猛士知谁守疆土。","藜藿不采虎在山，安得有臣如此虎。"]},{"t":"忻师介轩","f":"五言古诗","c":["念我昔年少，刚介颇成癖。","多钱嗤守虏，饱饭嘲谷伯。","有口能雌黄，反眼辄青白。","阿奴恃火攻，未必出下策。","一笑当尊拳，仅得贷鸡肋。","只今真老大，须髯已如戟。","折肱成良医，忤物知何益。","要令空洞中，下视沧溟窄。","峣峣固难全，容容聊自适。","知雌在守雄，外曲当内直。","此理吾已明，师独未之得。","愿言戒覆车，聊用铭子壁。"]},{"t":"三月五日晚霁大风","f":"七言律诗","c":["雨后风扉拥青嶂，家在斜阳晚潮上。","沙头飞尽雪色鸥，柳下初横短篷舫。","皇天恶料风忽颠，贾客仓黄回五两。","老人倚杖不肯归，看打南湖白头浪。"]},{"t":"九江王兴道早岁休官作易安奚疑二室要余作诗 其一","f":"七言律诗","c":["心如止水不妨清，身似无官不为名。","但把一椽供偃蹇，从他百鬼瞰高明。","路迷鸡犬家何在，身与渔樵席屡争。","眼看青云有矰缴，鹪鹩巢小未宜轻。"]},{"t":"九江王兴道早岁休官作易安奚疑二室要余作诗 其二","f":"七言律诗","c":["朽骨枯茎未必灵，行藏何苦访君平。","问津世路心先懒，买地江干计已成。","解向急流求勇退，便知幽事合关情。","裕陵将种今谁在，但恐君王问姓名。"]},{"t":"倚杖","f":"五言律诗","c":["雨脚收寒久，东风倚杖频。","浪翻双鹭起，船过小鹅嗔。","客饭长腰米，林居折角巾。","浇山一掬泪，回首故乡春。"]},{"t":"寒食日归郡舟中作二首 其一","f":"五言律诗","c":["归棹浮江水，寒衾拥醉眠。","乱花飞送客，细浪稳随船。","泪落浇山酒，愁生禁火天。","一从胡骑入，飘泊到今年。"]},{"t":"寒食日归郡舟中作二首 其二","f":"五言律诗","c":["世事聊相挽，吾归亦有期。","白湖为客久，寒食到家迟。","接屋花仍在，遮门柳自垂。","向来歌社里，应著老人嬉。"]},{"t":"春事","f":"五言律诗","c":["春事无多日，江村有数家。","等闲飞燕子，容易落梨花。","草色过薄雨，柳阴暝淡霞。","诗成不归去，暝立看栖鸦。"]},{"t":"湖居春晚杂赋八绝 其一","f":"七言绝句","c":["雪屋临湖忆系船，柳汀吹絮又经年。","白鸥大似知人意，分与沧波十里天。"]},{"t":"湖居春晚杂赋八绝 其二","f":"七言绝句","c":["雨后春湖拍拍流，近门谁系两三舟。","水边寒食飞双燕，柳外斜阳卧一牛。"]},{"t":"湖居春晚杂赋八绝 其三","f":"七言绝句","c":["数日东风紧闭门，小桃知有一枝新。","花飞不复到老眼，可是春寒欺得人。"]},{"t":"湖居春晚杂赋八绝 其四","f":"七言绝句","c":["倚床相伴一枝藤，强作春游老不能。","花底婵娟诗妩媚，枕中日月睡瞢腾。"]},{"t":"湖居春晚杂赋八绝 其五","f":"七言绝句","c":["黄蜂归后燕成家，杨柳初飞一两花。","已是无春可拚得，乱红何苦恼霜华。"]},{"t":"湖居春晚杂赋八绝 其六","f":"七言绝句","c":["晓镜烟凝水绕湖，晚汀飞鹭又成图。","早知鱼鸟堪同乐，愁得华颠政不须。"]},{"t":"湖居春晚杂赋八绝 其七","f":"七言绝句","c":["两日东风着意颠，南湖风浪不行船。","飞沙走石成何事，吹得杨花也上天。"]},{"t":"湖居春晚杂赋八绝 其八","f":"七言绝句","c":["湖水波连野水边，欲晴鸠唤未晴天。","懒吹云去风无力，打得花残雨可怜。"]},{"t":"雨中立杏花下","f":"七言律诗","c":["浅红疏蕊出墙头，事往人空锁北楼。","鸟为春愁浑不语，花知人意亦含羞。","东风脉脉情何限，细雨濛濛泪不休。","却忆去年花下醉，依稀记得小蛮讴。"]},{"t":"恭闻已迎原庙圣容入行在所","f":"五言律诗","c":["戎气腥京洛，桥山万木悲。","园陵回望远，衮绣自天垂。","日月瞻遗像，衣冠拜赤墀。","樱桃荐原庙，重见汉官仪。"]},{"t":"雨后二首 其一","f":"五言律诗","c":["造物有佳思，放晴娱薄游。","湖光散凫雁，野日下羊牛。","水欲满旧壑，草还青远畴。","云来犹倚杖，雨过忽横舟。"]},{"t":"雨后二首 其二","f":"五言律诗","c":["晚日纤纤出，痴云阵阵回。","风林无定翼，晴汉有残雷。","白水自天去，青山随眼来。","峰高月未吐，更拟着诗催。"]},{"t":"夜半热甚湖上短歌","f":"七言律诗","c":["江头老父谁共语，白发垂肩汗如雨。","儿方高枕作自畀，雷翁开门傍河浒。","水边云黑雨欲成，山外天高月将吐。","江湖满地身未归，星斗横空夜如许。"]},{"t":"舟中睡起","f":"七言律诗","c":["幅巾听雨卧风樯，呼得青奴伴晚凉。","白发蠹书缘已熟，黑甜攲枕味偏长。","月侵冰簟何妨白，舟入荷花不奈香。","更倩长年打双桨，云山青处是吾乡。"]},{"t":"五月十九日雨中困卧起读西清录见其载欧阳文忠公与许昌龄事甚异作此","f":"七言绝句","c":["四字丹书亦偶然，石唐未必是真仙。","无人解得潮州意，也复留衣与大颠。"]},{"t":"即席二首 其一","f":"七言绝句","c":["凋尽朱颜年少春，不堪柳下对离樽。","刘郎已是无肠断，更唱阳关恼客魂。"]},{"t":"即席二首 其二","f":"七言绝句","c":["旧家明月醉归时，夜静朱楼歌折枝。","只有杜娘真好事，樽前犹唱后山词。"]},{"t":"将归白湖而雨","f":"七言律诗","c":["世间那得此间身，恐是前生贺季真。","白水窗闲频入梦，黄梅雨细却留人。","重听欸乃烟中曲，净扫离骚几上尘。","但得南风送归棹，未应幽独解伤神。"]},{"t":"中元日雨中录所见","f":"七言律诗","c":["颠风急来万木萎，迅雷不听人掩耳。","南山栖鸟失故巢，北山翔龙卷湖水。","翔龙掉尾不肯收，眼看沧波接云起。","想当舟楫避惊涛，无数鱼虾趁龙尾。"]},{"t":"读张载扬所示近诗颇怀其人","f":"七言律诗","c":["眼中人物欠曹刘，老矣逢君接胜游。","诗与漫郎推行辈，字从坡老得源流。","羸骖又踏千山去，黄菊空催九日愁。","横槊想多秋后句，诗成须着锦囊收。"]},{"t":"次韵仲照秋怀四绝 其一","f":"七言绝句","c":["日斜楼阁暮云中，黄菊红蕖满院风。","酒熟未酬花烂熳，诗来时听玉丁东。"]},{"t":"次韵仲照秋怀四绝 其二","f":"七言绝句","c":["老去篇章谁与酬，秋来又喜与君游。","遗音固自成三叹，妙语不应惭四愁。"]},{"t":"次韵仲照秋怀四绝 其三","f":"七言绝句","c":["白发新愁满眼中，骚人零落怨秋风。","年来诗思成何事，聊伴寒螀泣露丛。"]},{"t":"次韵仲照秋怀四绝 其四","f":"七言绝句","c":["秋在幽人行乐中，好山欲尽更须穷。","花姑水绕几时到，罨画溪遥路欲通。"]},{"t":"秋雨连日","f":"五言律诗","c":["老鬓风吹急，愁云带雨飞。","白添平岸水，红掩傍幽扉。","力尽方谋食，天寒未授衣。","此身惭社燕，秋晚亦能归。"]},{"t":"次韵罗仲共教授闲居三首 其一","f":"七言律诗","c":["为米要令陶令出，无毡今坐广文穷。","悬知嚼蜡世味薄，未抵扑衣山色浓。","大盖且从渠自拥，小槽当与客频中。","家谈安得从三老，华萼同编是古风。"]},{"t":"次韵罗仲共教授闲居三首 其二","f":"七言律诗","c":["了事痴儿不到诗，间中鼓吹自应奇。","莫教句法惊人甚，便恐功名入手迟。","性癖雅宜嵇叔懒，官闲只有漫郎知。","庭梧想得西风急，秋意微生楚些悲。"]},{"t":"次韵罗仲共教授闲居三首 其三","f":"七言律诗","c":["拟筑扬雄宅一区，碧鸡坊外且成居。","湖江君尚作浮宅，风雨我当无敝庐。","平日梦游嗟路远，新凉见面恰秋馀。","便须载酒相从去，要识平生未见书。"]},{"t":"白湖闻雁三首 其一","f":"七言绝句","c":["斗落参横天雨霜，梦残灯尽客思乡。","丁宁莫作叫云去，老眼不禁秋夜长。"]},{"t":"白湖闻雁三首 其二","f":"七言绝句","c":["晚向濒湖寄一椽，只凭沙雁与周旋。","北来南去莫惆怅，我亦飘零那记年。"]},{"t":"白湖闻雁三首 其三","f":"七言绝句","c":["华人流落几秋风，南望中原信不通。","好寄书来苏属国，君王方射上林中。"]},{"t":"九日风雨终日用怀载扬韵","f":"七言律诗","c":["九日清尊强挽秋，满庭风雨复谁游。","俗人言下无三语，此老胸中有九流。","白发不妨欺短帽，黄花应解笑痴愁。","客情老去何曾好，双鲤书来几日收。"]},{"t":"九日不出","f":"五言律诗","c":["白发谁怜我，黄花最忆渠。","酒杯今日把，筋力去年殊。","身远秋如梦，谋疏老更愚。","客愁浇不下，强欲醉茱萸。"]},{"t":"桥成","f":"五言律诗","c":["尚忆防秋日，疏渠转曲城。","万方知盗息，此地看桥成。","拄杖知频过，游鱼莫漫惊。","明朝趁虚去，画柱晓霜明。"]},{"t":"雪夜","f":"五言律诗","c":["病眼怕遥夜，宿炉依小温。","酒醨嫌雪厚，书细苦灯昏。","残腊归时梦，他乡尽处村。","可怜双白鬓，深闭一蓬门。"]},{"t":"读蔡中郎传","f":"五言古诗","c":["人生无先知，颇欲邀后福。","自言苟依违，安得有颠覆。","伯喈英伟资，高义甚敦笃。","不为左回天，辄作流水曲。","立朝有公言，谁能保家族。","朝奏皂囊封，暮就洛阳狱。","晚节不自守，一跌变前躅。","起依千里草，九徙如转轴。","卓死固已久，安得复嚬蹙。","琴中知杀气，此理反未烛。","陋哉王司徒，避谤私欲戮。","公忠信安在，志操等流俗。","何能起颓纲，此辈真碌碌。"]},{"t":"责鸡","f":"五言古诗","c":["豢犬欲司夜，畜鸡要鸣晨。","二物一失职，遂辜畜养恩。","嗟我笼中鸡，芥羽光照人。","峨冠事饮啄，缄口随晨昏。","我怒欲尔烹，鸡笑复自陈。","君看多言者，以忠获怒嗔。","台评与幕辨，呶呶常杀身。","幸此北窗卧，颇似羲皇民。","五起笑朝士，三号惊梦魂。","使子卧红日，谢客扃柴门。","此意殊不恶，诮我无谆谆。"]},{"t":"客舍二首 其一","f":"五言律诗","c":["日日湖边路，频来我不嗔。","故山无百里，客舍遂三春。","红落含桃过，青垂小杏新。","光阴花委地，飘泊燕依人。"]},{"t":"客舍二首 其二","f":"五言律诗","c":["畴昔江湖意，儿曹总不知。","幅巾沾雨过，拄杖看云移。","凤子飞应远，莺儿语最迟。","闲从梅雪后，直到麦秋时。"]},{"t":"送张颠东归","f":"七言律诗","c":["张颠佳处是清高，不但诗狂酒亦豪。","自说平生耽翰墨，未尝名讳落官曹。","书工耻作云间榜，画好能添颊上毛。","早信人间苦荆棘，不嫌门外长蓬蒿。"]},{"t":"薄暮二首 其一","f":"五言律诗","c":["物外无馀子，愁边有是翁。","梦回惊日脚，雨罢看云峰。","天与长闲处，湖供不断风。","犹嫌太多事，身落乱书丛。"]},{"t":"薄暮二首 其二","f":"五言律诗","c":["睡熟不知雨，梦残无限凉。","莺飞时到眼，鹭起不成行。","瓜熟分苍玉，莲香擘翠房。","扫门还待月，近水更移床。"]},{"t":"静夜二首 其一","f":"五言律诗","c":["家与重湖近，门当永夜开。","鹭随波浩荡，人共月徘徊。","晓色催星落，飞云带雨来。","长须汲水去，小艇淂鱼回。"]},{"t":"静夜二首 其二","f":"五言律诗","c":["湖影入散发，晚沙横断汀。","冠攲从自落，门设未尝扃。","鬼着林边火，萤翻水上星。","时闻有船过，月黑夜冥冥。"]},{"t":"雨晴望青山","f":"七言古诗","c":["世间尤物如异人，青山不入诸山群。","晚来浓翠欲成滴，雨后数鬟高切云。","人言兹山下埋玉，太白祠扉落岩谷。","至今樵牧无斧斤，馀润油然归草木。","往岁小生来酹公，秋山未霜叶尚绿。","是时落日在屋梁，彷佛如照公眉目。","今我不乐湖水滨，青山到眼无朝昏。","更欲再拜望拱木，公已乘鸾上天门。","帝乡渺渺不知处，谁能为我招清魂。","死生夜旦何足道，不敢复作湘累文。"]},{"t":"仆去岁作湖居十二诗向开叔有诗次韵乃为谢","f":"七言律诗","c":["三年湖雨一茅茨，坐遣幽人识面迟。","遗恨忽从愁里尽，交情先向句中知。","重寻故里空劳梦，亟买归舟会有期。","何日剧谈听亹亹，满倾春酒细论诗。"]},{"t":"得木犀","f":"七言绝句","c":["三年身在菰蒲里，手把岩花意惘然。","折得秋芳香满袖，梦魂常绕故山前。"]},{"t":"夜苦秋蚊达旦不寐","f":"五言古诗","c":["昔年记淮邦，茅庐蔚秋草。","两耳无晨昏，秋蚊困飞绕。","利吻极惨伤，群飞固轻矫。","悬知孀女祠，未可较多少。","至今梦中雷，客枕疑已晓。","那知三家村，复此终夕挠。","青烟郁蒿艾，横空益奔扰。","手倦劳扑缘，眼病恶薰燎。","谁言天宇大，微物吝除剿。","何必养嘉羞，便可付丹鸟。"]},{"t":"归自白湖舟中作","f":"五言律诗","c":["客舍三寒暑，扁舟八往还。","残年不如意，老色日凋颜。","暗谷鸣珊佩，晴峦结翠鬟。","江禽浑识面，似欲唤人闲。"]},{"t":"寄家龙溪寺小阁初成","f":"七言律诗","c":["三年波浸白湖门，佛屋新分水北村。","窗可近书真窈窕，室才容榻颇深温。","妻孥共社同香火，鱼鼓催人作晓昏。","雪颔已疏怜我老，云踪无定与谁论。"]},{"t":"次韵雷飞卿送其女兄南归","f":"七言律诗","c":["兰皋飞佩一凄然，别酒深倾玉满船。","谁唤孤帆落天际，尽驱秋色到愁边。","燎须心在人能说，拟絮才高墨未乾。","莫向南湖频着眼，断鸿疏影在云烟。"]},{"t":"次韵陈季陵阅猥藁见寄","f":"七言律诗","c":["相思一日九回肠，多谢来书细作行。","镜里有霜怜我老，鼎中无脔付君尝。","衰颜本自羞连璧，佳句仍惊得夜光。","五凤楼高无此手，曹刘真是及肩墙。"]},{"t":"次韵文殊老人题宝顶寺","f":"七言律诗","c":["门连弱水不可渡，山似妙高知几寻。","得雨僧分香积饭，行檀人施袅蹄金。","重新佛屋龙天喜，已退魔军岁月深。","老去愿随君共隐，谁能拥膝更长吟。"]},{"t":"杨次公侍讲得古印于洪井其文云东海开国次翁之子德润以赠徐伯远伯远有诗次韵","f":"七言律诗","c":["王谢风流本自长，天教洪井发珍藏。","定知东海新金斗，可继文安旧印章。","龟去岂无江上恋，鹊来今得石中黄。","传家已作他年兆，莫把功名付锦囊。"]},{"t":"次韵雷飞卿游山时余以病不往","f":"七言律诗","c":["一病能令百念阑，霜蓬零乱照衰颜。","心知只可开三径，炙手何劳叩八关。","老喜社中多臭味，梦思方外有跻攀。","劝君莫放寻山屐，嬴取浮生半日闲。"]},{"t":"渡陂南用斜川韵","f":"五言古诗","c":["万物自有得，吾生感行休。","及兹天气佳，步寻水南游。","青板得野航，竟渡一苇流。","乘流本无心，岂有不下鸥。","开口月有几，百年终一邱。","与世似异趋，此行谁我俦。","村醪亦足醉，对影自献酬。","未知垂老日，能遂此乐不。","事定会当谐，不复怀预忧。","但愿营自安，孰是都无求。"]},{"t":"归陂北用斜川韵","f":"五言古诗","c":["薄游不尽兴，归卧当少休。","曲水虽陈迹，斜川有新游。","浩歌独长往，岂亦惭此流。","侨寓三家村，飘如浮水鸥。","屡争渔樵席，共守狐鼠邱。","削迹屏冠服，索居谢朋俦。","樽中有馀滴，子献复父酬。","殷勤问稚子，汝复乐此不。","稚子掉头笑，老夫豁深忧。","但令常复尔，过是吾何求。"]},{"t":"舟中次韵飞卿赠别长句","f":"七言律诗","c":["早岁从田叹不逢，老随乘雁听西东。","青山约在何时了，白发欢成一笑空。","昨夜清歌催别酒，只今寒月上孤蓬。","相逢莫怪长相忆，举世交游无此风。"]},{"t":"雪后望文脊诸峰哦韦苏州门对寒流雪满山之句得两诗 其一","f":"七言绝句","c":["雪压寒林春未回，晚山犹带玉崔嵬。","谁将旧日韦郎句，貌取郭熙平远来。"]},{"t":"雪后望文脊诸峰哦韦苏州门对寒流雪满山之句得两诗 其二","f":"七言绝句","c":["新来袅袅娉娉雪，犹在重重叠叠山。","莫作故时峰岭看，玉京今不是人间。"]},{"t":"送方元相宰钱塘","f":"七言律诗","c":["云路飞腾合到君，不应犹现宰官身。","未分东观消长日，聊为西湖作主人。","天近得声知亦易，民饥当念可须嗔。","簿书丛里江山在，了事何妨得句频。"]},{"t":"向开叔借陈公诗卷以诗奉寄且易乙藁 其一","f":"七言绝句","c":["谁言静寄是穷儿，尽得陈公晚岁诗。","一读便醒双泪眼，头风更拟倩谁医。"]},{"t":"向开叔借陈公诗卷以诗奉寄且易乙藁 其二","f":"七言绝句","c":["平生不识陈惊坐，传得新诗喜失床。","闻道明珠犹满眼，烦君为我一倾囊。"]},{"t":"舟过道场山下将往游舟师告以雪涂不可行而止","f":"五言古诗","c":["风蒲饱朝航，霁色急新涨。","云山绕平湖，水墨澹屏障。","夷犹柂初回，突兀山入望。","何妨倾寸眸，便足了千嶂。","想像钟磬音，隐约霄汉上。","我欲一往游，遐瞻兹可畅。","暮雪犹在涂，遗事不得访。","人生蜡屐缘，一世能几两。","登山追胜游，脚力须少壮。","重来定何时，吾策今可杖。","老愿复尔违，抚事一惆怅。"]},{"t":"老日","f":"五言律诗","c":["老日那容惜，晴光到眼休。","蚕知今日浴，麦复几时收。","黄犊分青草，花凫趁绿沟。","谁能更归得，已是一春留。"]},{"t":"西湖山下梅花坞行可里许至陈御史园亭","f":"五言古诗","c":["倦客厌卑栖，白日坐飘忽。","呼我同舍郎，缓策扶勃窣。","缘山得人家，附影蔽深樾。","湖水一镜明，梅花千树发。","扶疏弄清影，仿佛见罗袜。","凄迷香雾中，身已在月窟。","穷探意未已，取径无诘屈。","谁家歌舞园，花乱竹复密。","御史投绂馀，课竖种梨栗。","吾曹不解事，尚此学操瑟。","当从汉阴人，抱瓮日搰搰。"]},{"t":"寒食前五日作二绝 其一","f":"七言绝句","c":["杜鹃新听晓来声，暖气催花一夜成。","寒食只今无几日，故乡何处不关情。"]},{"t":"三月二十二日春雨终日","f":"七言律诗","c":["此情谁与问天公，幽事全归白发翁。","袖手寻诗红烛里，卷帘听雨绿阴中。","杯盘眼见樱桃熟，时节心惊柳絮空。","谁为羁栖到三月，还家犹及舞雩风。"]},{"t":"奉酬德庄见和","f":"七言律诗","c":["横飞衮衮见诸公，着眼何由到此翁。","胡粤相忘千里外，金兰投分一言中。","诗缘渐熟情难洗，老色来煎念已空。","销尽客愁知底事，爱君回雪与流风。"]},{"t":"酌六一泉颇怀昔游","f":"五言古诗","c":["孤山屹中流，长堤转湖尾。","泯然怀昔游，踊跃尚壮齿。","道人引清甘，一掬托分似。","重来固依然，岁月今有几。","华堂失雄观，缺甃久未理。","谁令走蛙黾，投笔便如鬼。","龙宫空一炬，狗盗忽四起。","佳处不负人，环山自湖水。","并游适相契，况我二三子。","少留当何之，再来吾老矣。"]},{"t":"黄文若携秦别驾侍儿像见过戏题二绝 其一","f":"七言绝句","c":["能事空传王右丞，句如徐庾转难名。","明眸正似溪光样，自古无人画得成。"]},{"t":"黄文若携秦别驾侍儿像见过戏题二绝 其二","f":"七言绝句","c":["谢家林下小梅花，不着红蓝染绛纱。","莫笑画师无国手，玉肌元不受铅华。"]},{"t":"次韵黄文若春日山行过秦德久六首 其一","f":"七言绝句","c":["百金聊作杖头沽，旋剪春苗荐野蔬。","便可且倾陶令酒，未须真忆季鹰鱼。"]},{"t":"次韵黄文若春日山行过秦德久六首 其二","f":"七言绝句","c":["眼前风物一番新，江上桃花恼杀人。","可笑草玄窗下客，满庭吹絮不知春。"]},{"t":"次韵黄文若春日山行过秦德久六首 其三","f":"七言绝句","c":["阶前春草唤愁生，屋上鸣鸠报晚晴。","忽有好诗来照眼，似逃空谷听人声。"]},{"t":"次韵黄文若春日山行过秦德久六首 其四","f":"七言绝句","c":["不作林间曳履行，老来春日总无情。","还惊柳上风催燕，又见花边雨弄晴。"]},{"t":"次韵黄文若春日山行过秦德久六首 其五","f":"七言绝句","c":["樱桃花下小窗扉，闻说婵娟是柳枝。","茗椀已烦罗袖捧，篆香仍借好风吹。"]},{"t":"次韵黄文若春日山行过秦德久六首 其六","f":"七言绝句","c":["鸟啼花发未春阑，日饮无何意自闲。","更唤小蛮娱醉客，主人风味似香山。"]},{"t":"追和向苏州罢吴门作","f":"七言律诗","c":["幕北传烽飞夕埃，庙堂今日要真才。","肯将身向急流退，要问客从何处来。","宝墨光翻银汉落，画船恩重锦帆开。","胸中丘壑公元有，便恐鸱夷挽不回。"]},{"t":"追和向苏州顷在吴门尝用韦应物作凝香阁旧有白公桧今不复存为补植之","f":"七言律诗","c":["韦白两公名欲埃，芗林一出未难才。","树从居士池边种，香入苏州句里来。","陶令北窗应好在，何郎东阁为谁开。","二疏归后今重见，遥想都门张饮回。"]},{"t":"追和向苏州舟次京口闻召诸公简朝中知旧","f":"七言律诗","c":["圣主思清战骑埃，尽将尺一起群才。","匈奴莫向云中入，尚父今从海上来。","绣祫不当毡毳用，玉关宁为犬羊开。","公冠已挂知何事，犹有忠肠日九回。"]},{"t":"古风二首别李守 其一","f":"五言古诗","c":["东南富佳郡，此地复名城。","拜策奉温诏，谒帝辞明庭。","悠悠出金阙，旆旆摇熊旌。","兰风蔼微和，玉露湑以零。","征鼙肃郊垒，啸咏闲斋铃。","微生等薜萝，托根符馀荣。","误遭一笑盼，永怀千古情。","千古不足多，喜遇罕所并。","白璧勿漫予，按剑徒取憎。"]},{"t":"古风二首别李守 其二","f":"五言古诗","c":["逸足思长途，劲翮慕远汉。","壮志忽蹉跎，功名失华旦。","孤芳不自惜，靡靡同草蔓。","饥寒日劬劳，霜雪念衰晏。","眇焉尚遐征，遄车指芳甸。","故国念离忧，高轩增老恋。","会当酬知心，努力加餐饭。","微勇或可贾，未和南山粲。"]},{"t":"叔共出近诗百馀篇携归灯下读竟题小诗其后三首 其一","f":"七言绝句","c":["避地两家三五口，只今那忍记当时。","谁知临老相逢日，犹得重看乱后诗。"]},{"t":"叔共出近诗百馀篇携归灯下读竟题小诗其后三首 其二","f":"七言绝句","c":["翠鬟当户山如染，匹练绕檐江自寒。","纵有鹅溪谁写得，要从无色画中看。"]},{"t":"叔共出近诗百馀篇携归灯下读竟题小诗其后三首 其三","f":"七言绝句","c":["东平不复叹涂穷，有侄贤如阮仲容。","净观庵中诗作社，水西山下酒分钟。"]},{"t":"读巴东集二首 其一","f":"七言绝句","c":["熟睡能令虏退师，高谈聊决庙堂疑。","胡尘洗尽浑无事，却卷波澜入小诗。"]},{"t":"读巴东集二首 其二","f":"七言绝句","c":["谈笑成卢事亦难，一言能借百年安。","群奸未死公休恨，但遣枯枝作岁寒。"]},{"t":"次韵韩伯嘉拟陆龟蒙坐眠行倚食学书吟八题 其一","f":"七言绝句","c":["口角澜翻二十年，书多却厌腹便便。","年来拗折枯藤杖，参得跏趺面壁禅。"]},{"t":"次韵韩伯嘉拟陆龟蒙坐眠行倚食学书吟八题 其二","f":"七言绝句","c":["黑甜有味要须尝，一枕谁同夜雨床。","世路风波难著脚，老来当以梦为乡。"]},{"t":"次韵韩伯嘉拟陆龟蒙坐眠行倚食学书吟八题 其三","f":"七言绝句","c":["年来孛窣与谁□，林下婆娑万事休。","草浅沙平溪路稳，漫郎空棹小回舟。"]},{"t":"次韵韩伯嘉拟陆龟蒙坐眠行倚食学书吟八题 其四","f":"七言绝句","c":["梦中棐几得常凭，更有南窗可寄情。","便是人间好消息，别无胜解可讥评。"]},{"t":"次韵韩伯嘉拟陆龟蒙坐眠行倚食学书吟八题 其五","f":"七言绝句","c":["平生不识大官馀，小摘时寻雪后蔬。","一岁不斋能几日，北山松韭未宜疏。"]},{"t":"次韵韩伯嘉拟陆龟蒙坐眠行倚食学书吟八题 其六","f":"七言绝句","c":["伎痒撩人不易禁，读残书叶喜重临。","牙签玉轴知多少，浪与儿童较寸阴。"]},{"t":"次韵韩伯嘉拟陆龟蒙坐眠行倚食学书吟八题 其七","f":"七言绝句","c":["妙画心传岂学能，是中真乐不容声。","讥评尽入雌黄口，写得吾心不要名。"]},{"t":"次韵韩伯嘉拟陆龟蒙坐眠行倚食学书吟八题 其八","f":"七言绝句","c":["老来无意作悲秋，不奈庾郎知处愁。","笔底波澜何日了，人间风雨几时休。"]},{"t":"谒颜鲁公祠时新筑怀忠堂云","f":"七言律诗","c":["平生高目看儿童，晚喜低头拜鲁公。","政恐父师千载后，未输丞相百年中。","投诸魑魅知何事，碎得狻猊有底功。","长遣忠臣泣遗恨，谩营华屋照丰容。"]},{"t":"吴兴道中过落石祠庙貌甚严榜云唐李英公庙","f":"七言古诗","c":["天厌孤隋失群丑，鹿走中原死谁手。","爬搔痒疥不足平，虬髯少年十八九。","经营四海多腹发，英公扶持真臂肘。","从来断国要老成，公独含糊无可否。","留得宫中老孽妻，几覆昭陵一杯酒。","蚤岁功名塞天破，九庙丘墟只回首。","狐埋未几狐掘之，天上浮云倏苍狗。","更凭顽石作灵祠，颇似当年柳州柳。","不如梁公摩虎须，为言百岁不祔姑。","提师十万复谁可，兴邦一言还要渠。","人间万事本难料，老将未须轻腐儒。"]},{"t":"河桥晚思三首 其一","f":"七言绝句","c":["出门犹未夕阳低，倚杖还惊露湿衣。","等得树头鸦定后，会邀林外月同归。"]},{"t":"河桥晚思三首 其二","f":"七言绝句","c":["雨后津桥饮断虹，暮林重噪一蝉风。","月来烟陇挂玉玦，云向碧天成峭峰。"]},{"t":"河桥晚思三首 其三","f":"七言绝句","c":["秋水平堤带雨浑，小桥分港到篱根。","晚来幽事亦可喜，忽有渔舟时傍门。"]},{"t":"次韵德庄送别 其一","f":"七言律诗","c":["千里辞家复卧疴，赖君一笑肯相过。","梦看赤鲤春腾浪，归见牵牛秋渡河。","空里懒能书怪事，酒中自可作无何。","一竿忍负平生意，重钓花姑溪上波。"]},{"t":"次韵德庄送别 其二","f":"七言律诗","c":["乌帽前头没马尘，个中元自不无人。","风流公是习主簿，文字我惭阴子春。","此日定交真有意，一生吊影复谁亲。","相从又失秋来约，已结茅椽着病身。"]},{"t":"题黄县丞墨牛","f":"七言律诗","c":["一牛饱卧春草绿，一牛下坡引黄犊。","长安可笑人海中，眼前见此三觳觫。","诗翁老去饥满腹，归把春犁岂非欲。","人生所愿能几何，百亩良田一牛足。"]},{"t":"鹿苑假寐","f":"五言古诗","c":["挂席月未落，辍棹日将午。","亟寻墟里烟，尽阅菱芡浦。","烈日方在舟，腾云未成雨。","濒河得风岩，佛饭过斋鼓。","龛灯明广殿，妙炷绕残缕。","窈窕几僧窗，款欠无一语。","我来兀昼梦，得句瘖不吐。","攲巾倒乌纱，堕扇横白羽。","凉襟亦已披，归杖当复拄。","为君趣扁舟，夜雨轧鸣橹。"]},{"t":"次韵崔都巡马上望天目山","f":"七言律诗","c":["雨后青云万里开，翠螺新染玉萦回。","将军马健随风去，天目山高入眼来。","稚子能文非好武，君王赋韵不为才。","且将横槊新传句，独对西风侑酒杯。"]},{"t":"苕霅舟中戏题","f":"七言绝句","c":["永日扁舟破浪迟，青蘋不动柳垂垂。","满川安得飞来雨，看湿红裙雪藕丝。"]},{"t":"再赋二首 其一","f":"五言律诗","c":["故国辞家远，苕溪转柂深。","交游千里隔，岁月二毛侵。","满意悲烟树，移时看水禽。","唯应陆鲁望，相见可知心。"]},{"t":"再赋二首 其二","f":"五言律诗","c":["云暗千家雨，寒生两岸秋。","水翻波入户，人靓玉明楼。","山色遮愁眼，荷香满客舟。","水晶宫里梦，还作此生游。"]},{"t":"船晓","f":"五言律诗","c":["瞑鸟惊飞急，孤舟犯晓行。","柂牙侵月白，帆腹受风轻。","云破千峰出，秋随一雨生。","倚樯谁共语，蓬首看参横。"]},{"t":"舟中晚色二绝 其一","f":"五言绝句","c":["望处天仍阔，云边雨未成。","秋风莫吹散，留作打篷声。"]},{"t":"舟中晚色二绝 其二","f":"五言绝句","c":["风急雨初过，天高日未曛。","翠鬟堆晚岫，水墨画秋云。"]},{"t":"临安道中晚晴书所见二首 其一","f":"五言律诗","c":["客路乡关远，云山暮色添。","秋高尚寒薄，雨过却风恬。","附陇田成陛，倾崖水作帘。","此行殊不恶，未愧贾胡淹。"]},{"t":"临安道中晚晴书所见二首 其二","f":"五言律诗","c":["何日王摩诘，潇湘画短屏。","扁舟横远壑，晚翼在青冥。","木杪收残照，云间得数星。","吴姬不惊客，拜月下中庭。"]},{"t":"西湖寒食","f":"七言绝句","c":["落花残絮忆西园，寒食归心似纸鸢。","无复御廊分冷食，又看茅屋禁清烟。"]},{"t":"十日不至湖上","f":"五言古诗","c":["我始跨匹马，蹭蹬来东吴。","东吴亦何有，政复为西湖。","西湖如静女，婉然真彼姝。","湘娥结烟鬟，水镜涵空虚。","晴光固不恶，雨态亦自殊。","窈窕一僧窗，烟云媚朝晡。","上下数白鸟，飞翻与人娱。","只今雨鸣叶，便作破跳珠。","寒窗挂薜萝，身疑在菰蒲。","咫尺不得往，况乃千里馀。","始来梅欲花，旋复春去徂。","幸兹得少留，驻我西征车。","尚可具小舟，红妆醉芙蕖。"]},{"t":"苏公堤","f":"七言绝句","c":["翰林一去几经秋，犹有平堤绕碧流。","谁向西州还度曲，此翁零落已山邱。"]},{"t":"次韵关子东筇杖","f":"七言律诗","c":["林下相从政要君，春来花草各欣欣。","须烦无语木上座，时伴能言郑广文。","徒步饱看山入眼，醉归应有句凌云。","谁知九节仙人杖，解与先生立茂勋。"]},{"t":"闷题","f":"五言律诗","c":["命薄官如虱，年多鬓似银。","酒醺虽有圣，钱少本无神。","含笑花欺老，妨眠鸟闹人。","青山浑可恋，白眼莫相嗔。"]},{"t":"湖堤步游客言此苏小墓也","f":"七言律诗","c":["野水横分青草陂，谁埋玉树与琼枝。","湖边山自向人绿，门外柳今何处垂。","行雨行云钧是梦，施朱施粉未相宜。","一从蕙死兰枯后，刚道桃花好面皮。"]},{"t":"题净空泉二首 其一","f":"七言绝句","c":["谁穿巨石贮清泉，不见超公旧讲筵。","龙伴白云归宝藏，鱼随流水下春田。"]},{"t":"题净空泉二首 其二","f":"七言绝句","c":["欲寻遗事苦无碑，老宿犹传古律师。","尚恐蜿蜒在空谷，水清不敢唾方池。"]},{"t":"送别王元韵徙居武康","f":"五言古诗","c":["扁舟忆东来，梅冷殊未芳。","故人念客寒，满意倾酒浆。","坐中东床君，笑语芝兰香。","相从忽三月，共饮湖水光。","花事乃如此，碧草日夜长。","子归我当留，语离意难忘。","似闻小山居，一苇仅可航。","会寻霅川盟，着屐登上方。"]},{"t":"晚雨薄寒枕上作","f":"七言律诗","c":["睡过花时常掩关，老人欢意自应阑。","愁边可奈雨如许，客里不禁天尚寒。","数月乡音无雁到，一年春事已梅酸。","梦馀犹忆江头路，拟唤归舟下急湍。"]},{"t":"奉酬德庄见和一首","f":"七言律诗","c":["老于春事岂相关，只有翻书意未阑。","白眼何由常玩世，黑裘元自不遮寒。","饱听风雨眠方熟，细说穷愁语更酸。","日诵离骚三百字，便知新句有惊湍。"]},{"t":"楼居杂句五首 其一","f":"七言绝句","c":["吴江横绝断云间，白鸟归飞去不还。","烟树青连越王国，暮潮声过海门山。"]},{"t":"楼居杂句五首 其二","f":"七言绝句","c":["湖光山影入楼明，晓色催人梦自惊。","画栋去天无一握，青山衔月恰三更。"]},{"t":"楼居杂句五首 其三","f":"七言绝句","c":["上方重阁乱山前，喷雪跳珠日夜泉。","暂借小楼听雨睡，更携官焙与僧煎。"]},{"t":"楼居杂句五首 其四","f":"七言绝句","c":["五月江南烟雨时，吴侬初喜饷杨梅。","绿枝红雨连山暗，应似泸戎摘荔枝。"]},{"t":"楼居杂句五首 其五","f":"七言绝句","c":["人间第一东南郡，天上飞来碧峭峰。","更乞老僧双不借，为君穿尽玉玲珑。"]},{"t":"雨中湖上晚归书所见三绝句 其一","f":"七言绝句","c":["菰蒲风里棹歌迟，属玉双飞欲暮时。","荷叶吹香送归客，片云催雨湿燕姬。"]},{"t":"雨中湖上晚归书所见三绝句 其二","f":"七言绝句","c":["谁家歌管载凉州，何处跳珠入柂楼。","山雨忽随云渡岭，明眸还与水争愁。"]},{"t":"雨中湖上晚归书所见三绝句 其三","f":"七言绝句","c":["风荷忆伴醉颜红，湖水重来照雪翁。","此世相看最长久，只应南北两高峰。"]},{"t":"孤山新作三贤祠","f":"七言律诗","c":["两公才力尽骅骝，俱得东南第一州。","易湿青衫江上泪，难禁白发海边秋。","此生名字依然在，晚岁功名亦未酬。","处士若无当日节，更将何物配风流。"]},{"t":"晚至灵峰 其一","f":"七言绝句","c":["绿树千枝与万枝，灵峰寺里看杨梅。","青山行尽且归去，红子熟时应再来。"]},{"t":"晚至灵峰 其二","f":"七言绝句","c":["山前山后僧来浴，两两三三松下行。","自是眼边无俗物，老夫不浴更身轻。"]},{"t":"五月六日湖上晚归初见荷二绝 其一","f":"七言绝句","c":["藕湖烟水欲沉沙，已着芙渠一两花。","拟借短蓑随雨去，共谁同把钓鱼车。"]},{"t":"五月六日湖上晚归初见荷二绝 其二","f":"七言绝句","c":["毵毵烟柳谁家树，拍拍西湖尽日风。","和靖宅边山雨急，苏公堤下藕花红。"]},{"t":"晓起趋郡湖上作","f":"七言律诗","c":["湖色初分宿雾馀，绿蒲深处听跳鱼。","一枝聊作乌栖树，五晓尚随人趁虚。","老矣坐曹真戏事，归欤怀旧却情疏。","未开禁钥听传漏，残梦犹堪付竹舆。"]},{"t":"五月二十二日再葺静寄","f":"七言律诗","c":["晚将华发试青衫，静寄从来是旧衔。","俗子未须怜怨鹤，老夫元不负耕岩。","晴山有约长相见，恶木妨人要尽芟。","自笑飘零苦无定，今年来此诵琅函。"]},{"t":"初凉","f":"五言律诗","c":["白露初垂叶，轻阴渐着衣。","幽虫近床语，黄叶到阶飞。","暮雨村常暗，秋风客未归。","短檠还有意，凉满读书帏。"]},{"t":"武林逢邵文伯","f":"五言古诗","c":["念昔与君游，相过江水傍。","翩翩俱少年，满镜青丝长。","别来二十载，四海一战场。","物色到朋旧，十客八九亡。","今年好时节，匹马不犯疆。","将军锁金甲，万玉朝明堂。","长安人海中，衮衮逢此郎。","惊视久乃识，两帽俱垂霜。","抚事念晼晚，含凄各酸伤。","便当呼醽醁，暖热浇中肠。","我笑谓君言，语离且勿忙。","人生如水凫，相值不可常。","况此秋物佳，草木交青黄。","与君着只屐，尚可相扶将。","愿言迟明发，历井升南冈。"]},{"t":"次韵文伯与余游孤山","f":"五言古诗","c":["客尘费爬搔，佳士要推挽。","谁与同薄游，君来慰愁眼。","并湖得名山，水色淡平远。","清泉手可掬，汲绠不畏短。","何人谈醉翁，但取瀹茗椀。","古干不受寒，霜露阅岁晚。","向来后庭花，想像空婉娈。","堂堂两使君，摹昼暗丹粉。","名节冠今古，风流未渠泯。","处士一癯儒，万像共偃蹇。","珠玉俨在前，未肯作寒窘。","胜游那可既，客意殊未满。","更当穷两高，岂复悔重趼。","果腹尚可期，尝鼎安一脔。"]},{"t":"秋夜闻雨","f":"五言律诗","c":["堂空自生秋，凉簟已无暑。","齿虫含微酸，唧唧相对语。","天公知客意，夜寂谁与处。","慎勿遣西风，吹断芭蕉雨。"]},{"t":"酌龙井泉书聪师房二首 其一","f":"七言绝句","c":["十里泉声咽断岩，绣衣玄衮闭朱龛。","老翁不要千山雨，只乞龙君一酌甘。"]},{"t":"酌龙井泉书聪师房二首 其二","f":"七言绝句","c":["八十霜髭不出门，老师犹是辩才孙。","高人已复如云散，旧事那堪与客论。"]},{"t":"太学落成二首 其一","f":"五言律诗","c":["偃革逢华旦，三雍识汉仪。","明伦先太学，首善自京师。","圣主脩文日，诸生望幸时。","宸奎在轮奂，万目仰宏规。"]},{"t":"太学落成二首 其二","f":"五言律诗","c":["当宁敷文德，贤关喜气多。","横经将正坐，讲艺忽投戈。","云拥桥门路，风摇辟水波。","小臣歌圣化，无地献菁莪。"]},{"t":"秋夕卧病效唐人作语 其一","f":"七言绝句","c":["画阁兰膏欲尽初，小窗留住玉蟾蜍。","欲知此地愁多少，一夜秋声入井梧。"]},{"t":"秋夕卧病效唐人作语 其二","f":"七言绝句","c":["此夜秋怀谁得知，幽虫相语替人悲。","自从啼破黄昏后，直到寒窗无月时。"]},{"t":"西溪道人全一堂","f":"七言律诗","c":["道人不爱葛藤禅，参得维摩妙法门。","颇怪后三犹有说，要从全一便归根。","昭文琴在何须鼓，惠子书多亦费言。","闻道山中少来客，炉香清坐与谁论。"]},{"t":"次韵季长感事","f":"七言律诗","c":["久将华发寄林泉，尺一呼来近日边。","身退已甘无事老，眼明重见太平年。","鼎湖龙去心虽在，长乐钟鸣喜欲颠。","解道贞元朝士少，刘郎定自有新篇。"]},{"t":"种罂粟","f":"七言古诗","c":["墙根有地一弓许，人言可种数十竹。","翁来只作三年留，仅比浮屠桑下宿。","竹成须待五六年，我已归乡卜新筑。","园夫笑谓主人言，不如锄苗种罂粟。","二月春风上翠茎，三月轻红照深绿。","嫣花落尽罂不空，碎粒圆时粟初熟。","乳膏自入崖蜜甜，满贮醍醐饮僧粥。","与其种竹供后人，孰若栽花资老腹。","人间作计真眼前，万事皆尔真可怜。","十年种木尚不肯，百年种德知何缘。","倚锄自顾颇羞涩，病眼对花空惘然。"]},{"t":"周秀实陈庭藻携酒见过徜徉湖山间甚款明日秀实有诗乃次韵","f":"五言古诗","c":["少年怀二妙，一日如三秋。","岂料京洛间，岁暮方从游。","空疏坐晚缪，清楚知前脩。","周郎古名士，功以一战收。","太丘亦贤者，盛德令人羞。","周旋奉谈笑，领略开羁囚。","有如我辈人，夫岂公等俦。","窈窕寻远壑，共赋临清流。","青山傥在眼，白发从满头。","西湖如西子，好句岂易酬。","不敢妄作语，恐有不下鸥。","微君妙篇章，何以写我忧。","人生每如此，万户不足侯。","斯盟傥未寒，小艇尚可浮。"]},{"t":"送乔民瞻赴官闽中","f":"七言古诗","c":["我昔游梁走千里，回望江南隔江水。","是时公作桐汭官，不复东来问行李。","人言左史有重客，玉面青衫气豪伟。","酒催红蜡诗欲成，月堕秋江客方起。","我从京洛尘中来，哦君新篇眼如洗。","溅血惊魂二十年，长梦清樽奉簪履。","相逢吴会不相识，昔年强健今如此。","如公自是台阁人，老困一官何乃尔。","只今尚作入幕宾，无事不令公怒喜。","丈夫要当列鼎食，何止忍饥分斗米。","且须拄颊望闽山，饱看麦秋丹荔子。"]},{"t":"送关康子将还青阳治旧田","f":"七言律诗","c":["关郎人物妙人间，莫作云长一样看。","不到青云知有命，频遭白眼坐无官。","纫兰秋浦应须尔，索米长安政恐难。","我欲买田犹未可，但令归梦逐征鞍。"]},{"t":"书杭僧法惠事后见边郎中观音感应记","f":"七言绝句","c":["眼中铁弹不辞枯，眢井重波事亦殊。","不用三三前说法，要须六六后还珠。"]},{"t":"次韵叶兵部九日不出十日登北高峰","f":"七言律诗","c":["登临一笑与谁同，此事人间未易逢。","莫恨清樽负重九，且看黄菊笑西风。","江连碧海潮初上，山近丹霄路欲通。","向晚归来得新句，便知云梦落胸中。"]},{"t":"顷岁盗起徽严间兵既临城部使者而下皆弃官以走别乘强幼安摄郡事解衣高卧而贼不至城遂以全仆尝作送行诗以书其事后二十一年岁癸亥幼安始得州相遇于钱塘幼安犹能诵鄙诗而余漫不复省矣手录见遗读之惘然为题三绝其后 其一","f":"七言绝句","c":["当年玉食轸深忧，两月东南弃八州。","只有孤城强别驾，醉中看雪倚江楼。"]},{"t":"顷岁盗起徽严间兵既临城部使者而下皆弃官以走别乘强幼安摄郡事解衣高卧而贼不至城遂以全仆尝作送行诗以书其事后二十一年岁癸亥幼安始得州相遇于钱塘幼安犹能诵鄙诗而余漫不复省矣手录见遗读之惘然为题三绝其后 其二","f":"七言绝句","c":["使君功大苦难酬，埋没孤忠二十秋。","便拥一麾知未称，伯郎犹解得凉州。"]},{"t":"顷岁盗起徽严间兵既临城部使者而下皆弃官以走别乘强幼安摄郡事解衣高卧而贼不至城遂以全仆尝作送行诗以书其事后二十一年岁癸亥幼安始得州相遇于钱塘幼安犹能诵鄙诗而余漫不复省矣手录见遗读之惘然为题三绝其后 其三","f":"七言绝句","c":["江上孤城欲破时，闭门高卧复谁知。","我无文字铭金石，安用烦君写恶诗。"]},{"t":"张鳌诗","f":"五言古诗","c":["曹瞒举汉鼎，一目窥九州。","凌轹欺孤儿，大蒙口舌羞。","左慈有道者，何为与之游。","堂堂清献公，盛德岂操俦。","鳌乃元放徒，为公亦少留。","了知高世士，至意俱难求。","先生两琴鹤，清节贯白头。","雅宜鸿宝书，取火遽自投。","公今骑箕尾，笑谈阅千秋。","椿年亦细事，蚁梦轻封侯。","强侯公自出，矫矫亦此流。","作诗纪异事，誓将踵前脩。","愧乏大手笔，为公著嘉猷。"]},{"t":"去年闻载扬在武林及余至而载扬病已久逮其归则逝矣乃追用往时九日诗韵以悼其亡","f":"七言律诗","c":["与君一别几经秋，忽作脩文地下游。","诗忆向来云态度，人今何在柳风流。","西湖烟月生前恨，客路风霜晚岁愁。","胜日交流半零落，数行老泪倩谁收。"]},{"t":"次韵德庄惠南城纸衾且示妙句","f":"五言古诗","c":["范公古遗直，富贵不自娱。","平生一布衾，岁晚眠粗疏。","至今镵新铭，尚得司马书。","此老抱刚节，岂与公孙俱。","乃知枯槁士，白单良复须。","衰年忍风露，蹭蹬来东吴。","感君借馀温，此意知何如。","青毡寄幽梦，蕙帐羞吾庐。","得此林下具，烂锦不愿馀。","况乃粲佳句，薄袖翻明珠。","恨我无苍珉，为君载龟趺。","愿与冰雪姿，卧起同卷舒。","荆土作翠被，此俑无乃愚。","问言拥六尺，岂不贤一襦。"]},{"t":"十月二十日晨起见枇杷花","f":"七言绝句","c":["枝头红日退霜华，矮树低墙密护遮。","黄菊已残秋后朵，枇杷又放隔年花。"]},{"t":"夜宿净慈明日当宿斋宫","f":"七言律诗","c":["上方枝策记当年，仿佛天宫五日间。","老去新添唯白发，重来好在只青山。","已怜雪意催寒急，更遣泉声唤梦还。","明日郊宫禋社稷，此生犹得缀朝班。"]},{"t":"斋宫夜雨明日大雪","f":"五言律诗","c":["郊祭严祠事，斋宫肃夜寒。","鸾刀催宰急，庭燎及晨难。","雨湿牛羊俎，烟埋币帛坛。","南山忽清晓，万玉已巑岏。"]},{"t":"闻耘老犹在霅川","f":"五言律诗","c":["湖上虽相见，重来失后期。","风尘为客久，舟楫送归迟。","雁远无消息，梅残恼别离。","何时酌君酒，烂漫说新诗。"]},{"t":"十一月十一日夜步行中庭月色明甚作诗三绝 其一","f":"七言绝句","c":["冰轮渐出海西头，身在三吴近海州。","赖有梅花管羁客，细分疏影上驼裘。"]},{"t":"十一月十一日夜步行中庭月色明甚作诗三绝 其二","f":"七言绝句","c":["香风袅袅月娟娟，月满中庭夜悄然。","只恐大罗天上有，人间今夕是何年。"]},{"t":"十一月十一日夜步行中庭月色明甚作诗三绝 其三","f":"七言绝句","c":["少年邀月伴清樽，老去空馀满袖尘。","多谢蟾光深有意，尚来同我作三人。"]},{"t":"二十一日雪中归资国","f":"七言律诗","c":["出门天意已垂垂，湖上回鞭雪满衣。","人在水晶宫里住，马从银色界中归。","树头云冻依然在，湖面鸥寒断不飞。","今夜灯前有残榼，拥炉深闭一篷扉。"]},{"t":"蜡梅大有生意","f":"五言古诗","c":["幽芳念初分，厚地冻始裂。","耐寒怜孤根，忍苦度尺雪。","谁持万金良，起死医寸蘖。","伶俜初回姿，荏苒似看叶。","灌木犹未成，已与凡草别。","平生冰玉交，胜韵颇奇绝。","微风折轻黄，香雾湿寒月。","棐几著冰壶，馀芬散清樾。","只今满眼花，想像疑可折。","感君分似意，老味倍欣悦。","添我小窗春，芳意未衰歇。","盛德不可忘，封殖宁敢阙。"]},{"t":"石佛道中隔水梅花满山","f":"五言古诗","c":["平明跨羸骖，遥遵石头路。","循山一溪横，隔水得幽处。","树疑虬龙骧，石作苍虎踞。","云庵有遗屋，突兀在烟树。","方壶岂不佳，弱水无船渡。","空馀恼幽香，梅花满春屿。","心知姑射仙，兹焉饮风露。","水自平湖分，香从一山度。","风姿不自持，照影各矜顾。","安得从之游，徘徊著双屦。"]},{"t":"书东窗二首 其一","f":"七言绝句","c":["枕上青山翠扑衣，西湖郡更似西施。","苦无能事王摩诘，领略烟鬟却要诗。"]},{"t":"书东窗二首 其二","f":"七言绝句","c":["湖上梅花春意回，水光山影入衔杯。","无人许我分幽事，故遣双飞属玉来。"]},{"t":"次韵强幼安岁晚感事","f":"五言律诗","c":["寒日催残岁，新诗得夜光。","雪犹随处有，梅亦为春芳。","愁鬓何从白，流年有底忙。","官闲应放腊，燕寝自凝香。"]},{"t":"岁晚杂题四首 其一","f":"五言律诗","c":["安稳三冬计，栖迟一舍宽。","卷帘唯水近，倚杖得山看。","老罢人谁数，天寒岁又阑。","自无稽古力，未可怨儒冠。"]},{"t":"岁晚杂题四首 其二","f":"五言律诗","c":["草色无人地，梅花近腊天。","拟飞犹未雪，将尽欲新年。","漫与空成恨，无求合信缘。","平生为晚计，老去更茫然。"]},{"t":"岁晚杂题四首 其三","f":"五言律诗","c":["倚杖千山里，穷年一水滨。","有官羞隐吏，无句作诗人。","雨送灯前梦，傩催腊后春。","孤山林处士，笑我是比邻。"]},{"t":"岁晚杂题四首 其四","f":"五言律诗","c":["老病时携客，斜阳更上楼。","山寒犹有雪，湖晚最宜鸥。","诗可书幽事，儿能伴薄游。","人生每如此，吾意复何忧。"]},{"t":"次韵幼安寺丞感旧见示","f":"七言律诗","c":["当时长啸敌先摧，不费官军一炬灰。","黠虏自惊风鸟散，使君方看玉山颓。","撄城捍贼今亡矣，抗疏论功有是哉。","相见可堪谈旧事，为公搔首一徘徊。"]},{"t":"甲子立春口号四首 其一","f":"七言绝句","c":["梅花消息未阑珊，春入千门笑语喧。","人道上元新甲子，从头却数太平年。"]},{"t":"甲子立春口号四首 其二","f":"七言绝句","c":["春来玉烛又初调，尽喜官仪是汉朝。","御道雪晴方试辇，彤庭日暖渐闻韶。"]},{"t":"甲子立春口号四首 其三","f":"七言绝句","c":["力争和议众初疑，事在君王子母知。","旧日塞垣啼鸟处，如今长乐晓钟时。"]},{"t":"甲子立春口号四首 其四","f":"七言绝句","c":["晴日初生禁籞春，苑花宫树一番新。","君王勤俭无行乐，只作银钩赐近臣。"]},{"t":"元夕前三日书事 其一","f":"五言律诗","c":["旧岁冬馀雪，今年雨复晴。","奉常新奏乐，蕃使近朝正。","灯火鳌山路，风光凤辇城。","须烦天一笑，四海尽无兵。"]},{"t":"元夕前三日书事 其二","f":"五言律诗","c":["落日沧江上，潮回水自平。","云连子胥庙，山接阖闾城。","海岳朝吴会，衣冠奉帝京。","端门旧灯火，还向此时明。"]},{"t":"饭馀过总持庵","f":"五言律诗","c":["饱饭度永日，问邻从小园。","闲携居士杖，来扣总持门。","花木无人见，文书听客翻。","更将方外事，细为老夫论。"]},{"t":"德庄别后以诗见寄再游钱塘始见之次韵奉答且以叙将别之意","f":"五言律诗","c":["分作经年别，还成一笑同。","看君须点漆，羞我鬓吹蓬。","共醉宁非梦，缘诗各坐穷。","相逢又惊散，往往似征鸿。"]},{"t":"二月二十三日薄雪","f":"七言律诗","c":["湖上春风结暮阴，乱云堆雪晚来深。","便随柳絮飞将去，谁管桃花冷不禁。","自苦多愁成客恨，不关难测是天心。","乘除妙理谁能会，明日朝暾忽满林。"]},{"t":"次韵子东春雪","f":"七言律诗","c":["春光早已到千林，尚有馀寒压晓衾。","解作飞花朝蔌蔌，绝胜疏雨晓涔涔。","无田亦有三登意，是瑞何妨一尺深。","雪里故人谁过我，西湖岩壑似山阴。"]},{"t":"湖上戏题","f":"七言律诗","c":["一湖春水绿漪漪，卧水桃花红满枝。","去住云情浑不定，阴晴天色故相欺。","风前柳作小垂手，雨后山成双画眉。","何必娉娉仍袅袅，西湖应便是西施。"]},{"t":"后二日又题一首","f":"七言律诗","c":["家在东湾古渡头，柴扉草阁枕寒流。","无人拟弹能言鸭，有眼那惊不下鸥。","月里踏歌何处社，樽中载酒几家游。","溪南溪北村村水，春雨春风日日愁。"]},{"t":"后五日又题一首","f":"七言律诗","c":["几日春风大放颠，晚来寒日露晴天。","浪纹随棹湖如镜，日脚翻鸦月似弦。","便可饱看花入眼，不应直待柳吹绵。","庾郎分得愁千斛，肯与青丝作少年。"]},{"t":"湖居无事日课小诗 其一","f":"七言绝句","c":["春湖潮满入青天，浪拍东风打钓船。","人在空濛飞絮里，鸟啼红白乱花前。"]},{"t":"湖居无事日课小诗 其二","f":"七言绝句","c":["天上阴晴不可猜，两番云黑又云开。","鹭从落日山边去，鱼趁晚湖潮里来。"]},{"t":"湖居无事日课小诗 其三","f":"七言绝句","c":["茶了诗窗饭后杯，儿书未熟急须催。","鸟于花外唤客出，山自眼前将句来。"]},{"t":"湖居无事日课小诗 其四","f":"七言绝句","c":["老向华胥占一窗，无心更梦小云郎。","城居可似湖居好，诗味颇随茶味长。"]},{"t":"湖居无事日课小诗 其五","f":"七言绝句","c":["花枝满树雨添肥，晴色十分春又归。","一生万事无不尔，行年六十尽成非。"]},{"t":"湖居无事日课小诗 其六","f":"七言绝句","c":["多情白鸟去还来，无事风扉闭复开。","山下一帆冲雨过，水边双燕得泥回。"]},{"t":"湖居无事日课小诗 其七","f":"七言绝句","c":["海内名流诗有宗，时传佳句落闲中。","不道建安六七子，可是近时三数公。"]},{"t":"次韵同季夜宿松园兼呈清照师","f":"五言律诗","c":["鹤骨松园老，霜髯八十春。","相逢看日夕，留客赋诗新。","鬼亦来听法，谁应可作邻。","折腰营斗粟，宁不愧斯人。"]},{"t":"强幼安用余与曾同季唱酬韵作二章见寄谨用韵为谢 其一","f":"五言律诗","c":["江国从游地，花今几度春。","老唯羁客在，情独使君新。","未敢论倾盖，应须托善邻。","如公真盛德，举世更何人。"]},{"t":"强幼安用余与曾同季唱酬韵作二章见寄谨用韵为谢 其二","f":"五言律诗","c":["花落青墩寺，谁从作好春。","锦囊题句近，旧旆得州新。","老手摧强敌，馀风睦四邻。","他年数循吏，神爵有斯人。"]},{"t":"寄李司农三首 其一","f":"五言律诗","c":["东阁当年夜，华灯照别樽。","断碑思雁塔，佳客愧龙门。","岂料三吴路，相逢一水村。","只今悬望眼，犹欲黯离魂。"]},{"t":"寄李司农三首 其二","f":"五言律诗","c":["徽水定何处，谪官今几时。","长沙应有赋，南涧可无诗。","柳絮催春远，梅花寄客迟。","谁怜忆公久，头白少相知。"]},{"t":"寄李司农三首 其三","f":"五言律诗","c":["谢朓南齐守，司农古汉官。","杯今与谁把，山亦要公看。","细札颁何日，离骚读又残。","侍郎兄弟在，往往上金銮。"]},{"t":"客舍春寒","f":"七言律诗","c":["每日东风吹暗尘，小池幽树不成春。","妨他燕子关何事，折尽梅花最恼人。","愁里了知身是幻，老来惟与睡相亲。","去年湖水浑依旧，欲买扁舟钓白蘋。"]},{"t":"洗马行和关子东韵","f":"七言古诗","c":["忆昔四海多甲兵，令严细柳将军营。","铁衣健卒持满立，黑头壮士从军行。","眼前千马复万马，寸土不耕犁与骍。","自从虎皮蒙剑戟，此马不闻鼙鼓惊。","只今尽浴长安水，七十万匹俱长鸣。","风騣雾鬣久不试，日餍官粟无斗升。","庙堂伊吕自有策，不与韩白齐功名。","圉人但喜马肥健，野老安知无战争。","有君如此岂不乐，俟河几时今得清。","不须天育骠骑种，云雾晦冥方降精。","我欲刻石上浯水，白头弄笔羞书生。","不闻铁骑响鸣镝，但听玉箫吹九成。"]},{"t":"读楚词三首 其一","f":"七言绝句","c":["借令无策拒强秦，何至甘心受虎吞。","楚国已墟三十载，区区犹念尔东门。"]},{"t":"读楚词三首 其二","f":"七言绝句","c":["方从黄棘望回骖，可笑襄王又信谗。","已分世间无鲍叔，便须水底觅彭咸。"]},{"t":"读楚词三首 其三","f":"七言绝句","c":["人生长策是同流，却遣何人为国忧。","鼎镬轩裳俱一死，屈原何得畏阳侯。"]},{"t":"夜中闻雨枕上作","f":"五言律诗","c":["老去飘零日，春愁烂漫中。","诗窗窥窈窕，睡枕听朦胧。","弱柳妨晴态，小桃吹落红。","颠风莫相恼，花事不关侬。"]},{"t":"为人贺沈镇江生日 其一","f":"七言律诗","c":["一麾新领浙西州，重说当年八咏侯。","要遣虏人知宿将，故乘轺传作遨头。","朅来京口颁明诏，便合甘泉从禁游。","红袖相扶客为寿，莫嫌和月醉西楼。"]},{"t":"为人贺沈镇江生日 其二","f":"七言律诗","c":["甲子重新数中兴，济川人为圣时生。","五花名肃金銮殿，八阵威寒铁瓮城。","贺客杯觞方潋滟，使君忠力转精明。","祝年有意留公住，只恐调元要老成。"]},{"t":"春寒","f":"词","c":["杨柳毵毵一水间，梅花憔悴雨??。","春愁已自难禁酒，病骨何由更耐寒。"]},{"t":"种兰","f":"七言绝句","c":["桃杏花中偶并栏，依然风味是幽兰。","莫因移种长安市，不作春山一样看。"]},{"t":"种萱","f":"七言绝句","c":["万事全归两鬓霜，新愁尽属少年场。","如今乞得忘忧草，已自无忧可得忘。"]},{"t":"次韵张元明同边郎中游西湖二君讲同年之好有此游","f":"七言律诗","c":["十里春波翠染衣，小寻鱼鸟共追随。","船头风急何妨醉，湖上山多尽入诗。","藜杖偶来飞絮里，芦鞭犹忆看花时。","两公人物如连璧，同上金銮亦未迟。"]},{"t":"皇帝亲祀高禖十五韵","f":"五言古诗","c":["历欲绵洪祚，郊宜筑巨台。","有司脩祝册，天子祭高禖。","意与群情合，春随上瑞来。","翠舆瞻玉座，桂酒奠金罍。","喜色回中壸，欢声入九垓。","熊罴占已兆，弧矢射将催。","异礼关宗社，馀波被草莱。","灵基千岁永，玉叶万枝开。","制度新仪著，歌诗旧典该。","鲁侯徒复宇，后稷始封邰。","帝德应先格，天心亦易回。","至诚参造化，妙响疾风雷。","历数周家久，封疆汉地恢。","山河今壮矣，瓜瓞信悠哉。","准拟螽斯咏，微臣愧不才。"]},{"t":"校李从一台阁集因效其体 其一","f":"五言律诗","c":["细诵台州句，湖边草舍幽。","好山来竞秀，清濑与争流。","吏可供书札，儿能伴校雠。","小窗谁共此，唯有夕阳留。"]},{"t":"校李从一台阁集因效其体 其二","f":"五言律诗","c":["旧旆来分赖，唐朝有百人。","诸公皆泯灭，此句独清新。","异世名空在，今年迹已尘。","何由吊高冢，一望石麒麟。"]},{"t":"次韵子东奉命祠高禖斋宫望临平山","f":"七言律诗","c":["遥想祠宫晓色寒，卷帘聊此看孱颜。","官闲颇似苏司业，诗好全如庾子山。","觅句不妨烟雨外，浮家犹记往来间。","旧游有意重回首，恐上金銮未得还。"]},{"t":"甲子春日二首 其一","f":"七言绝句","c":["燕来不拟著帘遮，要听双飞语日斜。","芳草满庭人不扫，东风吹尽石楠花。"]},{"t":"甲子春日二首 其二","f":"七言绝句","c":["海棠枝上晓莺啼，栀子花边蛱蝶飞。","贪看游蜂偷蕊去，不知双燕得泥归。"]}]};